-- ============================================================

UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცეში გადაადგილება“: ბავშვი უკვე სწავლობს ვიწრო ადგილებში გავლას, დაბრკოლებების ქვეშ გაძრომასა და მათზე გადაბიჯებას. სახლში ბალიშებისა და ყუთებისგან პატარა „დაბრკოლებების ზოლი“ მოაწყვეთ. ეს დაეხმარება მას საკუთარი სხეულის ზომების აღქმაში (პროპრიოცეპტიული შეგრძნებები) და მოძრაობების დაგეგმვაში.') WHERE id = '2b1c5f94-7b82-40ce-9f0d-d663053b5141';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მიჯაჭვულობა: ბავშვი თქვენდამი სიყვარულს უკვე უფრო მკაფიო ჟესტებით გამოხატავს — შეიძლება მოულოდნელად მოვიდეს, ჩაგეხუტოთ ან თავზე მოგეფეროთ. თქვენც იმავე სითბოთი უპასუხეთ. ეს ემოციური ურთიერთგაცვლა ყველაზე მნიშვნელოვანი საზრდოა იმისთვის, რომ მან თავი უსაფრთხოდ და ღირებულად იგრძნოს.') WHERE id = 'de41f735-eeb7-4ab7-ab3c-cfc2d80548ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '16-ე თვეში გადავდივართ! ბავშვს უკვე შეუძლია „მამასა“ და „დედას“ გარდა 5-10 სხვადასხვა სიტყვის გააზრებულად თქმა. შესაძლოა, სიტყვებს ჯერ სრულად სწორად ვერ წარმოთქვამდეს, მაგრამ თითოეულ მათგანს კონკრეტული მნიშვნელობა აქვს. მხარი დაუჭირეთ მის ყოველ მცდელობას და მის მიერ ნაწილობრივ წარმოთქმული სიტყვა სრული წინადადებით დაადასტურეთ. მაგალითად, როცა ის ამბობს „მა“, უპასუხეთ: „დიახ, ეს მანქანაა“.') WHERE id = 'd807a9a4-6329-44cd-97d5-dae1bf4a8ff6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოძრაობის ახალი ეტაპი: ბავშვს უკვე შეუძლია, ხელით მხარდაჭერისას კიბეზე ფეხზე მდგარმა ავიდეს. ეს მოძრაობა მის ბარძაყისა და მენჯის კუნთებს აძლიერებს. კიბესთან ყოველთვის მის გვერდით იყავით და დაეხმარეთ. არ დაგავიწყდეთ, დარწმუნდეთ, რომ სახლში კიბის შესასვლელებთან დამონტაჟებული უსაფრთხოების დამცავი ბარიერები (gate) დაკეტილია.') WHERE id = '22600f5c-8f2a-4f8d-9f3c-76e5a5fcda2c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე სიამოვნებს მარტივი მითითებების შესრულება. როდესაც ეუბნებით: „გთხოვ, ბურთი მომიტანე“ ან „აიღე შენი ქუდი“, მას ამის გაკეთება შეუძლია. ეს აჩვენებს, რამდენად კარგად აქვს განვითარებული რეცეპტული ენა (ნათქვამის გაგების უნარი). მცირე და სასიამოვნო დავალებების მიცემით ხელი შეუწყვეთ როგორც მეტყველების, ისე პასუხისმგებლობის გრძნობის განვითარებას.') WHERE id = '44a68c23-5478-40d4-a83c-2dc9f09d429d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ჩემია!“ — ეს განცდა კიდევ უფრო მძაფრდება. ბავშვმა შეიძლება მტკიცედ არ მოისურვოს თავისი საყვარელი სათამაშოს სხვისთვის მიცემა. ეს მისი პირადი საზღვრების გაცნობიერების ნაწილია. ნუ აიძულებთ გაზიარებას. ამის ნაცვლად, აჩვენეთ, როგორ გამოიყენოთ სათამაშოები რიგრიგობით („ახლა შენი ჯერია, შემდეგ კი — მამასი“) და ამგვარად განუვითარეთ სამართლიანობის განცდა.') WHERE id = '3dc015ff-56bb-4a43-b76e-ffb3ffd6a8c8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკის დახვეწა: ბავშვი კონსტრუქტორის ბლოკებს (კუბებს) უკვე მხოლოდ ერთმანეთზე კი არ აწყობს, არამედ ცდილობს, გვერდიგვერდ განალაგოს და „მატარებელი“ ან „გზა“ გააკეთოს. ეს აჩვენებს, რომ მისი სივრცითი აღქმა უფრო რთულ საფეხურზე გადადის. სხვადასხვა ფორმის კონსტრუქტორების შეთავაზებით წაახალისეთ მისი შემოქმედებითობა.') WHERE id = '05f48dd1-b441-4a53-83ad-213693a97b1c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებაში „არჩევითი მადის“ პერიოდი იწყება. ბავშვმა შეიძლება მოულოდნელად უარი თქვას ზოგიერთ საკვებზე. ეს გემოვნების რეცეპტორების განვითარებისა და საკუთარი ნების გამოხატვის ნაწილია. ნუ აიძულებთ ჭამას, თუმცა რამდენიმე დღის შემდეგ უარყოფილი საკვები სხვა სახით კვლავ შესთავაზეთ (მაგალითად, პიურეს ნაცვლად — ნაჭრებად). სუფრასთან შეინარჩუნეთ დადებითი ატმოსფერო.') WHERE id = '01373d24-e28a-437e-998d-4ae78f2851c2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ქაღალდზე „ჯღაბნისას“ ბავშვი უკვე უფრო ფართო მოძრაობებს აკეთებს. ფანქარი უფრო თავდაჯერებულად უჭირავს და ზოგჯერ ფერების გარჩევასაც ცდილობს. მიეცით ბავშვებისთვის უსაფრთხო, მსხვილი ფერადი ფანქრები და დიდი ზომის სახატავი ფურცლები. მისი ეს პირველი „ხელოვნების ნიმუშები“ ფასდაუდებელია როგორც ხელისა და თვალის კოორდინაციის გასავითარებლად, ისე საკუთარი თავის გამოსახატავად.') WHERE id = '10f5c993-c3c9-44f8-a870-3ed80a4cfbed';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „მიბაძვა“ უკვე ყოველდღიურ საქმიანობაზეც ვრცელდება. როდესაც თქვენ სახლს ალაგებთ, მასაც სურს, რამე გაწმინდოს, ხოლო საჭმლის მომზადებისას — თავადაც მოურიოს. მიეცით პატარა საწმენდი ტილო ან სათამაშო ცოცხი. ეს ეხმარება ბავშვს, თავი ოჯახის საჭირო წევრად იგრძნოს და სასარგებლო ჩვევები შეიძინოს.') WHERE id = 'd75c2f77-0a11-4bee-830a-88006d025c3c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე მხოლოდ საგნებს კი არ აგროვებს, არამედ მათ ფერის მიხედვით დაჯგუფებასაც ცდილობს. მიეცით ორი სხვადასხვა ფერის კონტეინერი და აჩვენეთ, როგორ მოათავსოს იმავე ფერის სათამაშოები შესაბამის კონტეინერში. ეს თამაში სწრაფად ავითარებს მის ვიზუალურ აღქმასა და ლოგიკურ აზროვნებას. ყოველი სწორი არჩევანისას შეაქეთ, რათა სწავლისადმი ინტერესი გაუღვივდეს.') WHERE id = '7aebe8cd-a4e5-44f9-8f57-fc363b89129a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური აქტივობის ახალი ეტაპი — „უკან გადადგმული ნაბიჯი“. ბავშვმა უკვე აღმოაჩინა უკან სიარული. ეს წონასწორობის რთული ვარჯიშია და აჩვენებს, რამდენად კარგად აქვს განვითარებული სხეულის კოორდინაცია. შეუქმენით პირობები, რომ ეს ახალი უნარი დაბრკოლებებისგან თავისუფალ და რბილ სივრცეში მოსინჯოს. სხეულის მართვის უნარის გაუმჯობესებასთან ერთად მისი თავდაჯერებულობაც იზრდება.') WHERE id = '23d55f43-944e-41ff-a1f0-31e749c5ea5d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვა და ცნობისმოყვარეობა“. ბავშვი უკვე მიუთითებს საგნებზე და ამბობს: „ეს რა არის?“ (ან თავის ენაზე მსგავს ბგერებს წარმოთქვამს). მოთმინებით დაუსახელეთ ყველაფერი: „ეს წითელი მანქანაა“, „ეს დიდი ხეა“. თუ მის ცნობისმოყვარეობას უპასუხოდ არ დატოვებთ, ეს ხელს შეუწყობს როგორც პასიური, ისე აქტიური ლექსიკური მარაგის გამდიდრებას.') WHERE id = '741cbef2-ffcd-4b10-9cdf-8e41aa164e28';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ხუმრობები“. ბავშვი განზრახ გაწვდით სათამაშოს, შემდეგ კი მაშინვე უკან მიაქვს და იცინის? ეს მიუთითებს, რომ მას იუმორის გრძნობა და სოციალური ურთიერთობის უნარი უყალიბდება. ხალისით აჰყევით მის ამ „თამაშს“. ერთად სიცილი თქვენ შორის ემოციურ კავშირს აძლიერებს და ბავშვს ჯანსაღ თავდაჯერებულობას უყალიბებს.') WHERE id = '5a726b9c-27a1-4456-85ed-e5c0d76d2484';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „პირამიდა და რგოლები“. ბავშვი უკვე უფრო ოსტატურად ალაგებს რგოლებს დიდიდან პატარისკენ (ან პირიქით). ეს მოქმედება ავითარებს როგორც ზომის აღქმას (დიდი-პატარა), ისე ხელისა და თვალის კოორდინაციას. რგოლების დალაგებისას მათი ფერებიც ხმამაღლა დაასახელეთ.') WHERE id = '51378f6a-c746-490d-b2e3-d4da3d093685';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვსვამ“. ბავშვი უკვე თითქმის ახერხებს ღია ჭიქიდან წყლის დალევას ისე, რომ არ დაღვაროს. მიეცით ბავშვის ზომის, გადაყირავებისადმი მდგრადი (მძიმე ძირიანი) პლასტმასის ჭიქა. დამოუკიდებლად წყლის დალევა მის ტუჩებისა და ენის კუნთებს მეტყველებისთვის ამზადებს და დამოუკიდებლობის განცდას უძლიერებს.') WHERE id = '44c70121-397f-4987-8f6a-6aae583c01e5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებისას „საჭმელი ხელსაწყოებით მანევრირება“. ბავშვს უკვე უფრო ზუსტად შეუძლია, ბავშვის ჩანგალი საკვებში (მაგალითად, რბილად მოხარშულ ბოსტნეულში) ჩაარჭოს და პირისკენ წაიღოს. ეს უნარი ხელს უწყობს როგორც ხელისა და თვალის კოორდინაციის გაუმჯობესებას, ისე საკუთარი თავის დამოუკიდებელ პიროვნებად აღქმას. სუფრაზე მცირე არეულობის მიუხედავად, მიეცით ამის შესაძლებლობა.') WHERE id = '28156e7f-7e18-4b94-927c-a444469bee3e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცითი მეხსიერება“ და ძიება: ბავშვს უკვე შეუძლია გაიხსენოს, სად დადეთ სათამაშო რამდენიმე საათის წინ, და იპოვოს ის. ითამაშეთ მასთან თამაში „იპოვე დაკარგული ნივთი“. ეს აუმჯობესებს როგორც მის ვიზუალურ მეხსიერებას, ისე ყურადღების კონცენტრირების უნარს. თითოეული ნაპოვნი ნივთი მისთვის პატარა „აღმოჩენის“ გამარჯვებაა.') WHERE id = '15ff0052-98cf-4d44-8277-9931b5bbd7bd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „ემპათია“ ძლიერდება. როდესაც ბავშვი ხედავს, რომ სხვა ვინმეს (ან მის სათამაშოს) „ეწყინა“, შეიძლება ჩაეხუტოს ან მოეფეროს. ეს მიანიშნებს, რომ ის სხვების გრძნობების გაგებას იწყებს. მისი ემოციების დასახელებით, მაგალითად, ფრაზით „დიახ, შენი მეგობარი ახლა ცოტა მოწყენილია“, ხელი შეუწყვეთ მისი ემოციური ინტელექტის განვითარებას.') WHERE id = '6c93684c-6781-4a11-bb15-1580d5f66d36';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: ბავშვი უკვე სწავლობს ადგილზე შემობრუნებასა და უკან ნაბიჯის გადადგმას. ეს წონასწორობის შენარჩუნების რთული ვარჯიშია. მიეცით შესაძლებლობა, ფართო და დაბრკოლებებისგან თავისუფალ სივრცეში მოსინჯოს ეს ახალი უნარები. სხეულის მართვის უნარის გაუმჯობესებასთან ერთად, დაცემის შიში მცირდება და მისი მოძრაობის არეალი ფართოვდება.') WHERE id = '33b5778f-3fe2-440a-8f22-62f63b5a956d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: „ვითომ“ (Pretend play) თამაშები უფრო რთული ხდება. ბავშვმა შეიძლება სათამაშო მანქანის „vrr-vrr“ ხმა გამოსცეს ან თავი მოაჩვენოს, თითქოს ცარიელი თეფშიდან „ჭამს“. შეუერთდით მას ამ თამაშებში და ახალი კითხვებით წაახალისეთ მისი წარმოსახვა. ეს აძლიერებს როგორც მის შემოქმედებით უნარებს, ისე ლოგიკური კავშირების დამყარების უნარს.') WHERE id = 'd2fca029-5edb-4176-b69f-5a506afd4a61';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნებისყოფა და საზღვრები: ბავშვი უკვე რეაგირებს სიტყვებზე „არ შეიძლება“, თუმცა ზოგჯერ განზრახ იმეორებს აკრძალულ მოქმედებას და თან გიყურებთ. ასე ის თქვენს მოთმინებასა და წესების უცვლელობას ამოწმებს. შეინარჩუნეთ სიმშვიდე, თუმცა იყავით მტკიცე. წესების თანმიმდევრულობა ბავშვს უსაფრთხოებისა და წესრიგის განცდას უყალიბებს.') WHERE id = '3e76b053-c97c-4476-b999-951be493bb64';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წონასწორობა და კოორდინაცია: ბავშვი უკვე ცდილობს, ადგილზე იხტუნაოს. შესაძლოა, ჯერ ორივე ფეხის ერთდროულად იატაკიდან აწევა ვერ შეძლოს, მაგრამ მუხლების მოხრა და ზამბარასავით მოძრაობა მისი მსხვილი მოტორიკის განვითარებაზე მიუთითებს. მასთან ერთად რიტმულ მუსიკაზე იცეკვეთ. ეს არა მხოლოდ სახალისო, არამედ ფიზიკურადაც ძალიან სასარგებლო ვარჯიშია.') WHERE id = '47585bf0-21b2-4948-bcc0-cc0d44631bdd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციურ განვითარებაში „სურვილისა და შესაძლებლობის“ წინააღმდეგობა. როდესაც ბავშვს რაიმეს გაკეთება სურს, მაგრამ არ გამოსდის, შეიძლება იყვიროს ან გაბრაზდეს. ასეთ მომენტებში სიმშვიდე შეინარჩუნეთ და მისი გრძნობა დაასახელეთ: „გაბრაზდი, რადგან კუბები დაგენგრა, მესმის“. თქვენი ასეთი თანაგრძნობა მას ემოციების მართვასა და სირთულეების წინაშე სულის არდაკარგვას ასწავლის.') WHERE id = 'a0a20bce-4839-4117-9368-c41ef5150778';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე არა მხოლოდ მიუთითებს სხეულის ნაწილებზე (ხელი, ფეხი, მუცელი), არამედ მათი სახელების წარმოთქმასაც ცდილობს. ჩაცმისას ჰკითხეთ: „სად არის შენი მუცელი?“ და პასუხისთვის დრო მიეცით. ეს შესანიშნავი ვარჯიშია სხეულის სქემის გასააზრებლად და ლექსიკური მარაგის გასააქტიურებლად.') WHERE id = '9f429553-7b9f-4533-9a8c-fa277c16a3ea';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლობისკენ სწრაფვა ჩაცმის დროსაც ვლინდება. ბავშვმა შეიძლება წინდა მოქაჩოს და გაიხადოს ან ქუდის თავზე დახურვა სცადოს. ხელს ნუ შეუშლით „თვითმომსახურების“ ასეთ მცდელობებში. მიეცით საშუალება, აჩქარების გარეშე, თავად შეძლოს რაიმეს გაკეთება — ეს ყველაზე მეტად ზრდის მის თვითშეფასებას (self-esteem).') WHERE id = 'eb7b56da-4f69-416f-ae1f-039fef91ef94';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სიტყვათა შეხამების“ პირველი ნიშნები: ბავშვს უკვე შეუძლია ორი სიტყვის ერთმანეთთან დაკავშირება (მაგალითად, „მამა, მოდი“ ან „მომეცი წყალი“). თუ სიტყვებს ჯერ არ აერთიანებს, თავად მიეცით მაგალითი. როცა ის ამბობს „ბურთი“, თქვენ უპასუხეთ: „დიახ, დიდი ბურთი“ და ამგვარად გააფართოეთ ნათქვამი. ეს მის ტვინში გრამატიკული სტრუქტურების ჩამოყალიბებას უწყობს ხელს.') WHERE id = '6753f0e0-f84e-40f2-a42e-a2fc56030ffe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკა — „წიგნის გვერდები“. ბავშვს უკვე უკეთ შეუძლია სქელი მუყაოს გვერდების სათითაოდ გადაფურცვლა. შესთავაზეთ ინტერაქტიული წიგნები, რომლებსაც შეხებით შესაცნობი (touch-and-feel) ელემენტები აქვს. გვერდების დამოუკიდებლად გადაფურცვლა მას დამოუკიდებლობის განცდას უვითარებს და ამავდროულად ავარჯიშებს თითების მცირე კუნთებს, რაც წერისთვის მომზადებაში დაეხმარება.') WHERE id = 'ed122971-473f-43f3-a24c-a44303a6f746';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სიტყვათა შეთანხმებები“. ბავშვი უკვე ორ სიტყვას ერთმანეთთან აკავშირებს და მარტივ წინადადებებს ადგენს: „მამა, მოდი“, „მომეცი ვაშლი“. თუ ჯერ სიტყვებს არ აერთიანებს, მის მიერ ნათქვამ ერთ სიტყვას თქვენ განავრცეთ: „დიახ, ვაშლი გინდა? აი, გემრიელი ვაშლი“. ეს მის ტვინში გრამატიკული სტრუქტურების განმტკიცებას უწყობს ხელს.') WHERE id = '3ec1877f-e8dc-4ba3-893d-678bde1927b1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკის განვითარების „ფაზლების“ პერიოდი. ბავშვი უკვე სწავლობს მარტივი, 2-3-ნაწილიანი ფაზლების აწყობას ან ფიგურების შესაბამის ღიობებში მოთავსებას. ეს თამაში მნიშვნელოვნად ავითარებს როგორც მის ვიზუალურ აღქმას, ისე პრობლემების გადაჭრის უნარს. თუ არ გამოუვა, მშვიდად დაეხმარეთ და გაამხნევეთ.') WHERE id = 'b4b1a4bc-e49d-4497-b688-464c24f79875';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „პარალელური თამაში“. სხვა ბავშვებთან ყოფნისას თქვენი ბავშვი მათთან ერთად კი არა, მათ გვერდით, თავისთვის თამაშობს. ეს მე-17 თვისთვის სრულიად ნორმალურია. სხვა ბავშვებზე დაკვირვებით ის ბევრ რამეს სწავლობს. კვლავ მიიყვანეთ თანატოლებთან, რათა სოციალურ გარემოს შეეგუოს.') WHERE id = '0d8b6018-4d34-41fe-ad70-9143e9c2615f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვიბან“. ბანაობისას ან ხელების დაბანისას ბავშვი ცდილობს, საპონი ან ღრუბელი აიღოს და სხეული თავად გაიწმინდოს. მხარი დაუჭირეთ ჰიგიენური ჩვევებისადმი მის ინტერესს. საკუთარი თავის „გასუფთავება“ ეხმარება, უკეთ გაიცნოს სხეულის ნაწილები და განივითაროს დამოუკიდებლობის განცდა.') WHERE id = '3c2bb527-c368-4b69-94c1-76665087b2b9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეხსიერების გაძლიერება: „დაკარგული ნივთები“. თქვენ მიერ დამალული სათამაშოს საპოვნელად ბავშვი რთულ ხერხებს იყენებს – საბანს სწევს, ყუთში იხედება. ეს აჩვენებს, რომ მას „ობიექტის მუდმივობის“ ცნება სრულად აქვს ათვისებული. სახლში მასთან ერთად პატარა „განძის ძიების“ თამაშები ითამაშეთ და ამგვარად მისი ყურადღება ავარჯიშეთ.') WHERE id = 'd0afa5e2-c732-43e9-af9d-2f3d19c36c4e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვა და „საოჯახო საქმეები“. ბავშვი სათამაშო ტელეფონით „საუბრობს“ ან სათამაშო ცოცხით იატაკს გვის. ის თქვენს თითოეულ მოძრაობას იმეორებს. მიბაძვა სამყაროს შეცნობის მისი გზაა. მიეცით საკუთარი პატარა „სამუშაო ხელსაწყოები“, რათა თავი მნიშვნელოვნად იგრძნოს.') WHERE id = '9dfb3516-1999-4989-989e-9e6fdb3fb9e5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: „ცოცვის ოსტატობა“. ბავშვს უკვე ძალიან მოსწონს კიბეზე დამოუკიდებლად ასვლა (ჯერჯერობით ოთხზე ცოცვით ან თქვენი ხელის დახმარებით). სიმაღლის აღქმის გაუმჯობესებასთან ერთად, საჭიროა მას ჩამოსვლაც ასწავლოთ. ყოველთვის აჩვენეთ, რომ ზურგით ჩამოსვლა უფრო უსაფრთხოა.') WHERE id = '15095e09-193b-4e26-bc2e-4f81de7c413d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 500 დღე გავიდა! თქვენი ბავშვი უკვე სრულად გამოვიდა ჩვილობის ასაკიდან და საკუთარი ხასიათისა და ნების მქონე პატარა ბავშვად იქცა. დღეს მასთან ერთად დრო მის საყვარელ საქმიანობას დაუთმეთ (მაგალითად, ხატვას ან პარკში გასეირნებას). თქვენი მოთმინება და სიყვარული ყველაზე დიდი ძალაა, რომელმაც ის ამ ეტაპამდე მოიყვანა. ყოჩაღ, დედა!') WHERE id = '3427ae53-cf26-4b28-928a-b9787dc9cf32';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი „მე“-ს ცნებას უკვე საკუთარი ქცევით გამოხატავს. ტანსაცმლის თავად არჩევის ან დამოუკიდებლად ჭამის სურვილი მისი დამოუკიდებლობის ნიშანია. მიეცით მას ამის შესაძლებლობა: „რომელი მაისურის ჩაცმა გინდა?“. მცირე არჩევანის შეთავაზება მას გადაწყვეტილების მიღების უნარს უვითარებს და სიჯიუტის ეპიზოდებსაც ამცირებს.') WHERE id = '1f190c82-9146-4726-b79a-d4e22c530f6d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური აქტივობა: „დაბრკოლებების გადალახვა“. ბავშვი უკვე სწავლობს, როგორ გადააბიჯოს იატაკზე დაყრილ სათამაშოებსა და ბალიშებს ან გვერდი აუაროს მათ. ეს სივრცის აღქმის რთული უნარია. სახლში უსაფრთხო დაბრკოლებების მოწყობით დაეხმარეთ მას, ივარჯიშოს როგორც წონასწორობის შენარჩუნებაში, ისე სხეულის მართვაში.') WHERE id = '0762347b-3e67-4f92-a1cc-28fc730be874';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველება: „სიტყვების მნიშვნელობა“. ბავშვი უკვე უბრალოდ კი არ იმეორებს სიტყვებს, არამედ მათ კონკრეტული სიტუაციების შესაბამისად იყენებს. მაგალითად, როცა თქვენ ფეხსაცმელს იცვამთ, მან შეიძლება თქვას „ტატა“ (გარეთ). განავრცეთ მისი ნათქვამი: „დიახ, ახლა ფეხსაცმელს ჩავიცვამთ და პარკში წავალთ“. ეს მის გონებაში მოვლენებსა და სიტყვებს შორის კავშირს აძლიერებს.') WHERE id = '32725b0c-885a-420b-8b00-82ddb5c437d8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკა: „დიზაინი და კონსტრუირება“. ბავშვი კუბებს უკვე მხოლოდ ერთმანეთზე კი არ აწყობს, არამედ ცდილობს, მათგან „მატარებლის“ ან „ღობის“ მსგავსი ჰორიზონტალური ფორმები შექმნას. ეს მიუთითებს, რომ მისი სივრცითი აზროვნება განვითარების ახალ ეტაპზე გადავიდა. შესთავაზეთ სხვადასხვა ფორმის კონსტრუქტორები და ხელი შეუწყვეთ მის წარმოსახვას.') WHERE id = 'd22bf585-b849-4796-8341-19d360ee9434';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: თამაში „საჭმლის მომზადება“. ბავშვმა შესაძლოა სათამაშო ჭურჭლით თავი ისე მოაჩვენოს, თითქოს რაღაცას „ამზადებს“. შეუერთდით მას ამ თამაშში: „მეც მომცემ ცოტაოდენ საჭმელს?“. ეს აჩვენებს, რამდენად ყურადღებით აკვირდება ის ყოველდღიურ რიტუალებს და როგორ ვითარდება მისი წარმოსახვა.') WHERE id = '0303ebf1-df3e-4e81-bd4e-6f1dea97c188';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: ბავშვი უკვე ცდილობს, დაბალ საფეხურებზე ან დივნის კიდეზე დამოუკიდებლად აძვრეს. მიუხედავად იმისა, რომ სიმაღლის აღქმა უვითარდება, რისკები ჯერ ბოლომდე არ ესმის. ყოველთვის ახლოს იყავით, რომ საჭიროების შემთხვევაში დაიჭიროთ, და აჩვენეთ უსაფრთხოდ ჩამოსვლის გზები (მაგალითად, ზურგით ჩამოსვლა).') WHERE id = '4a36804a-6409-441e-bfa1-5d47aa7ddf64';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ცხოველებისა და მათი ხმების გარჩევა“. ბავშვი სურათზე ნანახ ძროხასა და კატას უკვე ერთმანეთისგან არჩევს და მათი ხმების გამოხატვა შეკითხვის გარეშეც შეუძლია. თუ წიგნის კითხვისას ჰკითხავთ: „სად არის აქ კატა?“ და ის თითით მიგითითებთ, ეს აჩვენებს, რამდენად გაუძლიერდა ვიზუალური მეხსიერება და ყურადღება.') WHERE id = '48266b98-24f4-486a-8c86-5edb343f6455';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები და „არა“. როდესაც ბავშვს ყველაფრის დამოუკიდებლად გაკეთება სურს და არ გამოსდის, შეიძლება მოულოდნელად გაბრაზდეს. ასეთ დროს ჩაეხუტეთ და მშვიდად უთხარით: „გაბრაზდი, რადგან ფეხსაცმლის ჩაცმა ვერ შეძელი, მესმის“, — ასე მის ემოციას სახელს დაარქმევთ. თქვენი სიმშვიდე მისთვის ემოციების მართვის სწავლის საუკეთესო მაგალითია.') WHERE id = 'bd6e2ef7-be9f-49e8-9f5a-73c5aca2c6c7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ავლენს საკუთარ გემოვნებას. მან შეიძლება გადაჭრით აირჩიოს მაისური, რომლის ჩაცმაც სურს, ან წიგნი, რომლის წაკითხვაც უნდა. ამ პერიოდში მიეცით „შეზღუდული არჩევანის“ შესაძლებლობა: „დღეს წითელი მაისურის ჩაცმა გინდა თუ ლურჯის?“. ეს მას საკუთარი გადაწყვეტილებების მართვის განცდას უჩენს და მომავალში სიჯიუტით გამოწვეული კრიზისების თავიდან აცილებას უწყობს ხელს.') WHERE id = 'e2f29ee5-abb0-4ec5-8bfb-7fca6b238c4f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „სირბილის ოსტატობა“. ბავშვი სირბილისას უკვე უკეთ ინარჩუნებს წონასწორობას და შეუძლია მოულოდნელად გაჩერდეს. ეს აჩვენებს, რამდენად გაუუმჯობესდა კუნთების ძალა და ტვინსა და კუნთებს შორის კოორდინაცია. პარკში ან ეზოში მოუძებნეთ დაბრკოლებებისგან თავისუფალი სივრცე, სადაც სირბილით ენერგიის დახარჯვას შეძლებს.') WHERE id = '85cc1293-16e0-49cd-904b-171804ae1853';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „ემპათიის“ ნიშნები. როდესაც ბავშვი ხედავს, რომ მოწყენილი ხართ ან რამე გეტკინათ, შესაძლოა მოვიდეს, შეგეხოთ ან ჩაგეხუტოთ კიდეც. ეს აჩვენებს, რომ ის უკვე გრძნობს სხვების ემოციებს. დაარქვით მის ამ გრძნობას სახელი და უთხარით: „დიდი მადლობა, რომ მხარს მიჭერ“. ეს ემოციური ინტელექტის საფუძველია.') WHERE id = '3a9d7d72-ab6c-4777-b054-a56b8986ee74';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად მოწესრიგება“. ბავშვი, თქვენი მიბაძვით, ცდილობს ხელების დაბანას, სახის გაწმენდას ან კბილების გახეხვას (ჯერჯერობით მხოლოდ ჯაგრისის ღეჭვით). ნუ ჩაუხშობთ დამოუკიდებლობის ამ სურვილს. დაუდგით საფეხურიანი სკამი (step stool), რათა საჭირო ადგილებს მისწვდეს, და მიეცით საშუალება, თქვენი მოქმედებები გაიმეოროს. ეს მას თვითმოვლის ჩვევებს უყალიბებს.') WHERE id = '090f40d7-6abc-46b1-8914-c34325dbcaa0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეხსიერება და „სივრცითი მეხსიერება“. ბავშვს უკვე შეუძლია დიდხანს ახსოვდეს, სად არის დამალული მისი სათამაშო. სახლში მასთან ერთად ითამაშეთ პატარა „განძის ძიების“ თამაშები. დამალეთ რაიმე ნივთი გადასაფარებლის ქვეშ და დააკვირდით, როგორ იპოვის მას. ეს თამაშები ბავშვს როგორც ყურადღების კონცენტრირებას, ისე პრობლემის გადაჭრის გზის პოვნას ასწავლის.') WHERE id = '0bfe8ad5-dcd4-46e4-af49-e5c2a87c763e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: თამაში „ვითომ“ (Pretend play). ბავშვს უკვე შეუძლია თავი მოაჩვენოს, თითქოს ცარიელი ფინჯნიდან „ჩაის სვამს“ ან თოჯინას „აჭმევს“. შეუერთდით მას ამ თამაშებში. ასეთი თამაშები ხელს უწყობს როგორც ბავშვის შემოქმედებითი უნარების განვითარებას, ისე ყოველდღიური ცხოვრების რიტუალების უკეთ გააზრებას.') WHERE id = '9a097c94-eb06-4b23-b839-a6859f4ee3f2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: „აძრომა და ჩამოსვლა“. ბავშვი უკვე ცდილობს, დაბალ საფეხურებზე ან დივნის კიდეზე დამოუკიდებლად აძვრეს. მიუხედავად იმისა, რომ სიმაღლის აღქმა უვითარდება, ის ჯერ კიდევ სრულად ვერ აცნობიერებს რისკებს. ყოველთვის აჩვენეთ, რომ ზურგით ჩამოსვლა უფრო უსაფრთხოა. თქვენი მეთვალყურეობის ქვეშ ასეთი ვარჯიში სხეულის მართვის უნარს უძლიერებს.') WHERE id = '0f9b9189-8ffa-4276-919f-031f8673dbe8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები და „არა“. ბავშვი უკვე რეაგირებს სიტყვაზე „არ შეიძლება“, თუმცა ზოგჯერ განზრახ იმეორებს აკრძალულ მოქმედებას და თან თქვენ გიყურებთ. ამგვარად ის თქვენს მოთმინებასა და წესების უცვლელობას ამოწმებს. შეინარჩუნეთ სიმშვიდე, მაგრამ იყავით მტკიცე. წესების თანმიმდევრულობა ბავშვს უსაფრთხოებისა და წესრიგის განცდას უყალიბებს.') WHERE id = '3fbc8bef-6814-4548-b448-0883b201e56d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი ნივთებს უკვე მხოლოდ კი არ აგროვებს, არამედ ფერის მიხედვით დაჯგუფებასაც ცდილობს. მიეცით მას ორი სხვადასხვა ფერის ჭურჭელი და აჩვენეთ, როგორ მოათავსოს შესაბამის ჭურჭელში იმავე ფერის სათამაშოები. ეს თამაში სწრაფად ავითარებს მის ვიზუალურ აღქმასა და ლოგიკურ აზროვნებას. ყოველი სწორი არჩევანისას შეაქეთ და წაახალისეთ.') WHERE id = 'be0ade15-5544-47ec-9b0f-c9482045c9e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „უკან გადადგმული ნაბიჯი“. ბავშვმა უკვე აღმოაჩინა უკან სიარული. ეს წონასწორობის რთული ვარჯიშია და აჩვენებს, რამდენად კარგად აქვს განვითარებული სხეულის კოორდინაცია. შეუქმენით პირობები, რომ ეს ახალი უნარი დაბრკოლებებისგან თავისუფალ და რბილ ზედაპირზე გამოსცადოს. სხეულის მართვის უნარის გაუმჯობესებასთან ერთად მისი თავდაჯერებულობაც იზრდება.') WHERE id = '4090fd14-b660-4e63-9f79-fd22a575576f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „კითხვა და ცნობისმოყვარეობა“. ბავშვი უკვე მიუთითებს საგნებზე და ამბობს: „ეს რა არის?“ (ან მსგავს ბგერებს თავის ენაზე). თქვენ მოთმინებით დაასახელეთ ყველაფერი: „ეს წითელი მანქანაა“, „ეს დიდი ხეა“. თუ მის ცნობისმოყვარეობას უპასუხოდ არ დატოვებთ, ეს ხელს შეუწყობს როგორც პასიური, ისე აქტიური ლექსიკური მარაგის გამდიდრებას.') WHERE id = '4d85c160-6a89-4bf6-8f45-da46fe9e61c0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „ხუმრობები“. ბავშვი განზრახ გაწვდით სათამაშოს, შემდეგ კი მაშინვე უკან მიაქვს და ამაზე იცინის? ეს მიუთითებს, რომ მას იუმორის გრძნობა და სოციალური ურთიერთქმედების უნარი უვითარდება. ენთუზიაზმით აჰყევით მის ამ „თამაშს“. ერთად სიცილი აძლიერებს თქვენს შორის ემოციურ კავშირს და ბავშვს ჯანსაღ თავდაჯერებულობას უყალიბებს.') WHERE id = '843dc844-89cf-4311-8b84-968a8aaa47d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „პირამიდა და რგოლები“. ბავშვი უკვე უფრო ოსტატურად აწყობს რგოლებს დიდიდან პატარისკენ (ან პირიქით). ეს მოქმედება უვითარებს როგორც ზომის აღქმას (დიდი-პატარა), ისე ხელისა და თვალის კოორდინაციას. რგოლების აწყობისას მათი ფერებიც ხმამაღლა დაასახელეთ.') WHERE id = 'da06e49e-5a35-41bf-9d03-b1f30db1e3f3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვსვამ“. ბავშვი უკვე თითქმის ახერხებს ღია ჭიქიდან წყლის დალევას ისე, რომ პრაქტიკულად არ იღვრება. მიეცით მას ბავშვის ზომის, მყარი და მძიმე ძირის მქონე პლასტმასის ჭიქა. წყლის დამოუკიდებლად დალევა მის ტუჩისა და ენის კუნთებს მეტყველებისთვის ამზადებს და დამოუკიდებლობის განცდას უძლიერებს.') WHERE id = '7672591f-bef4-411a-94a3-365d4ae118a3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: თამაში „საჭმლის მომზადება“. ბავშვს შეუძლია სათამაშო ჭურჭლით თავი ისე მოაჩვენოს, თითქოს რაღაცას „ამზადებს“. ჩაერთეთ მასთან ერთად ასეთ თამაშებში: „მეც მომცემ ცოტა საჭმელს?“. ეს აჩვენებს, რამდენად დაკვირვებით აკვირდება ის ყოველდღიურ რიტუალებს და როგორ ვითარდება მისი წარმოსახვა.') WHERE id = '54cd9ab8-e1d5-4a0e-ab3a-58d28bf66df0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: ბავშვი უკვე ცდილობს დაბალ საფეხურებზე ან დივნის კიდეზე დამოუკიდებლად აძრომას. მიუხედავად იმისა, რომ სიმაღლის აღქმა უვითარდება, რისკებს ჯერ სრულად ვერ აცნობიერებს. ყოველთვის ახლოს იყავით, დაიცავით ის და უსაფრთხოდ ჩამოსვლის გზები (მაგალითად, უკუსვლით) აჩვენეთ.') WHERE id = 'b93116ed-f9b5-4701-8c1f-2fc127b8352c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ცხოველებისა და მათი ხმების გარჩევა“. ბავშვი სურათზე ნანახ ძროხასა და კატას უკვე ერთმანეთისგან არჩევს და მათი ხმების მიბაძვა შეკითხვის გარეშეც შეუძლია. თუ წიგნის კითხვისას ჰკითხავთ: „სად არის აქ კატა?“ და ის თითით მიგითითებთ, ეს მისი ვიზუალური მეხსიერების გაძლიერებაზე მეტყველებს.') WHERE id = 'dcd3b6fa-3aa2-4a2f-98c6-4125a36e33d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები და „არა“. როდესაც ბავშვს ყველაფრის დამოუკიდებლად გაკეთება სურს და არ გამოსდის, შეიძლება უეცრად გაბრაზდეს. ასეთ დროს შეგიძლიათ ჩაეხუტოთ და მშვიდად უთხრათ: „გაბრაზდი, რადგან ფეხსაცმლის ჩაცმა ვერ შეძელი, მესმის შენი“, რითაც მის ემოციას სახელს დაარქმევთ. თქვენი სიმშვიდე მისთვის საუკეთესო მაგალითია, რომელიც საკუთარი ემოციების მართვას ასწავლის.') WHERE id = '352efc53-2735-4313-8ef5-1cd93238bca8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-18 თვისკენ, ანუ წელიწად-ნახევრისკენ, პირველ ნაბიჯს ვდგამთ! ბავშვი სირბილისას უკვე უკეთ ინარჩუნებს წონასწორობას და სურვილისამებრ გაჩერებაც შეუძლია. ეს როგორც ფიზიკური ძალის, ისე ტვინისა და კუნთების კოორდინაციის მნიშვნელოვანი განვითარებაა. პარკში ან ეზოში მისთვის დაბრკოლებებისგან თავისუფალი სივრცე მოძებნეთ, რათა სირბილით ენერგია ჯანსაღად დახარჯოს.') WHERE id = '20741f1b-1447-4efb-94f4-6f3a4844a16e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სიტყვათა შეთანხმებების“ განვითარება ჩქარდება. ბავშვი უკვე ორ სიტყვას აერთიანებს და უფრო რთულ სურვილებს გამოხატავს: „მამა, მოდი“, „მომეცი ვაშლი“, „ბურთი სადაა?“. თუ ის სიტყვებს ჯერ არ აერთიანებს, ნუ ინერვიულებთ; მის მიერ ნათქვამ ცალკეულ სიტყვებს წინადადებად აქციეთ და ისე უპასუხეთ: „ჰო, ბურთი გინდა? აი, შენი წითელი ბურთი“.') WHERE id = '81c4a684-a911-49c4-a9d7-1699f6fa7902';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილი მოტორიკის განვითარების „ფაზლების“ პერიოდი. ბავშვი უკვე სწავლობს მარტივი, 2-3-ნაწილიანი ფაზლების აწყობას ან გეომეტრიული ფიგურების შესაბამის ღიობებში მოთავსებას. ეს თამაში მნიშვნელოვნად ავითარებს როგორც მის ვიზუალურ აღქმას, ისე პრობლემების გადაჭრის უნარს. თუ არ გამოუვა, მშვიდად მიეცით მინიშნება და გაამხნევეთ.') WHERE id = 'f29daf62-95a9-439b-9639-5474aad5c6b0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში ჯერ კიდევ დომინირებს „პარალელური თამაში“. სხვა ბავშვებთან ყოფნისას თქვენი ბავშვი მათთან ერთად კი არა, მათ გვერდით, თავისთვის თამაშობს. ეს 18 თვემდე ასაკის ბავშვებისთვის სრულიად ნორმალურია. ის სხვა ბავშვებზე დაკვირვებით ბევრ რამეს სწავლობს. განაგრძეთ მისი თანატოლებთან მიყვანა, რათა სოციალურ გარემოს შეეგუოს.') WHERE id = 'b30c9be9-ec87-4316-9f1a-0e4dee84bd75';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვიბან“. ბანაობისას ან ხელების დაბანისას ბავშვი ცდილობს, საპონი ან ღრუბელი აიღოს, ტანი გაიწმინდოს და თქვენ მოგბაძოთ. ხელი შეუწყვეთ მის ინტერესს ჰიგიენური ჩვევების მიმართ. საკუთარი თავის „დაბანა“ მას ეხმარება, უკეთ გაიცნოს სხეულის ნაწილები და განივითაროს დამოუკიდებლობის განცდა.') WHERE id = '4e8730af-51d2-460d-ac2a-1e5c1f18dbf2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეხსიერების გაძლიერება: „სივრცითი მეხსიერება“. თქვენ მიერ დამალული სათამაშოს საპოვნელად ბავშვი რთულ ხერხებს იყენებს – სწევს გადასაფარებელს, იყურება ყუთში და ბალიშის ქვეშაც კი ყოფს ხელს. ეს მიუთითებს, რომ მას „ობიექტის მუდმივობის“ ცნება უკვე სრულად აქვს გააზრებული. სახლში მასთან ერთად ითამაშეთ პატარა „განძის ძიების“ თამაშები, რათა ყურადღება განუვითაროთ.') WHERE id = '88dfd514-9103-49dd-80b3-7233dd30fb8c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვა და „საოჯახო საქმეები“. ბავშვი სათამაშო ტელეფონით „საუბრობს“ ან სათამაშო ცოცხით იატაკს გვის. ის თქვენს თითოეულ ყოველდღიურ მოქმედებას იმეორებს. ასეთი მიბაძვა მისთვის სამყაროს შეცნობის საშუალებაა. მიეცით საკუთარი პატარა „სამუშაო ხელსაწყოები“, რათა თავი მნიშვნელოვნად იგრძნოს.') WHERE id = '86806a6e-92ce-48bc-8348-5f82c21f79d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: „ცოცვის ოსტატობა“. ბავშვს უკვე ძალიან მოსწონს კიბეზე დამოუკიდებლად ასვლა (ჯერჯერობით თქვენი ხელის დახმარებით ან ოთხზე ცოცვით). სიმაღლის აღქმის განვითარებასთან ერთად, მას ჩამოსვლაც უნდა ასწავლოთ. აჩვენეთ, რომ კიბეზე ზურგით ჩამოსვლა ყოველთვის უფრო უსაფრთხოა, და დასაზღვევად მუდამ მის სიახლოვეს იყავით.') WHERE id = 'bdb8a9e0-fbd7-4c99-b8e8-bdcb234283e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ცხოველებისა და მათი ხმების გარჩევა“. ბავშვი სურათზე ნანახ ძროხასა და კატას უკვე კარგად არჩევს ერთმანეთისგან და მათი ხმების მიბაძვაც შეკითხვის გარეშე შეუძლია. როდესაც წიგნის კითხვისას ეკითხებით: „აბა, სად არის აქ კატა?“ და ის თითით გიჩვენებთ, ეს იმაზე მეტყველებს, თუ რამდენად გაუძლიერდა ვიზუალური მეხსიერება და ყურადღება.') WHERE id = 'c66b2427-57b0-459e-a0a3-0cf6bedf7007';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები და „არა“. როდესაც ბავშვს ყველაფრის დამოუკიდებლად გაკეთება სურს და არ გამოსდის, შეიძლება უეცრად გაბრაზდეს. ასეთ დროს ჩაეხუტეთ და მშვიდად უთხარით: „გაბრაზდი, რადგან კუბიკები წაიქცა, მესმის შენი“ — ასე მის ემოციას სახელს დაარქმევთ. თქვენი ასეთი თანაგრძნობა მას ემოციების მართვასა და სირთულეების წინაშე სულის არდაკარგვას ასწავლის.') WHERE id = 'a52afb36-cf2f-4e94-8f57-7e002290fbaf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ცდილობს, საგნები ფერის მიხედვით დააჯგუფოს. მიეცით ორი სხვადასხვა ფერის ჭურჭელი და აჩვენეთ, როგორ მოათავსოს იმავე ფერის სათამაშოები შესაბამის ჭურჭელში. ეს თამაში სწრაფად ავითარებს მის ვიზუალურ აღქმასა და ლოგიკურ აზროვნებას. ყოველი სწორი არჩევანისას შეაქეთ და გაამხნევეთ, რათა სწავლისადმი ინტერესი გაუძლიერდეს.') WHERE id = '59526637-405e-4f57-afc2-14b281d0bec6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „უკან გადადგმული ნაბიჯი“. ბავშვმა უკვე აღმოაჩინა უკან-უკან სიარული. ეს წონასწორობის რთული ვარჯიშია და აჩვენებს, რამდენად განვითარებულია მისი სხეულის კოორდინაცია. შეუქმენით პირობები, რომ ეს ახალი უნარი დაბრკოლებებისგან თავისუფალ და რბილ ზედაპირზე მოსინჯოს. სხეულის მართვის უნარის გაუმჯობესებასთან ერთად მისი თავდაჯერებულობაც გაძლიერდება.') WHERE id = '75475781-7679-4745-947b-4230a1dabd3f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვა და ცნობისმოყვარეობა“. ბავშვი უკვე მიუთითებს საგნებზე და ამბობს: „ეს რა არის?“ (ან თავის ენაზე მსგავს ბგერებს წარმოთქვამს). თქვენ მოთმინებით დაარქვით ყველაფერს სახელი: „ეს წითელი მანქანაა“, „ეს დიდი ხეა“. თუ მის ცნობისმოყვარეობას უპასუხოდ არ დატოვებთ, ეს მისი როგორც პასიური, ისე აქტიური ლექსიკური მარაგის გამდიდრებას შეუწყობს ხელს.') WHERE id = '428ddabc-76ae-4dd9-8955-566bc3b0021c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ხუმრობები“. ბავშვი განზრახ გაწვდით სათამაშოს, შემდეგ კი მაშინვე უკან მიაქვს და იცინის? ეს მიუთითებს, რომ მას იუმორის გრძნობა და სოციალური ურთიერთქმედების უნარი უყალიბდება. ენთუზიაზმით აჰყევით მის ამ „თამაშს“. ერთად სიცილი თქვენს შორის ემოციურ კავშირს აძლიერებს და ბავშვს ჯანსაღ თავდაჯერებულობას უყალიბებს.') WHERE id = '6f7f5c96-a971-4edb-9629-1420d3e51d5d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკა: „პირამიდა და რგოლები“. ბავშვი უკვე უფრო ოსტატურად აწყობს რგოლებს დიდიდან პატარისკენ (ან პირიქით). ეს მოქმედება უვითარებს როგორც ზომის აღქმას (დიდი–პატარა), ისე ხელისა და თვალის კოორდინაციას. რგოლების აწყობისას მათი ფერებიც დაასახელეთ.') WHERE id = '90eaad7f-688e-4fd5-ac4b-58ae26fd12fd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვსვამ“. ბავშვი უკვე თითქმის ახერხებს ღია ჭიქიდან წყლის დალევას ისე, რომ პრაქტიკულად არ დაღვაროს. მიეცით ბავშვის ზომის, გადაყირავებისადმი მდგრადი (მძიმე ძირიანი) პლასტმასის ჭიქა. დამოუკიდებლად წყლის სმა მის ტუჩებისა და ენის კუნთებს მეტყველებისთვის ამზადებს და დამოუკიდებლობის განცდას უძლიერებს.') WHERE id = 'ee6a42af-cce1-4d37-af51-df5adf60a403';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: თამაში „საჭმლის მომზადება“. ბავშვმა შეიძლება სათამაშო ჭურჭლით თავი მოაჩვენოს, თითქოს რაღაცას „ამზადებს“. ჩაერთეთ მის თამაშში: „მეც მომცემ ცოტა საჭმელს?“. ეს აჩვენებს, რამდენად დაკვირვებით აკვირდება ის ყოველდღიურ საქმიანობას და როგორ ვითარდება მისი წარმოსახვა.') WHERE id = 'f1803978-8c6d-4ba6-919b-9d07f71e4f23';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: ბავშვი უკვე ცდილობს დამოუკიდებლად აძვრეს დაბალ საფეხურებზე ან დივნის კიდეზე. მიუხედავად იმისა, რომ სიმაღლის აღქმა უვითარდება, რისკებს ჯერ სრულად ვერ აცნობიერებს. ყოველთვის ახლოს იყავით, რომ დაიცვათ, და უსაფრთხოდ ჩამოსვლის გზები (მაგალითად, ზურგით ჩამოსვლა) აჩვენეთ.') WHERE id = '992522f4-e329-4100-a785-ed11e118cc9d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველება: „ცხოველებისა და მათი ხმების გარჩევა“. ბავშვი უკვე ერთმანეთისგან არჩევს სურათზე გამოსახულ ძროხასა და კატას და შეუძლია მათი ხმების დაუკითხავად გამოცემა. თუ წიგნის კითხვისას ჰკითხავთ: „სად არის აქ კატა?“ და თითით მიგითითებთ, ეს მისი ვიზუალური მეხსიერების გაძლიერებაზე მიუთითებს.') WHERE id = 'a6dfa03f-81ed-42c6-9520-9c6097e0b191';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები და „არა“. როცა ბავშვს ყველაფრის დამოუკიდებლად გაკეთება სურს და არ გამოსდის, შეიძლება მოულოდნელად გაბრაზდეს. ასეთ დროს ჩაეხუტეთ და მშვიდად უთხარით: „გაბრაზდი, რადგან ფეხსაცმლის ჩაცმა ვერ შეძელი. მესმის შენი“, — ამგვარად მის ემოციას სახელს დაარქმევთ. თქვენი სიმშვიდე მისთვის საუკეთესო მაგალითია, რომელიც ემოციების მართვას ასწავლის.') WHERE id = 'fe5d769a-36f6-497a-abae-90604ca433b9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: „დიალოგი სათამაშოებთან“. ბავშვი უკვე „ესაუბრება“ თოჯინას ან დათუნიას, „აძინებს“ ან „სინჯავს“ მათ. ეს მისი ემოციური ინტელექტისა და ყოველდღიური რიტუალების სიღრმისეულად ათვისების მაჩვენებელია. შეუერთდით მას ამ როლურ თამაშებში.') WHERE id = '966e6ab8-7afb-4514-ac61-ac17ed1b3363';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური განვითარება: „ბურთის დარტყმა ფეხით“. ბავშვი უკვე ცდილობს, ფეხზე მდგარმა ისე დაარტყას ბურთს, რომ წონასწორობა არ დაკარგოს. ეს რთული კოორდინაციის მომთხოვნი მოძრაობაა. ეთამაშეთ მას მსუბუქი ბურთით სახლში ან ეზოში. სთხოვეთ, ბურთი თქვენკენ გამოაგოროს, რათა ორმხრივი თამაშის უნარიც განუვითარდეს.') WHERE id = '074c6e28-5574-4dba-9c17-b0a8532eb39d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რატომ?“ ეტაპის წინაპირობები. ბავშვი ყველაფერზე თითით მიგანიშნებთ, ამბობს „ეს?“ და თქვენს განმარტებას ელოდება. მარტივი წინადადებებით აუხსენით თითოეული ნივთის სახელი და დანიშნულება. თქვენი განმარტებები მის გონებაში სამყაროს რუკას ქმნის. ყოველთვის შეუნარჩუნეთ ცნობისმოყვარეობა.') WHERE id = '8bf76af3-3dd5-49ef-bbdd-da6f06260256';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 550 დღე შესრულდა! თქვენი ბავშვი უკვე ოფიციალურად 1.5 წლისაა. ეს ბავშვის განვითარების ერთ-ერთი ყველაზე მნიშვნელოვანი და საინტერესო პერიოდია. მას უკვე სრულად ესმის მარტივი მითითებები, მკაფიოდ გამოხატავს ემოციებს და პატარა „მკვლევარია“, რომელიც მზადაა სამყაროს აღმოსაჩენად. აღნიშნეთ ეს დღე მასთან ერთად მისი საყვარელი თამაშით!') WHERE id = 'f706bcc8-1266-48d0-82ad-7920a5e14e37';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-19 თვეში! თქვენი ბავშვი უკვე სრულად ცნობს საკუთარ თავს სარკეში და ანარეკლს „სხვა ბავშვად“ კი არა, საკუთარ თავად აღიქვამს. ეს მნიშვნელოვანი ნაბიჯია მისი თვითცნობიერების (self-awareness) განვითარებაში. დადექით მასთან ერთად სარკის წინ და განაგრძეთ სხეულის ნაწილების უფრო სიღრმისეულად სწავლება სიტყვებით: „ნახე, ეს შენი თვალებია, ეს კი დედას თვალებია“.') WHERE id = '696f3d72-602f-4dc5-8009-bf57000cd9a2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „გვერდითი ნაბიჯი“. ბავშვს უკვე შეუძლია არა მხოლოდ წინ და უკან, არამედ გვერდულადაც (crab walk) სიარული. ეს წონასწორობისა და კოორდინაციის რთული ვარჯიშია. მუსიკის ფონზე აჩვენეთ, როგორ იმოძრაოს სხვადასხვა მიმართულებით. ეს ერთდროულად სახალისო ცეკვაცაა და ფეხის კუნთების სხვადასხვა ჯგუფსაც აძლიერებს.') WHERE id = '29558e25-5ccf-4193-9fb7-c0eb732293d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ცდილობს, ადგილზე იხტუნაოს. შესაძლოა, ჯერ ორივე ფეხს ერთდროულად ვერ სწყვეტდეს იატაკს, მაგრამ მუხლების მოხრა და ზამბარასავით მოძრაობა მისი მსხვილი მოტორიკის განვითარების ნიშანია. მასთან ერთად რიტმულ მუსიკაზე იცეკვეთ. ეს არა მხოლოდ სახალისო, არამედ ძალიან სასარგებლო ფიზიკური ვარჯიშია, რომელიც ფეხის კუნთებს აძლიერებს.') WHERE id = '11679c4b-f0ae-4e4b-8e36-e62ed51385bb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში სიტყვა „ჩემის“ აღმოჩენა. ბავშვი უკვე ცნობს საკუთარ ნივთებს და ცდილობს, დაიცვას ისინი სიტყვით „ჩემია“ (ან თავის ენაზე გამოხატული რაიმე ნიშნით). ეს ეგოიზმი კი არა, საკუთარი პირადი საზღვრების გაცნობიერებაა. მიეცით მას შესაძლებლობა, თავად იზრუნოს საკუთარ ნივთებზე — ეს უყალიბებს თავდაჯერებასა და საკუთრების ცნებას.') WHERE id = '76f2d8e6-3dab-4534-8a50-e8454558158c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დახარისხება და ლოგიკა“ წვრილ მოტორიკაში. ბავშვი უკვე იწყებს ნივთების გარჩევას არა მხოლოდ ფერის, არამედ ზომის მიხედვითაც (დიდი–პატარა). მიეცით სხვადასხვა ზომის ჭურჭელი და სთხოვეთ, ერთმანეთში ჩააწყოს. ეს მისი მომავალი მათემატიკური აზროვნების ერთ-ერთი ყველაზე ადრეული საფუძველია.') WHERE id = 'c34d1f9d-7805-4ebe-a5ef-2eba5d6e613a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლობა: „მე თვითონ ვიცვამ“. ბავშვი უკვე ცდილობს, შარვალი ზემოთ აიწიოს, წინდები გაიხადოს ან ადვილად ჩასაცმელი ფეხსაცმელი ჩაიცვას. ხელს ნუ შეუშლით და ნუ დააჩქარებთ. იმის დანახვა, რომ რაღაც თავად შეძლო, მისთვის ყველაზე დიდი ჯილდოა. ყოველთვის შეაქეთ მცირე წარმატებებისთვისაც.') WHERE id = 'e8325a98-332b-4719-b50a-32bc427f8a46';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„რიგის დაცვა“ სოციალურ ქცევაში. ბავშვი უკვე ხვდება, რომ სათამაშოთი სათამაშოდ ცოტა ხანს უნდა მოიცადოს. თამაშებით — „ახლა ჩემი ჯერია, შემდეგ კი შენი“ — ასწავლეთ მოთმინება. ეს ერთ-ერთი უმნიშვნელოვანესი უნარია საბავშვო ბაღთან ან სხვა სოციალურ გარემოსთან ადაპტაციისთვის.') WHERE id = 'fb3f5f38-3ad4-4db7-9933-796ef621c2db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„კოვზის დამოუკიდებლად გამოყენების ოსტატობა“ კვებისას. ბავშვი უკვე სწავლობს, კოვზზე საკვები მოათავსოს და პირთან ისე მიიტანოს, რომ თითქმის არ დაღვაროს. მისთვის უფრო ადვილია ვარჯიში იოგურტის ან პიურეს მსგავსი სქელი საკვებით. ნუ შეგაშინებთ მაგიდის დასვრა; დამოუკიდებლად ჭამა მას უვითარებს როგორც ხელისა და თვალის კოორდინაციას, ისე დანაყრების შეგრძნებას.') WHERE id = 'eb358b29-c8ba-43ce-9ec4-901370abee63';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მითითებების შესრულება“: ბავშვს უკვე შეუძლია ზედიზედ ორი მოქმედებისგან შემდგარი დავალებების გაგება. მაგალითად: „აიღე ბურთი და ყუთში ჩადე“. ეს ავითარებს როგორც მის მეტყველების აღქმას, ისე მუშა მეხსიერებას. მიეცით ასეთი მარტივი, ორსაფეხურიანი „დავალებები“, რათა ყურადღება ავარჯიშოს.') WHERE id = 'b9afb514-aca9-4563-b096-907e76f4594a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „წიგნების სიყვარული“. ბავშვი უკვე ცდილობს, თხელი ქაღალდის ფურცლები დაუხევლად გადაფურცლოს (თქვენი მეთვალყურეობით). მას შეიძლება საყვარელი ზღაპრების მრავალჯერ მოსმენა მოუნდეს. ყოველი წაკითხვისას სურათზე სხვადასხვა დეტალზე მიუთითეთ: „შეხედე, აქ პატარა პეპელაც არის“. ეს აუმჯობესებს როგორც მის ვიზუალურ ყურადღებას, ისე მოთმინებას.') WHERE id = 'dd8c337a-acae-4f9f-a64d-1a2e2dbf15fb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი ჰიგიენა“. ბავშვი უკვე ცდილობს ხელების გამშრალებას, სახის მოწმენდას ან ღრუბლით დამოუკიდებლად „დაბანას“. წაახალისეთ მისი ინტერესი ჰიგიენური ჩვევების მიმართ. მიეცით საკუთარი პატარა პირსახოცი. საკუთარ თავზე ზრუნვის განცდა აყალიბებს მის თავდაჯერებულობასა და საკუთარი სხეულისადმი პატივისცემას.') WHERE id = '31f5c493-87d9-45d8-950b-ce108414919b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „სიმბოლური გაზიარება“. ბავშვმა შეიძლება უკვე „შემოგთავაზოთ“ თავისი სათამაშოს ნაწილი ან საკვების ერთი ლუკმა. მაშინაც კი, თუ სინამდვილეში არ მოგცემთ, ეს ჟესტი გაზიარების ცნების საფუძველია. ასეთი საქციელისთვის აუცილებლად შეაქეთ და უთხარით: „დიდი მადლობა, ძალიან კეთილი ხარ“.') WHERE id = '10acade6-6a92-4cf8-b728-f33648cdd314';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „გეომეტრიული ფიგურები“. ბავშვი უკვე იწყებს წრის, კვადრატისა და სამკუთხედის ერთმანეთისგან გარჩევას (ფაზლებში ან ფიგურების ჩასასმელ სათამაშოებში). უთხარით ამ ფიგურების სახელები. მართალია, ჯერ თავად ვერ ასახელებს, მაგრამ მათი ვიზუალურად ერთმანეთისგან გარჩევა გეომეტრიული აზროვნების საფუძველია.') WHERE id = '36dfa91f-6b4c-45f4-8057-bfc8dec4de87';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გაბედულება: „დაბლა გადახტომა“. ბავშვმა შეიძლება უკვე სცადოს დაბალი საფეხურიდან (სულ რამდენიმე სანტიმეტრის სიმაღლიდან) მიწაზე გადახტომა. ხელი ჩაჰკიდეთ და დაეხმარეთ. ეს მოძრაობა არა მხოლოდ მის კოჭებს აძლიერებს, არამედ სიმაღლისა და მანძილის პრაქტიკულად აღქმასაც ასწავლის.') WHERE id = '20c66b93-4f9a-4106-b0f1-86263f239cfe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებაში „არჩევითობა“ და „კონტროლი“. ზოგჯერ ბავშვმა შეიძლება ჭამაზე უარი მხოლოდ იმიტომ თქვას, რომ „კონტროლი მის ხელში იყოს“. ნუ აიძულებთ ჭამას. ამის ნაცვლად, სუფრაზე ორი ჯანსაღი არჩევანი შესთავაზეთ: „ბროკოლი გინდა თუ სტაფილო?“. არჩევანის შესაძლებლობა მის წინააღმდეგობას ამცირებს და აგრძნობინებს, რომ მის გადაწყვეტილებებს პატივს სცემენ.') WHERE id = '597fce8a-7564-428a-aa97-6b8b166f2f7c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცის აღქმა“ და „სიმაღლე“. ბავშვს უკვე უკეთ ესმის, რომ სიმაღლე შეიძლება სახიფათო იყოს და დაბალი ადგილებიდან ჩამოსვლისას სიფრთხილეს იჩენს. შეახსენეთ, რომ დივნიდან ან საფეხურიდან ზურგით ჩამოვიდეს. ეს მნიშვნელოვანია, რათა მან საკუთარი სხეულის უსაფრთხოების წესები აითვისოს.') WHERE id = '42d59296-b192-45dd-b455-11502c8aeaec';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „მიბაძვა“ უკვე ემოციებზეც ვრცელდება. როცა თქვენ იცინით, ისიც იცინის, ხოლო როცა სერიოზული ხართ, ისიც ჩუმდება. თქვენ ბავშვის ემოციური სარკე ხართ. მასთან თამაშისას სახის სხვადასხვა გამომეტყველება აჩვენეთ და სთხოვეთ, გაიმეოროს. ეს ხელს უწყობს მისი ემოციური ინტელექტისა და სხვების გაგების უნარის განვითარებას.') WHERE id = 'c03e79b5-c416-4e9a-8cda-23ab824d2ea7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად დალაგების“ ჩვევა: ბავშვმა შეიძლება სათამაშოების ყუთში ჩალაგება უკვე „მოვალეობად“ აღიქვას. თამაშის დასრულების შემდეგ წაახალისეთ და უთხარით: „მოდი, მანქანები თავიანთ სახლში დავაბრუნოთ“. ეს მასში აყალიბებს როგორც წესრიგის ჩვევას, ისე დაწყებული საქმის დასრულების პასუხისმგებლობას. ყოველთვის დაეხმარეთ და შეაქეთ.') WHERE id = '4be37208-93a9-4898-b72a-811ae2d7a051';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „კითხვა-პასუხის“ დიალოგი რთულდება. კითხვას „ეს რა არის?“ ის უკვე არა მხოლოდ იმიტომ სვამს, რომ პასუხი არ იცის, არამედ თქვენთან ურთიერთობის გასაგრძელებლადაც. პასუხისას წინადადება ოდნავ გააფართოეთ: „ეს წითელი ვაშლია, შენ ის გიყვარს“. ეს ბავშვის ლექსიკურ მარაგს სწრაფად ამდიდრებს.') WHERE id = '59968193-d8d9-46a6-bcc6-77f1e1c44a81';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმის ოსტატობა“. ბავშვს უკვე შეუძლია სირბილისას წინ მდებარე ბურთს ფეხი დაარტყას. ამისთვის საჭიროა მოძრაობისა და წონასწორობის ერთდროულად მართვა. მასთან სახლში ან ეზოში „ფეხბურთის“ თამაშით ეს დინამიკური წონასწორობის უნარი განუმტკიცეთ. თქვენთან ერთად მოძრაობა მისთვის ყველაზე დიდი გართობაა.') WHERE id = '591884a7-b1fd-4edf-bb0d-3dca04af2ea4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ემოციების გამოხატვა“. ბავშვი უკვე განსაკუთრებული ბგერებით ან მარტივი სიტყვებით გამოხატავს, რომ შია, დაიღალა ან რაღაცის ეშინია. მისი ეს სიგნალები სიტყვებით დაადასტურეთ: „კი, შენ დაიღალე, მოდი, ცოტა დავისვენოთ“. ეს უდიდესი მხარდაჭერაა იმისთვის, რომ მომავალში მან საკუთარი ემოციების სიტყვებით მართვა შეძლოს.') WHERE id = '402a1eb2-6224-49f3-92d8-6ebdc1c68d75';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის გაძლიერება: „სათამაშოები ცოცხლდებიან“. ბავშვი უკვე სათამაშო მანქანებით რბოლას აწყობს ან თოჯინებს ერთმანეთთან „ალაპარაკებს“. ეს მის შემოქმედებითობასა და რთული აზროვნების უნარზე მიუთითებს. შეუერთდით ამ როლურ თამაშებს და სცენარი ოდნავ გააფართოეთ: „მანქანა საწვავის ჩასასხმელად მიდის?“.') WHERE id = '50b52b0c-f730-4500-a2ea-7d50f4678b25';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე „მე თვითონ!“ პერიოდის მწვერვალზეა. მას სურს, თავად გააღოს კარი, თავად დააჭიროს ღილაკს ან კიბეზე დამოუკიდებლად ავიდეს. ეს სიჯიუტე კი არა, საკუთარი შესაძლებლობების გამოცდაა. იქ, სადაც უსაფრთხოა, რამდენიმე წამით მეტი დრო მიეცით, რომ თავად სცადოს. იმის დანახვა, რომ რაღაც დამოუკიდებლად შეძლო, მისი თავდაჯერებულობის ჩამოყალიბების უმნიშვნელოვანესი ფაქტორია.') WHERE id = '0424ded1-f254-419a-bacc-912b20a6465b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „ბურთის მიზანში სროლა“. ბავშვი ბურთს უკვე უბრალოდ ძირს კი არ აგდებს, არამედ ცდილობს, კონკრეტული მიმართულებით ან თქვენკენ ისროლოს. ეს მხრის კუნთებისა და თვალისა და ხელის კოორდინაციის მნიშვნელოვან განვითარებაზე მიუთითებს. ითამაშეთ მასთან თამაში „ჩააგდე ბურთი კალათში“, რათა სიზუსტე განუვითარდეს.') WHERE id = 'd62bdbf3-d7fd-43c8-9cef-8ef0c95e0352';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ზედსართავი სახელების აღმოჩენა“. ბავშვი უკვე მხოლოდ საგნებს კი არ ასახელებს, არამედ მათ თვისებებსაც იგებს: „ცხელი“, „ცივი“, „დიდი“, „პატარა“. ჭამის ან ბანაობის დროს ხშირად გამოიყენეთ ეს სიტყვები: „ნახე, ეს წყალი თბილია“. ეს ეხმარება, სამყარო უფრო დეტალურად აღწეროს და აბსტრაქტული აზროვნება განივითაროს.') WHERE id = 'f549d4ea-b5e9-4a79-81eb-61a06771145c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „დალაგება და აცმა“. ბავშვმა შეიძლება უკვე სცადოს მძივების ძაფზე აცმა (დიდი ზომის მძივებით და ზედამხედველობის ქვეშ) ან გასაღების საკეტში ჩასმა. ეს მოქმედებები თითის კუნთების უაღრესად ზუსტ კოორდინაციას მოითხოვს. ასეთი ვარჯიშები მომავალში ფანქრის სწორად დაჭერისა და წერის უნარებისთვის მნიშვნელოვან საფუძველს ქმნის.') WHERE id = '499eb64f-17b7-4928-a28f-32d77bae69bd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე არა მხოლოდ არჩევს ფერებს ერთმანეთისგან, არამედ მათი სახელების წარმოთქმასაც ცდილობს. თუ თქვენი თხოვნისას — „ლურჯი მანქანა მომეცი“ — სწორ ფერს ირჩევს, ეს მისი ვიზუალური მეხსიერებისა და მეტყველების აღქმის მნიშვნელოვანი მიღწევაა. ხშირად გაუსვით ხაზი ფერებს მის ყოველდღიურ ტანსაცმელსა და სათამაშოებში, რათა ეს ცოდნა განმტკიცდეს.') WHERE id = '1ab53f62-49d6-486d-9a52-ff092cc01b9c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: ბავშვს უკვე უფრო მეტად სურს ადგილზე ახტომა (ორივე ფეხის ერთდროულად იატაკიდან აწევა). ეს ფეხის კუნთებისა და წონასწორობის შეგრძნების რთულ კოორდინაციას მოითხოვს. რბილ ხალიჩაზე მასთან ერთად ითამაშეთ თამაში „ვინ უფრო მეტჯერ ახტება“, რათა ენერგიის დახარჯვის საშუალება მისცეთ.') WHERE id = 'fac02d76-edc4-45d2-ac23-faa60bad4132';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სივრცის აღმნიშვნელი სიტყვები“. ბავშვს უკვე პრაქტიკულად ესმის ისეთი სიტყვების მნიშვნელობა, როგორებიცაა „ზემოდან“, „ქვემოდან“ და „შიგნით“. შეამოწმეთ ეს და უთხარით: „ბურთი სკამის ქვეშ დადე“. ასეთი დავალებები ავითარებს როგორც მის ენობრივ უნარებს, ისე სივრცეში ორიენტაციას. ამ ცნებების თამაშებში ჩართვით მის ლოგიკურ აზროვნებას გააძლიერებთ.') WHERE id = '30c8f80f-c5ad-42c7-a784-1930afcd9e96';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი“ და ნებისყოფა. ბავშვს უკვე მტკიცე აზრი აქვს იმის შესახებ, თუ რა ჩაიცვას ან რომელი ჭურჭლიდან ჭამოს. თუ არჩევანის საშუალებას მისცემთ და ჰკითხავთ: „დღეს ლურჯი ჭურჭლიდან გინდა ჭამა თუ მწვანიდან?“, ეს დაეხმარება, თავი დამოუკიდებელ პიროვნებად იგრძნოს და თავიდან აიცილოს უმიზეზო სიჯიუტე.') WHERE id = '6f9d4056-a417-4319-83b2-043809df814a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „დიზაინი და კონსტრუირება“. ბავშვს უკვე შეუძლია 6-8 კუბის (ბლოკის) ერთმანეთზე დალაგება და მაღალი კოშკის აშენება. ეს მოითხოვს როგორც ყურადღების კონცენტრაციას, ისე ხელის მოძრაობების სიზუსტეს. როდესაც კოშკი დაინგრევა, ამას მხიარულად შეხვდით, რათა ბავშვს წარუმატებლობის არ შეეშინდეს და ხელახლა ცდის სურვილი ჰქონდეს.') WHERE id = '17f5c5df-ea05-4d59-8a28-32ffc0cbb3e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „მზრუნველობა“. ბავშვს უკვე შეუძლია სათამაშო დათუნიას „აჭამოს“, „საწოლში ჩააწვინოს“ ან ტირილისას „დაამშვიდოს“. ეს სიმბოლური თამაშის განვითარების ნიშანია. სითბო და მზრუნველობა, რომელსაც თქვენ ბავშვის მიმართ იჩენთ, ახლა უკვე მის თამაშებშიც ვლინდება.') WHERE id = 'bc61e4f6-e294-4033-b040-474d57e5f13b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სიტყვათა შეთანხმებები“ სწრაფად ვითარდება. ბავშვს უკვე შეუძლია თავისი სურვილების ორი-სამი სიტყვით გამოხატვა: „მამა, ბურთი მომეცი“, „დედა, წყალი მინდა“. საუბრისას ყურადღებით მოუსმინეთ თითოეულ სიტყვას და თვალით კონტაქტი დაამყარეთ. პასუხისას მისი წინადადებები ოდნავ გააფართოეთ, რათა ბავშვის ლექსიკური მარაგი კიდევ უფრო გამდიდრდეს.') WHERE id = '4a36674f-0b66-41a0-beba-daa82b8d9f0b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკა: „ფაზლები და თავსატეხები“. ბავშვი უკვე უფრო სწრაფად აწყობს მარტივ, 3-4-ნაწილიან ფაზლებს ან შესაბამის ღიობებში ათავსებს სხვადასხვა ფორმას. ეს ავითარებს როგორც სივრცის აღქმას, ისე ვიზუალური ანალიზის უნარს. თუ დავალება რთული აღმოჩნდება, მიეცით მცირე მინიშნებები, რათა მოტივაცია არ დაკარგოს.') WHERE id = 'cce26ca5-c2df-4a63-a452-8753ade9a3fe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური ქცევა: „სიმბოლური გაზიარება“. ბავშვმა შეიძლება უკვე „შემოგთავაზოთ“ თავისი სათამაშო ან მისი ნაწილი (ან მაშინვე უკან წაიღოს). ეს გაზიარების ცნების ჩამოყალიბების პირველი ნიშნებია. აუცილებლად შეაქეთ ეს ჟესტი: „დიდი მადლობა, რომ შენი სათამაშო მაჩვენე“. ეს ბავშვს დადებითი სოციალური ჩვევების საფუძველს უყალიბებს.') WHERE id = '35b68ddd-9074-4a9a-97b7-0fddbf831df1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვალაგებ“. ბავშვი გბაძავთ და ცდილობს, ხელები გაიმშრალოს, სახე მოიწმინდოს ან მაგიდა სათამაშო ტილოთი გაწმინდოს. ნუ ჩაუკლავთ დამოუკიდებლობის ეს სურვილი. მიეცით საკუთარი პატარა პირსახოცი ან ჯაგრისი და ჩართეთ „საოჯახო საქმეებში“. ეს მას პასუხისმგებლობის გრძნობას უყალიბებს.') WHERE id = '37a69b03-aa17-4bad-982a-11091970591b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეხსიერება და „სივრცითი მეხსიერება“ განვითარების პიკზეა. ბავშვს უკვე შეუძლია რამდენიმე საათის შემდეგაც გაიხსენოს, სად დამალეთ სათამაშო. სახლში ერთად ითამაშეთ „განძის ძიება“. სათამაშო ბალიშის ქვეშ დადეთ და დააკვირდით, როგორ იპოვის. ეს თამაში დადებითად მოქმედებს როგორც ყურადღების კონცენტრაციაზე, ისე პრობლემების გადაჭრის უნარზე.') WHERE id = '105285fc-eb7a-4111-ad71-74ef8c1d89b9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: „დიალოგი სათამაშოებთან“. ბავშვი თოჯინას ან სათამაშო დათვს „ესაუბრება“, აჭმევს ან აძინებს. ეს ემოციური ინტელექტის განვითარებისა და ყოველდღიური რიტუალების ათვისების მაჩვენებელია. შეუერთდით ამ როლურ თამაშებს: „ახლა სად მიდის დათვი?“. ეს სწრაფად ავითარებს ბავშვის შემოქმედებით აზროვნებას.') WHERE id = '1d1a3072-a955-4f0c-b97e-45be9ab5c292';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებაში — „წყლის დამოუკიდებლად დალევა“. ბავშვს უკვე შეუძლია ღია ჭიქიდან წყალი თავდაჯერებულად დალიოს და თითქმის არ დაღვაროს. ეს იმის მაჩვენებელია, თუ რამდენად მზადაა მისი ტუჩებისა და ყბის კუნთები მეტყველებისთვის. კვლავ მიეცით ბავშვის ზომის, ხელში ადვილად დასაჭერი ჭიქები, რათა ეს უნარი სრულყოფილად აითვისოს.') WHERE id = 'f0007c08-4f82-470d-976e-b690d945c125';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახალი შიშები: ბავშვს შეიძლება მოულოდნელად შეეშინდეს სიბნელის, ძლიერი ხმების ან ნიღბიანი პერსონაჟების. ეს მისი წარმოსახვისა და გარემოს აღქმის განვითარებას უკავშირდება. ნუ დასცინებთ მის შიშს — უბრალოდ იყავით მის გვერდით, ჩაეხუტეთ და აგრძნობინეთ, რომ უსაფრთხოდაა. დროთა განმავლობაში ამ შიშებს ცნობისმოყვარეობა ჩაანაცვლებს.') WHERE id = 'c56b4f54-c6b4-4285-a227-6cdf7c49e75e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „პირველი რთული წინადადებები“. ბავშვს უკვე შეუძლია გამოიყენოს მარტივი წარსული დროის წინადადებები, როგორიცაა „მამა მოვიდა“ და „მე წყალი დავლიე“. გაიმეორეთ მისი ნათქვამი სწორი გრამატიკული ფორმით და ამგვარად წაახალისეთ მისი მცდელობები. თქვენი მეტყველება მისთვის მთავარი მაგალითია. ყოველთვის მკაფიოდ და გულწრფელად ესაუბრეთ.') WHERE id = 'ec0cb279-7627-42fd-8c4b-82e97e640420';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკუსვლით სიარულის ოსტატობა“. ბავშვს უკვე შეუძლია უკან მოუხედავად რამდენიმე ნაბიჯი გადადგას. ეს მნიშვნელოვანია სივრცეში საკუთარი სხეულის მდებარეობის შეგრძნებისთვის (პროპრიოცეპტული შეგრძნება). უთხარით: „მოდი, კიბორჩხალასავით ვიაროთ“ და ეს მოძრაობა თამაშად აქციეთ. თქვენთან ერთად მოძრაობა მისთვის მსოფლიოში ყველაზე დიდი გართობაა.') WHERE id = '891890ba-7797-463a-90b9-18dda87b2142';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-20 თვეში გადავდივართ! ბავშვს უკვე საკუთარი „გემოვნება“ უყალიბდება. მან შეიძლება ჯიუტად აირჩიოს ფეხსაცმელი, რომლის ჩაცმაც სურს, ან საკვები, რომლის ჭამაც უნდა. ეს მისი ნების გაძლიერების ნიშანია. მიეცით ორ უსაფრთხო ვარიანტს შორის არჩევანის გაკეთების შესაძლებლობა: „დღეს ვაშლს შეჭამ თუ მსხალს?“. ეს მას თავდაჯერებასაც მატებს და სიჯიუტით გამოწვეულ კრიზისებსაც ამცირებს.') WHERE id = '9857fafb-dba1-41f5-bd34-455d5b939f6f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ კოორდინაციაში — „დინამიკური წონასწორობა“. ბავშვს უკვე შეუძლია დაიხაროს, იატაკიდან რამე აიღოს და წაქცევის გარეშე კვლავ წამოდგეს. ეს მიუთითებს, რომ მისი წელისა და ფეხების კუნთები მნიშვნელოვნად გაძლიერდა. იატაკზე სხვადასხვა სიმაღლეზე დაუწყვეთ სათამაშოები და სთხოვეთ, ერთ ყუთში ჩააწყოს. ეს მოძრაობა სხეულის მართვის უნარს სრულყოფს.') WHERE id = '21286f36-7532-41d3-a58d-4d4ecfb6df25';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: „აცოცება და ჩამოსვლა“. ბავშვს უკვე შეუძლია კიბეზე უფრო სწრაფად, თითო საფეხურის გადადგმით ასვლა (თქვენი ხელის დახმარებით). სიმაღლის აღქმის განვითარებასთან ერთად, კვლავ და კვლავ აჩვენეთ მას ჩამოსვლის უსაფრთხო გზა (ზურგით ჩამოსვლა). დარწმუნდით, რომ დამცავი ბარიერები კვლავ ადგილზეა და დაკეტილია.') WHERE id = '3dfce46e-871b-4ff0-b52c-ef4021fb63e3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: ბავშვი უკვე რეაგირებს სიტყვაზე „არ შეიძლება“, თუმცა ზოგჯერ კვლავ არღვევს წესებს თქვენი რეაქციის შესამოწმებლად. ყველაზე მნიშვნელოვანია, სიმშვიდე შეინარჩუნოთ, მაგრამ მტკიცედ იდგეთ თქვენს პოზიციაზე. თუ რამეზე „არა“ თქვით, ყოველ ჯერზე იგივე თანმიმდევრულობით გაიმეორეთ. წესების უცვლელობა ბავშვს შინაგანი წესრიგისა და უსაფრთხოების განცდას უყალიბებს.') WHERE id = '3d5db953-53d5-41ac-96c7-0de1abf8d13a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე არა მხოლოდ არჩევს ფერებს, არამედ მათ შესაბამის საგნებთან დაკავშირებაც შეუძლია. თუ თქვენი თხოვნისას — „ლურჯი ბურთი ლურჯ ყუთში ჩადე“ — დავალებას სწორად ასრულებს, ეს მისი ვიზუალური აზროვნების დიდი მიღწევაა. ყოველდღიურ საუბარში ფერებზე აქცენტის მქონე ფრაზების გამოყენებით, მაგალითად, „წითელი ვაშლი“ ან „მწვანე ფოთოლი“, ეს ცოდნა განუმტკიცეთ.') WHERE id = '7bf7487b-3d3e-49a7-9bc5-a3a917c3fbbf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური აქტივობა: „ადგილზე ხტომა“. ბავშვი უკვე ცდილობს, ორივე ფეხი ერთდროულად მოსწყვიტოს იატაკს და ახტეს. ეს ფეხის კუნთების ძალასა და წონასწორობის შესანარჩუნებლად რთულ კოორდინაციას მოითხოვს. მასთან ერთად ითამაშეთ თამაში „კურდღელივით ვიხტუნაოთ“. ეს არა მხოლოდ სახალისოა, არამედ ფიზიკური განვითარებისთვისაც ძალიან სასარგებლოა.') WHERE id = '37a6e358-9a9e-40cc-aab7-74b540fd0681';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ზედსართავი სახელების მატება“. ბავშვს უკვე ესმის არა მხოლოდ საგნების სახელები, არამედ მათი თვისებებიც (ცხელი, ცივი, დიდი, პატარა, რბილი, მაგარი). ჭამის დროს უთხარით: „ეს პიურე ცხელია“, სათამაშოს შეხებისას კი — „ეს დათუნია რბილია“, რათა მისი შეგრძნებების აღმწერი ლექსიკა გაამდიდროთ. ეს დაეხმარება მას, სამყარო უფრო დეტალურად აღწეროს.') WHERE id = 'e5f3d411-7714-4b52-b440-c00913f921c9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „ფანქრის დაჭერის“ უნარი უმჯობესდება. ბავშვი უკვე ცდილობს, ფანქარი არა მთელი ხელისგულით, არამედ თითებთან უფრო ახლოს დაიჭიროს. ქაღალდზე უფრო გამოკვეთილ წრეებს ან ქაოსურ, მაგრამ მკვეთრ ხაზებს ავლებს. მიეცით ფერადი ფანქრები და დიდი ზომის ქაღალდი, რათა მისი „შემოქმედებისთვის“ მეტი სივრცე შექმნათ.') WHERE id = '286d8a77-5c51-4a8f-96ae-733178c15fb0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლობა: „მე თვითონ ვიცვამ“. ბავშვი უკვე უფრო დაჟინებით ცდილობს, თავად გაიხადოს წინდა, დაიხუროს ქუდი ან ჩაიცვას ადვილად ჩასაცმელი ფეხსაცმელი. ამ პროცესისთვის მას რამდენიმე დამატებითი წუთი დაუთმეთ. თუ არ დააჩქარებთ და მისცემთ შესაძლებლობას, თავად გაართვას თავი, ეს მის თავდაჯერებულობასა და დამოუკიდებლობის განცდას განავითარებს.') WHERE id = '947a00f0-f695-4c17-b833-1f7ad19529e3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური ქცევა: „რიგის დაცვა“. ბავშვს უკვე ესმის, რომ პარკში საქანელაზე დასაჯდომად ან სათამაშოთი სათამაშოდ ცოტა ხნით მოცდაა საჭირო. თამაშებით — „ახლა ჩემი ჯერია, შემდეგ კი შენი“ — მას მოთმინება ასწავლეთ. ეს უნარი მომავალში საბავშვო ბაღისა და სკოლის გარემოსთან ადაპტაციისთვის ერთ-ერთი უმნიშვნელოვანესი სოციალური საფუძველია.') WHERE id = 'f555abb8-3ed3-4f14-968a-d2f98f543e71';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვება: „ჩანგლისა და კოვზის ოსტატობა“. ბავშვი უკვე სწავლობს, კოვზით აიღოს საკვები და თითქმის დაუღვრელად მიიტანოს პირთან. შესთავაზეთ ბოსტნეულისა და ხილის პატარა ნაჭრები, რომელთა ჩანგლით აღებაც ადვილია (fork-friendly). დამოუკიდებლად ჭამა ეხმარება, ამოიცნოს დანაყრების შეგრძნება და მეტი ინტერესი გამოიჩინოს სხვადასხვა ტექსტურის საკვების მიმართ.') WHERE id = 'a925547f-11ed-45ce-9474-cab706a5ddda';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: „დიალოგი სათამაშოებთან“. ბავშვი უკვე „ესაუბრება“ თოჯინას ან დათუნიას, „აჭმევს“ ან „აძინებს“ მათ. ეს მისი ემოციური ინტელექტისა და ყოველდღიური რიტუალების სიღრმისეულად ათვისების მაჩვენებელია. შეუერთდით მას ამ როლურ თამაშებში და სცენარი ოდნავ გააფართოეთ.') WHERE id = 'a151a89a-61af-4831-b10f-8a215a565721';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური განვითარება: „ბურთის დარტყმა ფეხით“. ბავშვი უკვე ცდილობს, ფეხზე დგომისას წონასწორობის დაკარგვის გარეშე დაარტყას წინ მდებარე ბურთს. ეს მოძრაობა რთულ კოორდინაციასა და ცალ ფეხზე წამიერად წონასწორობის შენარჩუნებას მოითხოვს. სახლში ან ეზოში მსუბუქი ბურთით ეთამაშეთ, რათა მოძრაობის სისწრაფეც და სიზუსტეც განუვითარდეს.') WHERE id = 'deb4ac24-b3c7-4d6b-a7be-c36edea03c4e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 600 დღე გავიარეთ! თქვენი ბავშვი უკვე 20 თვის ნახევარზეა. მას სრულად ესმის მარტივი მითითებები, მკაფიოდ გამოხატავს ემოციებს და პატარა „მკვლევარია“, რომელიც მზადაა სამყაროს დასაპყრობად. აღნიშნეთ ეს დღე მასთან ერთად მის საყვარელ პარკში ან სათამაშო ოთახში დროის გატარებით. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '1f1a3784-4c01-4fba-825d-ca3fcac15f79';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-20 თვის ბოლო ათდღეულს ვიწყებთ. ბავშვი უკვე არა მხოლოდ სხეულის ნაწილებს აჩვენებს, არამედ მათი დანიშნულების გაგებასაც იწყებს. როდესაც ჰკითხავთ: „რას აკეთებ ფეხებით?“, მან შეიძლება სირბილი ან ფეხების ბაკუნი გაჩვენოთ. ეთამაშეთ თამაში „ეს რისთვისაა?“. ეს ავითარებს როგორც მის ლექსიკურ მარაგს, ისე ფუნქციურ აზროვნებას.') WHERE id = 'dee4db38-d5ad-4ab8-80a6-e91df1c6234f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოძრაობის უნარებში — „დაბრკოლებების ქვეშ გაძრომა“. ბავშვი უკვე არა მხოლოდ სწორად დგომას, არამედ დახრას, მაგიდის ან სკამის ქვეშ გაძრომასა და სივრცეში საკუთარი სხეულის ზომების გათვალისწინებასაც სწავლობს. ეს აუმჯობესებს მის მიერ საკუთარი სხეულის აღქმას (body awareness). სახლში ბალიშებისა და სკამებისგან „გვირაბები“ მოაწყვეთ და ამ უნარის განვითარებაში დაეხმარეთ.') WHERE id = '4db05b48-52f1-4673-a7b9-28436103d6d9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ნაცვალსახელების პირველი ნიშნები“. ბავშვი უკვე ცდილობს, საკუთარ თავზე თქვას „მე“, თქვენ კი „შენ“-ით მოგმართოთ (ან ეს სიტყვები თავის ენაზე განსხვავებული ბგერებით წარმოთქვას). ეს იმის დასტურია, რომ ის საკუთარ თავს გარესამყაროსგან სრულიად დამოუკიდებელ პიროვნებად აღიქვამს. როდესაც საკუთარ სახელს ამბობს, უპასუხეთ: „დიახ, შენ, (თქვით მისი სახელი), აქ ხარ“ — ამით საკუთარი „მე“-ს აღქმას განუმტკიცებთ.') WHERE id = '15ef8b0a-68af-41c5-881d-ef1aaddc31ca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ხრახნებისა და თავსახურების მოხსნა“. ბავშვი უკვე ცდილობს, ბოთლის თავსახურები დატრიალებით მოხსნას ან დაახუროს. ეს მოძრაობა მაჯის კუნთებისა და ბრუნვითი მოძრაობის შესანიშნავი ვარჯიშია. მიეცით სხვადასხვა ზომის უსაფრთხო ჭურჭელი და ამ ახალი „უნარის“ გამოცდის საშუალება.') WHERE id = 'eca36160-9ece-4da0-80c8-687ec7c51745';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „დახმარების სურვილი“. ბავშვს უკვე ძალიან უნდა, საყიდლების ჩანთიდან რამე ამოიღოს ან რაიმე მოგიტანოთ. მიეცით პატარა დავალებები, მაგალითად: „გთხოვ, ეს საფენი მომაწოდე“. დავალების შესრულების შემდეგ უთხარით: „ძალიან დამეხმარე, დიდი მადლობა“. ეს მასში სოციალური პასუხისმგებლობისა და საკუთარი სარგებლიანობის განცდას აყალიბებს.') WHERE id = 'ee7370f4-6eb2-48da-aebb-00ccc3c2ad1b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„კბილების დამოუკიდებლად გახეხვა“. ბავშვი უკვე გბაძავთ, კბილის ჯაგრისი პირთან მიაქვს და ამოძრავებს. ჯერჯერობით ეს მხოლოდ თამაშია და კბილები თქვენ უნდა გაუხეხოთ, თუმცა ამ ჩვევისადმი მისი ინტერესი წაახალისეთ. საკუთარი ჯაგრისის ქონა და კბილების გახეხვის მცდელობა ჰიგიენური ჩვევების ჩამოყალიბებას ხელს უწყობს.') WHERE id = '183dc3b9-e225-46b4-b630-b164f5414528';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „დაწყვილება“ (Matching). ბავშვს უკვე შეუძლია ერთი და იმავე ცხოველის ან ნივთის ორი განსხვავებული გამოსახულება ერთმანეთს შეუსაბამოს. ეთამაშეთ მარტივი ბარათებით თამაში „იპოვე ერთნაირი“. ეს მის ვიზუალურ ყურადღებასა და მეხსიერებას საოცრად ავითარებს. როცა სწორად იპოვის, სიხარულით შეეგებეთ მის წარმატებას, რათა მოტივაცია არ დაკარგოს.') WHERE id = '45e380ad-6559-467d-84f4-eced81427f7d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „კიბეზე თითო საფეხურის გავლით ჩამოსვლა“. როცა ხელს ჰკიდებთ, ბავშვი უკვე ცდილობს კიბეზე უფრო თავდაჯერებულად, თითო საფეხურის გავლით ჩამოვიდეს. ჩამოსვლა ასვლაზე რთულია და მეტ წონასწორობას მოითხოვს. უსაფრთხოებისთვის ყოველთვის მის გვერდით იყავით და მიეცით საშუალება, კიბის მოაჯირს დაეჭიდოს.') WHERE id = '9b3b0e2c-c4cd-4d64-a63f-e74713052b56';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ემოციების დასახელება“. როცა ბავშვი ბრაზდება, უხარია ან რცხვენია, ეს ემოციები სიტყვებით გამოხატეთ: „ახლა ძალიან გიხარია!“, „ცოტა მოწყენილი ხარ, რადგან სათამაშო დაგივარდა?“ ემოციების დასახელება ბავშვს მომავალში „ტანტრუმის“ (ძლიერი გაღიზიანების შეტევების) დროს საკუთარი თავის უფრო ადვილად მართვაში ეხმარება.') WHERE id = 'da0fa9b2-9fec-47fb-a56d-5e0c384540ea';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის გაძლიერება: „წარმოსახვითი თამაშები“. ბავშვს უკვე შეუძლია ერთი ნივთი მეორის ნაცვლად გამოიყენოს. მაგალითად, შესაძლოა კუბიკი „ტელეფონად“ აქციოს და ყურთან მიიდოს. ეს ბავშვის აბსტრაქტული აზროვნებისა და შემოქმედებითობის განვითარების უმაღლესი გამოვლინებაა. შეუერთდით ამ თამაშებში და წაახალისეთ მისი წარმოსახვა.') WHERE id = 'f71a9e64-80ca-4672-869a-4b4e2012c4b5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე უფრო ხშირად იყენებს სიტყვებს „მე“ და „ჩემი“. ეს იმის ნიშანია, რომ ის საკუთარ პიროვნებასა და პირად საზღვრებს აცნობიერებს. ნორმალურია, თუ საყვარელ სათამაშოს ჩაეხუტება და იტყვის: „ჩემია!“ მიეცით საშუალება, საკუთარი ნივთების მიმართ კუთვნილების განცდა ჰქონდეს — ეს მნიშვნელოვანი საფუძველია იმისთვის, რომ მომავალში სხვების საზღვრებსაც პატივი სცეს.') WHERE id = 'b7d51937-c7a2-4d6d-b732-4b494fc952b3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „უკან სიარულის ოსტატობა“. ბავშვს უკვე შეუძლია უკან მოუხედავად და წონასწორობის დაკარგვის გარეშე რამდენიმე ნაბიჯით უკან წავიდეს. ეს შესანიშნავი ვარჯიშია სივრცეში საკუთარი სხეულის მდებარეობის შეგრძნებისთვის (პროპრიოცეპტული შეგრძნება). ეთამაშეთ თამაში „ვიაროთ კიბორჩხალასავით“. ეს ერთდროულად სახალისო აქტივობაცაა და ფეხის კუნთებსაც განსხვავებულად ავარჯიშებს.') WHERE id = '513f1229-f55a-4c5d-a40b-fc0fd9f8ae37';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში კითხვების „რატომ?“ წინამორბედი ეტაპი. ბავშვი ყველაფერზე მიგითითებთ და გეკითხებათ: „ეს?“ — შემდეგ კი თქვენს განმარტებას ელოდება. თითოეული ნივთის სახელი და დანიშნულება მარტივი წინადადებებით აუხსენით. მაგალითად: „ეს კბილის ჯაგრისია, კბილების გასაწმენდად გამოიყენება“. თქვენი პასუხები მის ტვინს სამყაროს უფრო სისტემურად დაჯგუფებაში ეხმარება.') WHERE id = 'cd8ca16e-d97a-4620-91cf-5f294687b3b5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციურ განვითარებაში „თვითკონტროლის მცდელობები“. გაბრაზებისას ბავშვმა შეიძლება შემოგხედოთ და თქვენს რეაქციას დაელოდოს. ასეთ დროს სიმშვიდე შეინარჩუნეთ და მისი გრძნობა დაასახელეთ: „ახლა გაბრაზებული ხარ, რადგან სათამაშო ვერ ააწყვე“. თქვენი სიმშვიდე მისთვის ემოციების მართვის საუკეთესო გაკვეთილია. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '10a65a4a-b905-4a99-8c90-141b7917fa27';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე უფრო ოსტატურად იყენებს კოვზსა და ჩანგალს. მას საკვების უმეტესი ნაწილის პირთან დაღვრის გარეშე მიტანა შეუძლია. ეს ნატიფი მოტორიკისა და თვალისა და ხელის კოორდინაციის განვითარების მაღალ დონეზე მიუთითებს. შეუქმენით პირობები, რომ სხვადასხვა ტექსტურის საკვები დამოუკიდებლად მიირთვას. ეს დამოუკიდებლობა მას დანაყრების შეგრძნების უკეთ აღქმაში ეხმარება.') WHERE id = 'cd235f0e-55bc-496a-a89f-89523cd7e8fe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „აძრომა და ჩამოსვლა“. ბავშვს უკვე შეუძლია დივანზე ან დაბალ საფეხურებზე დამოუკიდებლად აძრომა. ყოველთვის შეახსენეთ, რომ სიმაღლიდან ზურგით, ჯერ ფეხების ჩამოშვებით ჩამოვიდეს. ეს მნიშვნელოვანი უნარია, რომელიც მას საკუთარი სხეულის უსაფრთხოების წესების ათვისებასა და რისკების ვიზუალურად შეფასებაში ეხმარება.') WHERE id = 'b1b72a87-fa8e-4ffe-811e-9806f2ea1d7c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მოქმედების აღმნიშვნელი სიტყვები“. ბავშვი უკვე შესაბამის სიტუაციებში სწორად იყენებს ისეთ ზმნებს, როგორებიცაა „წადი“, „მოდი“, „დაიძინე“, „ჭამე“. უპასუხეთ მისი ნათქვამის გაფართოებით: „დიახ, ახლა პარკში მივდივართ“. ეს მის მეტყველებაში გრამატიკული სტრუქტურების ჩამოყალიბებას აჩქარებს.') WHERE id = '275f2048-2ec2-445d-b693-5c34e41e7b83';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „დაწყობა და კონსტრუირება“. ბავშვს უკვე შეუძლია 8-10 კუბი ერთმანეთზე დააწყოს და მყარი კოშკი ააგოს. ეს მოითხოვს როგორც ყურადღების კონცენტრაციას, ისე თითის წვერების მოძრაობის სიზუსტეს. როდესაც კოშკი დაინგრევა, ამას მხიარულად შეხვდით, რათა ბავშვს ხელახლა ცდის სურვილი გაუჩნდეს. ეს პრობლემების გადაჭრისას მის შეუპოვრობას აძლიერებს.') WHERE id = '97370ca6-2fbc-4894-81aa-9ab979d2d27e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ზედსართავი სახელების გაერთიანება“. ბავშვი საგნებს უკვე უბრალოდ კი არ ასახელებს, არამედ მათ ფერს ან ზომასაც ამატებს: „დიდი ბურთი“, „წითელი მანქანა“. წაახალისეთ მისი ეს მცდელობები და წინადადება ოდნავ გაუფართოეთ: „დიახ, ეს შენი დიდი და რბილი ბურთია“.') WHERE id = 'b2c7d131-58dd-486b-9609-a0affe8ae4df';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ვერტიკალური და ჰორიზონტალური ხაზები“. ბავშვს ფანქარი უკვე უფრო თავდაჯერებულად უჭირავს და ქაღალდზე გამიზნულად სწორი ხაზების გავლება შეუძლია. მიეცით მსხვილი ფერადი ფანქრები და დიდი სახატავი ფურცლები. მის მიერ გავლებული თითოეული ხაზი ხელს უწყობს თვალისა და ხელის კოორდინაციისა და მომავალში წერის უნარის განვითარებას.') WHERE id = 'cc6fb892-8f1f-42d8-95a3-eba0a72b0349';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი“ და ჩაცმა. ბავშვს უკვე მტკიცედ აქვს გადაწყვეტილი, რომელი წინდის ან ქუდის ჩაცმა სურს. შესთავაზეთ ორი უსაფრთხო არჩევანი: „დღეს მწვანე ქუდს ჩაიცვამ თუ ლურჯს?“. ასეთი მცირე გადაწყვეტილებები ბავშვს ეხმარება, თავი მნიშვნელოვნად იგრძნოს და სიჯიუტის ეპიზოდებს მინიმუმამდე ამცირებს.') WHERE id = '38af9059-ae27-4644-b4e5-977b53c68250';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „თანამშრომლობა“: ბავშვს უკვე სიამოვნებს სათამაშოების თქვენთან ერთად ალაგება. როდესაც ეტყვით: „მოდი, მანქანები ერთად დავაბრუნოთ თავიანთ სახლში“, ის დაგეხმარებათ. ეს წესრიგის დაცვის ჩვევაცაა და ერთობლივი საქმიანობით მიღებული სიხარულიც. არ დაგავიწყდეთ მისი შექება ყოველი დახმარების შემდეგ.') WHERE id = '49ba697d-2e60-439d-966b-ca621530805d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „ნაწილების გაერთიანება“. ბავშვს უკვე დამოუკიდებლად შეუძლია ორ- ან სამნაწილიანი მარტივი ფაზლების (თავსატეხების) აწყობა. სურათების შეერთება და მთლიანი გამოსახულების დანახვა მის ვიზუალურ-სივრცით აზროვნებას ავითარებს. თუ არ გამოსდის, მშვიდად მიანიშნეთ: „შეხედე, ძაღლის კუდი აქ არის“. ეს პრობლემის გადაჭრისადმი მის მონდომებას აძლიერებს.') WHERE id = '1bcc9149-af08-4bbd-bac4-e8848b1380ea';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთისთვის ფეხის დარტყმა და სირბილი“. ბავშვს უკვე შეუძლია, სირბილის დროს წინ მდებარე ბურთს ფეხი დაარტყას. ამ დროს ის ერთდროულად აკონტროლებს მოძრაობის სიჩქარესა და დინამიკურ წონასწორობას. სახლში ან პარკში მასთან ერთად „ფეხბურთის“ თამაშით მოძრაობის სიზუსტე განუვითარეთ.') WHERE id = '56be9450-be4f-4da2-bbc6-79d6b2c42f94';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „სიმბოლური ზრუნვა“. ბავშვმა შეიძლება სათამაშო დათუნიას „წყალი დაალევინოს“, საბანი გადააფაროს ან ტირილისას მოეფეროს. ეს მისი ემოციური ინტელექტისა და სხვების გრძნობების გაგების უნარის განვითარების ნიშანია. არ დაგავიწყდეთ მისი ასეთი მზრუნველი ქცევის შექება.') WHERE id = '4c44b890-83ea-41cb-99e6-72cdc0b1bf1f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად დალაგების“ ჩვევა: ბავშვი უკვე იწყებს სათამაშოების ყუთში ჩალაგების თამაშის დასასრულად აღქმას. პროცესი სახალისო გახადეთ და უთხარით: „მოდი, მანქანები თავიანთ საწოლში ჩავაწვინოთ“. ეს მასში მოწესრიგებულობასა და პასუხისმგებლობის გრძნობას აყალიბებს. როდესაც გეხმარებათ, თავს დიდ და სასარგებლო ადამიანად გრძნობს.') WHERE id = 'a363f89b-584e-494b-8c74-513903336560';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ერთნაირი და განსხვავებული“ კოგნიტიურ განვითარებაში. ბავშვს უკვე შეუძლია ერთნაირი ფერის ან ერთი და იმავე სახეობის ნივთების დაჯგუფება. გამოსცადეთ მისი უნარი და უთხარით: „მოდი, ყველა წითელი ნივთი აქ შევაგროვოთ“. ასეთი თამაშები საფუძველს უყრის მის ლოგიკურ აზროვნებასა და ვიზუალური ანალიზის უნარს.') WHERE id = 'f0afc0a3-b89f-4803-b20f-1fd14e1c84af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „დაღმართზე სიარული“. დახრილ ზედაპირებზე (პატარა გორაკებზე) სიარული ბავშვისგან წონასწორობის ახალ უნარს მოითხოვს. ეს აძლიერებს მის კოჭებსა და სხეულის სიმძიმის ცენტრის მართვის უნარს. პარკში სეირნობისას შეუქმენით პირობები ასეთი მცირე ფიზიკური გამოწვევებისთვის.') WHERE id = 'c7f6bf36-ec3f-4dad-b529-a2a1c67afd8f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სახელი–ნაცვალსახელის კავშირი“. ბავშვმა საკუთარი სახელის წარმოთქმიდან შესაძლოა თანდათან „მე“-ს გამოყენებაზე გადასვლა დაიწყოს. თუ შეკითხვისას პასუხობს „მე“ ან „ჩემი“, ეს საკუთარი პიროვნების გაცნობიერების ჩამოყალიბებაზე მიუთითებს. ამ თემაზე მასთან დიალოგები გამართეთ: „ვისი ბურთია ეს? ჩემია!“.') WHERE id = 'da725a7e-8a5a-4880-b76d-f59275696659';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: „რთული მიბაძვა“. ბავშვი უკვე რამდენიმე ეტაპისგან შემდგარ მოქმედებებს ბაძავს. მაგალითად, „ბაზარში მიდის“, „პროდუქტებს ყიდულობს“ და „საჭმელს ამზადებს“. ეს აჩვენებს როგორც მის მეხსიერებას, ისე იმას, თუ რამდენად ღრმად აკვირდება მოვლენებს შორის ლოგიკურ კავშირს.') WHERE id = '385dd8e9-365e-4aee-b063-18466c68a303';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარების ნაწილი — „ფაზლები და ლოგიკა“. ბავშვი უკვე ცდილობს, 4-5-ნაწილიანი მარტივი ფაზლები დამოუკიდებლად ააწყოს. სურათების ვიზუალურად გაერთიანება მას უვითარებს როგორც ყურადღების კონცენტრირების, ისე პრობლემების გადაჭრის უნარს. თუ არ გამოსდის, მშვიდად მიანიშნეთ სწორი გზა, მაგრამ მის ნაცვლად ნუ გააკეთებთ. ეს პატარა „გამარჯვებები“ მის შემეცნებით უნარებს აძლიერებს.') WHERE id = '39e90e4b-782c-46d9-9e9f-4cff4dfc1e98';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკუსვლით სიარული“. ბავშვს უკვე შეუძლია, რამდენიმე ნაბიჯი თავდაჯერებულად გადადგას უკან. ეს წონასწორობის შენარჩუნების რთული ფორმაა და სივრცეში სხეულის კოორდინაციას მოითხოვს. ეთამაშეთ თამაში „ვიაროთ კიბორჩხალასავით“. ეს არა მხოლოდ კუნთების სხვადასხვა ჯგუფს ავარჯიშებს, არამედ მხიარულ და სიცილით სავსე წუთებსაც ქმნის.') WHERE id = 'f9c866fa-1063-46f8-bd49-769efa10ff9a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „კითხვა-პასუხის“ დიალოგი უფრო რთული ხდება. ბავშვმა შეიძლება გკითხოთ „ეს რა არის?“ არა მხოლოდ იმისთვის, რომ საგნის დასახელება გაიგოს, არამედ თქვენთან საუბრის გასაგრძელებლადაც. პასუხისას საგნის დანიშნულებაც აუხსენით: „ეს სავარცხელია, თმის დასავარცხნად ვიყენებთ“. თქვენი ვრცელი განმარტებები სწრაფად აფართოებს მის წარმოდგენას სამყაროზე.') WHERE id = 'b9cee91c-b40d-4bad-a4d5-c04129fdcf20';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები და „არა“. ბავშვი შეიძლება გაბრაზდეს, როდესაც ყველაფრის დამოუკიდებლად გაკეთება სურს ან სასურველს დაუყოვნებლივ ვერ იღებს. ასეთ დროს სიმშვიდე შეინარჩუნეთ და მისი გრძნობა დაასახელეთ: „ახლა ძალიან გაბრაზებული ხარ, მაგრამ (უთხარით წესი) არ შეიძლება“. თქვენი თანმიმდევრულობა და მშვიდი ტონით ახსნა საუკეთესო გაკვეთილია, რომელიც მას საკუთარი ემოციების მართვას ასწავლის.') WHERE id = '4c29e86c-55c8-4844-9903-13a58d0c9468';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე მარტივად ასრულებს ორსაფეხურიან დავალებებს. მაგალითად: „აიღე სათამაშო და თაროზე დადე“. ეს მიუთითებს, რომ მისი მუშა მეხსიერება და მეტყველების აღქმა განვითარების ახალ დონეზე გადავიდა. დღის განმავლობაში ასეთი პატარა „დავალებების“ მიცემით მას პასუხისმგებლობის გრძნობასაც განუვითარებთ და ყურადღებასაც გაუვარჯიშებთ.') WHERE id = '63b64ef1-0e7a-45db-8f97-702657621c76';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოძრაობის უნარი — „კიბეზე ასვლის ოსტატობა“. ბავშვს უკვე შეუძლია სცადოს კიბეზე თითო საფეხურის თითო ნაბიჯით ასვლა, თუ ერთი ხელით დაიჭერთ. ეს ბარძაყისა და მენჯის კუნთების გაძლიერებაზე მიუთითებს. ყოველთვის ახლოს იყავით, დაიცავით დაცემისგან და მისი წარმატებები ტაშით აღნიშნეთ.') WHERE id = '4d704d6f-6be2-478b-b2bb-0363d0dde71b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე 22-ე თვის შუაშია და მის ლექსიკურ მარაგში „სიტყვების აფეთქება“ გრძელდება. ის უკვე ცდილობს, არა მხოლოდ საგნებს, არამედ რთულ ემოციებსა და მოქმედებებსაც დაარქვას სახელი. მასთან საუბრისას თქვენი წინადადებები ოდნავ გაართულეთ: „მოდი, წითელი ქუდი დავიხუროთ და გარეთ გავიდეთ“. ეს მის სმენით მეხსიერებასა და გრამატიკულ აღქმას აძლიერებს.') WHERE id = '9ec78a78-6722-4c40-af92-d0238d028cd3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ადგილზე ხტომის ოსტატობა“. ბავშვი უკვე უფრო თავდაჯერებულად ახერხებს ორივე ფეხის ერთდროულად აცილებას იატაკიდან. ეს მოძრაობა მის წვივის კუნთებს ავითარებს და წონასწორობის დაცვას აუმჯობესებს. მუსიკის ფონზე მასთან ერთად ხტომაში შეჯიბრი მოაწყვეთ. ეს ენერგიის დახარჯვის ყველაზე სახალისო გზაა.') WHERE id = '43c73105-af4e-4d3a-b15d-a50b903d4d3e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ზედსართავი სახელების სიმრავლე“. ბავშვი უკვე უკეთ განასხვავებს საგნების თვისებებს (ფერს, ფორმას, გემოს). მის ყოველდღიურ ცხოვრებაში შეიტანეთ ისეთი გამოთქმები, როგორებიცაა „მჟავე ლიმონი“, „ტკბილი ვაშლი“, „ცივი წყალი“. ეს დაეხმარება, სიტყვები შეგრძნებებს დაუკავშიროს და სამყარო უფრო მრავალფეროვნად აღწეროს.') WHERE id = '39e55b53-a529-49e6-9321-ad14c32b7c7c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ხრახნებისა და თავსახურების მოხსნა“. ბავშვი უკვე ინტერესდება სხვადასხვა ზომის ბოთლის თავსახურებისა თუ კონტეინერების დატრიალებით გახსნით. ეს მოძრაობა მაჯის მბრუნავი მოძრაობისთვის შესანიშნავი ვარჯიშია. მიეცით უსაფრთხო, ცარიელი პლასტმასის ჭურჭელი და ამგვარად ხელი შეუწყვეთ მის „მექანიკურ“ ინტერესს.') WHERE id = 'be39779f-3011-4da7-aa56-861a48e906e9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სიჯიუტე — „მე თვითონ ვიცვამ“ — პიკს აღწევს. ბავშვი უკვე ცდილობს, ადვილად ჩასაცმელი შარვალი აიწიოს ან ფეხსაცმელი თვითონ ჩაიცვას. ამ პროცესისთვის რამდენიმე წუთით მეტი დრო მიეცით. თუ არ დააჩქარებთ და შესაძლებლობას მისცემთ, თავად გაართვას თავი რაიმეს, ეს ყველაზე მეტად გაზრდის მის თვითშეფასებას (self-esteem). თქვენი მოთმინება მისი დამოუკიდებლობის განვითარებაში უდიდესი წვლილია.') WHERE id = 'f0ed327b-3dc6-4a59-97ba-d4b77cc256ae';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გაზიარების პირველი გაკვეთილები“. ბავშვი უკვე ხვდება, რომ სათამაშოს დროებით სხვისთვის მიცემა მის სამუდამოდ დაკარგვას არ ნიშნავს. თუმცა „ჩემია“ განცდა ჯერ კიდევ ძალიან ძლიერია. ნუ აიძულებთ გაზიარებას; ამის ნაცვლად აჩვენეთ, რას ნიშნავს „მორიგეობით თამაში“. ეს სოციალურ ადაპტაციას ამარტივებს.') WHERE id = 'ea8bf74e-874e-47bc-9e0f-7dc3094dfe1c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მიზეზ-შედეგობრივი“ გამოთქმები. ბავშვს უკვე შეუძლია სცადოს თქვას „იმიტომ, რომ“ (ან ამის მსგავსი ბგერები) და ახსნას, რატომ სურს რაღაც. თქვენც აუხსენით მიზეზები: „ახლა ნაყინს არ ვჭამთ, რადგან ცივა“. ეს მისი ლოგიკური აზროვნებისა და არგუმენტირების უნარის საფუძველია.') WHERE id = 'f2f8883c-9f63-473e-95a0-d34bd2a07048';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „მოხრახვნა და დატრიალება“. ბავშვს უკვე შეუძლია ბოთლის თავსახურებისა და სათამაშო ხრახნების თავდაჯერებით მოშვება და მოჭერა. ეს მაჯის კუნთების ბრუნვითი მოძრაობის შესანიშნავი ვარჯიშია. მიეცით სხვადასხვა ზომის პლასტმასის ჭურჭელი და ხელი შეუწყვეთ მის ინტერესს ამ მექანიზმის მიმართ. ეს უნარი მომავალში ისეთი რთული მოქმედებებისთვისაა მნიშვნელოვანი, როგორიცაა ფანქრის სწორად დაჭერა.') WHERE id = '691bb5ce-e086-4aaa-85cf-679930593155';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვიბან“. ბანაობისას ბავშვი ცდილობს აიღოს საპონი ან ღრუბელი, ტანზე წაისვას და მოგბაძოთ. ნუ ჩაუხშობთ ჰიგიენური ჩვევებისადმი მის ინტერესს. საკუთარი თავის „დაბანა“ ეხმარება, უკეთ გაიცნოს სხეულის ნაწილები და ადრეული ასაკიდანვე აითვისოს პირად ჰიგიენაზე ზრუნვა.') WHERE id = 'd4a78241-9e41-44ca-8bb9-8ed66f07c05f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „გაზიარების სირთულე“. ამ ასაკში შეძახილები „ჩემია!“ სრულიად ნორმალურია. ბავშვი საკუთარი ნივთების დაცვას სწავლობს. ნუ აიძულებთ გაზიარებას; ამის ნაცვლად გამოიყენეთ პრინციპი: „მორიგეობით ვითამაშოთ“. ეს ბავშვს უსაფრთხოების განცდას აძლევს — მან იცის, რომ სათამაშოს უკან დაიბრუნებს. თქვენი მოთმინება მის სოციალურ ინტელექტს აყალიბებს.') WHERE id = '6ff62ac3-5f68-4753-ac59-118eb1c39c2b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „შესაბამისობის პოვნა“ (Matching). ბავშვს უკვე შეუძლია ერთმანეთს შეუსაბამოს ერთი და იმავე ცხოველის სხვადასხვა სურათი ან ერთი ფერის ნივთები. ეთამაშეთ მარტივი ბარათებით თამაში „იპოვე ასეთივე“. ეს სწრაფად ავითარებს როგორც მის ვიზუალურ ყურადღებას, ისე კატეგორიების მიხედვით აზროვნების უნარს.') WHERE id = '63ba4843-04a1-423b-8338-e5d3a90cedb9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის შორს სროლა“. ბავშვი ბურთს უკვე უბრალოდ აღარ აგდებს ძირს — ცდილობს, ის მხარს ზემოდან (overhand) წინ გაისროლოს. ეს მოძრაობა მთელი სხეულის კოორდინაციას მოითხოვს. პარკში ან ფართო სივრცეში ეთამაშეთ თამაში „ვინ უფრო შორს გადააგდებს ბურთს?“. ეს არა მხოლოდ მის ხელებს აძლიერებს, არამედ მანძილის აღქმის უნარსაც აუმჯობესებს.') WHERE id = '972bc93a-ef8b-4efd-af66-730802aaa073';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვსვამ“. ბავშვს უკვე შეუძლია ღია ჭიქიდან წყალი თავდაჯერებულად და თითქმის დაუღვრელად დალიოს. ეს აჩვენებს, რამდენად კარგად არის მისი ტუჩებისა და ყბის კუნთები მეტყველებისთვის მომზადებული. განაგრძეთ მისთვის ბავშვის ზომის, ადვილად დასაჭერი ჭიქების მიცემა, რათა ეს უნარი სრულყოფილად აითვისოს.') WHERE id = '20e5b03d-5d16-4142-97b2-3cffec7b0034';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „იუმორის გრძნობა“. ბავშვმა შეიძლება განზრახ გააკეთოს რაღაც „არასწორად“ (მაგალითად, ქუდი ფეხზე ჩაიცვას), შემდეგ შემოგხედოთ და გაიცინოს. ეს მიანიშნებს, რომ მას უყალიბდება ხუმრობის გაგებისა და სოციალური ზემოქმედების უნარი. ენთუზიაზმით აჰყევით მის ამ „თამაშს“. ერთად სიცილი თქვენს შორის ემოციურ კავშირს კიდევ უფრო გააღრმავებს.') WHERE id = '0f7fea0c-bb47-4b7d-9391-ab4589f33670';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „სიმაღლე და მანძილი“. ბავშვს უკვე უკეთ შეუძლია მანძილის შეფასება კიბიდან ან დივნიდან ჩამოსვლისას. ყოველთვის შეახსენეთ, რომ ფრთხილად იყოს და უსაფრთხოდ, ზურგით წინ ჩამოვიდეს. ეს მნიშვნელოვანი ეტაპია, რათა მან საკუთარი სხეულის უსაფრთხოების წესები აითვისოს.') WHERE id = '6dd30633-3c9b-4455-9878-c9a89b329928';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „მანევრირება ხტომისას“. ბავშვი უკვე მხოლოდ ადგილზე კი აღარ ხტება, არამედ ხტომისას მიმართულების შეცვლასაც ცდილობს. ეს მსხვილი მოტორული უნარების მაღალ კოორდინაციაზე მიუთითებს. მასთან ერთად რბილ ხალიჩაზე მოძრავი თამაშები ითამაშეთ. ეს დაეხმარება როგორც ენერგიის დახარჯვაში, ისე საკუთარი სხეულის უკეთ მართვაში.') WHERE id = '85fd0d24-866e-4847-be35-912d99da58df';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ცხოველები და მათი ნაშიერები“. ბავშვმა უკვე იცის ცხოველების სახელები, ახლა კი შეიძლება მათი ნაშიერების (მაგალითად, კატისა და კნუტის) გარჩევით დაინტერესდეს. წიგნის კითხვისას ყურადღება გაამახვილეთ ამ დეტალებზე. ეს განუვითარებს როგორც კატეგორიებად აზროვნების უნარს, ისე ბუნებისადმი ინტერესს.') WHERE id = 'ce938ec0-b1a1-418d-9c79-f5996a2ee822';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციურ განვითარებაში — „ნება და საზღვრები“. ბავშვს უკვე სრულად ესმის სიტყვა „არას“ ძალა და მას ხშირად იყენებს. ასეთ დროს სიმშვიდე შეინარჩუნეთ და არჩევანის შეთავაზებით ეცადეთ, „არა“ „კიდ“ აქციოთ. თქვენი სიმტკიცე და, ამავე დროს, რბილი მიდგომა საუკეთესო გაკვეთილია, რომელიც მას წესების ფარგლებში თავისუფლებას ასწავლის.') WHERE id = '699f4641-31b9-4174-a887-f0cb838a43e4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „თხოვნა“. როდესაც ბავშვს რამე სურს, უკვე მხოლოდ თითით კი არ მიუთითებს, არამედ შეუძლია თქვას „მომეცი“ ან „თუ შეიძლება“ (ან მსგავსი შეძახილი). ყოველთვის მიეცით თავაზიანი საუბრის მაგალითი. თქვენგან სიტყვების „დიდი მადლობა“ ან „თუ შეიძლება“ მოსმენა მისი მომავალი ურთიერთობის კულტურას საფუძველს უყრის.') WHERE id = '0ffa5444-e49f-4507-b5e7-cc95f08b1d36';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის გაძლიერება: „როლური თამაშები რთულდება“. ბავშვი უკვე მხოლოდ საჭმელს კი არ ამზადებს, არამედ სათამაშოებს სტუმრად ეპატიჟება, „მკურნალობს“ ან „მანქანაში სვამს და სამსახურში მიჰყავს“. ეს აჩვენებს, როგორ აერთიანებს ის მეხსიერებაში არსებულ მოვლენებს. ჩაერთეთ მასთან ერთად ამ როლურ თამაშებში — ეს მის შემოქმედებით უნარებს კიდევ უფრო განავითარებს.') WHERE id = '24d4307d-0d0c-428b-a2fb-db25c78400d8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი ფერებს უკვე არა მხოლოდ ცნობს, არამედ მათი შეხამებაც კარგად შეუძლია. თუ თხოვნაზე „იპოვე შენი წითელი წინდის წყვილი“ ამას სწორად აკეთებს, ეს მისი ვიზუალური ლოგიკის განვითარების ნიშანია. ყოველდღიური ჩაცმისას ხშირად გაუსვით ხაზი ფერებს: „დღეს მწვანე მაისური ჩავიცვათ?“. ეს მის ლექსიკაში ზედსართავ სახელებს განამტკიცებს.') WHERE id = '179a1147-4671-4989-8a35-24a67964487b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ერთ ფეხზე წონასწორობის შენარჩუნება“. ბავშვს უკვე შეუძლია, თუნდაც რამდენიმე წამით, ერთი ფეხი მიწიდან ასწიოს და წონასწორობის შენარჩუნება სცადოს. ეს სხეულის სიმძიმის ცენტრის სამართავად საჭირო რთული კოორდინაციაა. ითამაშეთ მასთან „ყარყატის თამაში“. ეს ერთდროულად სახალისოცაა და ფიზიკური განვითარებისთვისაც ძალიან სასარგებლო.') WHERE id = '6a2ac5db-ce06-4c8b-b0f1-21122d14d9a3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროის აღქმის პირველი ნიშნები“. ბავშვი იწყებს ისეთი სიტყვების განსხვავების გაგებას, როგორიცაა „ახლა“ და „შემდეგ“. თუ თქვენი ნათქვამის — „ჯერ ვჭამოთ, შემდეგ კი პარკში წავიდეთ“ — გაგებისას მას ლოდინი შეუძლია, ეს დიდი წინსვლაა. განაგრძეთ მოქმედებებით დროითი თანმიმდევრობის ახსნა, რათა მას მოთმინების უნარი ჩამოუყალიბდეს.') WHERE id = '91b2f1d2-b8e0-4586-beb2-1ed7668e668d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ფაზლების ოსტატობა“. ბავშვს უკვე შეუძლია 5-6-ნაწილიანი მარტივი ფაზლების დამოუკიდებლად აწყობა. გამოსახულებების ვიზუალურად გაერთიანება აუმჯობესებს როგორც ყურადღების კონცენტრაციას, ისე პრობლემების გადაჭრის უნარს. თუ არ გამოსდის, მშვიდად მიანიშნეთ სწორი გზა, მაგრამ მის ნაცვლად ნუ გააკეთებთ. ეს პატარა „გამარჯვებები“ მის შემეცნებით უნარებს აძლიერებს.') WHERE id = 'feada4a3-1665-4491-8ec1-8dc39ef9224c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '23-ე თვის ბოლო ათეულს ვიწყებთ! ბავშვი უკვე სრულად აცნობიერებს და იყენებს ნაცვალსახელს „მე“. ისეთი წინადადებები, როგორიცაა „მე მოვედი“ და „მე ვჭამე“, ადასტურებს, რომ ის საკუთარ თავს გარემოსგან განცალკევებულ პიროვნებად აღიქვამს. მხარი დაუჭირეთ მის დამოუკიდებელ გამონათქვამებს და განავრცეთ დიალოგი: „დიახ, შენ გემრიელი საჭმელი შეჭამე, ყოჩაღ!“.') WHERE id = '7aacd700-e4fe-464f-89ef-4b8e3945aa5a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „მანევრირება სირბილისას“. ბავშვს უკვე შეუძლია სწრაფი სირბილის დროს მოულოდნელად შეიცვალოს მიმართულება ან დაბრკოლებებს გვერდი აუაროს. ეს მიუთითებს როგორც კუნთების სიძლიერეზე, ისე სწრაფად გადაწყვეტილების მიღების უნარზე. პარკში მასთან ერთად ითამაშეთ „დამიჭირე“ და დაეხმარეთ მოქნილობის განვითარებაში.') WHERE id = 'a492f1d5-4125-4356-ab32-a3a06c3ae006';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „რაოდენობის ცნება“. ბავშვი უკვე იწყებს „ერთსა“ და „ბევრს“ შორის განსხვავების გაგებას. აჩვენეთ მისი სათამაშოები და უთხარით: „აქ ბევრი მანქანაა“, რითაც თვლის უნარის პირველ საფუძვლებს ჩაუყრით. მიუხედავად იმისა, რომ ჯერ რიცხვებს თანმიმდევრულად ვერ ამბობს, რაოდენობრივი განსხვავების ვიზუალურად აღქმა მისი მათემატიკური აზროვნების დასაწყისია.') WHERE id = '6541c63d-d78c-444c-93ac-32836d55b462';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ხელოვნების ნიმუშები“. ბავშვი უკვე უფრო ზუსტად იჭერს ფანქარს და ცდილობს „დახურული ხაზების“ — წრის მსგავსი ფორმების — დახატვას. მიეცით მას სხვადასხვა ფერის ფანქრები და წაახალისეთ, მის მიერ დახატული თითოეული ფორმა რაიმე საგანს მიამსგავსეთ: „ნახე, ეს ბურთს ჰგავს!“.') WHERE id = 'de8e6a20-ca58-4eb3-bdc2-7db3ed5bcda2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ გეხმარები“. ბავშვს დიდ სიამოვნებას ანიჭებს თქვენთვის საოჯახო საქმეებში დახმარება. მიეცით რეალური დავალებები, მაგალითად: „დამეხმარე, ტანსაცმელი კალათაში ჩააწყე“. ეს ავითარებს როგორც მის მოტორულ უნარებს, ისე ოჯახში პასუხისმგებლობის გრძნობას. დახმარების შემდეგ უთხარით: „შენ ჩემი ყველაზე დიდი დამხმარე ხარ“.') WHERE id = 'f2819b1a-b1cb-4ed8-b546-aae23641438e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „თავაზიანობის წესები“. ბავშვმა უკვე შეიძლება სათანადოდ დაიწყოს სიტყვების „გმადლობ“ და „თუ შეიძლება“ გამოყენება. რა თქმა უნდა, ეს თქვენს მაგალითზეა დამოკიდებული. ყოველთვის, როცა რამეს აძლევთ ან მისგან იღებთ, თავად გამოიყენეთ ეს სიტყვები და მაგალითი მიეცით. ეს მისი სამომავლო ურთიერთობის კულტურის ყველაზე მტკიცე საფუძველია.') WHERE id = 'eb0307cc-cb5a-49a5-b989-e572cad76794';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარება: „წელიწადის დროები და ამინდი“. ბავშვი უკვე ამჩნევს ამინდის ცვლილებებს (წვიმას, მზეს, ქარს) და მათზე რეაგირებს. გაიხედეთ ფანჯრიდან და მოვლენებს სახელები დაარქვით, მაგალითად: „წვიმს“. ეს აძლიერებს მის კავშირს გარემოსთან და მის ლექსიკას ბუნებასთან დაკავშირებული ახალი სიტყვებით ამდიდრებს.') WHERE id = 'e5dc7560-975f-4493-9ff3-ea6744e46ec0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მიზანში დარტყმა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს წინ მდებარე ბურთს ფეხს, არამედ ცდილობს, ის გარკვეული მიმართულებით (მაგალითად, კარისკენ) გაგზავნოს. ეს მხედველობითი ყურადღებისა და მოძრაობის კოორდინაციის ერთობლიობაა. სახლში რბილი ბურთით პატარა „საფეხბურთო“ შეჯიბრება მოაწყვეთ.') WHERE id = 'f701f5d4-0488-45fc-bf57-a9b74d61b0af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველება: „მეხსიერება და ზღაპრები“. ბავშვმა თავისი საყვარელი ზღაპარი უკვე იმდენად კარგად იცის, რომ როდესაც წინადადებას დაუსრულებლად დატოვებთ, მას შეუძლია მისი დასრულება. ზღაპრის კითხვისას გააკეთეთ პაუზები და დაელოდეთ, სანამ თავად გააგრძელებს. ეს საოცრად ავითარებს როგორც მის მეხსიერებას, ისე მოვლენათა თანმიმდევრობის აღქმის უნარს.') WHERE id = 'c61438a5-bdff-4ed0-b914-6e977fdb2bc1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მზაობა: 2 წლის შესრულებამდე სულ რამდენიმე დღე დარჩა! ბავშვი საკუთარ გრძნობებს უკვე უფრო რთული ფორმით გამოხატავს. მან შეიძლება მოულოდნელად ჩახუტება მოინდომოს ან დამოუკიდებლობის დასამტკიცებლად გაიქცეს და დაიმალოს. ამ პერიოდში მასთან მოთმინებით ურთიერთობა და იმის განცდის შექმნა, რომ ყოველ ნაბიჯზე მის გვერდით ხართ, მისი ემოციური უსაფრთხოებისთვის ყველაზე მნიშვნელოვანია.') WHERE id = 'bcd3ac04-2293-413d-8bfd-ba0e21e03fe2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე მტკიცედ ავლენს საკუთარ გემოვნებასა და არჩევანს. მას თავად სურს გადაწყვიტოს, რომელი წიგნი წაიკითხოთ ან რომელი სათამაშოთი ითამაშოთ. მიეცით მას ლიდერობის ეს მცირე შესაძლებლობები. ეს მას გადაწყვეტილების მიღების უნარს უვითარებს და ამავდროულად ეხმარება, თავი ღირებულ პიროვნებად იგრძნოს.') WHERE id = 'b41a09b6-e8fc-4b09-b81c-400b678af920';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური განვითარება: „დინამიკური წონასწორობა“. ბავშვი უკვე ცდილობს, ხაზზე გაიაროს ან დაბალი ბორდიურის კიდეს (როდესაც ხელი გიჭირავთ) გაჰყვეს. ეს სხეულის სიმძიმის ცენტრის მართვისთვის შესანიშნავი ვარჯიშია. პარკში სეირნობისას მიწაზე დახაზულ ხაზებზე სიარულის თამაში ითამაშეთ და ამ გზით მისი კოორდინაცია გააუმჯობესეთ.') WHERE id = '5d42a805-244d-4112-9107-40ebc50ef785';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სამსიტყვიანი წინადადებები“. ბავშვი უკვე უფრო რთულ წინადადებებს აყალიბებს, მაგალითად: „დედა, წყალი მომეცი“, „მამა, პარკში წავიდეთ“. მას უკვე შეუძლია საკუთარი საჭიროებების სრულად გამოხატვა. დაადასტურეთ მისი ნათქვამი და წინადადება ოდნავ გააფართოეთ: „დიახ, მოდი, ახლა წყალი დავლიოთ, შემდეგ კი პარკში წავიდეთ“. ეს ბავშვს გრამატიკული აღქმის დახვეწაში ეხმარება.') WHERE id = '8ba75ebe-7968-4c36-9120-369b2e5d0ec2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „ფაზლების აწყობის ოსტატობა“ იზრდება. ბავშვს უკვე შეუძლია 6-8 ნაწილისგან შემდგარი მარტივი ფაზლების დამოუკიდებლად აწყობა. ეს მოითხოვს როგორც ვიზუალურ ანალიზს, ისე თითების კუნთების ზუსტ მოძრაობას. ყოველ ჯერზე, როცა სურათს დაასრულებს, სიხარულით შეაქეთ, რათა უფრო რთული დავალებებისადმი ინტერესი გაუძლიერდეს.') WHERE id = '527f78da-7fbc-42ab-a36c-6bee3afe966e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვალაგებ“. სათამაშოების თავის ადგილზე დალაგება მისთვის უკვე უბრალოდ დავალება კი არა, პასუხისმგებლობაცაა. თუ გეხმარებათ, როცა ეუბნებით: „მოდი, მანქანები თავიანთ საწოლში ჩავაწვინოთ“, ეს დისციპლინის საფუძველია. მომავალში ეს ჩვევა მისი პირადი ორგანიზებულობისთვის ძალიან მნიშვნელოვანი იქნება.') WHERE id = '4cae5197-2921-4caa-b98c-16f64a7694c8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გაზიარება და რიგის დაცვა“. ბავშვს უკვე ესმის, რომ როდესაც ეუბნებით: „ახლა შენი ჯერია“, ცოტა ხნით მოცდაა საჭირო. მოთმინების სწავლა ამ ასაკისთვის დიდი მიღწევაა. მხარი დაუჭირეთ თამაშებში, სადაც რიგის დაცვაა საჭირო (მაგალითად, ბურთის ერთმანეთისთვის გადაცემისას). თქვენი ასეთი მომთმენი მიდგომა მის სოციალურ ადაპტაციას ამარტივებს.') WHERE id = 'e3e7be7f-e682-47f1-bdf9-05213d301d28';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „ერთნაირი და განსხვავებული“. ბავშვს უკვე შეუძლია ერთი ტიპის ნივთების დაჯგუფება (მაგალითად, ყველა ცხოველის ერთ ადგილას, ხოლო ყველა მანქანის — სხვა ადგილას მოთავსება). დაუსვით კითხვები, მაგალითად: „აქ რომელი სათამაშოა განსხვავებული?“ და ამგვარად შეამოწმეთ მისი ვიზუალური ლოგიკა. კატეგორიებით აზროვნება მის შემეცნებით უნარებს ახალ საფეხურზე აჰყავს.') WHERE id = '9960803a-4e47-4edd-b50d-dc62d848c875';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ადგილზე ხტომა და დატრიალება“. ბავშვი უკვე უბრალოდ კი არ ხტება, არამედ ხტომისას სხეულის შემოტრიალებასაც ცდილობს. ეს მსხვილი მოტორიკის მაღალ კოორდინაციაზე მიუთითებს. მასთან ერთად მოაწყვეთ მუსიკის თანხლებით აქტიური „ცეკვის“ საათები. ეს ერთდროულად გართობაცაა და სხეულის მოქნილობისთვის შესანიშნავი ვარჯიშიც.') WHERE id = 'b8a638df-098e-4767-9ebb-0f4df5304a5e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მეხსიერება და მოვლენები“. ბავშვს შეუძლია გაიხსენოს დღის განმავლობაში მომხდარი მარტივი ამბავი (მაგალითად, „პარკში ძაღლი დავინახე“) და მოგიყვეთ. ყურადღებით მოუსმინეთ მის მონათხრობს და ჰკითხეთ: „შემდეგ რა მოხდა?“ — ასე დაეხმარებით მოვლენების თანმიმდევრულად გადმოცემაში. ეს აძლიერებს როგორც მის მეხსიერებას, ისე აზრის გამოხატვის უნარს.') WHERE id = '9fdcc45e-2b1e-4d3c-95a7-d7f5adca9ccb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მზადყოფნა: 2 წლის შესრულებამდე სულ რაღაც 50 დღე დარჩა! ბავშვი საკუთარ გრძნობებს უკვე უფრო ღრმად გამოხატავს. მან შეიძლება თქვენდამი სიყვარული მოულოდნელი ჩახუტებით ან კოცნით გამოხატოს. თქვენც ასეთივე სითბოთი უპასუხეთ. ეს ემოციური ურთიერთგაცვლა ყველაზე მნიშვნელოვანი საზრდოა იმისთვის, რომ თავი უსაფრთხოდ და, რაც მთავარია, „საყვარელ ადამიანად“ იგრძნოს.') WHERE id = '78317024-ad5b-4a00-86b5-ab43a417337b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე არა მხოლოდ არჩევს ფერებს ერთმანეთისგან, არამედ ბევრი მათგანის სახელსაც სწორად წარმოთქვამს. თუ თხოვნისას — „მომიტანე ლურჯი მანქანა“ — არ ცდება, ეს მისი მხედველობითი და ვერბალური მეხსიერების ერთობლივი მუშაობის შედეგია. ყოველდღიური სეირნობისას განაგრძეთ მისი სამყაროს გაფერადება ისეთი აღწერებით, როგორებიცაა „მწვანე ფოთოლი“ და „ყვითელი მზე“.') WHERE id = '85496aa4-c911-4bb2-8f2e-3e5a32779858';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „კიბეზე დამოუკიდებლად ასვლა“. ბავშვი უკვე ცდილობს, მხოლოდ ერთ ხელზე მოჭიდებით, კიბეზე თითო საფეხურზე თითო ფეხის მონაცვლეობით ავიდეს. ეს მსხვილი მოტორიკის განვითარების მნიშვნელოვანი მიღწევაა. ყოველთვის ახლოს იყავით და დაიცავით, თუმცა აგრძნობინეთ ნდობა, რათა დამოუკიდებლად ნაბიჯის გადადგმა შეძლოს.') WHERE id = 'e1b72aca-8d9f-4f33-aedd-ed905b733dbf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სივრცის აღმნიშვნელი სიტყვები“. ბავშვი ისეთ ცნებებს, როგორებიცაა „ზემოდან“, „ქვემოდან“ და „უკან“, უკვე მოქმედებებით გამოხატავს. ითამაშეთ მასთან პატარა თამაში და უთხარით: „ბურთი სკამის ქვეშ დადე“. ასეთი დავალებები სწრაფად ავითარებს როგორც ენის გაგების, ისე სივრცეში ორიენტაციის უნარს.') WHERE id = '455a2119-ac1e-44e4-8b8c-20b0405c50d6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „მოხრახნისა და დატრიალების ოსტატობა“. ბავშვს უკვე შეუძლია ბოთლის თავსახურებისა და სათამაშო ხრახნების თავდაჯერებით გახსნა და დახურვა. ეს მაჯის კუნთების მოქნილობისთვის შესანიშნავი ვარჯიშია. მიეცით სხვადასხვა ზომის უსაფრთხო ჭურჭელი და მხარი დაუჭირეთ მის ინტერესს ასეთი „მექანიკური“ აღმოჩენებისადმი.') WHERE id = '61305052-b44e-493c-a6f8-ffe876e0e01e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვიცვამ“ ეტაპი უფრო რთულდება. ბავშვი უკვე ცდილობს ელვა-შესაკრავის შეკვრას (მას შემდეგ, რაც თქვენ დაუწყებთ) ან დიდი ღილების გახსნას. ამ პროცესში ხელს ნუ შეუშლით და ნუ დააჩქარებთ. იმის დანახვა, რომ რაღაც თავად შეუძლია, მისთვის თავდაჯერებულობის უდიდესი წყაროა. მცირე წარმატებებისთვის აუცილებლად შეაქეთ და გაამხნევეთ.') WHERE id = 'f6d69242-03a3-4cc8-a444-aac7bbd07185';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „ემპათია“ იზრდება. როცა ბავშვი დაინახავს, რომ თქვენ ან სხვა ბავშვი მოწყენილი ხართ, შეიძლება მოვიდეს, თავისი სათამაშო შემოგთავაზოთ ან ჩაგეხუტოთ. ეს მისი ემოციური ინტელექტის (EQ) შესანიშნავი მაჩვენებელია. მისი ასეთი მზრუნველობა წაახალისეთ სიტყვებით: „დიდი მადლობა, რომ მხარში დამიდექი“.') WHERE id = '98c8accf-ca7d-4901-b417-a3bce7f325f2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარება: „ფორმა და ზომა“. ბავშვს უკვე შეუძლია ერთი და იმავე ფორმის (მაგალითად, წრის) დიდი და პატარა ვარიანტების გარჩევა. აჩვენეთ, როგორ მოათავსოს სხვადასხვა ზომის ჭურჭელი ერთმანეთში. ეს უვითარებს „თანმიმდევრობით დალაგების“ უნარს, რომელიც მისი მომავალი მათემატიკური აზროვნების საფუძველია.') WHERE id = 'bfdb17de-cc0d-437c-870c-13801051e507';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და დამიზნება“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ის კონკრეტული მიმართულებით გაგზავნოს. ეს მხედველობითი ყურადღებისა და მოძრაობის კოორდინაციის ერთობლიობაა. სახლში ან პარკში გაუკეთეთ „პატარა კარი“ და ითამაშეთ მასთან ბურთის კარში გატანა. ეს აძლიერებს მისი ფეხის კუნთებს და აუმჯობესებს სიზუსტეს.') WHERE id = 'a17dc9b7-c84f-4802-8431-7aad7b966067';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ამბის მოყოლის მცდელობები“. ბავშვს ძალიან სურს, მოგიყვეთ დღის განმავლობაში ნანახი რაიმე საინტერესო (მაგალითად, „დიდი ძაღლი დავინახე“). ბოლომდე მოუსმინეთ მის ამბავს და კითხვებით განავრცეთ: „რა ფერის იყო ძაღლი?“. ეს აძლიერებს როგორც მის მეხსიერებას, ისე საკუთარი აზრის გამოხატვის უნარს.') WHERE id = 'daff24e3-d7cd-46e0-9c7d-75e6a3417d53';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: ბავშვმა შეიძლება უკვე მტკიცედ გამოხატოს საკუთარი ნება და თქვას: „მე არ მინდა“. ასეთ დროს, გაჯიუტების ნაცვლად, მიეცით არჩევანის საშუალება და ამ გზით ყურადღება გადაატანინეთ. თქვენი მოთმინება და თანმიმდევრული წესები ბავშვს უსაფრთხოების განცდას უქმნის. 2 წლის შესრულებამდე სულ რაღაც 40 დღე დარჩა – თქვენ დიდ საქმეს აკეთებთ!') WHERE id = '30c55932-1036-4bc0-a31f-1b927f46a841';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე 23-ე თვის ბოლოს უახლოვდება. ახლა მას კარგად ესმის, რომ მას არა მხოლოდ „მე“-თი, არამედ საკუთარი სახელითაც მოიხსენიებენ. თუ საუბრისას ჰკითხავთ: „ეს შენ გააკეთე?“ და ის ამაყად გიპასუხებთ: „კი“, ეს მისი თვითიდენტობის ცნობიერების განვითარებაზე მიუთითებს. შეაქეთ მიღწევებისთვის და სახელით მიმართეთ: „ყოჩაღ, (ბავშვის სახელი), შენ ეს შეძელი!“.') WHERE id = '9459dc0c-afe8-45b3-b94d-dd65b48126f2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „თავისუფლად სირბილი და გაჩერება“. ბავშვს უკვე შეუძლია სირბილისას მოულოდნელად, წაქცევის გარეშე გაჩერდეს. ეს აჩვენებს, რამდენად არის განვითარებული მისი შემაკავებელი კონტროლის (inhibitory control) სისტემა და კუნთები. პარკში მასთან ერთად ითამაშეთ „გაიქეცი და გაჩერდი!“ — ეს სახალისოცაა და კოორდინაციის განვითარებისთვისაც სასარგებლოა.') WHERE id = 'ecf7ae38-688c-4cbe-90a0-7112da130536';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვების დასმის პერიოდი“. რადგან ბავშვმა უკვე ბევრი საგნის სახელი იცის, ახლა აინტერესებს, რისთვის გამოიყენება ისინი. როდესაც საგანზე მიგითითებთ და გეკითხებათ: „ეს?“, აუხსენით არა მხოლოდ მისი სახელი, არამედ დანიშნულებაც: „ეს ქოლგაა, წვიმისგან დასაცავად გამოიყენება“. თქვენი ამომწურავი პასუხები სწრაფად აფართოებს მის წარმოდგენას სამყაროზე.') WHERE id = 'cb8ab97b-604a-4728-ac40-ae0675a2ce85';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ვერტიკალური და ჰორიზონტალური ხაზები“. ბავშვს უკვე უფრო თავდაჯერებულად უჭირავს ფანქარი და ქაღალდზე მიზანმიმართულად ავლებს სწორ ხაზებს. მიეცით სხვადასხვა ფერის ფანქრები და დიდი ზომის ქაღალდი, რათა ხელი შეუწყოთ მისი „ხატვის“ უნარის განვითარებას. ეს მომავალი წერის უნარებისთვის მნიშვნელოვანი საფუძველია.') WHERE id = 'b5be883e-3ec9-4583-905f-d5eaa6d996f3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანის“ სურვილი პიკს აღწევს. ბავშვს უკვე თავად სურს გადაწყვიტოს, რას შეჭამს, რომელი სათამაშოთი ითამაშებს და რომელი გზითაც კი წავა. შესთავაზეთ შეზღუდული არჩევანი: „დღეს ვაშლს შეჭამ თუ ბანანს?“. ეს არა მხოლოდ გადაწყვეტილების მიღების უნარს უვითარებს, არამედ ეხმარება, თავი არა მართულ, არამედ საკუთარი ქცევის მმართველ პიროვნებად იგრძნოს.') WHERE id = 'd071c76a-b155-43af-a2a1-de9194ca4c11';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „სიმბოლური მიბაძვა“. ბავშვი უკვე იმეორებს თქვენს საოჯახო როლებს: „ამზადებს საჭმელს“, „საუბრობს ტელეფონით“, „ალაგებს სახლს“. ასეთი მიბაძვა მისთვის სამყაროს შეცნობის გზაა. მიეცით პატარა სათამაშო ცოცხი ან ჭურჭელი და შეუწყვეთ ხელი, რომ თქვენი „დამხმარე“ გახდეს.') WHERE id = 'ee398ccc-6f29-41df-b0a4-1bb95b88b1a5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარების ეტაპი — „მთელის ნაწილებისგან აწყობა“. ბავშვს უკვე შეუძლია მარტივი, 3-4-ნაწილიანი ფაზლების ვიზუალურად აწყობა. ეს ავითარებს როგორც ყურადღების კონცენტრაციას, ისე პრობლემის გადაჭრის უნარს. თუ არ გამოსდის, მშვიდი ტონით დაეხმარეთ: „შეხედე, ეს ძაღლის კუდია, სად შეიძლება იყოს მისი ადგილი?“. ასეთი პატარა გამარჯვებები მის შემეცნებით უნარებს აძლიერებს.') WHERE id = '6ae9f735-9ae2-46e6-8771-fa1ead2cea34';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია — „ბურთისთვის ფეხის დარტყმა და სირბილი“. ბავშვს უკვე შეუძლია სირბილისას წინ მდებარე ბურთს ისე დაარტყას ფეხი, რომ წონასწორობა არ დაკარგოს. ეს მოძრაობის სიჩქარისა და დინამიკური წონასწორობის ერთდროულად მართვას გულისხმობს. ეზოში ან პარკში მასთან ერთად „ფეხბურთის“ თამაშით მოძრაობის სიზუსტის გაუმჯობესებაში დაეხმარეთ. თქვენთან ერთად მოძრაობა მისთვის საუკეთესო გართობაა.') WHERE id = '17868f49-652d-4efe-940b-fac27063768e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მოგონებების გადმოცემა“. ბავშვს შეუძლია გაიხსენოს და მოგიყვეთ გუშინ ნანახი ან მის თავს გადახდენილი ამბავი (მაგალითად, „პარკში ჩიტი დავინახე“). ყურადღებით მოუსმინეთ მის მონათხრობს და დიალოგი კითხვით განავრცეთ: „რას აკეთებდა ჩიტი?“. ეს წარმოუდგენლად აძლიერებს როგორც მის მეხსიერებას, ისე საკუთარი აზრის გამოხატვის უნარს.') WHERE id = 'd99ef035-085a-4da0-b18e-ddf8dda326d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 700 დღე გავიარეთ! 2 წლის შესრულებამდე მხოლოდ ერთი თვე (30 დღე) დარჩა. თქვენი ბავშვი უკვე სრულად გამოვიდა ჩვილობის ასაკიდან და პატარა „ადამიანად“ იქცა, რომელსაც საკუთარი ხასიათი, სურვილები და უნარები აქვს. დღეს ეს დიდი გზა მასთან ერთად მისი საყვარელი თამაშის თამაშით აღნიშნეთ. თქვენ საოცარი გზა გაიარეთ, დედა!') WHERE id = '0e3a52c6-9f66-42e2-994a-692b5b642618';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ვიწყებთ ბოლო ნაბიჯების გადადგმას 24-ე თვისკენ, ანუ ბავშვის 2 წლის იუბილისკენ! ბავშვი უკვე ძალიან კარგად ცნობს საკუთარ ნივთებსა და ტანსაცმელს. თუ თხოვნაზე — „ტანსაცმლის კარადიდან შენი მაისური მომიტანე“ — ამას ასრულებს, ეს ნიშნავს, რომ მისი მეხსიერება და კუთვნილების განცდა ძლიერდება. ასეთი პატარა დავალებები მის თავდაჯერებულობას ზრდის.') WHERE id = 'f1337afd-8cd4-4800-85b9-83874ec33ec8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ბორდიურზე წონასწორობის დაცვა“. ბავშვს უკვე აინტერესებს დაბალ ბორდიურზე სიარული, როცა ხელით გიჭირავთ. ეს წონასწორობის კომპლექსურ შეგრძნებას უვითარებს. უსაფრთხო ადგილებში ხელი შეუწყვეთ ამ ინტერესს, რადგან ის მომავალში უფრო რთული ფიზიკური მოძრაობების შესრულების საფუძველია.') WHERE id = '48e8258d-7e1b-417f-861b-84e4a830fb92';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ნაცვალსახელების ზუსტად გამოყენება“. ბავშვი უკვე უფრო სწორად ათავსებს წინადადებაში ისეთ ნაცვალსახელებს, როგორებიცაა „მე“, „შენ“ და „ის“. მაგალითად: „მე მშია“ ან „შენ მოდი“. ამ წინსვლის მხარდასაჭერად, ბავშვთან საუბრისას თქვენც გაამახვილეთ ყურადღება ნაცვალსახელებზე. ეს მას სოციალური კომუნიკაციის უნარის სწრაფად განვითარებაში დაეხმარება.') WHERE id = '6c0e87a6-05f9-4b6b-826c-adb939561dc2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „კონსტრუირების ოსტატობა“. ბავშვი უკვე მხოლოდ ერთმანეთზე კი არ აწყობს კუბებს, არამედ მათგან „სახლს“, „მატარებელს“ ან „ღობეს“ აშენებს. ეს მიუთითებს, რომ მისი ვიზუალურ-სივრცითი აზროვნება განვითარების ახალ ეტაპზე გადავიდა. ინტერესით შეხვდით მის „ნაგებობებს“ და დაუსვით ისეთი კითხვები, როგორიცაა: „აქ ვინ მოვა?“') WHERE id = 'd0a7b08b-aa7f-465e-8cfb-7b1cbe914d24';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „როლური თამაშების გართულება“. ბავშვი უკვე რამდენიმე თანმიმდევრული მოქმედებისგან შემდგარ თამაშებს იგონებს: მაგალითად, სათამაშო დათუნიას „ბანს“, „ამშრალებს“ და შემდეგ „აძინებს“. ეს აჩვენებს, როგორ აერთიანებს ის მეხსიერებაში შენახულ ყოველდღიური ცხოვრების სცენარებს თანმიმდევრულად.') WHERE id = '290cdbcc-b930-4c04-ac8f-c9e9a99f2bd8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად კვების ოსტატობა“. ბავშვს უკვე ძალიან კარგად შეუძლია საკვების ჩანგლით აღება და პირთან მიტანა. მიეცით მას მეტი შესაძლებლობა, დამოუკიდებლად ჭამოს. მაგიდის ოდნავ დასვრა მცირე საფასურია იმისთვის, რომ მან ნატიფი მოტორიკა და თავის მოვლის პასუხისმგებლობა განივითაროს.') WHERE id = 'a907e23d-d22f-4f12-8eba-ed2e00af2852';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დიდი-პატარა-საშუალო“. ბავშვმა შესაძლოა უკვე არა მხოლოდ ორი, არამედ სამი განსხვავებული ზომის გარჩევაც დაიწყოს. მიეცით ერთი და იმავე სათამაშოს სამი სხვადასხვა ზომის ვარიანტი და შეამოწმეთ, უთხარით: „ყველაზე დიდი მომეცი“. ეს მათემატიკური შედარების უნარის საფუძველია. ყოველი სწორი არჩევანისას შეაქეთ და წაახალისეთ.') WHERE id = '228f5557-8af1-45e0-8eea-dab6d6ab319d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორი ფეხით წინ გადახტომა“. ბავშვს უკვე შეუძლია არა მხოლოდ ადგილზე ახტომა, არამედ ოდნავ წინ გადახტომაც. ეს ფეხის კუნთების ფეთქებად ძალასა და სხეულის კოორდინაციას მოითხოვს. პარკში მასთან ერთად ითამაშეთ თამაში „კურდღლები მდელოზე ხტუნავენ“. ეს არა მხოლოდ სახალისოა, არამედ მსხვილი მოტორიკისთვისაც შესანიშნავი ვარჯიშია.') WHERE id = 'fed4cb8e-d23c-4ef3-9fb0-62697ac89488';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გაზიარება და საზღვრები“. ბავშვს უკვე ესმის, რომ ზოგი ნივთი მას ეკუთვნის, ზოგი კი — სხვებს. შესაძლოა, მას ჯერ კიდევ უჭირდეს სათამაშოს გაზიარება. ასწავლეთ მორიგეობის პრინციპი შემდეგი სიტყვებით: „ახლა ეს შენია, ცოტა ხანში კი შენი მეგობარი ითამაშებს“. ეს სოციალური ადაპტაციისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი ნაბიჯია.') WHERE id = '0337bbc8-021f-48c3-b2d6-9d07615b2eb6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე გეხმარები“. ბავშვს ძალიან სიამოვნებს თქვენთვის საოჯახო საქმეებში დახმარება. ისეთი პატარა დავალებები, როგორიცაა ტანსაცმლის კალათაში ჩაყრა ან სუფრაზე პურის დადება, მას ოჯახის „მნიშვნელოვან წევრად“ აგრძნობინებს თავს. შეაქეთ მისი მონდომება: „შენ რომ არ ყოფილიყავი, ამას უფრო გვიან დავასრულებდი!“.') WHERE id = '176cc57c-d49b-4d93-9ce5-5829f43afd94';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „ფერების სახელები“. ბავშვი უკვე არა მხოლოდ არჩევს ფერებს, არამედ ბევრი მათგანის სახელსაც სწორად წარმოთქვამს. პარკში სეირნობისას სთხოვეთ: „აბა, სად არის აქ მწვანე ფოთოლი?“ ან „მაჩვენე ყვითელი ყვავილი“, რათა ცოდნა პრაქტიკაში გამოიყენოს. ეს მის მხედველობით და ვერბალურ მეხსიერებას ერთმანეთთან აკავშირებს.') WHERE id = 'b1599687-8b9b-4b36-972d-e646da9ca057';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მხარს ზემოდან გადაგდება“. ბავშვი ბურთს უკვე უბრალოდ მიწაზე აღარ აგდებს — ცდილობს, მიზანმიმართულად წინ ან თქვენკენ ისროლოს. ეს მკლავის კუნთებისა და მიზნის აღქმის განვითარებაზე მიუთითებს. სიზუსტის გასაუმჯობესებლად მასთან ერთად ითამაშეთ თამაში „ვინ ჩააგდებს ბურთს კალათაში?“.') WHERE id = 'a5dba3a5-d849-43ef-ab12-3acff84027fc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „თხოვნა და თავაზიანობა“. როდესაც ბავშვს რამე სურს, ის უკვე მხოლოდ თითით აღარ მიუთითებს და ცდილობს თქვას „მომეცი“ ან „გთხოვ“ (თუნდაც თავისებურად). თქვენი თავაზიანი ქცევა მის კომუნიკაციის სტილს აყალიბებს. ყოველთვის, როცა „დიდი მადლობა“-ს ამბობთ, ბავშვიც ბუნებრივად ითვისებს ამ კულტურას.') WHERE id = 'd8b07d2d-d5ae-44e4-8e83-13117a3ef758';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მზადყოფნა: 2 წლის შესრულებამდე სულ რაღაც 10 დღე დარჩა! ბავშვი უკვე ძალიან მკაფიოდ გამოხატავს თავის გრძნობებს (სიხარულს, ბრაზს, მორცხვობას). მოთმინებით შეხვდით მის ემოციებს და დაარქვით მათ სახელები: „ახლა გიხარია, რადგან პარკში მივდივართ“. გრძნობებისთვის სახელების დარქმევა ბავშვს საკუთარი შინაგანი სამყაროს გაგებასა და მომავალში თვითკონტროლის განვითარებაში ეხმარება.') WHERE id = '5b177d90-0a27-4e2b-8501-6cbcb2351fef';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „დასკვნის გამოტანა“. ბავშვს უკვე შეუძლია ზოგიერთი მოვლენის შედეგის წინასწარ განსაზღვრა. მაგალითად, როცა ფეხსაცმელს იღებთ, გეკითხებათ: „გარეთ მივდივართ?“ ეს აჩვენებს, რამდენად კარგად შეუძლია მას ლოგიკური კავშირების დამყარება. დაადასტურეთ მისი ვარაუდი და დამატებითი ინფორმაციაც მიაწოდეთ: „დიახ, წავალთ და ჩიტებს პურს დავუყრით“.') WHERE id = '0aaeb1eb-0155-44f3-b404-be39c9061780';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მზადება: 2 წლის შესრულებამდე სულ რაღაც 20 დღე დარჩა! ბავშვი უკვე უფრო მკაფიოდ გამოხატავს საკუთარ გრძნობებს და თქვენდამი სიყვარულს ჟესტებით — „მიყვარხარ“ (ან თავის ენაზე მსგავსი მნიშვნელობის გამოხატვით) — გაჩვენებთ. ამ დღეებში მასთან გატარებული ყოველი წამი მის ემოციურ სამყაროში წარუშლელ კვალს ტოვებს. თქვენ შესანიშნავი დედა და მეგზური ხართ!') WHERE id = 'f640772a-39c6-4d33-9c3f-64bd16ad5ed0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე „მე თვითონ ჩავიცვამ“ პერიოდის ყველაზე დაჟინებულ ეტაპზეა. შარვლის ჩაცმის ან ფეხსაცმლის ფეხზე თავად მორგების სურვილი (მიუხედავად იმისა, რომ ეს რთულია) მისი დამოუკიდებლობის გამოხატულებაა. მიეცით რამდენიმე დამატებითი წუთი, რათა თავად სცადოს. თქვენი მოთმინება მის მომავალ თავდაჯერებულობაში ჩადებული უდიდესი ინვესტიციაა.') WHERE id = 'e264db36-ff8b-4ffc-8d0c-2a9a86b8e80e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ადგილზე ტრიალი“. ბავშვს უკვე შეუძლია საკუთარი ღერძის გარშემო ტრიალი და ინტერესით აკვირდება ამის შედეგად წარმოქმნილ „თავბრუსხვევის“ შეგრძნებას. ეს მისი ვესტიბულური (წონასწორობის) სისტემის განვითარების ნაწილია. უსაფრთხო და რბილ სივრცეში მასთან ერთად იცეკვეთ და საშუალება მიეცით, ეს ახალი შეგრძნება აღმოაჩინოს.') WHERE id = 'c1b5ac77-3624-4a68-8f84-6255305e6a71';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მრავალსიტყვიანი წინადადებები“. ბავშვი უკვე 3-4 სიტყვის ერთმანეთთან დაკავშირებით რთულ აზრებს გამოხატავს: „დედა, მე დიდი მანქანა მინდა“. ნუ შეუსწორებთ წინადადებებს; პასუხისას უბრალოდ სწორი ვარიანტი გაუმეორეთ: „ჰო, იმ დიდ წითელ მანქანასთან თამაში გინდა?“ ეს მას ენის სტრუქტურის ბუნებრივად ათვისებაში ეხმარება.') WHERE id = '4ada0942-f71a-4215-a9a2-e770a9dcbe42';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „შემოქმედებითი საქმიანობა“. ბავშვი უკვე უფრო თავდაჯერებულად იჭერს ფანქარს და ქაღალდზე წრიული ხაზების დახატვას ცდილობს. ეს მომავალში წერისთვის საჭირო კუნთების კოორდინაციის საფუძველია. მიეცით სხვადასხვა ფერის საღებავები და დიდი ფურცლები, რათა ფანტაზიას თავისუფლება მისცეს.') WHERE id = 'c206267a-2d42-4d2c-8a75-f79f89a1455a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '2 წლის შესრულებამდე ბოლო 10 დღე დარჩა! ბავშვი უკვე სრულად აცნობიერებს საკუთარ პიროვნებას. სარკეში იყურება, თავის სახელს ამბობს ან ჟესტით გამოხატავს: „ეს მე ვარ!“ საკუთარი „მე“-ს გაცნობიერება მისი მომავალი თავდაჯერებულობის საფუძველია. დადექით მასთან ერთად სარკის წინ და ერთად აღნიშნეთ, რამდენად გაიზარდა და უკვე რამდენი რამ შეუძლია.') WHERE id = '391d8114-3346-495b-b8f3-45861173d919';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „რთული სირბილი“. ბავშვს უკვე შეუძლია სირბილისას წინ არსებული დაბრკოლებები სწრაფი მანევრით გადალახოს. ეს ფიზიკური ძალისა და სწრაფი გადაწყვეტილების მიღების უნარის ერთობლიობაა. სახლში ან ეზოში პატარა „დაბრკოლებების ზოლი“ მოუწყვეთ, რათა საკუთარი მოქნილობა გამოსცადოს.') WHERE id = '23f145d6-39f1-4e1e-84f1-49d36b707443';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მთხრობელის“ ეტაპი. ბავშვს უკვე შეუძლია გაიხსენოს და მოგიყვეთ დღის განმავლობაში მომხდარი მარტივი ამბავი (მაგალითად, „ჩიტი გაფრინდა“, „ნაყინი ვჭამე“). ყურადღებით მოუსმინეთ მის პატარა ამბებს და კითხვებით დაეხმარეთ მათ განვრცობაში. ეს აძლიერებს როგორც მის მეხსიერებას, ისე მოვლენებს შორის ლოგიკური თანმიმდევრობის დამყარების უნარს.') WHERE id = 'c8794b59-4f44-4d01-9dfd-9f86547c80bb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „წიგნის სიყვარული“. ბავშვს უკვე შეუძლია ქაღალდის თხელი ფურცლები დაუხევლად, სათითაოდ გადაფურცლოს. მას მოაქვს საყვარელი ზღაპრების წიგნი და მუხლებზე გიდებთ, რათა წაუკითხოთ. ეს რიტუალი შეუცვლელია როგორც მისი მეტყველების განვითარებისთვის, ისე თქვენთან ემოციური კავშირის გასაძლიერებლად. კითხვისას დაუსვით კითხვები სურათების შესახებ.') WHERE id = '25aab72e-4248-42bb-9009-a3467dd34bf8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „პირველი მეგობრობა“. ბავშვი უკვე უბრალოდ კი არ თამაშობს სხვა ბავშვების გვერდით, არამედ სათამაშოს სთავაზობს ან მათთან ერთად დარბის. ეს სოციალური თანამშრომლობის პირველი რეალური ნაბიჯებია. წაახალისეთ მისი დადებითი სოციალური ურთიერთობები და შეაქეთ იმისთვის, რომ მზად არის, სხვებს გაუზიაროს.') WHERE id = 'fbc5e912-7941-46bd-9137-7aea112e7d13';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი ჰიგიენა“. ბავშვს უკვე ძალიან სურს, ხელები საპნით დაიბანოს და პირსახოცით გაიმშრალოს. თავის მოვლის ეს ჩვევები მის დამოუკიდებლობის განცდას აძლიერებს. შეუქმენით მის სიმაღლეზე მორგებული პირობები, რათა ჰიგიენის ეს რიტუალები ყოველდღიური ცხოვრების ბუნებრივ ნაწილად აქციოს.') WHERE id = 'e689f8a3-742e-457c-849e-63c06d7af7c0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში — „თანმიმდევრობა და ლოგიკა“. ბავშვს უკვე შეუძლია 4-5 ნივთის ზომის მიხედვით დალაგება (დიდიდან პატარამდე). ეს მათემატიკური აზროვნების ყველაზე ადრეული საფუძველია. მიეცით სხვადასხვა ზომის კუბები ან ჭურჭელი, რათა თანმიმდევრობით დალაგების უნარი ავარჯიშოს. ყოველი წარმატებული „დალაგება“ მის ტვინში ახალ ნეირონულ კავშირებს ქმნის.') WHERE id = 'd3ed6715-8284-423a-bbce-cfe0156fda68';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორი ფეხით წინ გადახტომა“. ბავშვს უკვე შეუძლია არა მხოლოდ ადგილზე ახტომა, არამედ რამდენიმე სანტიმეტრით წინ გადახტომაც. ამას ფეხის კუნთების დიდი ძალა და შესანიშნავი წონასწორობა სჭირდება. პარკში მასთან ერთად ითამაშეთ თამაში „ორმოზე გადახტომა“. ეს ერთდროულად გართობაცაა და სხეულის მართვის გაკვეთილიც.') WHERE id = '710d761b-996a-4661-a9e2-1515ed31c7a0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ვინ ვარ მე?“. ბავშვს უკვე შეუძლია თქვას საკუთარი სახელი, ასაკი (თუნდაც თითებით აჩვენოს) და სქესი. ეს მისი თვითიდენტობის გაცნობიერების მნიშვნელოვანი ეტაპია. ესაუბრეთ ხვალინდელ დიდ დღეზე: „ხვალ უკვე დიდი, 2 წლის ბავშვი გახდები!“.') WHERE id = 'ee27a56e-6e80-46b6-8a93-8ee183712978';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! დღეს თქვენი ბავშვი ზუსტად 2 წლის გახდა! 730 დღის განმავლობაში წარმოუდგენელი მოთმინება, სიყვარული და შრომისმოყვარეობა გამოიჩინეთ. თქვენი ბავშვი ჩვილობის ასაკს უკვე გასცდა და ახლა პატარა პიროვნებაა, რომელიც მზად არის სამყაროს აღმოსაჩენად. ეს მნიშვნელოვანი დღე მასთან ერთად, მისი საყვარელი თამაშებით აღნიშნეთ. ყოჩაღ, დედიკო!') WHERE id = '493d8af7-6247-4790-9dba-5fe6ecd538f7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება ცხოვრების მესამე წლის პირველ დღეს! ბავშვი უკვე 2 წლის გახდა და თავს „დიდად“ გრძნობს. ამ პერიოდში ის საკუთარი ნივთებისა და სათამაშოების მიმართ უფრო მეტად ავლენს მესაკუთრეობის გრძნობას. მიეცით საშუალება, თავის ოთახში ან სათამაშო კუთხეში მცირე წესები თავად დააწესოს. ეს მას პასუხისმგებლობის გრძნობას უყალიბებს.') WHERE id = 'e1193c8b-9caf-42cc-b0d1-380bfd68848e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „კიბეზე დამოუკიდებლად ასვლა“. ბავშვს უკვე შეუძლია კიბეზე თითო საფეხურის გავლით, ყოველ საფეხურზე ფეხის მონაცვლეობით და მხოლოდ ერთი ხელის ჩაჭიდებით ასვლა. ეს აჩვენებს, რამდენად გაუძლიერდა ბარძაყის კუნთები და წონასწორობის უნარი. შეახსენეთ უსაფრთხოების წესები და თავდაჯერება შემატეთ.') WHERE id = '23cbdeb8-6ec7-49eb-b8f0-c4ae1a3cb46c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სიტყვათა მარაგის აფეთქება“. ბავშვი უკვე ყოველდღიურად რამდენიმე ახალ სიტყვას სწავლობს და 3-4 სიტყვისგან შემდგარ აზრიან წინადადებებს აწყობს. მაგალითად: „მე პარკში წასვლა მინდა“. მასთან საუბრისას დაუსვით ღია კითხვები: „რისი გაკეთება გინდა პარკში?“. ეს ავითარებს როგორც მის წარმოსახვას, ისე აზრის გამოხატვის უნარს.') WHERE id = 'c49d7f6c-cef1-458f-99cb-da68585b7ac5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „წრის დახატვა“. ბავშვი ფანქარს უკვე უფრო თავდაჯერებულად იჭერს და ქაღალდზე დაახლოებით წრის ფორმების დახატვას ცდილობს. ეს მისი ხელისა და თვალის კოორდინაციის ახალი დონეა. მიეცით ფერადი ფანქრები და დიდი ზომის ქაღალდები, რათა თავისი „პირველი ნახატების“ შექმნა შეძლოს.') WHERE id = '448009d5-07ef-4006-89f4-993bbe989179';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლობა: „მე თვითონ ვიცვამ“. ბავშვი უკვე არა მხოლოდ წინდების გახდას ახერხებს, არამედ მათ ჩაცმასაც ცდილობს, ან ადვილად ჩასაცმელ შარვალს ზემოთ იწევს. მიუხედავად იმისა, რომ ამ პროცესს შეიძლება დიდი დრო დასჭირდეს, ნუ ააჩქარებთ. მისთვის ყველაზე დიდი „ჯილდო“ რაიმეს დამოუკიდებლად გაკეთებაა. თქვენი მოთმინება მის თავდაჯერებას აძლიერებს.') WHERE id = 'ae5217ae-ff5f-4178-a4dd-001e8d391224';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „რიგის ცნება“. ბავშვს უკვე ესმის, რომ საქანელასთან ან სასრიალოსთან თავის რიგს უნდა დაელოდოს. ფრაზა „ახლა შენი ჯერია, შემდეგ კი შენი მეგობრის“ მისთვის უკვე უფრო გასაგებია. ეს სოციალური ადაპტაციისა და მოთმინების სწავლის ერთ-ერთი უმნიშვნელოვანესი ეტაპია.') WHERE id = 'fd888eb3-7169-4c50-bc0d-f0696ed103ff';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „ფერების დაჯგუფება“. ბავშვი უკვე სრულად განასხვავებს ერთმანეთისგან 4-5 სხვადასხვა ფერს და ბევრი მათგანის სახელიც იცის. ჩაუტარეთ პატარა გამოცდა და უთხარით: „ყველა ლურჯი სათამაშო მომეცი“. ასეთი თამაშები მის ვიზუალურ ანალიზსა და მეხსიერებას აძლიერებს.') WHERE id = '6aeca11f-b490-4362-b41c-539703e28816';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთზე ფეხის დარტყმა“. ბავშვს უკვე შეუძლია სირბილისას წონასწორობის დაუკარგავად დაარტყას წინ მდებარე ბურთს და მიზნისკენ მიმართოს. ამისთვის საჭიროა როგორც მოძრაობის კოორდინაცია, ისე ყურადღების ერთ წერტილზე კონცენტრირება. ეზოში მასთან ერთად პატარა „საფეხბურთო“ შეჯიბრი მოაწყვეთ და დაეხმარეთ, უფრო მოქნილი გახდეს.') WHERE id = 'da17a594-1250-4f85-98b1-50f0b6588294';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „როლური თამაშების გართულება“. ბავშვი უკვე რამდენიმე თანმიმდევრული მოქმედებისგან შემდგარ თამაშებს აწყობს: მაგალითად, სათამაშო დათუნიას „ბანს“, „ამშრალებს“ და შემდეგ „აძინებს“. ეს აჩვენებს, როგორ აერთიანებს ბავშვი მეხსიერებაში არსებულ ყოველდღიური ცხოვრების სცენარებს თანმიმდევრულად.') WHERE id = 'd343f65f-f46a-44dd-a5fc-a51c1510c094';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად კვება“. ბავშვი უკვე იმდენად კარგად იყენებს ჩანგალსა და კოვზს, რომ თითქმის არაფერს ღვრის. სრულად შეუწყვეთ ხელი, რომ საკვების მიღება თავად მართოს. ეს ძალიან მნიშვნელოვანია დანაყრების შეგრძნების გაცნობიერებისა და თავდაჯერებულობისთვის.') WHERE id = '61ba4f1e-aa7b-426a-97ad-a9a4240347af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში — „ნაწილებისგან მთლიანის აწყობა“. ბავშვს უკვე შეუძლია მარტივი, 4-6-ნაწილიანი ფაზლების ვიზუალურად აწყობა. ეს ავითარებს როგორც ყურადღების კონცენტრაციას, ისე პრობლემის გადაჭრის უნარს. თუ არ გამოსდის, მშვიდი ტონით დაეხმარეთ: „შეხედე, ეს ძაღლის კუდია, სად შეიძლება იყოს მისი ადგილი?“.') WHERE id = 'd008eb87-e4b7-4791-98e4-80774b7e5fc4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მხარს ზემოდან სროლა“. ბავშვი ბურთს უკვე უბრალოდ ძირს კი არ აგდებს, არამედ ცდილობს, მხარს ზემოდან (overhand) წინ ისროლოს. ეს მოძრაობა მთელი სხეულის კოორდინაციას მოითხოვს. პარკში მასთან ერთად ითამაშეთ თამაში „ვინ უფრო შორს გადააგდებს ბურთს?“.') WHERE id = '018d47a4-b94c-4bab-a923-24c091f9e302';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „თხოვნა და თავაზიანობა“. როცა ბავშვს რამე სურს, უკვე მხოლოდ თითით აღარ მიუთითებს და ცდილობს თქვას „მომეცი“ ან „გთხოვ“ (თუნდაც თავის ენაზე). თქვენი თავაზიანი მაგალითი მის კომუნიკაციის სტილს აყალიბებს. ყოველ ჯერზე, როცა „დიდი მადლობა“-ს ამბობთ, ბავშვიც ბუნებრივად ითვისებს ამ კულტურას.') WHERE id = '11cb7320-ce82-47a0-a231-8d9923b30f4a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მზაობა: „შიში და წარმოსახვა“. ამ ასაკში ბავშვებს ზოგჯერ შეიძლება სიბნელის ან გარკვეული ხმების შიში დაეწყოთ. ეს წარმოსახვის განვითარების ნიშანია. მის შიშს ნუ დასცინებთ — უბრალოდ მის გვერდით იყავით, ჩაეხუტეთ და აგრძნობინეთ, რომ უსაფრთხოდ არის. თქვენი მხარდაჭერა მის ემოციურ მდგრადობას აძლიერებს.') WHERE id = '4edde2f0-76ee-4d3a-a2af-2d7d71d87764';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რატომ?“ კითხვების ეტაპი იწყება. ბავშვი მის გარშემო არსებული ყველაფრის მიზეზით ინტერესდება. კითხვაზე „რატომ არის ასე?“ მარტივი და გულწრფელი პასუხები გაეცით. თქვენი ახსნა მის გონებაში სამყაროს ლოგიკურ სურათს ქმნის. მისი ცნობისმოყვარეობა არასდროს დატოვოთ უპასუხოდ — ეს სწავლის სურვილს გაუძლიერებს.') WHERE id = 'f3d92e61-3d30-4ede-90d4-27478dd2115f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური განვითარება: „დამოუკიდებლობა და საზღვრები“. როდესაც ბავშვს ყველაფრის დამოუკიდებლად გაკეთება სურს, მაგრამ არ გამოსდის, შეიძლება მძაფრი რეაქცია ჰქონდეს. ასეთ მომენტებში სიმშვიდე შეინარჩუნეთ და მისი განცდა სიტყვებით გამოხატეთ: „მესმის, რომ ამის დამოუკიდებლად გაკეთება გინდა“. თქვენი თანაგრძნობა მას ემოციების მართვის უნარის ჩამოყალიბებაში ეხმარება.') WHERE id = '1f37d9cd-995a-4d88-97e4-8b7fdb37e3d8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე სრულად გააზრებულად იყენებს ნაცვალსახელს „მე“. ისეთი წინადადებები, როგორებიცაა „მე მოვედი“ და „მე ვჭამე“, აჩვენებს, რომ ის საკუთარ თავს გარემოსგან განცალკევებულ პიროვნებად აღიქვამს. მხარი დაუჭირეთ მის დამოუკიდებელ გამონათქვამებს და განავრცეთ დიალოგი: „დიახ, შენ გემრიელი საჭმელი შეჭამე, ყოჩაღ!“.') WHERE id = 'bf78ea68-2a1f-4194-9ef3-62146ea4799d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ორი ფეხით წინ გადახტომა“. ბავშვს უკვე შეუძლია არა მხოლოდ ადგილზე, არამედ ოდნავ წინაც გადახტეს. ეს სხეულის კოორდინაციის მაღალ დონეზე მიუთითებს. პარკში მასთან ერთად ითამაშეთ თამაში „კურდღლები მინდორში ხტუნაობენ“. ეს მსხვილი მოტორიკის შესანიშნავი ვარჯიშია.') WHERE id = 'ce99df1c-1b81-4d41-b95d-9180c49c6d9f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მიზეზშედეგობრივი“ კავშირები. ბავშვს უკვე ესმის მოვლენებს შორის კავშირი: „წვიმს, დავსველდი“ ან „საჭმელი ცხელია, შეუბერე“. შეაქეთ მისი ასეთი ლოგიკური მსჯელობა. ეს აჩვენებს, რამდენად კარგად ვითარდება როგორც მისი მეტყველება, ისე აბსტრაქტული აზროვნების უნარი.') WHERE id = 'bcee9d16-cb48-4f63-9295-23b44110e7d6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „მოხრახნისა და დატრიალების ოსტატობა“. ბავშვს უკვე თავდაჯერებით შეუძლია ბოთლის თავსახურებისა და სათამაშო ხრახნების გახსნა და დახურვა. ეს მაჯის კუნთების მოქნილობის შესანიშნავი ვარჯიშია. მიეცით სხვადასხვა ზომის უსაფრთხო ჭურჭელი და მხარი დაუჭირეთ მის კვლევის ინტერესს.') WHERE id = 'bff29c40-0fa8-45dd-982c-f35a2f18ac52';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე მხოლოდ ფერებს კი არ ცნობს, არამედ მათი ერთმანეთთან შეხამებაც კარგად გამოსდის. თუ თქვენი თხოვნისას — „იპოვე შენი წითელი წინდის წყვილი“ — სწორ წინდას პოულობს, ეს მისი ვიზუალური აზროვნების განვითარების ნიშანია. ყოველდღიური ჩაცმისას ხშირად გაუსვით ხაზი ფერებს: „დღეს მწვანე მაისური ჩავიცვათ?“ ეს მის ლექსიკურ მარაგში ზედსართავ სახელებს განამტკიცებს.') WHERE id = 'f4611a68-9983-4caf-808b-4616cf4c60d5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ცალ ფეხზე წონასწორობის დაცვა“. ბავშვი უკვე ცდილობს, თუნდაც რამდენიმე წამით, ერთი ფეხი მიწიდან ასწიოს და წონასწორობა შეინარჩუნოს. ეს სხეულის სიმძიმის ცენტრის სამართავად საჭირო რთული კოორდინაციაა. ეთამაშეთ „ყარყატის თამაში“. ეს არა მხოლოდ სახალისოა, არამედ ფიზიკური განვითარებისთვისაც ძალიან სასარგებლოა.') WHERE id = 'c7634c82-b4b5-450c-9811-7e5cbdc218af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროის ცნების პირველი ნიშნები“. ბავშვი იწყებს ისეთი სიტყვების განსხვავების გაგებას, როგორიცაა „ახლა“ და „შემდეგ“. თუ თქვენი ნათქვამისას — „ჯერ ვჭამოთ, შემდეგ კი პარკში წავიდეთ“ — მოცდა შეუძლია, ეს მნიშვნელოვანი წინსვლაა. განაგრძეთ მოქმედებების საშუალებით დროითი თანმიმდევრობის ახსნა, რათა მას მოთმინების უნარი ჩამოუყალიბდეს.') WHERE id = '2c927604-0f3e-4615-94c5-86dc48b7896a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ზუსტი აწყობა“. ბავშვი უკვე უფრო აკურატულად აერთებს ერთმანეთს კონსტრუქტორის პატარა დეტალებს ან კუბებს. ეს მოითხოვს როგორც ყურადღების კონცენტრაციას, ისე თითის წვერების მოძრაობის სიზუსტეს. შეაქეთ მისი „საინჟინრო“ მცდელობები და ჰკითხეთ: „ეს ვისი სახლია?“') WHERE id = '92d8aec4-818c-4b3a-abd3-dd724c129df5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად წყლის დალევა“. ბავშვი უკვე თავდაჯერებულად სვამს წყალს ღია ჭიქიდან და თითქმის აღარ აქცევს. ეს იმის მაჩვენებელია, თუ რამდენად არის მისი ტუჩებისა და ყბის კუნთები მზად მეტყველებისთვის. კვლავ მიეცით ბავშვის ზომის, ხელში ადვილად დასაჭერი ჭიქები, რათა ეს უნარი სრულყოფილად აითვისოს.') WHERE id = '659e2094-8141-4a5a-bed6-c6f715c75799';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „იუმორი და ხუმრობები“. ბავშვმა შეიძლება განზრახ გააკეთოს რაღაც „არასწორად“ (მაგალითად, ქუდი ხელზე ჩამოიცვას), შემდეგ შემოგხედოთ და გაიცინოს. ეს აჩვენებს, რომ მას უყალიბდება იუმორის გაგება და სოციალური ზემოქმედების უნარი. ენთუზიაზმით აჰყევით მის ამ „თამაშს“. ერთად სიცილი თქვენ შორის ემოციურ კავშირს კიდევ უფრო გააღრმავებს.') WHERE id = 'c1045492-8f8e-491f-a86f-8a5ceb126f15';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „სიმაღლე და მანძილი“. ბავშვი კიბიდან ან დივნიდან ჩამოსვლისას მანძილს უკვე უკეთ აფასებს. ყოველთვის შეახსენეთ, რომ ფრთხილად იყოს და უსაფრთხოდ ჩამოვიდეს (ზურგით, ფეხებით წინ). ეს მნიშვნელოვანი ეტაპია სხეულის უსაფრთხოების წესების ათვისებისთვის.') WHERE id = 'c7630ee3-1695-4062-9e13-7540975aa465';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკუსვლით სიარულის ოსტატობა“. ბავშვს უკვე შეუძლია, უკან გახედვის გარეშე რამდენიმე ნაბიჯი უკუსვლით გადადგას. ეს მნიშვნელოვანია სივრცეში საკუთარი სხეულის მდებარეობის შეგრძნებისთვის (პროპრიოცეფციული შეგრძნება). უთხარით: „მოდი, კიბორჩხალასავით ვიაროთ“ და ეს მოძრაობა თამაშად აქციეთ. თქვენთან ერთად მოძრაობა მისთვის მსოფლიოში ყველაზე დიდი გართობაა.') WHERE id = 'e1577858-a1db-40b1-bd39-0ce8d678ff7a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სახელი-ნაცვალსახელის კავშირი“. ბავშვი საკუთარი სახელის ხსენებიდან სიტყვა „მე“-ს გამოყენებაზე უკვე სრულად გადადის. თუ თქვენს შეკითხვაზე პასუხად ამბობს „მე“ ან „ჩემი“, ეს მისი თვითიდენტობის განცდის სრულად ჩამოყალიბებაზე მიუთითებს. ამ თემაზე დიალოგები გამართეთ: „ვისია ეს ბურთი? ჩემია!“.') WHERE id = 'a37651fe-7cc3-4f59-bbce-f7763c1637a8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: ბავშვი სიტყვაზე „არ შეიძლება“ უკვე რეაგირებს, თუმცა ზოგჯერ წესებს კვლავ არღვევს, რათა თქვენი რეაქცია შეამოწმოს. ყველაზე მნიშვნელოვანია, შეინარჩუნოთ სიმშვიდე და ამავე დროს სიმტკიცე. თუ რამეზე „არა“ თქვით, ყოველ ჯერზე იგივე პასუხი გაიმეორეთ. წესების თანმიმდევრულობა ბავშვს შინაგანი წესრიგისა და უსაფრთხოების განცდას უყალიბებს.') WHERE id = '8f5c35ba-05d9-40e2-a687-7bfe8146f1ee';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '26-ე თვეში გადავდივართ! ბავშვს უკვე კარგად შეუძლია ორი განსხვავებული დავალების თანმიმდევრულად შესრულება. მაგალითად: „აიღე სათამაშო და თაროზე დადე“. ეს მიუთითებს, რომ როგორც მისმა მეხსიერებამ, ისე მეტყველების გაგების უნარმა განვითარების ახალ დონეს მიაღწია. დღის განმავლობაში ასეთი პატარა „დავალებები“ მიეცით, რათა თავი სასარგებლოდ იგრძნოს.') WHERE id = '86c6ccb4-326d-41d5-81c5-ea4c8d0faf13';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „სწრაფი მანევრი“. ბავშვს უკვე შეუძლია სირბილისას უეცრად შეიცვალოს მიმართულება ან დაბრკოლებებს მოხერხებულად აუაროს გვერდი. ეს როგორც კუნთების სიძლიერის, ისე სწრაფად გადაწყვეტილების მიღების უნარის მაჩვენებელია. პარკში მასთან ერთად „დაჭერობანა“ ითამაშეთ და სხეულის მართვის უნარის გაუმჯობესებაში დაეხმარეთ.') WHERE id = 'eb8969ec-bb8d-48c5-8dfb-f818249bf8e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მიზეზის ძიება“. მიუხედავად იმისა, რომ ბავშვი ჯერ სრულად ვერ ამბობს „რატომ?“, მოვლენების მიზეზებს თავისი ქმედებებით იკვლევს. აუხსენით: „ქურთუკს ვიცვამთ, რადგან გარეთ ქარია“. მოვლენებს შორის ლოგიკური კავშირის ჩვენება მომავალში მისი ლოგიკური აზროვნების განვითარების უმნიშვნელოვანესი საფუძველია.') WHERE id = 'f63d183c-6b97-43da-8c82-1a87c629cc0d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „მოხრახნისა და დატრიალების ოსტატობა“. ბავშვს უკვე თავდაჯერებულად შეუძლია ბოთლის თავსახურებისა თუ სათამაშო ხრახნების მოხსნა და დამაგრება. ეს მოძრაობა მაჯის კუნთების მოქნილობისთვის შესანიშნავი ვარჯიშია. მიეცით სხვადასხვა ზომის უსაფრთხო ჭურჭელი და ხელი შეუწყვეთ მექანიზმების აღმოჩენის მის სურვილს.') WHERE id = '583cd090-6bc1-4438-afd7-8703fd352e08';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი“ და ნებისყოფა. ბავშვს უკვე მტკიცე აზრი აქვს იმის შესახებ, თუ რა ჩაიცვას ან რომელი ჭურჭლიდან ჭამოს. არჩევანის შეთავაზება, მაგალითად: „დღეს ლურჯ მაისურს ჩაიცვამ თუ მწვანეს?“, ეხმარება მას, თავი დამოუკიდებელ პიროვნებად იგრძნოს და სიჯიუტის კრიზისებს მინიმუმამდე ამცირებს.') WHERE id = '5377658a-72e7-437d-b697-abdb7c76bfcd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თანამშრომლობა“ სოციალურ ქცევაში. ბავშვს უკვე დიდ სიამოვნებას ანიჭებს თქვენი დახმარება. როდესაც ეუბნებით: „მოდი, საყიდლების ჩანთიდან პური ამოვიღოთ“ და ის გიერთდებათ, ეს ნიშნავს, რომ ოჯახში საკუთარ როლს აცნობიერებს. ეს მას პასუხისმგებლობის გრძნობას უყალიბებს და თქვენ შორის კავშირსაც აძლიერებს.') WHERE id = '57201085-ec92-4795-8598-90d9a04fb33a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„კატეგორიები“ შემეცნებით განვითარებაში. ბავშვს უკვე შეუძლია ერთნაირი ტიპის საგნების დაჯგუფება (მაგალითად, ყველა ცხოველის ერთ ადგილას, ყველა მანქანის კი — სხვა ადგილას მოთავსება). დაუსვით ისეთი კითხვები, როგორიცაა: „აქ რომელი სათამაშოა განსხვავებული?“ და შეამოწმეთ მისი ვიზუალური ლოგიკა. კატეგორიებით აზროვნება მის შემეცნებით უნარებს ახალ საფეხურზე აიყვანს.') WHERE id = 'ffdc805c-2aad-4971-afc7-9cb3c0053b5c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორივე ფეხით ხტომის ოსტატობა“. ბავშვს უკვე თავდაჯერებულად შეუძლია ადგილზე უფრო მაღლა ან ოდნავ წინ გადახტომა. ეს მოძრაობა ფეხის კუნთების გაძლიერებაზე მიუთითებს. ეთამაშეთ „კურდღლები მინდორში“; ეს დიდი მოტორიკისთვის სახალისოცაა და სასარგებლოც.') WHERE id = 'dcd7700f-4c1a-40e7-9469-0739827e396d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ამბის მოყოლის მცდელობები“. ბავშვს ძალიან სურს, მოგიყვეთ დღის განმავლობაში ნანახი რაიმე საინტერესო (მაგალითად: „პარკში დიდი ძაღლი დავინახე“). ბოლომდე მოუსმინეთ მის ამბავს და კითხვებით განავრცეთ: „რას აკეთებდა ძაღლი?“. ეს აძლიერებს როგორც მის მეხსიერებას, ისე აზრის გამოხატვის უნარს.') WHERE id = 'e7fba00d-ba92-45d4-9c39-8a2e6decdc8c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური განვითარება: „თვითკონტროლი“. როცა ბავშვი ბრაზდება, შეიძლება შემოგხედოთ და თქვენს რეაქციას დაელოდოს. ასეთ დროს შეინარჩუნეთ სიმშვიდე და მისი გრძნობა დაასახელეთ: „ახლა გაბრაზებული ხარ, რადგან კუბები დაინგრა, მესმის შენი“. თქვენი სიმშვიდე მისთვის ემოციების მართვის საუკეთესო გაკვეთილია. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '4a2f0d04-3378-4296-a224-feb8d41e9254';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე არა მხოლოდ არჩევს ფერებს, არამედ ბევრი მათგანის სახელწოდებასაც სწორად წარმოთქვამს. თუ არ ცდება, როდესაც ეუბნებით: „ლურჯი მანქანა მომიტანე“, ეს მისი ვიზუალური და ვერბალური მეხსიერების ერთობლივი მუშაობის შედეგია. ყოველდღიური სეირნობისას განაგრძეთ მისი სამყაროს გაფერადება ისეთი აღწერებით, როგორიცაა „მწვანე ფოთოლი“ და „ყვითელი მზე“.') WHERE id = '57505a63-7f8c-48f6-bce2-90daca2c8189';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „კიბეზე დამოუკიდებლად ასვლა“. ბავშვს უკვე შეუძლია, როდესაც ერთი ხელით გიჭირავთ, კიბეზე თითო საფეხურზე ფეხების მონაცვლეობით ასვლა სცადოს. ეს მსხვილი მოტორიკის მნიშვნელოვანი მიღწევაა. ყოველთვის ახლოს იყავით და დაიცავით, თუმცა აგრძნობინეთ ნდობა, რათა დამოუკიდებლად გადადგას ნაბიჯები.') WHERE id = 'e9641593-3c91-4cf3-a6cc-b86c93ef50be';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სივრცითი მიმართებების აღმნიშვნელი სიტყვები“. ბავშვი უკვე მოქმედებით აჩვენებს ისეთ ცნებებს, როგორიცაა „ზემოდან“, „ქვემოდან“ და „უკან“. ითამაშეთ მასთან პატარა თამაში და უთხარით: „ბურთი სკამის ქვეშ დადე“. ასეთი დავალებები სწრაფად ავითარებს როგორც ენის გაგებას, ისე სივრცეში ორიენტაციის უნარს.') WHERE id = '2ff11d89-9e65-4caa-b39f-98e5298d4503';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „დახარისხება და ლოგიკა“. ბავშვი უკვე იწყებს საგნების გარჩევას არა მხოლოდ ფერის, არამედ ზომის მიხედვითაც (დიდი-პატარა). მიეცით სხვადასხვა ზომის ჭურჭელი და სთხოვეთ, ერთმანეთში ჩააწყოს. ეს მისი სამომავლო მათემატიკური აზროვნების საფუძველია.') WHERE id = 'cd04a6bc-1fab-4d68-920a-3fa77ebf8503';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვიცვამ“ ეტაპი უფრო რთულდება. ბავშვი უკვე ცდილობს ელვა-შესაკრავის შეკვრას (მას შემდეგ, რაც თქვენ დაუწყებთ) ან დიდი ღილების გახსნას. ამ პროცესში ხელს ნუ შეუშლით და ნუ ააჩქარებთ. იმის დანახვა, რომ რაღაც თავად შეუძლია, მისთვის თავდაჯერებულობის ყველაზე დიდი წყაროა. აუცილებლად წაახალისეთ ყოველი პატარა წარმატებისთვის.') WHERE id = '701a4eec-68f9-49ca-9e96-f1cb4b81484e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში ემპათია იზრდება. როდესაც ბავშვი ხედავს, რომ თქვენ ან სხვა ბავშვი მოწყენილი ხართ, შეიძლება მოვიდეს, თავისი სათამაშო შემოგთავაზოთ ან ჩაგეხუტოთ. ეს მისი ემოციური ინტელექტის (EQ) შესანიშნავი მაჩვენებელია. დააფასეთ მისი მზრუნველობა და უთხარით: „დიდი მადლობა, რომ მხარში მიდგახარ“.') WHERE id = 'db3deaea-d927-47d7-b65e-09bbf47b377f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარება: „ფორმა და ზომა“. ბავშვს უკვე შეუძლია ერთი და იმავე ფორმის (მაგალითად, წრის) დიდი და პატარა ვარიანტების გარჩევა. აჩვენეთ, როგორ ჩააწყოს სხვადასხვა ზომის ჭურჭელი ერთმანეთში. ეს უვითარებს „დალაგების“ უნარს, რომელიც სამომავლო მათემატიკური აზროვნების საფუძველია.') WHERE id = '1317ee1d-1c19-4d58-ab70-d9a1fa691c6f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და დამიზნება“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, გარკვეული მიმართულებით გააგოროს. ეს მხედველობითი ყურადღებისა და მოძრაობის კოორდინაციის შერწყმაა. სახლში ან პარკში ერთად მოაწყვეთ „პატარა კარი“ და ითამაშეთ მასში ბურთის გატანაზე. ეს ბავშვს ფეხის კუნთებს გაუძლიერებს და სიზუსტეს განუვითარებს.') WHERE id = 'c1e87167-2300-4b17-9def-ab985555b55e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველება: „ამბის მოყოლის მცდელობები“. ბავშვს ძალიან უნდა, მოგიყვეთ დღის განმავლობაში ნანახი რაიმე საინტერესო (მაგალითად, „დიდი ძაღლი დავინახე“). ბოლომდე მოუსმინეთ მის ამბავს და კითხვებით განავრცეთ: „ძაღლი რას აკეთებდა?“. ეს აძლიერებს როგორც მის მეხსიერებას, ისე აზრის გამოხატვის უნარს.') WHERE id = '404203bc-920b-47d3-b584-2989b01e93ee';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: ბავშვმა შესაძლოა უკვე მტკიცედ გამოხატოს საკუთარი ნება და თქვას: „მე არ მინდა“. ასეთ დროს გაჯიუტების ნაცვლად, არჩევანის შესაძლებლობა მიეცით და ყურადღება სხვა რამეზე გადაატანინეთ. თქვენი მოთმინება და თანმიმდევრული წესები ბავშვს უსაფრთხოების განცდას უქმნის. თქვენ შესანიშნავად ართმევთ თავს!') WHERE id = '17f5e755-5dec-4458-9be1-0d08e0586eaf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „ერთნაირი და განსხვავებული“. ბავშვს უკვე შეუძლია ერთნაირი ტიპის საგნების დაჯგუფება (მაგალითად, ყველა ცხოველის ერთ ადგილას, ხოლო ყველა მანქანის — სხვა ადგილას მოთავსება). დაუსვით შეკითხვები, როგორიცაა: „აქ რომელი სათამაშოა განსხვავებული?“ და შეამოწმეთ მისი ვიზუალური ლოგიკა. კატეგორიებით აზროვნება მის კოგნიტიურ განვითარებას ახალ საფეხურზე გადაიყვანს.') WHERE id = '09d14134-1ab9-423c-86bd-46c0a52d2f86';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და სირბილი“. ბავშვს უკვე შეუძლია სირბილისას მის წინ მდებარე ბურთს წონასწორობის დაკარგვის გარეშე დაარტყას. ეს არა მხოლოდ სახალისოა, არამედ ძალიან სასარგებლოცაა ფიზიკური განვითარებისთვის. სახლში ან ეზოში მსუბუქი ბურთით ეთამაშეთ, რათა მოძრაობის სისწრაფეც და სიზუსტეც განუვითაროთ.') WHERE id = '39fb4064-3e7d-4aa6-b4d5-c75b564c92cc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მოგონების გადმოცემა“. ბავშვს შეუძლია გაიხსენოს დღის განმავლობაში მომხდარი მარტივი ამბავი (მაგალითად, „პარკში ძაღლი ვნახე“) და მოგიყვეთ. ყურადღებით მოუსმინეთ მის მონათხრობს და შეკითხვით „შემდეგ რა მოხდა?“ დაეხმარეთ მოვლენების თანმიმდევრულად გადმოცემაში. ეს მის მეხსიერებასაც აძლიერებს და აზრის გამოხატვის უნარსაც.') WHERE id = '109cbe57-dd82-4d85-b381-3ebd329772ab';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური განვითარება: „თვითკონტროლის მცდელობები“. გაბრაზებისას ბავშვმა შეიძლება შემოგხედოთ და თქვენს რეაქციას დაელოდოს. ასეთ დროს სიმშვიდე შეინარჩუნეთ და მისი გრძნობა დაასახელეთ: „ახლა გაბრაზებული ხარ, რადგან სათამაშო ვერ ააწყვე“. თქვენი სიმშვიდე მისთვის ემოციების მართვის საუკეთესო გაკვეთილია. თქვენ შესანიშნავი დედა ხართ!') WHERE id = 'cbb6c494-b75d-458c-b798-2ddf1bf9e334';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 27-ე თვეში! ბავშვი უკვე სრულად ითვისებს „ორსაფეხურიან“ დამახსოვრებას. როდესაც ეუბნებით: „აიღე შენი სათამაშო და ყუთში ჩადე“, ორივე მოქმედებას თანმიმდევრულად ასრულებს. ეს თავის ტვინის პრეფრონტალური ქერქის განვითარებაზე მიუთითებს. დღის განმავლობაში მცირე და ლოგიკური დავალებები მიეცით, რათა ეს უნარი კიდევ უფრო დახვეწოს.') WHERE id = '0b872b3f-49b7-446a-bc7c-dfae010fe461';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „კიბეზე ჩამოსვლის ოსტატობა“. ბავშვს უკვე შეუძლია, ხელით რომ გიჭირავთ, კიბეზე უფრო თავდაჯერებულად, თითო საფეხურზე თითო ნაბიჯით ჩამოსვლა სცადოს. ჩამოსვლა ასვლაზე რთულია, რადგან მეტ წონასწორობას მოითხოვს. ყოველთვის ახლოს იყავით, დაიცავით დაცემისგან და მისი წარმატება ტაშით აღნიშნეთ.') WHERE id = '912ef746-569e-455d-af72-84d6cc3f170e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე სრულად გააზრებულად იყენებს ნაცვალსახელს „მე“. ისეთი წინადადებები, როგორებიცაა „მე მოვედი“ და „მე ვჭამე“, ადასტურებს, რომ ის საკუთარ თავს გარემოსგან განცალკევებულ პიროვნებად აღიქვამს. მხარი დაუჭირეთ მის დამოუკიდებელ გამოთქმებს და გააფართოეთ დიალოგი: „დიახ, შენ გემრიელი საჭმელი შეჭამე, ყოჩაღ!“.') WHERE id = '12f036fb-3726-4e17-bff9-217ad09dba7b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ბორდიურის კიდეზე სიარული“. როცა ბავშვს ხელს ჰკიდებთ, ის უკვე ინტერესდება დაბალ ბორდიურზე სიარულით. ეს მას წონასწორობის უფრო რთული უნარის განვითარებაში ეხმარება. უსაფრთხო ადგილებში მხარი დაუჭირეთ ამ ინტერესს, რადგან ის მომავალში უფრო რთული ფიზიკური მოძრაობების შესრულების საფუძველია.') WHERE id = '292c2a9d-2b19-4e22-9095-add20bbbeaf5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სამსიტყვიანი წინადადებების გახშირება“. ბავშვი უკვე უფრო რთულ წინადადებებს აყალიბებს, მაგალითად: „დედა, წყალი მომეცი“, „მამა, პარკში წავიდეთ“. მას უკვე შეუძლია საკუთარი საჭიროებების სრულად გამოხატვა. დაადასტურეთ მისი ნათქვამი და ოდნავ გააფართოეთ წინადადებები: „დიახ, მოდი, ახლა წყალი დავლიოთ, შემდეგ კი პარკში წავალთ“. ეს მის გრამატიკულ აღქმას ავითარებს.') WHERE id = '7132fa94-7590-4b27-b006-e5936aaf0907';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „ფაზლების აწყობის ოსტატობა“ უმჯობესდება. ბავშვს უკვე დამოუკიდებლად შეუძლია მარტივი, 6-8-ნაწილიანი ფაზლების აწყობა. ეს მოითხოვს როგორც ვიზუალურ ანალიზს, ისე თითების კუნთების ზუსტ მოძრაობას. ყოველ ჯერზე, როცა სურათს დაასრულებს, სიხარულით შეხვდით მის წარმატებას, რათა უფრო რთული დავალებების მიმართ ინტერესი გაუძლიერდეს.') WHERE id = 'd4e00b50-79ce-485c-9a88-f514c156f1f6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვალაგებ“. სათამაშოების თავის ადგილზე დალაგება მისთვის უკვე უბრალოდ დავალება კი არა, პასუხისმგებლობაცაა. თუ სიტყვებზე „მოდი, მანქანები თავიანთ საწოლში ჩავაწვინოთ“ დახმარებას გიწევთ, ეს დისციპლინის საფუძველია. ეს ჩვევა მომავალში მისი პირადი მოწესრიგებულობისთვის ძალიან მნიშვნელოვანი იქნება.') WHERE id = '03327c5a-8698-4e34-8b71-2d0914f0f88b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „რიგის დაცვა“. ბავშვს უკვე ესმის, რომ პარკში საქანელაზე დასაჯდომად ან სათამაშოთი სათამაშოდ ცოტა ხნით მოცდაა საჭირო. თამაშებით — „ახლა ჩემი ჯერია, შემდეგ კი შენი“ — ასწავლეთ მას მოთმინება. ეს უნარი მომავალში საბავშვო ბაღისა და სკოლის გარემოსთან მისი ადაპტაციისთვის ერთ-ერთი უმნიშვნელოვანესი სოციალური საფუძველია.') WHERE id = '3ea5aca0-7734-4b06-864f-00aa21361675';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ზედსართავი სახელებისა და ზმნიზედების ერთობლივი გამოყენება“. ბავშვს უკვე შეუძლია თქვას არა უბრალოდ „მანქანა“, არამედ „სწრაფი წითელი მანქანა“. სამყაროს აღსაწერად ის უფრო მეტ დეტალს იყენებს. მასთან საუბრისას ხაზი გაუსვით საგნების თვისებებს: „ეს მძიმე ქვაა“, „ეს რბილი ბალიშია“. ეს მის ლექსიკურ მარაგს ხარისხობრივად ამდიდრებს.') WHERE id = 'c940fb90-c1d6-4fa5-8baf-334e41b324f8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „შემოქმედება და კოორდინაცია“. ბავშვი უკვე უფრო მიზანმიმართულ წრეებს ან ქაოსურ, მაგრამ მკვეთრ ხაზებს ავლებს ქაღალდზე. მიეცით ფერადი ფანქრები და დიდი ზომის ფურცლები, რათა თავისუფლად შემოქმედებისთვის სივრცე შეუქმნათ. ეს უვითარებს კუნთოვან მეხსიერებას, რომელიც მომავალში წერისთვის დასჭირდება.') WHERE id = 'c40de8f9-d507-4cfb-810d-f904e8901ddd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმის მცდელობები“. ბავშვს უკვე არა მხოლოდ წინდის გახდა შეუძლია, არამედ დაჟინებით ცდილობს ქუდის დახურვასა და ფეხსაცმლის ჩაცმას. ამ პროცესისთვის რამდენიმე დამატებითი წუთი გამოუყავით. თუ არ დააჩქარებთ და შესაძლებლობას მისცემთ, რაღაც დამოუკიდებლად გააკეთოს, ეს მის თავდაჯერებასა და დამოუკიდებლობის განცდას გააძლიერებს.') WHERE id = 'c38e076c-fc5e-4ef7-ba82-49913f3b0c34';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „სიმბოლური ზრუნვა“. ბავშვმა შეიძლება სათამაშო დათუნიას „წყალი დაალევინოს“, საბანი დააფაროს ან, როცა ის „ტირის“, მოეფეროს. ეს მისი ემოციური ინტელექტისა და სხვების გრძნობების გაგების უნარის განვითარებაზე მიუთითებს. არ დაგავიწყდეთ მისი ასეთი მზრუნველი ქცევის შექება.') WHERE id = 'cbccdb44-553a-4ef8-8729-9f35675d89bf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „თვლის საფუძვლები“. მიუხედავად იმისა, რომ ბავშვი ჯერ რიცხვებს თანმიმდევრულად ვერ ითვლის, „ერთსა“ და „ორს“ შორის რაოდენობრივ განსხვავებას ვიზუალურად უკვე აღიქვამს. მიეცით ორი ვაშლი და უთხარით: „ერთი შენია, ერთი — ჩემი“, რათა გაზიარება და თვლა ერთად აჩვენოთ. ეს მისი მათემატიკური აზროვნების ყველაზე ადრეული საფუძველია.') WHERE id = '1953c2df-b74a-440f-aeda-02c40c3b1d9f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორი ფეხით წინ გადახტომა“. ბავშვს უკვე შეუძლია არა მხოლოდ ადგილზე, არამედ ოდნავ წინაც გადახტეს. ეს ფეხის კუნთების ძალასა და სხეულის კოორდინაციას მოითხოვს. მასთან ერთად ითამაშეთ თამაში „კურდღლები მინდორში დახტიან“. ეს ერთდროულად სახალისოცაა და მსხვილი მოტორიკის შესანიშნავი ვარჯიშიც.') WHERE id = '9999afba-b8a0-474d-b26c-6136ec804e12';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვა-პასუხის დიალოგი“. ბავშვს უკვე შეუძლია, მარტივი კითხვები დაგისვათ: „მამა სად არის?“, „ეს რა არის?“. პასუხისას გამოიყენეთ ვრცელი წინადადებები: „მამა სამსახურში წავიდა და საღამოს დაბრუნდება“. თქვენი დეტალური ახსნა ბავშვის გონებაში მოვლენებს შორის ლოგიკურ კავშირებს ამყარებს.') WHERE id = 'e0d072d6-3ce1-4139-b80e-a94b53d2fc54';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 800 დღე შევასრულეთ! ბავშვმა უკვე კარგა ხანია, რაც 2 წლის ასაკს გადააბიჯა და ყოველდღე რაღაც ახალს აღმოაჩენს. მას უკვე ესმის მარტივი წესები, მკაფიოდ გამოხატავს ემოციებს და თქვენთან სრულფასოვან ურთიერთობას ამყარებს. აღნიშნეთ ეს დღე მასთან ერთად მის საყვარელ პარკში. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '1df3c116-f7da-4df5-8d7e-4570b51bb9eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '27-ე თვის შუა პერიოდს ვუახლოვდებით. ბავშვი უკვე უფრო ღრმად აღიქვამს „ჯერ“ და „შემდეგ“ თანმიმდევრობას. როდესაც ეუბნებით: „ტანსაცმელი ჩაიცვი და შემდეგ გარეთ გავიდეთ“, მას ესმის, რომ მეორე მოქმედება ჯილდოა. ეს ბავშვში მოთმინებისა და დაგეგმვის უნარის პირველი საფუძვლებია. ხშირად შეახსენეთ ეს თანმიმდევრობა ყოველდღიური რიტუალების დროს.') WHERE id = 'bf2725f4-a91c-46df-b906-cbe0eca9ab09';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ცოცვის ოსტატობა“. ბავშვი უკვე უფრო თავდაჯერებულად ადის პარკის პატარა კიბეებზე ან სახლში უსაფრთხო სიმაღლეებზე. ამ დროს ხელებისა და ფეხების კუნთები სინქრონულად მუშაობს. ყოველთვის ახლოს იყავით, თუმცა მიეცით საშუალება, საკუთარი ძალები მოსინჯოს.') WHERE id = '03ce58c6-bf39-4cb2-86c0-fb921289cb85';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ლოგიკური კავშირები“. ბავშვი უკვე ორ მოვლენას ერთ წინადადებაში აერთიანებს: „გარეთ ცივა, ქურთუკი ჩაიცვი“. ეს აჩვენებს, რომ ის მხოლოდ კი არ ბაძავს, არამედ აზროვნებს კიდეც. დაუდასტურეთ მისი ასეთი ლოგიკური მსჯელობა სიტყვებით: „დიახ, მართალი ხარ“, რათა საკუთარი აზრების გამოხატვის მეტი სურვილი გაუჩნდეს.') WHERE id = '70d20b90-08cb-4a3d-b635-39b5e961b0df';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ქაღალდით მანიპულირება“. ბავშვმა შეიძლება უკვე გამოიჩინოს ინტერესი ქაღალდის დაკეცვის ან მარტივად დაჭრის მიმართ (დიდი საბავშვო მაკრატლით, თქვენი მეთვალყურეობის ქვეშ). ეს მოქმედებები თითების კუნთების მართვის უნარს ახალ დონეზე გადაიყვანს. შეუქმენით პირობები, რომ ფერადი ქაღალდებით სხვადასხვა მოქმედება შეასრულოს.') WHERE id = '1867a29d-cdef-4c25-9fb4-31fe661ffbe5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „როლური თამაშების გართულება“. ბავშვი უკვე ირგებს „ექიმის“, „მზარეულის“ ან „მძღოლის“ როლს. ამ თამაშების მეშვეობით ის გარშემომყოფთა საქმიანობას ეცნობა და თანაგრძნობას სწავლობს. ჩაერთეთ მის თამაშებში და მოიქეცით იმ „როლის“ შესაბამისად, რომელსაც ის მოგანიჭებთ.') WHERE id = '09d954dd-f762-40e1-8030-11d38ef87b47';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ხელების დაბანის“ ჩვევა. ბავშვს უკვე თითქმის დამოუკიდებლად შეუძლია ხელების საპნით დაბანა და წყლით ჩამობანა. ამ ასაკში ჰიგიენური ჩვევების განმტკიცება ძალიან მნიშვნელოვანია. დაუდგით მისი სიმაღლის შესაბამისი საფეხურიანი სკამი (step stool), რათა ეს პროცესი მისთვის სასიამოვნო იყოს.') WHERE id = '8f3c97e4-28e2-4575-994c-03b54f2a86ed';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „იპოვე განსხვავებული“. ბავშვს უკვე შეუძლია ნივთების ჯგუფიდან ვიზუალურად გამოარჩიოს განსხვავებული (მაგალითად, მანქანებს შორის ვაშლი). ეს მის ანალიზის უნარს ავითარებს. სახლში მოუწყეთ მარტივი თამაში „რომელია ზედმეტი?“. ეს სამომავლო მათემატიკური და ლოგიკური ამოცანებისთვის შესანიშნავი მომზადებაა.') WHERE id = '0c2d9534-6a6b-4045-844a-9433e0a69d75';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ცალ ფეხზე დგომის მცდელობები“. ბავშვს უკვე შეუძლია, თუნდაც რამდენიმე წამით, ერთი ფეხი მიწიდან ასწიოს და წონასწორობის შენარჩუნება სცადოს. ეს მნიშვნელოვანია იმისთვის, რომ სხეულმა სიმძიმის ცენტრის მართვა ისწავლოს. ითამაშეთ მასთან „ყარყატის თამაში“ და შეამოწმეთ, ვინ შეძლებს ცალ ფეხზე უფრო დიდხანს დგომას.') WHERE id = '5d944b43-095b-4d92-b030-b834a56949f2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „გრძნობების გამოხატვა“. ბავშვს უკვე შეუძლია სიტყვებით თქვას, რომ მოწყენილია, მხიარულია ან ეშინია: „მე შემეშინდა“ ან „მე მხიარული ვარ“. გრძნობებისთვის სახელების დარქმევა ბავშვის ემოციური ინტელექტის საფუძველია. როდესაც ის თავის გრძნობებზე საუბრობს, მოუსმინეთ და უთხარით: „დიახ, მესმის შენი“, რათა აჩვენოთ, რომ მის გრძნობებს აღიარებთ.') WHERE id = 'cb48e516-3844-4090-848b-2afd50d005de';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის ძალა: „უხილავი მეგობრები და საგნები“. ბავშვმა შეიძლება ჯოხი „ცხენად“ აქციოს და მასზე ამხედრებულივით ირბინოს. ეს სიმბოლური აზროვნების მწვერვალია – იმის გაგება, რომ ერთ საგანს შეუძლია სხვა რამ განასახიეროს. ეს უნარი მომავალში ძალიან მნიშვნელოვანია კითხვისა და მათემატიკისთვის (სიმბოლოების გასაგებად).') WHERE id = '76d9591a-d7e3-4913-96a8-5d2c420ccc81';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '27-ე თვის ბოლო ათდღეულს ვიწყებთ! ბავშვი უკვე არა მხოლოდ ცნობს ფერებს, არამედ მათი ერთმანეთთან შეხამებაც შესანიშნავად შეუძლია. თუ დავალებას — „იპოვე შენი წითელი წინდის მეწყვილე“ — სწორად ასრულებს, ეს მისი ვიზუალური აზროვნების განვითარების ნიშანია. ყოველდღიური ჩაცმისას ხშირად გაუსვით ხაზი ფერებს.') WHERE id = '5063e9dc-6139-4c88-93fd-950678f58bde';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში იწყება „კიბეზე დამოუკიდებლად მოძრაობის“ ეტაპი. ბავშვი უკვე ცდილობს, ცალი ხელით დაჭერისას კიბეზე ავიდეს და თითოეულ საფეხურზე მონაცვლეობით თითო ფეხი დადგას. ეს მსხვილი მოტორიკის განვითარებაში მნიშვნელოვანი მიღწევაა. ყოველთვის ახლოს იყავით და მისი უსაფრთხოება დაიცავით, თუმცა აგრძნობინეთ, რომ ენდობით და დამოუკიდებლად ნაბიჯის გადადგმის საშუალება მიეცით.') WHERE id = 'd4f943d2-bf71-4b16-b7d0-f1be4b723a37';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში ჩნდება „დროის ზმნიზედების პირველი ნიშნები“. ბავშვი უკეთ იწყებს ისეთი სიტყვების განსხვავების გაგებას, როგორებიცაა „ახლა“, „შემდეგ“ და „ცოტა ხანში“. თუ ფრაზის — „ჯერ ვჭამოთ, შემდეგ კი პარკში წავიდეთ“ — მოსმენისას ლოდინი შეუძლია, ეს მისი ნებისყოფის გაძლიერებაზე მიუთითებს. მოქმედებების საშუალებით დროითი თანმიმდევრობის ახსნა განაგრძეთ.') WHERE id = 'ad12a2ff-a0f6-446e-a287-18ac0e3ed236';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „ფაზლის აწყობის ოსტატობა“ ვითარდება. ბავშვს უკვე შეუძლია 6-9-ნაწილიანი მარტივი ფაზლების დამოუკიდებლად აწყობა. სურათების ვიზუალურად გაერთიანება აუმჯობესებს როგორც ყურადღების კონცენტრაციას, ისე პრობლემების გადაჭრის უნარს. თუ ვერ გამოსდის, მშვიდი ტონით მიეცით მინიშნებები.') WHERE id = 'ca532b10-de2c-4db5-9614-e001b1908ea1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი“ პიკს აღწევს. ბავშვს უკვე ჩამოყალიბებული აზრი აქვს იმის შესახებ, თუ რა ჩაიცვას ან რომელი სათამაშოთი ითამაშოს. არჩევანის შეთავაზება, მაგალითად, „დღეს ლურჯ ქუდს დაიხურავ თუ მწვანეს?“, ეხმარება მას, თავი დამოუკიდებელ პიროვნებად იგრძნოს და სიჯიუტის გამოვლინებები მინიმუმამდე ამცირებს.') WHERE id = 'fb9fc561-26c7-41b4-bbe1-31eada18c85f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში ვითარდება „რიგის დალოდების“ უნარი. ბავშვს უკვე ესმის, რომ პარკში საქანელაზე დასაჯდომად ცოტა ხნით მოცდაა საჭირო. თამაშებით — „ახლა მისი ჯერია, შემდეგ კი შენი“ — მოთმინება ასწავლეთ. ეს უნარი სოციალური ადაპტაციის ერთ-ერთი უმნიშვნელოვანესი საფუძველია.') WHERE id = '9df47b2e-3d86-40c8-a4bd-0d995655814b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „სიმაღლე და მანძილი“. ბავშვი კიბიდან ან დივნიდან ჩამოსვლისას მანძილს უკვე უკეთ აფასებს. ყოველთვის შეახსენეთ, რომ ფრთხილად იყოს და უსაფრთხოდ ჩამოვიდეს (ზურგით). ეს მნიშვნელოვანი ეტაპია სხეულის უსაფრთხოების წესების ათვისების პროცესში.') WHERE id = '0f7477b8-a1ff-4761-b386-ffe1e44a9a7a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და მიზანში მოხვედრა“. ბავშვი ბურთს უკვე უბრალოდ კი არ ურტყამს, არამედ ცდილობს, გარკვეული მიმართულებით გააგოროს. ეს მხედველობითი ყურადღებისა და მოძრაობის კოორდინაციის შერწყმაა. სახლში ან პარკში გაუკეთეთ „პატარა კარი“ და ითამაშეთ ბურთის კარში გატანა.') WHERE id = '050cfb5f-db53-4311-8b9f-fbb09f54e915';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ამბის მოყოლის მცდელობები“. ბავშვს ძალიან სურს, მოგიყვეთ დღის განმავლობაში ნანახი რაიმე საინტერესო (მაგალითად, „დიდი ძაღლი დავინახე“). ბოლომდე მოუსმინეთ მის ამბავს და კითხვებით განავრცეთ: „რა ფერის იყო ძაღლი?“. ეს აძლიერებს როგორც მის მეხსიერებას, ისე საკუთარი აზრის გამოხატვის უნარს.') WHERE id = 'd7af8a5b-1016-4dc8-921f-52af71c3d954';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: ბავშვმა შესაძლოა უკვე მკვეთრად გამოხატოს საკუთარი ნება და თქვას: „მე არ მინდა“. ასეთ დროს მასთან დაპირისპირების ნაცვლად, შესთავაზეთ არჩევანი და ყურადღება სხვა რამეზე გადაატანინეთ. თქვენი მოთმინება და თანმიმდევრული წესები ბავშვს უსაფრთხოების განცდას უყალიბებს. თქვენ შესანიშნავად ართმევთ თავს!') WHERE id = '80c062ac-b271-45ec-b67c-016fb884ca5b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '28-ე თვეში გადავდივართ! ბავშვი უკვე მარტივად ასრულებს „ორსაფეხურიან“ დავალებებს. მაგალითად: „აიღე შენი სათამაშო და თაროზე დადე“. ეს აჩვენებს, რომ მისმა მეხსიერებამ და ენის გაგების უნარმა განვითარების ახალ დონეს მიაღწია. დღის განმავლობაში მიეცით მცირე და ლოგიკური „დავალებები“, რათა პასუხისმგებლობის გრძნობა ჩამოუყალიბდეს.') WHERE id = 'a1060bb5-066a-438b-aafd-d9c5d706c7bc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „კიბეზე ჩამოსვლის ოსტატობა“. როცა ბავშვს ხელით იჭერთ, ის უკვე ცდილობს, კიბეზე უფრო თავდაჯერებულად ჩამოვიდეს და თითოეულ საფეხურზე თითო ფეხი დადგას. ჩამოსვლა ასვლაზე რთულია, რადგან მეტ წონასწორობას მოითხოვს. ყოველთვის ახლოს იყავით, დაიცავით დაცემისგან და მისი წარმატება შეაქეთ.') WHERE id = '05b34d22-95f5-4000-aee3-08f747372e4d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ზედსართავი სახელებისა და ზმნიზედების ერთობლივი გამოყენება“. ბავშვს უკვე შეუძლია თქვას არა უბრალოდ „მანქანა“, არამედ „სწრაფი წითელი მანქანა“. სამყაროს აღსაწერად ის უფრო მეტ დეტალს იყენებს. მასთან საუბრისას ხაზი გაუსვით საგნების თვისებებს: „ეს მძიმე ქვაა“, „ეს რბილი ბალიშია“. ეს მის ლექსიკურ მარაგს თვისებრივად ამდიდრებს.') WHERE id = '5838f818-d4e0-42c7-ba01-7e6420078ed2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „აწყობა და შენება“. ბავშვი კუბებისგან უკვე არა მხოლოდ კოშკს, არამედ „ღობეს“, „მატარებელს“ ან „სახლს“ აშენებს. ეს მისი ვიზუალურ-სივრცითი აზროვნებისა და წარმოსახვის ერთობლივი გამოვლინებაა. დაუსვით კითხვები მის ნაგებობებზე: „აქ ვინ ცხოვრობს?“.') WHERE id = '46a64e62-d979-410f-9a15-a2c7bbeb1ba9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი“ და ნებისყოფა. ბავშვს უკვე მტკიცე აზრი აქვს იმის შესახებ, თუ რა ჩაიცვას ან რომელი ჭურჭლიდან ჭამოს. მიეცით არჩევანის შესაძლებლობა, მაგალითად: „დღეს ლურჯი მაისური ჩაიცვა თუ მწვანე?“ ეს ეხმარება მას, თავი დამოუკიდებელ პიროვნებად იგრძნოს და სიჯიუტის ეპიზოდებს მინიმუმამდე ამცირებს.') WHERE id = 'f2f6cbfc-bdac-4534-9233-ecd8a693e212';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „სიმბოლური ზრუნვა“. ბავშვმა შეიძლება სათამაშო დათუნიას „წყალი დაალევინოს“, საბანი დააფაროს ან „უმკურნალოს“. ეს მისი ემოციური ინტელექტისა და სხვების გრძნობების გაგების უნარის განვითარების ნიშანია. აუცილებლად შეაქეთ ასეთი მზრუნველი ქცევისთვის.') WHERE id = '8ddc104a-ab8a-4e5a-943d-543dc807df66';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „იპოვე განსხვავებული“. ბავშვს უკვე შეუძლია საგნების ჯგუფიდან ვიზუალურად გამოარჩიოს განსხვავებული საგანი (მაგალითად, ვაშლი მანქანებს შორის). ეს მის ანალიზის უნარს ავითარებს. სახლში მოუწყეთ მარტივი თამაში „რომელია ზედმეტი?“. ეს მომავალი ლოგიკური დავალებებისთვის შესანიშნავი მომზადებაა.') WHERE id = 'a2b9980c-2bf2-401b-8655-ae5a31b2d842';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორი ფეხით წინ გადახტომა“. ბავშვს უკვე შეუძლია არა მხოლოდ ადგილზე ახტომა, არამედ ოდნავ წინ გადახტომაც. ამისთვის საჭიროა ფეხის კუნთების ძალა და სხეულის კოორდინაცია. ითამაშეთ მასთან თამაში „კურდღლები მინდორში დახტიან“. ეს ერთდროულად სახალისოცაა და მსხვილი მოტორიკის შესანიშნავი ვარჯიშიც.') WHERE id = '3b71e4fe-1f75-478c-bb70-76e4d5347b3d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვა-პასუხის დიალოგი“. ბავშვს უკვე შეუძლია მარტივი კითხვები დაგისვათ: „სად არის მამა?“, „ეს რა არის?“. პასუხის გაცემისას გამოიყენეთ ვრცელი წინადადებები: „მამა სამსახურში წავიდა და საღამოს დაბრუნდება“. თქვენი დეტალური განმარტებები მის გონებაში მოვლენებს შორის ლოგიკურ კავშირებს აძლიერებს.') WHERE id = '12f65b1a-8cde-4d4d-842d-5197bc6d6352';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის ძალა: „როლების გაცვლა“. ბავშვმა შეიძლება მოგბაძოთ, „დედა“ გახდეს ან თავისი სათამაშოები „სამსახურში წაიყვანოს“. ეს აჩვენებს, რამდენად კარგად იმახსოვრებს და ღრმად აკვირდება მოვლენებს შორის ლოგიკურ კავშირებს. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '1d0c6c5d-a275-43bf-bb3b-a961c2f6805e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე არა მხოლოდ არჩევს ფერებს, არამედ სულ მცირე 3-4 ძირითადი ფერის (წითელი, ლურჯი, მწვანე, ყვითელი) დასახელებასაც იწყებს. როდესაც ჰკითხავთ: „ეს რა ფერია?“, დიდია ალბათობა, რომ სწორად გიპასუხებთ. სეირნობისას მანქანებისა და ყვავილების ფერებზე კითხვით ეს ცოდნა განუმტკიცეთ.') WHERE id = '44e5c106-bbab-44d6-a4ac-bc4a1418e1eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ერთ ფეხზე წონასწორობის შენარჩუნება“. ბავშვს უკვე შეუძლია, თუნდაც რამდენიმე წამით, ერთი ფეხი იატაკიდან ასწიოს და წონასწორობის შენარჩუნება სცადოს. ეს სხეულის სიმძიმის ცენტრის სამართავად საჭირო რთული კოორდინაციაა. ეთამაშეთ „ყარყატის თამაში“. ეს არა მხოლოდ სახალისოა, არამედ ძალიან სასარგებლოცაა ფიზიკური განვითარებისთვის.') WHERE id = 'fbfbb0b9-9b09-4a23-9066-c80337eab4d6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროის აღქმის პირველი ნიშნები“. მართალია, ბავშვს სიტყვები „გუშინ“ და „ხვალ“ ჯერ ბოლომდე არ ესმის, მაგრამ უკვე არჩევს სიტყვებს „ახლა“, „შემდეგ“ და „ცოტა ხანში“. თუ ეუბნებით: „ჯერ ხელები დავიბანოთ, შემდეგ კი პური ვჭამოთ“ და მას მოცდა შეუძლია, ეს მისი ნებისყოფის გაძლიერებაზე მიუთითებს. განაგრძეთ მოქმედებების საშუალებით დროითი თანმიმდევრობის ახსნა.') WHERE id = 'a4ffacc2-0d5e-4231-a5d0-f90a33b4d6f5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „წრისა და ხაზის ოსტატობა“. ბავშვი უკვე უფრო მიზანმიმართულ წრეებს ან ქაოსურ, თუმცა გაბედულ სწორ ხაზებს ავლებს ქაღალდზე. მიეცით ფერადი ფანქრები და დიდი ზომის ფურცლები, რათა თავისი „პირველი ნახატები“ შექმნას. ეს მომავალი წერის უნარებისთვის ერთ-ერთი უმნიშვნელოვანესი ვარჯიშია.') WHERE id = 'efd8c509-5660-43d7-a555-e496a390e478';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '28-ე თვის ბოლო ათ დღეს ვიწყებთ! ბავშვი უკვე მარტივად ასრულებს ორსაფეხურიან დავალებებს. მაგალითად: „აიღე სათამაშო და თაროზე დადე“. ეს მიუთითებს, რომ მისმა მუშა მეხსიერებამ და მეტყველების გაგების უნარმა განვითარების ახალ დონეს მიაღწია. დღის განმავლობაში ასეთი პატარა „დავალებების“ მიცემით მას პასუხისმგებლობის გრძნობასა და ყურადღებას განუვითარებთ.') WHERE id = '1fed649f-83be-432e-bf3b-958f939d1d57';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური აქტივობის ახალი ეტაპი — „კიბეზე ასვლის ოსტატობა“. ბავშვს უკვე შეუძლია, მხოლოდ ერთ ხელზე მოჭიდებულმა სცადოს კიბეზე თითო ნაბიჯით ასვლა — თითოეულ საფეხურზე ერთი ფეხის დადგმით. ეს ბარძაყისა და მენჯის კუნთების გაძლიერებაზე მიუთითებს. ყოველთვის ახლოს იყავით, დაიცავით დაცემისგან და მისი წარმატებები შეაქეთ.') WHERE id = '2104ca19-971d-4ad2-bad2-4fb0d5fce478';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში ჩნდება „მიზეზშედეგობრივი“ გამონათქვამები. ბავშვმა შესაძლოა უკვე სცადოს თქვას „იმიტომ, რომ“ (ან ამის მსგავსი ბგერები), რათა ახსნას, რატომ სურს რაღაც. თქვენც აუხსენით მიზეზები: „ახლა ნაყინს არ ვჭამთ, იმიტომ, რომ ცივა“. ეს მისი ლოგიკური აზროვნებისა და არგუმენტების ჩამოყალიბების უნარის საფუძველია.') WHERE id = '9a1ea5be-b73b-4171-a8a3-6f9f06ff6d11';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილი მოტორიკა — „მოხრახვნა და დატრიალება“. ბავშვს უკვე შეუძლია ბოთლის თავსახურებისა და სათამაშო ხრახნების თავდაჯერებულად მოშვება და მოჭერა. ასეთი მოძრაობა მაჯის მბრუნავი მოძრაობისთვის საჭირო კუნთების შესანიშნავი ვარჯიშია. მიეცით სხვადასხვა ზომის უსაფრთხო ჭურჭელი და ხელი შეუწყვეთ მის ინტერესს ასეთი მექანიკური მოქმედებებისადმი.') WHERE id = '326af733-89d5-4b18-a86d-69d50b560d32';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვიბან“. ბანაობისას ბავშვი იღებს საპონს ან ღრუბელს, ცდილობს სხეული დაიბანოს და მოგბაძოთ. ნუ ჩაუხშობთ ჰიგიენური ჩვევებისადმი მის ინტერესს. საკუთარი თავის „გასუფთავება“ ეხმარება როგორც სხეულის ნაწილების უკეთ გაცნობაში, ისე ადრეული ასაკიდან პირად ჰიგიენაზე პასუხისმგებლობის გამომუშავებაში.') WHERE id = '059ef4bc-ae23-4023-aa71-ac7bfd7a180d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გაზიარების სირთულე“. ამ ასაკში შეძახილი „ჩემია!“ სრულიად ნორმალურია. ბავშვი საკუთარი ნივთების დაცვას სწავლობს. ნუ აიძულებთ გაზიარებას; ამის ნაცვლად გამოიყენეთ პრინციპი: „მოდი, რიგრიგობით ვითამაშოთ“. თქვენი მოთმინება მის სოციალურ ინტელექტს აყალიბებს.') WHERE id = '89f6ed5e-1781-4f77-8a89-eea339ecb1d6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმის“ დაჟინებული სურვილი. ბავშვი უკვე არა მხოლოდ წინდების გახდას ცდილობს, არამედ დაჟინებით ცდილობს ქუდის დახურვასა და ადვილად ჩასაცმელი ფეხსაცმლის ჩაცმასაც. ამ პროცესისთვის მას რამდენიმე დამატებითი წუთი მიეცით. თუ არ დააჩქარებთ და საშუალებას მისცემთ, თავად გაართვას თავი, ეს მას თავდაჯერებულობისა და დამოუკიდებლობის განცდის ჩამოყალიბებაში დაეხმარება.') WHERE id = 'ea6058fd-22cb-454f-b6df-36b6c6f564fd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „იუმორი და ხუმრობა“. ბავშვმა შეიძლება განზრახ გააკეთოს რაღაც „არასწორად“ (მაგალითად, ქუდი ხელზე ჩამოიცვას), შემდეგ შემოგხედოთ და გაიცინოს. ეს მიუთითებს, რომ მას იუმორის აღქმა და სხვებზე სოციალური ზემოქმედების უნარი უყალიბდება. ხალისით აჰყევით მის ამ „თამაშს“. ერთად სიცილი თქვენს შორის ემოციურ კავშირს კიდევ უფრო გააღრმავებს.') WHERE id = '90539d1c-30bc-43ec-8cb5-e89edef1568e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „სიმაღლე და მანძილი“. ბავშვი კიბიდან ან დივნიდან ჩამოსვლისას მანძილს უკვე უკეთ აფასებს. ყოველთვის შეახსენეთ, რომ ფრთხილად იყოს და უსაფრთხოდ, ზურგით ჩამოვიდეს. ეს მნიშვნელოვანი ეტაპია სხეულის უსაფრთხოების წესების ათვისებისა და რისკების ვიზუალურად შეფასების უნარის განვითარებისთვის.') WHERE id = '00eb14eb-16c9-4d20-9af4-97c177dc49f5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკუსვლით სიარული“. ბავშვს უკვე შეუძლია, უკან მოუხედავად რამდენიმე ნაბიჯი გადადგას უკუსვლით. ეს მნიშვნელოვანია სივრცეში საკუთარი სხეულის მდებარეობის შეგრძნებისთვის (პროპრიოცეპტული შეგრძნება). უთხარით: „მოდი, კიბორჩხალასავით ვიაროთ“ და ეს მოძრაობა თამაშად აქციეთ. ამგვარი სიარულისას ფეხის კუნთები განსხვავებულად მუშაობს.') WHERE id = '2b4f1496-5d34-4f25-9ad5-91b67ba2967b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სახელი-ნაცვალსახელის კავშირი“. ბავშვი საკუთარი სახელის წარმოთქმიდან ნაცვალსახელ „მე“-ს გამოყენებაზე უკვე სრულად გადადის. თუ თქვენს კითხვაზე პასუხად ამბობს „მე“ ან „ჩემი“, ეს მისი პიროვნული თვითშეგნების სრულად ჩამოყალიბებაზე მიუთითებს. ამ თემაზე მასთან დიალოგები გამართეთ: „ვისია ეს ბურთი? ჩემია!“. თქვენ შესანიშნავი გზის მაჩვენებელი ხართ!') WHERE id = '61b67af6-b8e7-43c0-aeec-e2ba32964d5a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: ბავშვს უკვე შეუძლია, მკაფიოდ გამოხატოს საკუთარი ნება და თქვას: „მე არ მინდა“. ასეთ დროს მასთან გაჯიუტების ნაცვლად არჩევანის შესაძლებლობა მიეცით და ყურადღება სხვა რამეზე გადაატანინეთ. თქვენი მოთმინება და თანმიმდევრული წესები ბავშვს უსაფრთხოების განცდას უყალიბებს. 840 დღე წარმატებით გავიარეთ – თქვენ საუკეთესოს იმსახურებთ!') WHERE id = 'f92d1e9f-889d-441d-90aa-ab2a51e762a4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „შესატყვისობის პოვნა“ (Matching). ბავშვს უკვე შეუძლია ერთი და იმავე ცხოველის განსხვავებული სურათების ან ერთნაირი ფერის ნივთების ერთმანეთთან შეწყვილება. ეთამაშეთ მარტივი ბარათებით თამაში „იპოვე მსგავსი“. ეს სწრაფად ავითარებს როგორც მის ვიზუალურ ყურადღებას, ისე კატეგორიების მიხედვით აზროვნების უნარს.') WHERE id = '1b1a5af3-541e-4a8b-826b-94504ae0251e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის შორს გადაგდება“. ბავშვი ბურთს უკვე უბრალოდ ძირს კი არ აგდებს, არამედ ცდილობს, ის მხარს ზემოდან (overhand) წინ გაისროლოს. ეს მოძრაობა მთელი სხეულის კოორდინაციას მოითხოვს. პარკში ეთამაშეთ თამაში „ვინ უფრო შორს გადააგდებს ბურთს?“. ეს მას მკლავებსაც გაუძლიერებს და მანძილის აღქმის უნარსაც გაუუმჯობესებს.') WHERE id = '985bce91-74bc-40ac-bdc4-be9aa7dbfeab';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „თხოვნის გამოხატვა“. როდესაც ბავშვს რამე სურს, უკვე მხოლოდ თითით კი არ მიუთითებს, არამედ შეუძლია თქვას „მომეცი“ ან „თუ შეიძლება“ (ან მსგავსი შეძახილი). ყოველ ჯერზე მიეცით თავაზიანი მეტყველების მაგალითი. თქვენგან „გმადლობთ“ ან „თუ შეიძლება“ სიტყვების მოსმენა მისი მომავალი ურთიერთობის კულტურას ჩაუყრის საფუძველს.') WHERE id = 'edefb696-9b37-48b2-bf5d-42c196545bf4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის გაძლიერება: „როლური თამაშები რთულდება“. ბავშვი უკვე უბრალოდ საჭმელს კი არ ამზადებს, არამედ სათამაშოებს სტუმრად იწვევს, „მკურნალობს“ ან „მანქანაში სვამს და სამსახურში მიჰყავს“. ეს გვიჩვენებს, როგორ აერთიანებს ის მეხსიერებაში შენახულ მოვლენებს. შეუერთდით მას ამ როლურ თამაშებში — ეს მის შემოქმედებით უნარებს მწვერვალამდე აიყვანს.') WHERE id = '22acecd0-67df-4601-b0d7-23a57c3444c3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 29-ე თვეში! ბავშვი უკვე იწყებს უფრო რთული პასუხების გაცემას, ვიდრე მხოლოდ „კი“ და „არაა“. კითხვაზე „რატომ გინდა ეს?“ შეიძლება უპასუხოს: „იმიტომ, რომ გემრიელია“ ან „იმიტომ, რომ წითელია“. ეს სიტყვებით საკუთარი შინაგანი მოტივაციის გამოხატვის უნარის დასაწყისია. ყურადღებით მოუსმინეთ მის ყოველ „იმიტომ, რომ“-ს.') WHERE id = '0e94d08f-2dfb-49bd-b8dc-5b547bbc54de';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „დინამიკური წონასწორობა“. ბავშვი უკვე ინტერესდება დაბალ ხაზზე ან იატაკზე დადებულ თოკზე „თოკზე მოსიარულესავით“ სიარულით. ეს ავითარებს მისი სხეულის შეგრძნებას (პროპრიოცეფციას). სახლში ფერადი ლენტებით ბილიკები გააკეთეთ და ამ უნარის განვითარებაში დაეხმარეთ.') WHERE id = '82c3b72a-274b-4062-9adf-7e5cce134bd3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მრავლობითი რიცხვის სუფიქსები“. ბავშვი უკვე არა მხოლოდ ხვდება განსხვავებას სიტყვებს „ვაშლი“ და „ვაშლები“ შორის, არამედ ცდილობს, ეს მეტყველებაშიც გამოიყენოს. აჩვენეთ მას სათამაშოები და უთხარით: „ნახე, აქ ბევრი მანქანაა“, რათა მრავლობითი რიცხვის ცნება განუმტკიცოთ. ეს იმაზე მიუთითებს, რომ მისი მეტყველების გრამატიკული სტრუქტურა უფრო რთული ხდება.') WHERE id = '64529c1d-caa7-4ac1-a772-2e82ed067453';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „თითების ძალა“. ბავშვს უკვე შეუძლია ტანსაცმლის სამაგრების (სარჭების) მოჭერა და გახსნა ან პლასტილინით მუშაობისას უფრო პატარა ნაჭრების მოწყვეტა. ეს მოძრაობები თითების მცირე კუნთებს აძლიერებს და ბავშვს მომავალში ფანქრის სწორად დაჭერისთვის ამზადებს.') WHERE id = 'e1008078-204c-4a5c-bac1-d07adf97ca32';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „სიმბოლური გაზიარება“. ბავშვი უკვე ცდილობს, სხვა ბავშვს სათამაშო ხელიდან მაშინვე არ წაართვას, უთხრას „მომეცი“ და დაელოდოს. ეს თვითრეგულაციის უნარის პირველი ჩანასახებია. როცა მის ასეთ მომთმენ ქცევას შეამჩნევთ, აუცილებლად შეაქეთ და უთხარით: „დიდი მადლობა, რომ შენს რიგს დაელოდე“.') WHERE id = '7f709f10-5a18-4150-b7b4-fa822721b9c8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვამზადებ“. ბავშვს სამზარეულოში თქვენი დახმარება ძალიან სიამოვნებს: ცომის მოზელა, ბოსტნეულის დაჭრა (უსაფრთხო დანით) ან სუფრაზე კოვზების დალაგება. ეს არა მხოლოდ მის მოტორულ უნარებს ავითარებს, არამედ საკვების მიმართ ინტერესსაც ზრდის.') WHERE id = '53d5b167-fe89-4403-8e4d-0684f94ae9c5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „თანმიმდევრობა და მეხსიერება“. ბავშვმა უკვე იცის თავისი საყვარელი ზღაპრის ან მულტფილმის მოვლენების თანმიმდევრობა. თუ ამბავს შეცდომით მოუყვებით, შესაძლოა შეგისწოროთ და გითხრათ: „არა, დათვი მოვიდა!“ ეს მიუთითებს, რომ მას კარგად აქვს განვითარებული ხანგრძლივი მეხსიერება და სიუჟეტური ხაზის აღქმის უნარი.') WHERE id = '51d45576-0732-4e17-9d1f-994a457d540c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ადგილზე ხტომა და შემოტრიალება“. ბავშვი უკვე უბრალოდ ზემოთ კი არ ხტება, არამედ ხტომისას ჰაერში სხეულის შემოტრიალებასაც ცდილობს. ეს რთულ ვესტიბულარულ კოორდინაციას მოითხოვს. ითამაშეთ მასთან რბილ ხალიჩაზე „აკრობატული“ თამაშები.') WHERE id = '9536e69d-203e-4017-ae80-dbe2f9eab99b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „საკუთარი თავის აღწერა“. ბავშვს უკვე შეუძლია თავისი მდგომარეობის შესახებ გითხრათ: „მე დიდი ვარ“, „მე დავრბივარ“. დადექით მასთან ერთად სარკის წინ და საკუთარი თავის შეცნობის პროცესი სახალისო გახადეთ ისეთი კითხვებით, როგორებიცაა: „რა ფერის თვალები გაქვს?“ და „სად არის შენი ცხვირი?“') WHERE id = 'eca2c14e-98c5-475b-94e6-e55601d2febb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური განვითარება: „დამოუკიდებლობის კრიზისი“. როდესაც ბავშვს ყველაფრის დამოუკიდებლად გაკეთება სურს და არ გამოსდის, შეიძლება ძალიან გაბრაზდეს. ასეთ დროს შეინარჩუნეთ სიმშვიდე და მხარი დაუჭირეთ სიტყვებით: „ახლა გაბრაზებული ხარ, რადგან ეს რთულია. მოდი, ერთად გავაკეთოთ“. თქვენი სიმშვიდე ყველაზე საიმედო ნავსაყუდელია, რომელიც მის ემოციურ ქარიშხალს აცხრობს.') WHERE id = '9fa6b04b-2e13-4b5c-ba62-6d1e0398948e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია ფერების არა მხოლოდ „წითლად“ ან „ლურჯად“ აღქმა, არამედ მათი მსგავსი ელფერების ვიზუალურად გარჩევაც. აჩვენეთ მას მწვანე ფერის სხვადასხვა ელფერის ფოთლები და ჰკითხეთ: „რომელია უფრო მუქი?“ ეს მის ვიზუალური ანალიზის უნარს ავითარებს.') WHERE id = '1d89cf33-54f4-473a-9dbf-869b4e96ac30';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ცალ ფეხზე ხტომის მცდელობები“. ბავშვი უკვე ცდილობს ცალ ფეხზე ოდნავ ახტომას. ეს კოჭის სიძლიერისა და წონასწორობის შესანარჩუნებლად საკმაოდ რთული მოძრაობაა. შეაქეთ მისი ეს გაბედული მცდელობები და მხარი დაუჭირეთ, რათა დაცემის შემთხვევაშიც არ დაკარგოს შემართება.') WHERE id = 'c09edac9-8b37-4347-a8dd-3e14699e7139';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „წარსული დროის პირველი ნიშნები“. ბავშვი უკვე მომხდარი მოვლენების აღსაწერად იყენებს ისეთ ზმნებს, როგორებიცაა: „წავედი“, „ვნახე“, „ვჭამე“. საღამოს ესაუბრეთ თემაზე: „რა გავაკეთეთ დღეს?“ ეს მას მეხსიერებასაც განუმტკიცებს და დროის აღქმის უნარსაც განუვითარებს.') WHERE id = '5e30771f-35e9-43cb-9e6c-1bfc3d0ea335';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „მიზანმიმართული გაფერადება“. ბავშვი უკვე ცდილობს ქაღალდზე გამოსახული დიდი ფიგურის (მაგალითად, წრის) შიგნით გაფერადებას ისე, რომ კონტურებს ძალიან არ გადასცდეს. ეს ხელის კუნთების კონტროლის მხრივ მნიშვნელოვანი წინსვლაა. შესთავაზეთ მარტივი გასაფერადებელი ფურცლები დიდი და მკაფიო კონტურებით.') WHERE id = '30b62203-ae1a-48ab-82d9-d252856f8bcb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე დამხმარე ვარ“. ბავშვი სახლში მცირე დასუფთავების საქმეებს (მტვრის გადაწმენდა, სათამაშოების ყუთში ჩალაგება) უკვე არა როგორც თამაშს, არამედ როგორც მოვალეობას ეკიდება. მიეცით მას საკუთარი პატარა საწმენდი ტილო. ეს მასში ოჯახური პასუხისმგებლობისა და მიკუთვნებულობის განცდას საოცრად აძლიერებს.') WHERE id = '75e40c4f-895e-4725-bab2-0bb5ec9f1edc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „მეგობრობის პირველი ნიშნები“. ბავშვს უკვე უხარია, როცა პარკში ნაცნობ ბავშვს ხედავს და თავის სათამაშოს სთავაზობს. ეს უბრალოდ ერთმანეთის გვერდით თამაშიდან ერთად თამაშზე (ინტერაქციულ თამაშზე) გადასვლის ეტაპია. მისი ეს სოციალური ნაბიჯები დადებითი სიტყვებით წაახალისეთ.') WHERE id = '73a7095e-32dd-413f-b911-0ace0be7e88d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „სიმაღლე და მოცულობა“. ბავშვი უკვე ვიზუალურად ადარებს, რომელ ჭიქაში ეტევა მეტი წყალი ან რომელი კოშკია უფრო მაღალი. ბანაობისას სხვადასხვა ზომის ჭურჭლით წყლის თამაში ითამაშეთ. კითხვა „რომელი ჭურჭელი აივსება უფრო სწრაფად?“ ფიზიკური სამყაროს შესახებ მის ცოდნას გააღრმავებს.') WHERE id = '3cf32da0-166e-4863-bf9c-f4ea80d66e98';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სირბილისას ბურთის მართვა“. ბავშვი უკვე ცდილობს, სირბილისას ბურთი ფეხით წინ წაიღოს (დრიბლინგი). ეს მოძრაობის სიჩქარისა და ფეხის სიზუსტის სინქრონიზაციას მოითხოვს. ღია ცის ქვეშ მასთან ერთად აქტიური საფეხბურთო თამაშები ითამაშეთ, რათა ენერგია სასარგებლოდ დახარჯოს.') WHERE id = 'c300bf1e-a81a-4d08-9bfb-583735c02aab';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „აბსტრაქტული კითხვები“. ბავშვი უკვე სვამს კითხვებს არა მხოლოდ „ეს რა არის?“, არამედ თვალით უხილავი მოვლენების შესახებაც, მაგალითად: „ჩიტი სად გაფრინდა?“ ან „მზე სად წავიდა?“. პასუხებში წარმოსახვაც ჩართეთ: „მზე დასაძინებლად წავიდა“. ეს მისი წარმოსახვისა და მოვლენების ღრმად გააზრების მაჩვენებელია.') WHERE id = '5d13e772-b0dc-414e-be1a-eb306de1058d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: ბავშვი პასუხის „არა“ მოსმენისას უკვე აღარ იწყებს მაშინვე ტირილს, როგორც ადრე, და ცდილობს მიზეზის გაგებას. წესები მშვიდი ტონით აუხსენით: „ახლა კანფეტს არ ვჭამთ, რადგან ვახშმის დროა“. თქვენი თანმიმდევრული და გონივრული ქცევა ბავშვს თვითკონტროლისა და მოთმინების უნარებს უვითარებს.') WHERE id = 'd426c7f4-84e8-442d-bd5f-c6c23fc0839f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარების უნარი — „თანმიმდევრობით დალაგება და შედარება“. ბავშვს უკვე შეუძლია 3-4 ობიექტის ზომის მიხედვით დალაგება. მიეცით სხვადასხვა ზომის კუბები და უთხარით: „ყველაზე პატარა ზემოდან დადე“. ეს ხელს უწყობს როგორც ვიზუალური ანალიზის, ისე ადრეული მათემატიკური აზროვნების განვითარებას. ყოველი სწორად შესრულებული ნაბიჯისას გაამხნევეთ სიტყვებით: „რა ყურადღებიანი ხარ!“') WHERE id = '4204844b-c0b2-424d-bc6a-7ddffcbc310c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის შორს, მიზანში სროლა“. ბავშვი უკვე უბრალოდ კი არ ისვრის ბურთს, არამედ უფრო ზუსტად მიმართავს კონკრეტული წერტილისკენ (მაგალითად, კალათისკენ ან თქვენკენ). ეს ხელისა და თვალის კოორდინაციისა და სიღრმის აღქმის (მანძილის აღქმის) ერთობლიობაა.') WHERE id = '2d64c34e-bf0d-4efe-9c0e-d67a9a461b59';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „კითხვა-პასუხის ჯაჭვი“. ბავშვი თქვენს კითხვებს უკვე მხოლოდ „კი/არა“-თი კი არა, სრული წინადადებებით პასუხობს. კითხვაზე „დღეს რა ნახე?“ შეიძლება გიპასუხოთ: „დიდი ხე დავინახე“. მასთან საუბრისას მეტყველების სტიმულირებისთვის დაუსვით დამატებითი კითხვები, როგორიცაა: „რა ფერის იყო?“ და „სად იყო?“') WHERE id = 'e8d19883-dd1e-49e0-bcde-510b73e5bdc1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '880 დღე შესრულდა! ბავშვი მალე 2 წლისა და ნახევრის (30 თვის) გახდება. ახლა ის როგორც ფიზიკურად, ისე ემოციურად უფრო ძლიერია. მას უკვე შეუძლია საკუთარი გრძნობების დასახელება („მხიარული ვარ“, „გავბრაზდი“). დღეს მასთან ერთად გატარებული ყოველი წამი მის მეხსიერებაში წარუშლელ დადებით კვალს ტოვებს. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '6218d94c-c601-40e6-8296-e74639caa069';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 30-ე თვეში — ბავშვი უკვე 2 წლისა და ნახევრისაა! ამ პერიოდში ბავშვი საკუთარ თავს უკვე სრულფასოვან პიროვნებად აღიქვამს. ის საკუთარი საზღვრების დასადგენად ამბობს: „ეს ჩემია“ ან „მე თვითონ გავაკეთებ“. მის დამოუკიდებლობისკენ სწრაფვას მოთმინებით მოეკიდეთ; ეს მისი ხასიათის ჩამოყალიბებისთვის ძალიან მნიშვნელოვანია.') WHERE id = '8c2026bd-7655-4fc6-8c90-c09af022e3d7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „დინამიკური წონასწორობა“. ბავშვს უკვე შეუძლია ცალ ფეხზე რამდენიმე წამის განმავლობაში (3-5 წამი) დამოუკიდებლად დგომა. ეს მისი ნათხემის განვითარებისა და კუნთების კოორდინაციის მაჩვენებელია. მასთან ერთად ითამაშეთ „ყარყატის თამაში“ და ნახეთ, ვინ შეძლებს უფრო დიდხანს დგომას.') WHERE id = '59136234-e72e-461f-a081-2d86fdd6b1f1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '29-ე თვის ბოლო ათ დღეს ვიწყებთ! ბავშვი უკვე თითქმის უშეცდომოდ იყენებს ნაცვალსახელებს „მე“ და „შენ“. საუბრისას საკუთარ სურვილებს მტკიცედ გამოხატავს: „მე ეს მინდა“. მხარი დაუჭირეთ საკუთარი „მე“-ს გაცნობიერებაში და აჩვენეთ, რომ პატივს სცემთ მის გადაწყვეტილებებს — ეს ჯანსაღი თავდაჯერებულობის საფუძველია.') WHERE id = '4a584dfd-3b1f-4ba7-b2c3-765c25e1ca50';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ხტომა და დაშვება“. ბავშვი უკვე ბედავს დაბალი საფეხურიდან (მაგალითად, ტროტუარის კიდიდან) ორივე ფეხით ერთდროულად მიწაზე ჩამოხტომას. ეს დიდი მიღწევაა როგორც ფეხის კუნთების გასაძლიერებლად, ისე სივრცეში წონასწორობის შეგრძნების განსავითარებლად. ყოველთვის ახლოს იყავით და უსაფრთხოება დაუზღვიეთ.') WHERE id = '55d65f2d-a7aa-455b-9e97-2b3375627fc7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კავშირების გამოყენება“. ბავშვი უკვე აერთიანებს ორ აზრს ისეთი სიტყვებით, როგორებიცაა „და“, „მაგრამ“, „რადგან“: „მე გავიქეცი და დავეცი“. ეს მიანიშნებს, რომ მისი აზროვნება უფრო სისტემური და თანმიმდევრული ხდება. მასთან საუბრისას თქვენც გამოიყენეთ ეს კავშირები და წინადადებები ოდნავ გაართულეთ.') WHERE id = 'a1740f48-0bf0-4597-985c-859e4a235e6b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „კვანძებისა და შეკვრისადმი ინტერესი“. ბავშვი უკვე ცდილობს ფეხსაცმლის თასმების მოქაჩვას, ღილების გახსნას ან მსხვილი მძივების ძაფზე აცმას. ეს მოქმედებები თითების კოორდინაციას მნიშვნელოვნად ავითარებს. მიეცით სხვადასხვა ფაქტურის ძაფები და ნახვრეტებიანი სათამაშოები, რათა ეს ინტერესი წაახალისოთ.') WHERE id = '17adcdf9-4e22-4431-92cb-4bcd0b67e350';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმის“ უნარი. ბავშვს უკვე კარგად გამოსდის შარვლის აწევა ან მარტივი მაისურის ჩაცმა (მას შემდეგ, რაც თავს გაუყრით). წაახალისეთ სიტყვებით: „აბა, ახლა წინდების ჩაცმა სცადე“. დამოუკიდებლობისკენ გადადგმული ეს პატარა ნაბიჯები ეხმარება, ყოველდღიურ ცხოვრებაში თავი უნარიან პიროვნებად იგრძნოს.') WHERE id = '306f738c-086a-4ef8-9272-59796c9176d7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წესების გააზრება“. ბავშვს უკვე ესმის სახლში ან პარკში მოქმედი გარკვეული წესები („ჭამის წინ ხელების დაბანა“, „სასრიალოზე რიგის დაცდა“). ზოგჯერ შეიძლება ამ წესების დარღვევა მოუნდეს, თუმცა თქვენი თანმიმდევრულობა ეხმარება, სოციალური ნორმები შინაგან დისციპლინად აქციოს.') WHERE id = '4a18c5ac-a958-4970-b854-89448eb42394';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული ცნებები“. ბავშვი უკვე იწყებს ისეთი გრძნობების დასახელებას, როგორიცაა „სიყვარული“, „ბედნიერება“ ან „შიში“. როდესაც გეუბნებათ „მიყვარხარ“ ან სიტყვებით „შემეშინდა“ ჩასახუტებლად მოდის, ეს მიუთითებს, რომ მისი ემოციური ინტელექტი (EQ) სწრაფად ვითარდება. ყოველთვის აღიარეთ და მიიღეთ მისი გრძნობები.') WHERE id = '2c9c993e-8ed6-4bde-970b-e837e161f321';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ვერტიკალური და ჰორიზონტალური ხაზები“. ბავშვი ფანქარს უკვე უფრო თავდაჯერებულად იჭერს და ქაღალდზე ერთმანეთზე გადაფარული ქაოსური ხაზების ნაცვლად უფრო მიზანმიმართულ სწორ ხაზებს ავლებს. მიეცით სხვადასხვა ფერის ფანქრები და შესთავაზეთ „გზების“ ან „კიბეების“ დახატვა.') WHERE id = '2e6c20d2-ff7f-4e05-b377-0a03f81606ea';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი ჰიგიენა“. ბავშვს უკვე სურს, თავად გაიხეხოს კბილები (თქვენი მეთვალყურეობით), დაისაპნოს ხელები და კარგად ჩამოიბანოს. ამ ასაკში ამ ჩვევების თამაშის ფორმით განმტკიცება დაეხმარება, მომავალში პასუხისმგებლობით მოეკიდოს პირად ჰიგიენას.') WHERE id = '9f592616-f0c7-4018-8751-de7b0540a2d9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „როლური თამაშები“. ბავშვი უკვე თავად ქმნის „სცენარს“: სათამაშოებს სტუმრად იწვევს, „ჩაის ასმევს“ ან „აძინებს“. ამ თამაშების მეშვეობით ის უფროსების სამყაროს ბაძავს და სოციალურ როლებსა და წესებს სიღრმისეულად სწავლობს.') WHERE id = 'b497facf-4e33-44ce-bb8d-95b34db2194a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „სხვადასხვა ფორმის ამოცნობა“. ბავშვმა უკვე იცის განსხვავება წრეს, კვადრატსა და სამკუთხედს შორის და მათ შესაბამის ჭრილებში ათავსებს. თუ თხოვნაზე „კვადრატი მომეცი“ არ ცდება, ეს მისი ვიზუალურ-სივრცითი აზროვნების წარმატებული განვითარების მაჩვენებელია.') WHERE id = 'e423f075-63ff-4c05-92b5-4ab5ac29b6be';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკან სიარული“. ბავშვს უკვე შეუძლია, უკან რამდენიმე ნაბიჯი ისე გადადგას, რომ არ გაიხედოს. ეს მოძრაობა მნიშვნელოვანია სივრცეში საკუთარი სხეულის მდებარეობის შეგრძნებისთვის (პროპრიოცეფცია). უთხარით „მოდი, კიბორჩხალასავით ვიაროთ“ და ეს მოძრაობა თამაშად აქციეთ; ასე ფეხის კუნთები განსხვავებულად იმუშავებს.') WHERE id = '4e7bdd0e-7517-4dbe-a3fb-4614d6b6754f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მრავალსიტყვიანი წინადადებები“. ბავშვი უკვე 4-5 სიტყვისგან შემდგარ რთულ წინადადებებს აყალიბებს: „დედა, მინდა პარკში წავიდე და ვითამაშო“. მის წინადადებებში კავშირები და დროის გამომხატველი ფორმები უკვე უფრო ხშირად გვხვდება. საუბრისას დაუსვით ღია კითხვები, რათა მეტი საუბრის სურვილი გაუჩნდეს.') WHERE id = 'd51c61a3-3310-47cc-be33-4e2fc01a2f12';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: ბავშვი უკვე იწყებს იმის გაგებას, თუ როგორ მოქმედებს თქვენზე მისი ზოგიერთი ქცევა. ის თქვენს სახეზე სევდასა და სიხარულს ამოიცნობს. აუხსენით ემოციური მიზეზ-შედეგობრივი კავშირები და უთხარით: „როცა სხვებს უზიარებ, მე ძალიან ბედნიერი ვარ“. ეს დაეხმარება, მზრუნველ და გულისხმიერ პიროვნებად გაიზარდოს.') WHERE id = '00079201-58ca-47e2-bd9f-428f9b22aea3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '900-დღიან დიდ მწვერვალამდე მხოლოდ 10 დღე დარჩა! ბავშვი უკვე ცოტათი სცდება „მე“-ზე ორიენტირებულ აზროვნებას და სხვების საჭიროებების გაგებასაც იწყებს. მაგალითად, შეიძლება გკითხოთ: „წყალი ხომ არ გინდათ?“ აუცილებლად შეაქეთ მისი ასეთი მზრუნველი მცდელობები — ეს მისი სოციალური ინტელექტის (EQ) მომწიფებაზე მიუთითებს.') WHERE id = '54cacacb-5f6d-4f6a-b6ea-082797db1faf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „კიბეზე მონაცვლეობითი ნაბიჯებით ჩამოსვლა“. ბავშვი უკვე ცდილობს კიბეზე თითო საფეხურის გავლით, ფეხების მონაცვლეობით ჩამოსვლას. ეს მოძრაობა ასვლაზე უფრო რთულია და წონასწორობის კარგად დაცვას მოითხოვს. მოთმინებით დაელოდეთ და აგრძნობინეთ, რომ მისი გჯერათ.') WHERE id = 'ce4fa5fc-7dc5-4de0-b4e5-b9c6bb215fb4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რთული კითხვების პერიოდი“. ბავშვი უკვე მხოლოდ „ეს რა არის?“ კი აღარ კითხულობს, არამედ სვამს ისეთ კითხვებსაც, როგორიცაა: „რატომ არის ასე?“ და „სად მივდივართ?“ უპასუხეთ გულწრფელად და მარტივად. თქვენი ახსნა მის გონებაში სამყაროს ლოგიკურ რუკას ქმნის. ყოველთვის წაახალისეთ მისი ცნობისმოყვარეობა: „შენი აზრით, რატომ არის ასე?“') WHERE id = 'b47ac63c-a31b-4cfe-b3d9-64f08edba2f8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „წრისა და ჯვრის დახატვა“. ბავშვი უკვე იწყებს ფანქრის უფრო მეტად „დიდივით“ დაჭერას (სამი თითით) და ქაღალდზე ისეთი ფორმების გამეორებას, როგორიცაა წრე და ჯვარი. ეს მომავალი წერის უნარებისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი მოტორული უნარია. მიეცით ფერადი ცარცები.') WHERE id = '4c756f1e-f764-4f55-8535-6552dafc167f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად კვება და არჩევანი“. ბავშვს უკვე თავად სურს გადაწყვიტოს, რამდენს შეჭამს სუფრასთან. ნუ აიძულებთ ჭამას. თვითმომსახურების უნარების განვითარებასთან ერთად შესთავაზეთ, საკუთარი თეფში თავად წაიღოს სამზარეულოში (თუ ეს უსაფრთხოა). ეს მას ოჯახში პასუხისმგებლობის გრძნობას უყალიბებს.') WHERE id = '04c3f7db-69bb-44ed-8348-5d4d92cb8c92';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარმოსახვითი თანამოამაშეები“ სოციალურ ქცევაში. ბავშვი უკვე ესაუბრება თავის სათამაშოებს, დავალებებს აძლევს და ისე ექცევა, თითქოს ისინი ცოცხლები იყვნენ. ეს მისი წარმოსახვისა და მოვლენებს შორის აბსტრაქტული კავშირების დამყარების ძლიერი უნარის მაჩვენებელია.') WHERE id = '2c67e108-3cf8-4072-89be-1ff519eaddcc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ფერთა ელფერების გარჩევა“ შემეცნებით განვითარებაში. ბავშვს უკვე შეუძლია ვიზუალურად გაარჩიოს არა მხოლოდ „მწვანე“, არამედ ღია და მუქი მწვანეც. აჩვენეთ სხვადასხვა ფერისა და ელფერის ფოთლები ან ფანქრები და ითამაშეთ თამაში „რომელია უფრო მუქი?“. ეს მის ვიზუალური ანალიზის უნარს აუმჯობესებს.') WHERE id = 'dcddf5f8-faa5-4048-a797-208e9715f0bf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სამთვლიანი ველოსიპედისადმი ინტერესი“. ბავშვი უკვე ცდილობს პედლების დატრიალებას ან ფეხებით მიწას მიაწვეს და ასე წავიდეს წინ. ეს მოძრაობა აძლიერებს როგორც ფეხის კუნთებს, ისე სივრცეში მიმართულების მართვის უნარს.') WHERE id = 'a4633b77-b5aa-45ed-9da1-475ae9482abc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარსული და მომავალი დრო“ მეტყველებაში. ბავშვი უკვე ცდილობს მეტყველებაში გამოიყენოს დროითი განსხვავებები (თუმცა ჯერ არა სრულიად ზუსტად), მაგალითად: „ხვალ წავალთ“ ან „გუშინ წავედით“. დღის ბოლოს ესაუბრეთ თემებზე: „რა გავაკეთეთ დღეს?“ და „რას გავაკეთებთ ხვალ?“. ეს მის მეხსიერებასა და დაგეგმვის უნარს აძლიერებს.') WHERE id = '3e7a62e8-608e-4fd7-88f9-177ba74dcb48';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 900 დღე გავიარეთ! ბავშვმა უკვე 2-ნახევარი წლის (30 თვის) ასაკს მიაღწია. ახლა ის როგორც ფიზიკურად, ისე ემოციურად უფრო ძლიერი, დამოუკიდებელი და შემოქმედებითია. ამ 900 დღის განმავლობაში თქვენ მიერ გამოვლენილი სიყვარული და თავდადება მისი მთელი მომავალი ცხოვრების საფუძვლად იქცა. თქვენ წარმოუდგენელი რამ შეძელით, დედა!') WHERE id = '3d5a9ac6-ec3e-4630-b503-91b84d5fef32';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '900-დღიანი დიდი ეტაპი უკან მოვიტოვეთ და ახალ ფაზას ვიწყებთ! ბავშვი უკვე 31-ე თვეში გადადის. ახლა ის როგორც საკუთარ, ისე ოჯახის წევრების სახელებს სრულიად ზუსტად წარმოთქვამს. დაათვალიერეთ მასთან ერთად საოჯახო ალბომი და ითამაშეთ თამაში „ვინ არის ეს?“. ეს მას როგორც მიკუთვნებულობის განცდას, ისე ვერბალურ მეხსიერებას გაუძლიერებს.') WHERE id = '5482dfbc-7126-4e7c-8510-4a2cfbf55aee';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ცალ ფეხზე ხტომა“. ბავშვი უკვე ცდილობს, თუნდაც სულ ოდნავ, ცალ ფეხზე ახტეს. ეს კოჭისა და წვივის კუნთების მნიშვნელოვან განვითარებაზე მიუთითებს. ამ უნარის გასავითარებლად პარკში მასთან ერთად მოაწყვეთ შეჯიბრება „კურდღელივით ხტომაში“.') WHERE id = '2840aa13-bbb5-476f-ad1f-11685bbcd555';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „არგუმენტირება“. ბავშვი უკვე არა მხოლოდ გამოთქვამს სურვილებს, არამედ ასაბუთებს კიდეც მათ: „ეს თოჯინა მინდა, რადგან ლამაზია“. ყურადღებით მოუსმინეთ მის „რადგან“-ებს. ეს აჩვენებს, რამდენად განვითარდა მისი ლოგიკური აზროვნება და საკუთარი აზრის გამოხატვის უნარი.') WHERE id = 'dd18fee0-7070-455b-a654-1c5450138cd5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „მიზანმიმართული გაფერადება“. ბავშვი უკვე აღიქვამს ქაღალდზე გამოსახული დიდი ფორმების საზღვრებს (მაგალითად, დიდი ვაშლის ნახატის) და გაფერადებისას ცდილობს, კონტურს არ გადასცდეს. ეს ხელის კუნთების კონტროლის განვითარებაში დიდი წინგადადგმული ნაბიჯია. მიეცით მას მსხვილკონტურიანი გასაფერადებელი ფურცლები.') WHERE id = '25d06f6c-6efb-491d-ac80-8bbd8fa74917';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმა“ და ღილები. ბავშვი უკვე ინტერესდება დიდი ღილების გახსნით ან ელვის შესაკრავის ზემოთ აწევით (მას შემდეგ, რაც შეკვრას დაუწყებთ). უთხარით: „მოდი, თავად სცადე“ და მიეცით ამის შესაძლებლობა. დამოუკიდებლად ჩაცმის უნარი ბავშვში წარმოუდგენლად აძლიერებს განცდას — „მე შემიძლია“ — და თავდაჯერებას.') WHERE id = 'e6e7a26c-5b45-4894-8a1d-19ed6e362c71';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „თანამშრომლობა და გაზიარება“. ბავშვი უკვე ხვდება, რომ სათამაშოს გაზიარება დროებითია. დროა, გაეცნოს პრინციპს: „ჯერ ცოტა ხანს შენ ითამაშე, შემდეგ კი მე“. ეს მას როგორც მოთმინებას, ისე სოციალურ ემპათიას უვითარებს.') WHERE id = '79abc2a4-51b0-4f9f-8334-d1eb1d4ea6eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიური განვითარების ეტაპი — „მოცულობის აღქმა“. ბავშვი უკვე ვიზუალურად ხვდება, რომ პატარა ყუთი დიდ ყუთში მოთავსდება, პირიქით კი შეუძლებელია. მიეცით სხვადასხვა ზომის ჭურჭელი და ჰკითხეთ: „რომელი ჩაეტევა ამაში?“ ეს სივრცითი აღქმაა, რომელიც მომავალში მათემატიკური და გეომეტრიული აზროვნების საფუძველი გახდება.') WHERE id = '615744e3-fb18-42f6-8110-3e9a2d54709c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია — „ბურთის მიზანში სროლა“. ბავშვი უკვე უბრალოდ კი არ ისვრის ბურთს, არამედ ცდილობს, ზუსტად თქვენკენ ან კონკრეტულ ყუთში (კალათში) ისროლოს. ეს ხელისა და თვალის კოორდინაციისა და სიღრმის აღქმის ერთობლიობაა. ითამაშეთ მასთან „პატარა კალათბურთი“.') WHERE id = '8fa193ab-3d15-4b10-9608-9e3d2bd116d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„აბსტრაქტული ცნებები“ მეტყველებაში. ბავშვი უკვე სათანადოდ იყენებს ისეთ სიტყვებს, როგორებიცაა „სიყვარული“, „წყენა“ და „მონატრება“. როცა გეუბნებათ: „მომენატრეთ“, ეს მისი ემოციური ინტელექტის განვითარების მაღალი დონეა. აუცილებლად გამოეხმაურეთ მის გრძნობებს და თქვენც დაასახელეთ საკუთარი ემოციები: „მეც ძალიან მიხარია შენი დანახვა“.') WHERE id = '13cc3bef-f498-4191-9d8c-212c97c4c3e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის ძალა — „უხილავი სტუმრები“. ბავშვი უკვე სტუმრად იწვევს სათამაშოებს და წარმოსახვით კერძებს სთავაზობს. ასეთი თამაშები, როდესაც ბავშვი თავს ისე აჩვენებს, თითქოს რაღაც რეალურად ხდება, მის მეხსიერებაში არსებული სოციალური სცენარების გათამაშების საშუალებაა. შეუერთდით მის წარმოსახვით სამყაროს თქვენც, როგორც სტუმარი!') WHERE id = 'a44149c1-0e64-49a3-936a-9d1d3a595e97';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე არა მხოლოდ „წითელ“ ან „ლურჯ“ ფერებს არჩევს, არამედ ვიზუალურად მათი მუქი და ღია ტონების გარჩევასაც იწყებს. მიეცით სხვადასხვა ფერის ფანქრები და უთხარით: „ყველაზე მუქი მომეცი“, რათა მისი ვიზუალური ანალიზის უნარი შეამოწმოთ. ეს ავითარებს როგორც მის ყურადღებას, ისე ესთეტიკურ აღქმას.') WHERE id = '5bd4135a-236e-4d8e-8be3-3ebc28e05d9e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოძრაობის უნარი — „უკან სიარული“. ბავშვს უკვე შეუძლია წონასწორობის დაკარგვის გარეშე რამდენიმე ნაბიჯის უკან გადადგმა. ეს მოძრაობა აძლიერებს სხეულის შეგრძნებას (პროპრიოცეფციას) და სივრცეში ორიენტაციის უნარს. ითამაშეთ მასთან თამაში „ვიაროთ კიბორჩხალასავით“.') WHERE id = '54996f87-c947-4849-9084-027fb47fcd81';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „რითმიანი სიტყვები და სიმღერები“. ბავშვს უკვე ძალიან მოსწონს მოსმენილი სიმღერების ბოლო სიტყვების რითმით დასრულება. ეს მისი ფონემატური სმენის განვითარების ნიშანია. ერთად წაიკითხეთ ლექსები და ბოლოს შეჩერდით, რათა ბავშვმა თავად დაასრულოს. ეს ავითარებს მის მეხსიერებას და მეტყველების ტემპის დარეგულირებაშიც ეხმარება.') WHERE id = 'acf4d772-adf5-4683-b12b-56ef67f21202';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „მძივების ძაფზე აცმა“. ბავშვს უკვე კარგად გამოსდის დიდი ნახვრეტის მქონე მძივების ან მაკარონის ძაფზე აცმა. ეს მოქმედება მოითხოვს როგორც მოთმინებას, ისე თითების ზუსტ კოორდინაციას. ამ გზით ის კუნთოვან მეხსიერებას ავითარებს, რაც მომავალში წერის უნარის ათვისებაში დაეხმარება.') WHERE id = 'acfd54f8-89c0-45e8-b646-d1e1362647ed';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'პროგრესი „დამოუკიდებელ ჰიგიენაში“. ბავშვს უკვე შეუძლია ხელების დაბანის შემდეგ დამოუკიდებლად გაიმშრალოს ისინი პირსახოცით და პირსახოცი თავის ადგილას დაკიდოს. ასეთი პატარა მოქმედებების ბოლომდე მიყვანა მას საკუთარ თავზე ზრუნვის პასუხისმგებლობას უვითარებს. მისი ასეთი მოწესრიგებული ქცევა შეაქეთ სიტყვებით: „რა მოწესრიგებული ხარ!“') WHERE id = 'd2072154-6990-473d-aae5-34ace20cbb48';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „სხვისი გრძნობების გაგება“. ბავშვმა შეიძლება უკვე შეამჩნიოს თქვენს სახეზე სევდა ან დაღლილობა და გკითხოთ: „რა მოხდა?“ ეს ემპათიის ყველაზე გულწრფელი ფორმაა. მარტივი სიტყვებით აუხსენით, რას გრძნობთ: „ცოტა დავიღალე, მოდი, ერთად დავისვენოთ“. ეს მის ემოციურ ინტელექტს (EQ) ავითარებს.') WHERE id = '146ce216-737a-480c-9a11-95c561e541a4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დალაგება და შედარება“. ბავშვს უკვე შეუძლია 3-4 სათამაშო ზომის მიხედვით, პატარიდან დიდისკენ დაალაგოს. ეს ადრეული მათემატიკური აზროვნების საფუძველია. მიეცით ისეთი დავალებები, როგორიცაა: „ყველაზე დიდი დათუნია სულ წინ დადე“. ეს ავითარებს როგორც ვიზუალური ანალიზის უნარს, ისე ყურადღების კონცენტრაციას.') WHERE id = 'a0704d4b-bb47-4a9f-8d8c-90add9dfed0e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „დინამიკური წონასწორობა“. ბავშვს უკვე აინტერესებს დაბალ სიმზე ან მიწაზე გავლებული ხაზის გასწვრივ „ბაგირზე მოსიარულესავით“ სიარული. ეს მისი ვესტიბულური სისტემის (წონასწორობის ცენტრის) მომწიფების ნიშანია. პარკში ხელი ჩასჭიდეთ და ბორდიურზე სიარულისას მისი ეს გამბედაობა წაახალისეთ.') WHERE id = '536458a4-4f3e-423b-9a13-cba42297d147';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროის ცნება: გუშინ და ხვალ“. მიუხედავად იმისა, რომ ბავშვი ამ სიტყვებს ჯერ ზუსტი დროის აღსანიშნავად არ იყენებს, ის ცდილობს წარსული და მომავალი მოვლენები ერთმანეთისგან განასხვაოს. დღის ბოლოს ესაუბრეთ: „ხვალ სად წავალთ?“ ეს მის დაგეგმვის უნარსა და მოვლენებს შორის დროითი კავშირის გააზრებას განამტკიცებს.') WHERE id = '6849680a-6227-4b9c-ad36-2d8926dfdf15';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მედეგობა: როცა ბავშვს რაიმე არ გამოსდის (მაგალითად, კუბები ეშლება), შესაძლოა მაშინვე აღარ ატირდეს და ხელახლა სცადოს. ეს „ბრძოლის ჟინი“ ძალიან მნიშვნელოვანია მომავალში სწავლის წარმატებისთვის. უთხარით: „ვხედავ, როგორ ბევრს ცდილობ“ — შეაქეთ არა შედეგი, არამედ მისი მონდომება.') WHERE id = '86a0403c-8de6-429b-885d-6a2141aa02c8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '31-ე თვის ბოლო ათ დღეს ვიწყებთ! ბავშვი უკვე საკუთრების ძლიერი განცდით იყენებს სიტყვებს „მე“ და „ჩემი“. ამ პერიოდში მნიშვნელოვანია, პატივი სცეთ მის საკუთრების განცდას. უთხარით: „ეს შენი სათამაშოა, მაგრამ მოდი, ვცადოთ, შენ და შენმა მეგობარმა მორიგეობით ითამაშოთ“ — ასე აჩვენებთ, რომ გაზიარება არჩევანია.') WHERE id = '84330770-7540-4b55-849d-a1cc950ead4d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „ორივე ფეხით წინ ხტომის ოსტატობა“. ბავშვს უკვე შეუძლია, არა მხოლოდ ადგილზე, არამედ ოდნავ წინაც (დაახლოებით 10-20 სმ) გადახტეს. ეს ფეხის კუნთების ფეთქებადი ძალის მატებაზე მიუთითებს. იატაკზე პატარა „დაბრკოლებები“ (მაგალითად, ფერადი ლენტები) მოუწყეთ და ხტომის თამაში ითამაშეთ.') WHERE id = '5741e7d1-1ed4-44c7-a88a-391b61cdae5d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „რთული წინადადებების სტრუქტურები“. ბავშვი უკვე ორ განსხვავებულ აზრს კავშირებით აერთიანებს: „მე მინდა პარკში წასვლა და საქანელაზე ქანაობა“. მის წინადადებებში მიზანი და განზრახვა უფრო მკაფიოდ ჩანს. საუბრისას დაუსვით კითხვა „რატომ?“ და წაახალისეთ, უფრო ვრცელი ახსნა მოგცეთ.') WHERE id = '1e35c889-6f4c-4fd3-ae21-e3389ec8548d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „აკურატულად დაკეცვა“. ბავშვი უკვე ცდილობს, თქვენი მიბაძვით დაკეცოს ქაღალდი ან პატარა პირსახოცი. ეს მოქმედება ავითარებს როგორც ხელისა და თვალის კოორდინაციას, ისე ვიზუალური სიმეტრიის აღქმას. ტანსაცმლის დაკეცვისას სთხოვეთ, თავისი პატარა ცხვირსახოცები დაკეცოს.') WHERE id = '3690ca7a-82f5-4004-93ab-5126e1011625';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად კვება და სუფრასთან ქცევის კულტურა“. ბავშვი კოვზისა და ჩანგლის გამოყენებისას თითქმის აღარაფერს ღვრის. ის უკვე სათანადო დროს იწყებს სუფრასთან დაკავშირებული ისეთი სიტყვების გამოყენებას, როგორებიცაა „გემრიელად მიირთვით“ ან „გმადლობთ“. ყოველთვის შეაქეთ ასეთი თავაზიანობისთვის — ეს მომავალში მისი ურთიერთობის კულტურის საფუძველი გახდება.') WHERE id = '43e9a2b0-67bf-44dc-b37a-1d4a9e1b3e86';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „როლური თამაშების გართულება“. ბავშვმა შეიძლება უკვე მასწავლებლის, ექიმის ან მშობლის როლი მოირგოს და თქვენ „მითითებები“ მოგცეთ. ასეთი თამაშებით ის სოციალურ როლებს ითავისებს. მონაწილეობა მიიღეთ მის „გაკვეთილებში“ — ეს მას ლიდერული უნარების განვითარებაში ეხმარება.') WHERE id = 'd218ecc4-3eae-4f6a-ba4c-e1f3fc1576d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „რიცხვისა და რაოდენობის პირველი კავშირი“. მართალია, ბავშვმა 1-დან 5-მდე თვლა ზეპირად იცის, მაგრამ ახლა უკვე „ორი ვაშლის“ თქმისას რაოდენობის გაგებასაც იწყებს. სთხოვეთ: „ორი ფანქარი მომეცი“, რათა რიცხვი შესაბამის რაოდენობას დაუკავშიროს. ეს მათემატიკური აზროვნების განვითარების ერთ-ერთი უმნიშვნელოვანესი ეტაპია.') WHERE id = 'e77c9dc0-0ffc-4afa-af6f-98372ac9412c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ფეხით ტარების მანევრები“. ბავშვს უკვე შეუძლია სირბილისას წინ მდებარე ბურთს წონასწორობის დაკარგვის გარეშე დაარტყას და მიმართულება შეუცვალოს. ეს დინამიკური წონასწორობის გაუმჯობესებაზე მიუთითებს. ახლა საუკეთესო დროა, რომ მასთან ერთად სუფთა ჰაერზე „ფეხბურთი“ ითამაშოთ.') WHERE id = 'f27d93f9-9b8c-4331-9608-1f9403361289';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ახალი ლექსიკა: ზედსართავი სახელების მატება“. ბავშვი საგნების აღწერისას უკვე იყენებს ისეთ სიტყვებს, როგორებიცაა „რბილი“, „მაგარი“, „ცხელი“, „ცივი“ და „მძიმე“. მიეცით სხვადასხვა ფაქტურის მქონე საგნები და ჰკითხეთ: „შეხებისას როგორია?“ ზედსართავი სახელების მარაგის ზრდა მას სამყაროს უფრო დეტალურად აღქმაში ეხმარება.') WHERE id = '2a117057-8af9-4f1a-8e6e-3d0291275ec5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმწიფე: ბავშვი ზოგჯერ უკვე აცნობიერებს საკუთარ ბრაზს და შეუძლია თქვას: „გავბრაზდი“. ეს ემოციური თვითშემეცნების განვითარებაში დიდი წინსვლაა. ასეთ დროს ჩაეხუტეთ და უთხარით: „მესმის, მოდი, ერთად დავმშვიდდეთ“. 930-დღიანი გზა წარმატებით გავიარეთ — თქვენ შესანიშნავი თანამგზავრი ხართ!') WHERE id = '9e7e7732-10aa-4ec3-9e8d-653645d590eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე უფრო ღრმად აღიქვამს „ჯერ“ და „შემდეგ“ თანმიმდევრობას. როცა ეუბნებით: „ჩაიცვი, შემდეგ კი გარეთ გავიდეთ“, ის ხვდება, რომ მეორე მოქმედება ჯილდოა. ეს ბავშვში მოთმინებისა და დაგეგმვის უნარის პირველი საფუძვლებია. ხშირად შეახსენეთ ეს თანმიმდევრობები ყოველდღიური რიტუალების დროს.') WHERE id = '97310562-0cc9-4922-aab5-bb0de93781d6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ცოცვის ოსტატობა“. ბავშვი უკვე უფრო თავდაჯერებულად ადის პარკის კიბეებზე ან სახლში უსაფრთხო სიმაღლეებზე. ამ დროს ხელებისა და ფეხების კუნთები სინქრონულად მუშაობს. ყოველთვის ახლოს იყავით, თუმცა მიეცით საშუალება, საკუთარი ძალები გამოსცადოს.') WHERE id = '5e669269-1aa2-4602-9a6d-be602f929f7a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ლოგიკური კავშირები“. ბავშვი უკვე ორ მოვლენას ერთ წინადადებაში აერთიანებს: „გარეთ ცივა, ქურთუკი ჩაიცვი“. ეს აჩვენებს, რომ ის უბრალოდ კი არ ბაძავს, არამედ აზროვნებს კიდეც. დაუდასტურეთ მისი ლოგიკური მსჯელობა სიტყვებით: „დიახ, მართალი ხარ“, რათა საკუთარი აზრების გამოხატვის მეტი სურვილი გაუჩნდეს.') WHERE id = 'c578b6d7-6027-41d3-bcb5-015328604f79';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ქაღალდით მანიპულირება“. ბავშვმა შეიძლება უკვე გამოიჩინოს ქაღალდის დაკეცვის ან მარტივად დაჭრის ინტერესი (დიდი, საბავშვო მაკრატლით და თქვენი მეთვალყურეობით). ეს მოქმედებები თითების კუნთების კონტროლს ახალ დონეზე ავითარებს. შეუქმენით პირობები ფერადი ქაღალდებით სამუშაოდ.') WHERE id = '369aa3fa-b6a2-4869-aff0-584c7cb30be3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „როლური თამაშების გართულება“. ბავშვი უკვე ირგებს „ექიმის“, „მზარეულის“ ან „მძღოლის“ როლს. ამ თამაშების მეშვეობით ის გარშემო მყოფი ადამიანების საქმიანობას ეცნობა და ემპათიას ავითარებს. ჩაერთეთ მის თამაშებში და მოიქეცით იმ „როლის“ შესაბამისად, რომელსაც ის მოგანიჭებთ.') WHERE id = '71802808-c37b-439f-8b0c-227ce432a07a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად სისუფთავის დაცვის“ ჩვევა. ბავშვს ხელების დაბანისას უკვე თითქმის დამოუკიდებლად შეუძლია საპნის წასმა და ჩამობანა. ამ ასაკში ჰიგიენური ჩვევების განმტკიცება ძალიან მნიშვნელოვანია. დაუდგით მისი სიმაღლის შესაბამისი საფეხურიანი სკამი, რათა ამ პროცესით სიამოვნება მიიღოს.') WHERE id = '916356ea-060f-4a2e-8be7-98dcab3ad0ee';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარება: „იპოვე განსხვავებული“. ბავშვს უკვე შეუძლია საგნების ჯგუფში ვიზუალურად ამოარჩიოს განსხვავებული საგანი (მაგალითად, მანქანებს შორის ვაშლი). ეს მის ანალიზის უნარს აუმჯობესებს. სახლში მოუწყეთ მარტივი თამაშები — „რომელია ზედმეტი?“. ეს შესანიშნავი მომზადებაა მომავალი მათემატიკური და ლოგიკური ამოცანებისთვის.') WHERE id = '9c6d24fc-1a56-41e1-93ca-e94c8c830e4f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ერთ ფეხზე დგომის მცდელობები“. ბავშვს უკვე შეუძლია, თუნდაც რამდენიმე წამით, ერთი ფეხი მიწიდან ასწიოს და წონასწორობის შენარჩუნება სცადოს. ეს მნიშვნელოვანია იმისთვის, რომ მან საკუთარი სხეულის სიმძიმის ცენტრის შეგრძნება ისწავლოს. ითამაშეთ მასთან „ყარყატის თამაში“ და ნახეთ, ვინ შეძლებს უფრო დიდხანს დგომას.') WHERE id = '1769bf32-48e2-40a7-b480-c6f396b19e4b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„გრძნობების გამოხატვა“ მეტყველებაში. ბავშვს უკვე შეუძლია სიტყვებით თქვას, რომ მოწყენილი, მხიარული ან შეშინებულია: „მე შემეშინდა“ ან „მე მხიარული ვარ“. გრძნობების დასახელება ბავშვის ემოციური ინტელექტის საფუძველია. როდესაც ის საკუთარ გრძნობებზე საუბრობს, მოუსმინეთ და უთხარით: „დიახ, მე შენი მესმის“, რითაც მის გრძნობებს აღიარებთ.') WHERE id = '7f6f2c0c-ef35-4291-8d3c-3c98cbe7cfa1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის ძალა: „სიმბოლური აზროვნება“. ბავშვმა შეიძლება ჯოხი „ცხენად“ წარმოიდგინოს და მასზე ამხედრებულივით ირბინოს. ეს არის უნარი, გაიგოს, რომ ერთი საგანი შეიძლება სხვა რამეს განასახიერებდეს. მომავალში ეს უნარი ძალიან მნიშვნელოვანია კითხვისა და მათემატიკისთვის (სიმბოლოების გასაგებად). თქვენ შესანიშნავი მეგზური ხართ!') WHERE id = 'b4910186-9bb2-4fc8-898b-364f4deeed97';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '32-ე თვის ბოლო ათ დღეს ვიწყებთ! ბავშვი უკვე იწყებს „ჩვენ“ ცნების გააზრებას. კითხვით „ჩვენ პარკში მივდივართ?“ ის საკუთარ თავს ოჯახის განუყოფელ ნაწილად წარმოაჩენს. მასთან საუბრისას გაუზიარეთ ოჯახის გეგმები: „დღეს ჩვენ ბებიასთან მივდივართ“. ეს ბავშვს კუთვნილებისა და უსაფრთხოების განცდას უძლიერებს.') WHERE id = '1b278c24-eef1-4629-acd4-d211ef0e2e61';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოძრაობის უნარი: „კიბეზე დამოუკიდებლად გადაადგილება“. ბავშვს უკვე შეუძლია კიბეზე თავდაჯერებით ასვლა, თითოეულ საფეხურზე თითო ნაბიჯის გადადგმით (ფეხების მონაცვლეობით), როცა მხოლოდ ცალ ხელზე გეჭიდებათ. ეს მიუთითებს, რომ მისი მსხვილი მოტორული უნარები სრულად მომწიფდა. უბრალოდ მის გვერდით იყავით და ემოციურად გაამხნევეთ.') WHERE id = '275df927-814f-46e6-87b1-244d3e43ae78';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული კითხვები“. ბავშვმა შეიძლება დასვას ისეთი კითხვები, როგორიცაა: „საიდან მოდის ღრუბელი?“ ან „სად წავიდა მთვარე?“. პასუხის გაცემისას წარმოსახვითი და რეალური ინფორმაცია დააბალანსეთ: „ღრუბლები შორიდან მოდიან და წვიმა მოაქვთ ჩვენთვის“. ასეთი საუბრები წარმოუდგენლად აფართოებს მის მსოფლმხედველობას და სწავლის სურვილს.') WHERE id = 'a8a1120b-b774-4f04-89b0-c124a8cbf647';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: ბავშვი უკვე უფრო გამძლეა წარუმატებლობის მიმართ. როცა კუბიკები ენგრევა, მაშინვე აღარ ტირის და შეუძლია თქვას: „თავიდან ავაწყობ“. მხარი დაუჭირეთ მის შეუპოვრობას. 950-დღიანი გზა უკვე გავიარეთ, 1000 დღემდე ძალიან ცოტა დარჩა! თქვენ ამ გზაზე მისთვის მასწავლებელიც ხართ და საუკეთესო მეგობარიც!') WHERE id = 'c5fe4618-aa8a-4004-b14e-8472a1232fc2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საგნების დაჯგუფება არა მხოლოდ მათი ტიპის, არამედ ფერის ტონების მიხედვითაც. მიეცით სხვადასხვა მწვანე ტონის სათამაშოები და უთხარით: „მოდი, ღიიდან მუქისკენ დავალაგოთ“, რათა მისი ვიზუალური ანალიზის უნარი განავითაროთ. ეს ამახვილებს მის ესთეტიკურ აღქმასა და ყურადღებას.') WHERE id = '4cccdb9f-0090-4953-be45-4aac0e3ecdc0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ცალ ფეხზე ხტომა“. ბავშვი უკვე ცდილობს ცალ ფეხზე ძალიან მცირე ნახტომის გაკეთებას. ეს კოჭის სიძლიერისა და ვესტიბულური სისტემის (წონასწორობის) მაღალი განვითარების მაჩვენებელია. ეთამაშეთ მას „ბაჭიას“ თამაში. ყოველთვის ახლოს იყავით, რათა დაცემის შიშის გარეშე თავისუფლად იმოძრაოს.') WHERE id = '611c7f89-d565-4c80-b60a-401386c94dd3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „საპირისპირო მნიშვნელობის სიტყვები“. ბავშვს უკვე სრულად ესმის ისეთი დაპირისპირებები, როგორიცაა „დიდი-პატარა“, „ცხელი-ცივი“, „მძიმე-მსუბუქი“, და მათ მეტყველებაშიც იყენებს. დაუსვით კითხვები, მაგალითად: „ეს ქვა მძიმეა, ეს ბამბა კი როგორია?“. ეს ხარისხობრივად ამდიდრებს მის ლექსიკურ მარაგს და აძლიერებს შედარებით აზროვნებას.') WHERE id = '8c5fde41-64b4-4f6a-8c4b-9b0a4470f2ce';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „უფრო რთული კონსტრუქციები“. ბავშვი კუბიკებისგან უკვე არა მხოლოდ კოშკს, არამედ ღიობების მქონე ფორმებსაც აშენებს, მაგალითად, „კიბეს“, „ღობეს“ ან „კარს“. ეს მისი სივრცითი აზროვნებისა და საინჟინრო ინტუიციის პირველი რეალური გამოვლინებებია.') WHERE id = '8323ecc8-fdd4-4a47-acab-de738c3b3b74';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ამბის შეთხზვა“. ბავშვი უკვე სურათების დათვალიერებით მარტივ ამბებს იგონებს. ისეთი თანმიმდევრული წინადადებები, როგორიცაა „კატა მოვიდა, რძე დალია და დაიძინა“, მისი მეხსიერებისა და წარმოსახვის ერთობლივი მუშაობის შედეგია. მიეცით წიგნები საინტერესო ილუსტრაციებით და ჰკითხეთ: „აქ რა ხდება?“ ეს მის შემოქმედებით აზროვნებას გააღვივებს.') WHERE id = '904512e9-992f-4497-b856-79751b10de80';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ზუსტად განთავსება“. ბავშვს უკვე ნაკლები შეცდომით შეუძლია პატარა სათამაშო ფიგურების განთავსება ან მძივების ძაფზე აცმა. ამ პერიოდში თითის წვერების მგრძნობელობა იზრდება. შესთავაზეთ თამაშები სხვადასხვა ტექსტურის მქონე პატარა საგნებით (თქვენი მეთვალყურეობით).') WHERE id = 'd9171a51-69d8-4d0a-829c-7db5c26a601f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმის“ დაჟინებული სურვილი. ბავშვი უკვე დაჟინებით ცდილობს, ღილების გარეშე მაისური ან შარვალი თავად ჩაიცვას. როდესაც ამბობს: „მე თვითონ!“, მიეცით დრო. დამოუკიდებლობის ეს მცდელობები მომავალი თავდაჯერებულობისა და პირადი პასუხისმგებლობის უმტკიცესი საფუძველია. აღნიშნეთ მისი პატარა წარმატებები სიტყვებით: „ხედავ, სულ მარტო შეძელი!“') WHERE id = 'b1c5306b-77bb-4136-8d44-3c944e44a9e3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ზრდილობის წესები“. ბავშვი სიტყვებს „თუ შეიძლება“, „გმადლობთ“ და „გთხოვთ“ უკვე უბრალოდ კი არ იმეორებს, არამედ მიზანმიმართულად იყენებს. თქვენი თავაზიანი ქცევა მისთვის საუკეთესო მაგალითია. შეაქეთ ასეთი ქცევისთვის და ამით მისი კომუნიკაციის კულტურა განამტკიცეთ.') WHERE id = '9e1b06c8-d4a2-4b28-b3bc-ad2c39ab7cb0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დროის ზმნიზედები“. ბავშვი სიტყვების „შემდეგ“, „ცოტა ხანში“ და „ახლა“ სწორად გამოყენებას იწყებს. როდესაც ეუბნებით: „ცოტა ხანში მოვალ“, მას ესმის, რომ გარკვეული დრო უნდა გავიდეს. ეს ბავშვს ლოდინისა და თვითრეგულირების უნარებს უვითარებს. ხშირად გამოიყენეთ ეს სიტყვები თქვენს ყოველდღიურ რიტუალებში.') WHERE id = '6f964b8f-02b2-4bed-adce-f35ba0656a6a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და დამიზნება“. ბავშვი ბურთს უკვე უბრალოდ კი არ ურტყამს, არამედ ცდილობს, კონკრეტული მიმართულებით გააგოროს — მაგალითად, ორ სათამაშოს შორის გაატაროს. ეს ხელისა და თვალის, ასევე ფეხისა და თვალის კოორდინაციის სინქრონული მუშაობაა. მოაწყვეთ მასთან ერთად სახლში „მინი ფეხბურთის“ ტურნირი.') WHERE id = '61ba305a-b8ae-4528-9ce2-bd394666ba9a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი: ამინდი და ტანსაცმელი“. ბავშვს უკვე ესმის, რომ თუ გარეთ ცივა, თბილად უნდა ჩაიცვას. შესთავაზეთ ორი ვარიანტი და უთხარით: „დღეს გარეთ ცივა, რომელი ქურთუკის ჩაცმა გინდა?“ საკუთარი არჩევანის შესაბამისად ჩაცმა ბავშვს პასუხისმგებლობის გრძნობასა და გადაწყვეტილების მიღების უნარს უვითარებს.') WHERE id = 'b6331bb4-9640-46b8-a4de-673e4569b48f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „სიმბოლური გაზიარება“. ბავშვს უკვე შეუძლია, მისთვის არცთუ ისე ძვირფასი სათამაშო მეგობარს ნებაყოფლობით მისცეს. ეს ეგოცენტრული პერიოდიდან („ყველაფერი ჩემია“) გამოსვლისა და სოციალური თანამშრომლობის დასაწყისია. აუცილებლად შეაქეთ მისი გულუხვობა და უთხარით: „რა მზრუნველი ხარ!“') WHERE id = '7a5cc16d-c4e3-465c-94b4-27327272c867';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „თანმიმდევრობა და დათვლა“. ბავშვს უკვე შეუძლია არა მხოლოდ 1-დან 10-მდე ზეპირად დათვლა, არამედ საგნებზე თითით მითითება და მათი რაოდენობის „ერთი, ორი, სამი“ პრინციპით განსაზღვრაც. ჰკითხეთ: „აქ რამდენი მანქანაა?“ ეს ის ეტაპია, როდესაც აბსტრაქტული რიცხვები პირველად მჭიდროდ უკავშირდება რეალურ სამყაროს.') WHERE id = '27d58f54-7d91-4fc1-9abe-0e7741238b0e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკან სიარული და სირბილი“. ბავშვს უკვე შეუძლია უკანმოუხედავად თავდაჯერებულად იაროს და რამდენიმე ნაბიჯიც კი გაირბინოს უკან. ეს მოძრაობა აჩვენებს, რამდენად კარგად აქვს განვითარებული სხეულის კოორდინაცია. ითამაშეთ მასთან „კიბორჩხალების რბოლა“ — ასე ერთადაც გაერთობით და მის კუნთებსაც განსხვავებულად აამუშავებთ.') WHERE id = '5835a9f7-31b7-47bc-af3b-fbaf1eae167a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კავშირების გამოყენება“. ბავშვი წინადადებებში იყენებს სიტყვებს „და“, „მაგრამ“, „რადგან“ და თავის აზრს უფრო სრულად გადმოსცემს: „მშია, მაგრამ ჭამა არ მინდა“. მოუსმინეთ მის წინადადებებს და თქვენც მსგავსი რთული წინადადებებით უპასუხეთ. ეს მას გრამატიკის უკეთ დაუფლებაში ეხმარება.') WHERE id = 'e679f00c-7a2a-4673-af5d-88a6f4d8128e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური გამძლეობა: როდესაც ბავშვს რაიმე არ გამოსდის, დახმარებას მაშინვე აღარ გთხოვთ და ჯერ თავად რამდენჯერმე ცდილობს. მხარი დაუჭირეთ მის ამ შეუპოვრობას. სიტყვები „ვხედავ, რომ ძალიან ცდილობ“ დაეხმარება, შედეგზე მეტად თავად პროცესი შეიყვაროს. 1000 დღემდე სულ 40 დღე დარჩა!') WHERE id = '73811b23-1334-47b6-aa32-fe16ca9f7dfe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე სწორად იყენებს ნაცვალსახელებს „მე“, „შენ“ და „ჩვენ“. როცა ამბობს: „ჩვენ ახლა ვჭამთ?“, თავს ოჯახის აქტიურ წევრად გრძნობს. მასთან საუბრისას თქვენს გეგმებში ისიც ჩართეთ: „მოდი, სუფრა ერთად გავაწყოთ“. ეს მას კუთვნილებისა და პასუხისმგებლობის განცდას გაუძლიერებს.') WHERE id = '0088ee7c-73a0-42ed-a073-c3d4d5a577af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „კიბეზე დამოუკიდებლად გადაადგილება“. ბავშვი უკვე თავდაჯერებულად ადის კიბეზე, ყოველ საფეხურზე თითო ფეხის მონაცვლეობით დადგმით და მხოლოდ ერთი ხელით დაყრდნობით. ეს მისი მსხვილი მოტორიკის სრულ მომწიფებაზე მიუთითებს. უბრალოდ მის გვერდით იყავით და ემოციურად მხარი დაუჭირეთ.') WHERE id = 'bf415e92-93fc-4c0c-8e41-d0e69018f7ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ამბის შეთხზვა“. ბავშვს უკვე შეუძლია სურათების დათვალიერებისას მარტივი ამბების მოფიქრება. თანმიმდევრული წინადადებები, როგორიცაა „კატა მოვიდა, რძე დალია და დაიძინა“, მისი მეხსიერებისა და წარმოსახვის ერთობლივი მუშაობის შედეგია. მიეცით წიგნები საინტერესო ილუსტრაციებით და ჰკითხეთ: „აქ რა ხდება?“. ეს მის შემოქმედებით აზროვნებას გააღვივებს.') WHERE id = 'e900e935-8ccc-4908-bf87-10603eb74cda';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ზუსტი განთავსება“. ბავშვს უკვე ნაკლები შეცდომით შეუძლია პატარა სათამაშო ფიგურების სწორ ადგილას მოთავსება ან მძივების ძაფზე აცმა. ამ პერიოდში თითის წვერების მგრძნობელობა იზრდება. შესთავაზეთ სხვადასხვა ტექსტურის მქონე პატარა ნივთებით თამაში (თქვენი მეთვალყურეობის ქვეშ).') WHERE id = '6c732ec0-7e78-45c4-a464-029d46e20701';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმის“ დაჟინებული სურვილი. ბავშვი უკვე დაჟინებით ცდილობს, თავად ჩაიცვას ღილების გარეშე მაისური ან შარვალი. როცა ამბობს: „მე თვითონ!“, დრო მიეცით. დამოუკიდებლობისკენ ეს მცდელობები მომავალში თავდაჯერებისა და პირადი პასუხისმგებლობის ყველაზე მტკიცე საფუძველია. აღნიშნეთ მისი პატარა წარმატებები სიტყვებით: „ხედავ, შენით შეძელი!“') WHERE id = '3fe4a18c-cebd-45f6-88ed-6acbe7109fd0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „თავაზიანობის წესები“. ბავშვი უკვე უბრალოდ კი არ იმეორებს სიტყვებს „თუ შეიძლება“, „დიდი მადლობა“, „გთხოვ“, არამედ მათ მიზანმიმართულად იყენებს. თქვენი თავაზიანი ქცევა მისთვის საუკეთესო მაგალითია. შეაქეთ ასეთი ქცევისთვის და ამით მას ურთიერთობის კულტურა განუმტკიცეთ.') WHERE id = 'e6b8bd35-5e9c-4328-a121-a6fecf7c7d62';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში — „დროის ზმნიზედები“. ბავშვი სიტყვების „შემდეგ“, „ცოტა ხანში“, „ახლა“ სწორად გამოყენებას იწყებს. როდესაც ეუბნებით: „ცოტა ხანში მოვალ“, მას ესმის, რომ გარკვეული დრო უნდა გავიდეს. ეს ბავშვს ლოდინისა და თვითრეგულირების უნარებს უვითარებს. ხშირად გამოიყენეთ ეს სიტყვები ყოველდღიური რიტუალების დროს.') WHERE id = 'eac1461c-042b-436c-8d00-465739e12f49';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და მიზანში მოხვედრა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ის გარკვეული მიმართულებით გააგოროს — მაგალითად, ორ სათამაშოს შორის გაატაროს. ამ დროს ხელი-თვალისა და ფეხი-თვალის კოორდინაცია სინქრონულად მუშაობს. მოაწყვეთ მასთან ერთად სახლში „მინი ფეხბურთის“ ტურნირი.') WHERE id = '3ddf5bfb-d5a6-4b94-8ee2-f4ce76892d43';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„აბსტრაქტული კითხვები“ მეტყველებაში. ბავშვმა შეიძლება დასვას ისეთი კითხვები, როგორიცაა: „ღრუბელი საიდან მოდის?“, „მთვარე სად წავიდა?“. პასუხის გაცემისას წარმოსახვითი და რეალური ინფორმაცია დააბალანსეთ: „ღრუბლები შორიდან მოდიან და წვიმა მოაქვთ“. ასეთი საუბრები საოცრად აფართოებს მის მსოფლმხედველობას და სწავლის სურვილს.') WHERE id = '1a341992-7717-4fca-abe1-d703ab6a7a2f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: ბავშვი უკვე უფრო მედეგია წარუმატებლობის მიმართ. როდესაც კუბიკებით აშენებული კონსტრუქცია ენგრევა, მაშინვე აღარ ტირის და შეუძლია თქვას: „თავიდან ავაშენებ“. მხარი დაუჭირეთ მის შეუპოვრობას. 970-დღიანი გზა უკვე გავიარეთ, 1000 დღემდე კი სულ რაღაც 30 დღე დარჩა! ამ გზაზე თქვენ მისთვის მასწავლებელიც ხართ და უახლოესი მეგობარიც!') WHERE id = 'e1da111f-ccec-436b-a492-b6e924de37bf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი ფერებს უკვე არა მხოლოდ „წითლად“ ან „ლურჯად“ აღიქვამს, არამედ მათ მუქ და ღია ტონებსაც ვიზუალურად არჩევს. მიეცით მას სხვადასხვა ფერის ფანქრები და სთხოვეთ: „ყველაზე მუქი მომეცი“, რათა მისი ვიზუალური ანალიზის უნარი შეამოწმოთ. ეს მას ყურადღებასაც უვითარებს და ესთეტიკურ აღქმასაც.') WHERE id = '1fa9d3d6-a970-457d-af04-c009e72b5e1b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „უკან სიარული“. ბავშვს უკვე შეუძლია, წონასწორობის დაკარგვის გარეშე რამდენიმე ნაბიჯი უკან გადადგას. ეს მოძრაობა მას საკუთარი სხეულის აღქმასა და სივრცეში ორიენტაციის უნარს უძლიერებს. ითამაშეთ მასთან თამაში „ვიაროთ კიბორჩხალასავით“.') WHERE id = '21db9a7e-7c35-47c7-9f2e-7e03f72a88a3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „დროის ცნება: გუშინ და ხვალ“. მიუხედავად იმისა, რომ ბავშვი ამ სიტყვებს ჯერ ზუსტი დროის აღსანიშნავად არ იყენებს, ის ცდილობს წარსული და მომავალი მოვლენები ერთმანეთისგან განასხვაოს. დღის ბოლოს ესაუბრეთ მას: „ხვალ სად წავალთ?“ ეს მის დაგეგმვის უნარსა და მოვლენებს შორის დროითი კავშირის აღქმას განამტკიცებს.') WHERE id = 'a8b25b83-9fde-45e1-b976-1cd3459165f2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: თუ ბავშვს რაიმე არ გამოუვა (მაგალითად, კუბიკები დაენგრევა), შესაძლოა მაშინვე აღარ ატირდეს და ხელახლა ცდა დაიწყოს. ეს „ბრძოლისუნარიანობა“ მომავალში სწავლის წარმატებისთვის ძალიან მნიშვნელოვანია. უთხარით: „ვხედავ, რომ ძალიან ცდილობ“ და შეაქეთ არა შედეგი, არამედ ძალისხმევა.') WHERE id = '0db561dc-233c-4544-804a-8f5b95ba51b9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე იწყებს „ჩვენ“ ცნების გააზრებას. კითხვით: „ჩვენ ახლა პარკში მივდივართ?“ ის საკუთარ თავს ოჯახის განუყოფელ ნაწილად აღიქვამს. მასთან საუბრისას გაუზიარეთ ოჯახის გეგმები: „დღეს ჩვენ ბებიასთან წავალთ“. ეს ბავშვს კუთვნილებისა და უსაფრთხოების განცდას განუმტკიცებს.') WHERE id = 'cb75068e-4a47-4582-8cce-0e1abcdf18e0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „კიბეზე დამოუკიდებლად სიარული“. ბავშვს უკვე შეუძლია კიბეზე თავდაჯერებულად ასვლა, თითო საფეხურზე თითო ფეხის მონაცვლეობით დადგმით და მხოლოდ ერთი ხელით დაყრდნობით. ეს აჩვენებს, რომ მისი მსხვილი მოტორული უნარები სრულად მომწიფდა. უბრალოდ მის გვერდით იყავით და ემოციურად მხარი დაუჭირეთ.') WHERE id = 'c4f997be-e1af-4807-8fcf-d6afc3087197';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ამბის შეთხზვა“. ბავშვს უკვე შეუძლია სურათების მიხედვით მარტივი ამბების მოფიქრება. თანმიმდევრული წინადადებები, როგორიცაა „კატა მოვიდა, რძე დალია და დაიძინა“, მისი მეხსიერებისა და წარმოსახვის ერთობლივი მუშაობის შედეგია. მიეცით წიგნები საინტერესო ილუსტრაციებით და ჰკითხეთ: „აქ რა ხდება?“ ეს მის შემოქმედებით აზროვნებას გააღვივებს.') WHERE id = '8a750939-d6ea-4327-ae01-fe2febf3e561';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „ზუსტად განთავსება“. ბავშვს უკვე შეუძლია პატარა სათამაშო ფიგურების ზუსტად განთავსება ან მძივების ძაფზე აცმა ნაკლები შეცდომით. ამ პერიოდში თითის წვერების მგრძნობელობა იზრდება. შესთავაზეთ თამაშები სხვადასხვა ტექსტურის მქონე პატარა საგნებით (თქვენი მეთვალყურეობის ქვეშ).') WHERE id = 'b81dacf6-43a1-47b5-b976-b04cc72c15b8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმის“ ჟინი. ბავშვი უკვე დაჟინებით ცდილობს, თავად ჩაიცვას მაისური ღილების გარეშე ან შარვალი. როცა ამბობს: „მე თვითონ!“, მიეცით დრო. დამოუკიდებლობისკენ ეს მცდელობები მომავალში თავდაჯერებისა და პირადი პასუხისმგებლობის მტკიცე საფუძველს ქმნის. აღნიშნეთ მისი პატარა წარმატებები სიტყვებით: „ნახე, შენით შეძელი!“') WHERE id = '5b370f66-ddd3-45df-8b72-80322e3b54c6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თავაზიანობის წესები“ სოციალურ ქცევაში. ბავშვი სიტყვებს „თუ შეიძლება“, „დიდი მადლობა“, „გთხოვ“ უკვე უბრალოდ კი არ იმეორებს, არამედ მიზანმიმართულად იყენებს. თქვენი თავაზიანი ქცევა მისთვის საუკეთესო მაგალითია. შეაქეთ ასეთი საქციელისთვის და ამით კომუნიკაციის კულტურა განუმტკიცეთ.') WHERE id = 'fb257145-0061-4b1c-8bd6-415874362912';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დროის ზმნიზედები“ კოგნიტიურ განვითარებაში. ბავშვი სიტყვების „შემდეგ“, „ცოტა ხანში“, „ახლა“ სწორად გამოყენებას იწყებს. როცა ეუბნებით: „ცოტა ხანში მოვალ“, ის ხვდება, რომ დრო უნდა გავიდეს. ეს ბავშვს ლოდინისა და თვითრეგულირების უნარს უვითარებს. ხშირად გამოიყენეთ ეს სიტყვები თქვენს ყოველდღიურ რიტუალებში.') WHERE id = '2d2fd92a-c54e-421a-b575-674a4add6e64';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და მიზანში მოხვედრა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ის კონკრეტული მიმართულებით გააგოროს — მაგალითად, ორ სათამაშოს შორის გაატაროს. ამ დროს ხელისა და თვალის, ასევე ფეხისა და თვალის კოორდინაცია სინქრონულად მუშაობს. მოაწყვეთ მასთან ერთად სახლში „მინი ფეხბურთის“ ტურნირი.') WHERE id = '4639b4f7-f878-413c-9ed9-f5c72fb301e3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„აბსტრაქტული კითხვები“ მეტყველებაში. ბავშვმა შეიძლება გკითხოთ: „ღრუბელი საიდან მოდის?“, „მთვარე სად წავიდა?“ პასუხის გაცემისას წარმოსახვითი და რეალური ინფორმაცია დააბალანსეთ: „ღრუბლები შორიდან მოდიან და წვიმა მოაქვთ“. ასეთი საუბრები მნიშვნელოვნად აფართოებს მის მსოფლმხედველობას და სწავლის სურვილს.') WHERE id = 'bc37e242-95d7-44a8-8a20-2eacd0325914';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მედეგობა: ბავშვი უკვე უფრო მშვიდად ეგუება წარუმატებლობას. როცა კუბიკები ენგრევა, მაშინვე აღარ ტირის და შეუძლია თქვას: „თავიდან ავაწყობ“. მხარი დაუჭირეთ მის შეუპოვრობას. 1000 დღემდე სულ რაღაც 10 დღე დარჩა! თქვენ ეს საოცარი გზა თქვენს ბავშვთან ერთად, ხელიხელჩაკიდებულმა გამოიარეთ. ყოჩაღ!') WHERE id = 'a124273d-b639-4f61-aa7d-a589a92dd962';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „რითმული სიტყვები და სიმღერები“. ბავშვს უკვე ძალიან მოსწონს მოსმენილი სიმღერების ბოლო სიტყვების რითმულად დასრულება. ეს მისი ფონემატური სმენის განვითარების ნიშანია. მასთან ერთად წაიკითხეთ ლექსები და შეჩერდით, რათა ბოლო თავად დაასრულოს. ეს ხელს უწყობს როგორც მეხსიერების განვითარებას, ისე მეტყველების ტემპის რეგულირებას.') WHERE id = '6ee138fb-22b9-41f6-a232-d405003097d3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „მძივების ძაფზე აცმა“. ბავშვს უკვე კარგად გამოსდის ძაფის გატარება მსხვილხვრელიან მძივებში ან მაკარონში. ეს მოქმედება მოითხოვს როგორც მოთმინებას, ისე თითების ზუსტ კოორდინაციას. ამ გზით ის მომავალი წერის უნარებისთვის საჭირო კუნთოვან მეხსიერებას ავითარებს.') WHERE id = 'e27670af-3f91-498b-a727-68765b4a34c6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'პროგრესი „დამოუკიდებელ ჰიგიენაში“. ბავშვს უკვე შეუძლია ხელების დაბანის შემდეგ დამოუკიდებლად გაიმშრალოს ისინი პირსახოცით და პირსახოცი თავის ადგილზე დაკიდოს. ეს პატარა „დასრულების“ მოქმედებები საკუთარი თავის მოვლის მიმართ მის პასუხისმგებლობას ზრდის. შეაქეთ ასეთი მოწესრიგებული ქცევისთვის და უთხარით: „რა მოწესრიგებული ხარ!“') WHERE id = '41467e61-a2ce-4e56-9659-81bc3b54b05e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „სხვისი გრძნობების გაგება“. ბავშვმა შეიძლება უკვე შეამჩნიოს თქვენს სახეზე სევდა ან დაღლილობა და გკითხოთ: „რა მოხდა?“ ეს ემპათიის ყველაზე სუფთა ფორმაა. აუხსენით თქვენი გრძნობები მარტივი სიტყვებით: „ცოტა დავიღალე, მოდი, ერთად დავისვენოთ“. ეს მის ემოციურ ინტელექტს ავითარებს.') WHERE id = '639f97f3-6003-448b-9622-c5dde4b5cec4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დალაგება და შედარება“. ბავშვს უკვე შეუძლია 3-4 სათამაშო ზომის მიხედვით, პატარიდან დიდისკენ, დაალაგოს. ეს ადრეული მათემატიკური აზროვნების საფუძველია. მიეცით ისეთი დავალებები, როგორიცაა: „ყველაზე დიდი დათუნია დასაწყისში მოათავსე“. ეს ავითარებს როგორც ვიზუალურ ანალიზს, ისე ყურადღების კონცენტრაციას.') WHERE id = '370bff62-25e0-4406-b269-39b56f69516b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „დინამიკური წონასწორობა“. ბავშვს უკვე აინტერესებს დაბალ თოკზე ან მიწაზე გავლებული ხაზის გასწვრივ „ბაგირზე მოსიარულესავით“ სიარული. ეს მისი ვესტიბულური სისტემის მომწიფების ნიშანია. პარკში ხელი ჩასჭიდეთ და ბორდიურზე სიარულისას მისი გამბედაობა წაახალისეთ.') WHERE id = '7d0f18e8-75ea-46a5-ae28-0011a1c178d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „თავისუფლება მწვერვალზეა“. ბავშვი უკვე საკმარისად გაბედულია, რომ ველოსიპედით იაროს, საქანელაზე დამოუკიდებლად იქანაოს ან მაღალი სასრიალოდან ჩამოსრიალდეს. იზრუნეთ მის უსაფრთხოებაზე, მაგრამ ხელს ნუ შეუშლით. საკუთარი ძალების რწმენა მის ხასიათს აძლიერებს.') WHERE id = '27b9a0e5-6b83-4460-8a15-0df9cab1dff0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „დროის სიღრმე“. ბავშვი უკვე იწყებს დროის ხაზზე საკუთარი ადგილის გააზრებას და ამბობს: „როცა პატარა ვიყავი...“ ან „როცა გავიზრდები...“. აჩვენეთ ჩვილობის ფოტოები და უამბეთ, რამდენი რამ გამოიარა. ეს ბავშვს პირადი ისტორიისა და საკუთარი იდენტობის (self-identity) სრულად ჩამოყალიბებაში ეხმარება.') WHERE id = '3439184d-c674-4353-b4d8-24d477730a8a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დიდ ფინალამდე 1 დღე დარჩა! დღეს განვლილ გზას გადახედეთ და იამაყეთ საკუთარი თავით. თქვენი ბავშვის ტვინის განვითარების 80% ამ პირველ 1000 დღეში დასრულდა. თქვენ მას საუბარი, სიყვარული, ნდობა და სამყაროს აღმოჩენა ასწავლეთ. ხვალ თქვენი ბავშვის ცხოვრებაში ახალი და ნათელი ფურცელი გადაიშლება. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '6f7bcab0-f835-4b32-baa1-c34bfb4bf5a9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! თქვენ წარმატებით დაასრულეთ პირველი 1000 დღე! 🌟 ეს ადამიანის ცხოვრებაში განვითარების უმნიშვნელოვანესი ეტაპია. ბავშვმა ჩვილობის პერიოდი უკვე გაიარა და ახლა პატარა გმირია, რომელიც მზადაა, სამყარო დაიპყროს. Anacan-ის ოჯახი ყოველ ნაბიჯზე თქვენ გვერდით იყო და ამ წარმატებას თქვენთან ერთად აღნიშნავს. დღეს დიდი დღესასწაულია — თქვენი და თქვენი ბავშვის გამარჯვების დღე!') WHERE id = 'df76a0b6-eddc-484e-b6f0-24845f214e66';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ჩვენი პირველი დღე 1000-დღიანი დიდი მარათონის შემდეგ! ბავშვი უკვე ცხოვრების მე-4 წელს იწყებს. ამ პერიოდში კითხვა „რატომ?“ ახალ მნიშვნელობას იძენს. ის მხოლოდ ინფორმაციას კი არ ეძებს, არამედ მოვლენებს შორის ლოგიკური კავშირის აღმოჩენას ცდილობს. მოთმინებით უპასუხეთ, რადგან ეს კითხვები მის ინტელექტუალურ საფუძველს ქმნის.') WHERE id = '458401f2-485d-418a-8b89-143f552eb250';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „დინამიკური მანევრები“. ბავშვს უკვე შეუძლია სირბილისას მკვეთრად შეუხვიოს ან სწრაფად აუაროს გვერდი დაბრკოლებებს. ეს სხეულის მართვის მაღალი დონის მაჩვენებელია. ეზოში მისთვის დაბრკოლებების მცირე შეჯიბრებები მოაწყვეთ.') WHERE id = '1242feeb-5e2f-4d55-aa93-952aedfbe568';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რთული დროის ფორმები“. ბავშვი მეტყველებაში უკვე იყენებს ისეთ რთულ დროის ფორმებს, როგორებიცაა „მე გაკეთებული მქონდა“ და „მე გავაკეთებ“. ესაუბრეთ მას წარსულში მომხდარ ამბებზე: „რა მოხდა გუშინ, ბებიასთან რომ მივედით?“. ეს ერთდროულად აძლიერებს მის მეხსიერებას და მეტყველების გრამატიკულ სიზუსტეს.') WHERE id = '5e199122-f8a1-4104-82fd-2c91af60c12f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „სიმეტრიის მცდელობები“. ბავშვი ცდილობს, ქაღალდი ზუსტად შუაზე გადაკეცოს ან ნახატზე დეტალები (მაგალითად, ადამიანის ორი თვალი და ორი ხელი) უფრო ზუსტად განათავსოს. გაუსვით ხაზი მის ვიზუალურ ყურადღებას და უთხარით: „ნახე, ორივე ხელი დაგიხატავს!“.') WHERE id = '9dfe80c5-1c6a-4ec4-852c-1433440d5b52';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „წესების გათავისება“. ბავშვს ზოგიერთი წესი უკვე თქვენი შეხსენების გარეშეც ახსოვს: „ჭამის წინ ხელები დავიბანო?“. ეს გარეგანი დისციპლინის შინაგან დისციპლინად გარდაქმნის დასაწყისია. აუცილებლად შეაქეთ ასეთი დამოუკიდებელი პასუხისმგებლობისთვის — ეს მისი ხასიათის ჩამოყალიბებაში დიდი ნაბიჯია.') WHERE id = '5760ce33-81a1-4f8c-a7a0-f30c320a688a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე და ჩემი მეგობარი“. ბავშვი სხვა ბავშვებთან უკვე არა უბრალოდ გვერდიგვერდ, არამედ საერთო სცენარის მიხედვით იწყებს თამაშს (მაგალითად, „შენ დედა იყავი, მე კი ბავშვი“). ეს სოციალური თანამშრომლობისა და როლების განაწილების პირველი მნიშვნელოვანი გამოცდილებაა.') WHERE id = 'e6c24a0b-d760-47b5-90b8-f6d05b42625b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „კლასიფიკაციის ოსტატობა“. ბავშვს უკვე შეუძლია საგნების ერთდროულად ორი ნიშნის მიხედვით დაჯგუფება: „ისინი, რომლებიც წითელიცაა და პატარაც“. მიეცით მას ერთმანეთში არეული სათამაშოები და უთხარით: „ყველა პატარა მანქანა აქ მოაგროვე“. ეს მის ტვინში ლოგიკური გაფილტვრის უნარს ავითარებს.') WHERE id = '083c5f31-3fe0-44d9-b65b-c4b92bb36ae4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სამთვლიანი ველოსიპედის დამოუკიდებლად მართვა“. ბავშვს უკვე შეუძლია, საჭის მართვის პარალელურად პედლებიც რიტმულად ატრიალოს. ეს სხეულის ქვედა და ზედა ნაწილების კოორდინაციის შესანიშნავი ერთიანობაა. დროა, პარკში გასეირნება უფრო აქტიური გახადოთ.') WHERE id = 'e81ab935-f108-46cd-a88f-e53e09ed924f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 1000-დღიანი დიდი მარათონის ბოლო ათეულში! ბავშვი უკვე სრულად აცნობიერებს საკუთარ თავს და მოქმედებს განცდით: „მე უკვე დიდი ვარ“. თვალი გადაავლეთ მასთან ერთად გატარებულ 991 დღეს — პირველ ნაბიჯს, პირველ სიტყვას... ახლა ის როგორც ფიზიკურად, ისე გონებრივად სრულფასოვანი პიროვნებაა. თქვენი სიყვარული ამ შენობის ყველაზე მტკიცე საძირკველია.') WHERE id = 'b5b8d286-f3be-458e-9da0-f739ba54a527';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „რთული მანევრები“. ბავშვს უკვე შეუძლია სირბილისას მოულოდნელად გაჩერდეს, მიმართულება შეიცვალოს ან დაბრკოლებას გადაახტეს. ეს მისი ნერვული სისტემისა და კუნთების კოორდინაციის მომწიფებაზე მიუთითებს. განაგრძეთ მასთან ერთად სუფთა ჰაერზე მოძრავი თამაშები.') WHERE id = '40ef129f-5b1b-4e7a-8bf0-78a6953a2417';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ლოგიკური დიალოგი“. ბავშვს უკვე შეუძლია თქვენთან მსჯელობა: „დაძინება არ მინდა, რადგან თამაში ჯერ არ დამიმთავრებია“. ეს მხოლოდ სიჯიუტე არ არის — მას უკვე შეუძლია საკუთარი აზრის დასაბუთება. უპასუხეთ ლოგიკური ახსნა-განმარტებით, მაგალითად: „მართალი ხარ, მაგრამ მალე დაბნელდება“ და ამ გზით ურთიერთპატივისცემა ჩაუნერგეთ.') WHERE id = 'b9aae384-2df5-41c3-b46c-488d1b02a6ae';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „შემოქმედებითი ნახატები“. ბავშვი უკვე მხოლოდ ხაზებს კი არ ავლებს, არამედ ცდილობს დახატოს „ადამიანი“ (ჩვეულებრივ, წრისა და ხაზებისგან შედგენილი ჯოხისებრი ფიგურა), „სახლი“ ან „მზე“. ამ ნახატებით მის გონებაში არსებული სიმბოლოები ქაღალდზე გადმოდის. აუცილებლად შეინახეთ ეს „ხელოვნების ნიმუშები“.') WHERE id = '28f47857-a1db-40ef-a9e2-553a55c8a841';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „მზრუნველობა“. როდესაც ბავშვი ხედავს, რომ დაიღალეთ ან მისი მეგობარი ტირის, უკვე მიდის მასთან და ცდილობს დაამშვიდოს. ეს ემოციური ინტელექტის (EQ) ერთ-ერთი უმაღლესი გამოვლინებაა. მისი სუფთა გული იმ თანაგრძნობის ანარეკლია, რომელსაც თქვენ მას ჩუქნით.') WHERE id = 'ad204761-7be7-4b3d-9813-46b7f3ddfbf5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რიცხვისა და სიმბოლოს სინთეზი“. ბავშვს უკვე შეუძლია ციფრების სიმბოლოების (1, 2, 3) ვიზუალურად ამოცნობა და მათი შესაბამის რაოდენობასთან დაკავშირება. მიეცით პატარა დავალებები, მაგალითად: „აქ 3 ვაშლია, მაჩვენე ციფრი ''3''“. ეს სკოლამდელი მომზადების ერთ-ერთი ყველაზე სახალისო და მნიშვნელოვანი ეტაპია.') WHERE id = '277f876e-8768-4106-82f9-f67a9aa287de';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ადგილის ზმნიზედები“. ბავშვს უკვე სრულად და ზუსტად ესმის და იყენებს ცნებებს: „გვერდით“, „უკან“, „ქვეშ“ და „ზემოთ“. თუ ამბობს: „ბურთი დივნის ქვეშაა“, ეს ნიშნავს, რომ სივრცეში ორიენტირების უნარი სრულად აქვს ჩამოყალიბებული. მასთან დამალობანა ითამაშეთ, რათა ეს უნარი კიდევ უფრო განუვითარდეს.') WHERE id = '64ca65c7-1a28-48d4-beca-77b3f217471c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „მოთმინების გამოცდა“. ბავშვს უკვე ესმის, რომ სასურველის მისაღებად რამდენიმე წუთი უნდა დაელოდოს და მაშინვე ტირილს აღარ იწყებს. ასეთ დროს უთხარით: „დიდი მადლობა, რომ მოითმინე — ეს უკვე დიდობის ნიშანია“. თქვენ შესანიშნავი თანამგზავრი ხართ ამ გზაზე!') WHERE id = 'd29729c2-dd1d-4552-9d6e-3a6745ad9680';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ფერებისა და ფორმების გაერთიანებით აღწერს სამყაროს. თუ ამბობს: „ის ყვითელი კვადრატული კუბიკი მომეცი“, ეს მიუთითებს, რომ მისი ტვინი ერთდროულად რამდენიმე მახასიათებელს ამუშავებს. ხელი შეუწყვეთ ამ უნარის განვითარებას ყოველდღიურ ცხოვრებაში მცირე დავალებებით (მაგალითად, „იპოვე შენი ლურჯი წინდები“).') WHERE id = '6e9a3917-235a-4638-821e-7544b6f6fd44';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „დინამიკური წონასწორობა“. ბავშვს უკვე შეუძლია ცალ ფეხზე 5 წამამდე დგომა. ეს ვესტიბულური სისტემის (წონასწორობის ცენტრისა) და ფეხის კუნთების გაძლიერებაზე მიუთითებს. მასთან ერთად ითამაშეთ „ყარყატი“ და შეამოწმეთ, ვინ შეძლებს ცალ ფეხზე უფრო დიდხანს დგომას.') WHERE id = 'bf8d8f80-94a0-4e9e-beaa-a9027d0e8ae4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მიზეზშედეგობრივი კავშირები“. ბავშვი უკვე იწყებს „თუ... მაშინ...“ ტიპის წინადადებების გაგებას. როდესაც ეუბნებით: „თუ სათამაშოებს დაალაგებ, მულტფილმს ვუყურებთ“, მას ეს პირობა ესმის. ეს მნიშვნელოვანი ნაბიჯია როგორც ლოგიკური აზროვნების, ისე თვითდისციპლინის (self-discipline) ჩამოყალიბებისთვის.') WHERE id = 'b1f57847-eeec-4119-b2fc-2905b91fb26b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „მაკრატლის გამოყენების პირველი გამოცდილება“. ბავშვი უკვე ინტერესდება ქაღალდის სწორ ხაზზე გაჭრით (უსაფრთხო მაკრატლის გამოყენებით). ეს მოქმედება მნიშვნელოვნად ავითარებს როგორც ხელისა და თვალის კოორდინაციას, ისე თითების წვრილ მოტორიკას. ნუ დატოვებთ მას ზედამხედველობის გარეშე, თუმცა დამოუკიდებლად მოქმედებაშიც ნუ შეუშლით ხელს.') WHERE id = 'bc3bff7e-368e-485f-8abd-ee144e6a6477';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „წარმოსახვითი თამაშის მეგობრები“. ბავშვი უკვე მარტო თამაშის დროსაც ხმამაღლა საუბრობს და სათამაშოებს სხვადასხვა როლს ანიჭებს. ეს „ეგოცენტრული მეტყველებაა“ და ბავშვს საკუთარი მოქმედებების სიტყვებით მართვაში ეხმარება. მის ამ „მონოლოგებს“ თუ მოუსმენთ, უკეთ გაიგებთ, რა ხდება მის შინაგან სამყაროში.') WHERE id = '9f4b387f-964e-4bb9-856d-1ac035b357f4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი: გადაწყვეტილების მიღება“. ბავშვმა უკვე ზუსტად იცის, რისი ჭამა ან რომელი თამაშის თამაში სურს. ყოველდღე შესთავაზეთ ორი ალტერნატივა: „ვაშლი გინდა თუ ბანანი?“. ეს მას საკუთარ ცხოვრებაზე კონტროლის განცდას უჩენს და თავდაჯერებულობას უმაღლებს.') WHERE id = '7022c99f-3026-41d3-8d24-5d2da8ff257d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „მოცულობისა და რაოდენობის მუდმივობის გააზრება“. ბავშვმა შეიძლება ჯერ კიდევ იფიქროს, რომ ვიწრო და მაღალ ჭურჭელში უფრო მეტი წყალია, ვიდრე განიერ ჭურჭელში. ეს პიაჟეს განვითარების ეტაპისთვის დამახასიათებელი ნორმალური მოვლენაა. ითამაშეთ მასთან წყლით და ერთად გადაასხით წყალი სხვადასხვა ჭურჭელში. ეს პრაქტიკული გამოცდილება ლოგიკური აზროვნების განვითარებას აჩქარებს.') WHERE id = '63894550-7c88-4d80-827d-abe697cce597';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორი ფეხით წინ გადახტომა“. ბავშვს უკვე შეუძლია დაბრკოლებებს (მაგალითად, იატაკზე დადებულ თოკს) ორივე ფეხით ერთდროულად გადაახტეს. ამას მთელი სხეულის კოორდინაცია და სწრაფი ძალისხმევა სჭირდება. უსაფრთხო ადგილებში მოუწყეთ პატარა დაბრკოლებების ზოლი.') WHERE id = 'cab49b1b-46a8-46fe-9575-6cef46f13add';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „დროის აბსტრაქტული გაგება“. ბავშვი უკვე ყოველდღიური რიტუალების მეშვეობით აცნობიერებს განსხვავებას „დილას“, „შუადღესა“ და „საღამოს“ შორის. როდესაც ეუბნებით: „საღამოს, როცა მამა მოვა...“, ის გონებაში დღის შესაბამის მონაკვეთს წარმოიდგენს. ყოველდღიური რეჟიმის დაცვა ეხმარება, დროის ეს გაგება უსაფრთხოების განცდას დაუკავშიროს.') WHERE id = '50a38f0a-e830-42a7-9b23-0d529496ee7f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმწიფე: სიტყვა „მაპატიეს“ მნიშვნელობა. ბავშვი უკვე აცნობიერებს, რამდენად მნიშვნელოვანია ბოდიშის მოხდა, როცა განზრახ ან უნებლიეთ ვინმეს აწყენინებს. ყოველთვის მიეცით მაგალითი — როცა შეცდომას დაუშვებთ, თავადაც მოუხადეთ ბოდიში, რათა მან ეს ქცევა სისუსტედ კი არა, სიძლიერედ აღიქვას.') WHERE id = 'f7b6ee04-7015-4382-abaa-03462e452408';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე სურათების მიხედვით მარტივ ამბებს იგონებს. ისეთი თანმიმდევრული წინადადებები, როგორიცაა „დათვი ტყეში წავიდა, მოშივდა და თაფლი შეჭამა“, აჩვენებს, რომ მას ლოგიკური თანმიმდევრობა ესმის. მიეცით წიგნები საინტერესო ილუსტრაციებით და ჰკითხეთ: „როგორ ფიქრობ, შემდეგ რა მოხდება?“ ეს მის შემოქმედებით წარმოსახვას მნიშვნელოვნად ავითარებს.') WHERE id = '5b5539ed-db72-44da-bf5f-8b147bfb9b43';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „კიბეზე თავისუფლად გადაადგილება“. ბავშვი უკვე თავდაჯერებულად ჩამოდის კიბეზე, თითო საფეხურზე ფეხების მონაცვლეობით დადგმით და მხოლოდ ერთი ხელის ჩაჭიდებით (ან საერთოდ ხელის ჩაჭიდების გარეშე). ეს მიუთითებს, რომ მისი მსხვილი მოტორული უნარები კარგად არის განვითარებული. უბრალოდ მის გვერდით იყავით და ემოციურად გაამხნევეთ.') WHERE id = 'e1ab27cc-4713-481c-b52f-32935f62d3d2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვა-პასუხის ჯაჭვი“. ბავშვი თქვენს შეკითხვებს უკვე არა მხოლოდ „კი/არა“-თი, არამედ სრული წინადადებებით პასუხობს. შეკითხვაზე „დღეს პარკში ვისთან ერთად ითამაშე?“ მას შეუძლია დეტალური პასუხი გაგცეთ. საუბრისას დაუსვით დამატებითი შეკითხვები, მაგალითად: „რა ფერის იყო?“ ან „რა გააკეთეთ?“ — ამგვარად მის მეტყველებას განავითარებთ.') WHERE id = '7d186d1a-0812-440c-b07e-ee9ed0da127d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „უფრო ზუსტად გაფერადება“. ბავშვი უკვე პატარა ფორმების საზღვრებსაც აღიქვამს და გაფერადებისას ცდილობს, კონტურებს ზედმეტად არ გადასცდეს. ეს ხელის კუნთების კონტროლის მხრივ დიდი წინსვლაა. მიეცით სხვადასხვა სისქის ფანქრები და შეუქმენით პირობები, რომ მოსინჯოს და ექსპერიმენტები ჩაატაროს.') WHERE id = 'a7b0a891-2fdb-4521-b60b-98a992dcf545';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმა: ელვა და ღილი“. ბავშვს უკვე კარგად შეუძლია დიდი ღილების გახსნა და ელვის ზემოთ აწევა (მას შემდეგ, რაც მის შეკვრაში დაეხმარებით). უთხარით: „მოდი, თავად სცადე“ და მოთმინებით დაელოდეთ. დამოუკიდებლად ჩაცმის უნარი ბავშვში „მე შემიძლია“ განცდასა და თავდაჯერებულობას საგრძნობლად აძლიერებს.') WHERE id = '9893a146-5d99-48e6-ae6a-1f46520795f5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გაზიარების ლოგიკა“. ბავშვი უკვე ცდილობს, სხვა ბავშვს სათამაშო ხელიდან მაშინვე არ წაართვას, თქვას „მომეცი“ და დაელოდოს. ეს თვითრეგულაციის (self-regulation) უნარის განმტკიცებაზე მიუთითებს. როდესაც ასეთ მოთმინებას გამოიჩენს, აუცილებლად შეაქეთ და უთხარით: „დიდი მადლობა, რომ შენს რიგს დაელოდე“.') WHERE id = '71a96327-cfe2-4ab5-bb79-d332a1ff5de4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „საპირისპირო მნიშვნელობის სიტყვების მარაგის გაფართოება“. ბავშვს უკვე ესმის ისეთი აბსტრაქტული საპირისპირო ცნებები, როგორიცაა „სწრაფი-ნელი“, „ბნელი-ნათელი“, „ცარიელი-სავსე“. აჩვენეთ ცარიელი და სავსე ჭიქები და ჰკითხეთ, რა განსხვავებაა მათ შორის. ეს გარემომცველი სამყაროს შედარებითი ანალიზის უნარს განუვითარებს.') WHERE id = 'a89f9de3-ed84-4cfa-95a8-cf4c5d345de7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „ფაზლების ოსტატობა“. ბავშვს უკვე შეუძლია რთული, 10-12-ნაწილიანი ფაზლების აწყობა — სურათის კიდეებისა და ცენტრალური ნაწილის ერთმანეთისგან გარჩევით. ეს ავითარებს როგორც ვიზუალურ მეხსიერებას, ისე თითების ზუსტი მოძრაობის უნარს. თუ არ გამოუვა, მშვიდი ტონით მიეცით მინიშნებები.') WHERE id = '81c4bfcb-e5df-4929-b621-91e622f18ac6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად დალაგება და დახმარება“. ბავშვს უკვე ძალიან მოსწონს სუფრის ალაგებისას თავისი თეფშის წაღება, ნამცეცების მოწმენდა და მსგავსი საქმეების შესრულება. მიეცით მის სიმაღლეზე მორგებული დასუფთავების ნივთები. ეს ოჯახში პასუხისმგებლობისა და კუთვნილების განცდას განუმტკიცებს. საკუთარი შრომის შედეგის დანახვა მას ძალიან აბედნიერებს.') WHERE id = '9ef3f34d-a63f-4f49-9005-c854d4303909';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „წესები და საზღვრები“. ბავშვს უკვე ოდნავ უკეთ ესმის სიტყვა „არას“ მიღმა არსებული ლოგიკა, თუმცა კვლავ უყვარს საზღვრების გამოცდა. თქვენი მოთმინება და თანმიმდევრულობა მას უსაფრთხოების განცდას უქმნის. ეცადეთ, წესები ყოველთვის ერთნაირად გამოიყენოთ.') WHERE id = 'c4d24c3e-4601-4235-8cdc-f39b3aa35149';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „რიგობითი რიცხვითი სახელები“. ბავშვს უკვე ესმის ცნებები „პირველი“, „მეორე“ და „ბოლო“. დაალაგეთ მანქანები მწკრივად და ჰკითხეთ: „რომელი მანქანაა პირველი?“ ეს თანმიმდევრობის აღქმასა და მათემატიკურ აზროვნებას განუვითარებს. შეჯიბრებისას სიტყვები „შენ პირველი მოხვედი!“ მისთვის დიდი მოტივაციაა.') WHERE id = 'b0d3eed0-e639-4528-9c81-8601b70e54bd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკან და გვერდულად სიარული“. ბავშვს უკვე შეუძლია სხვადასხვა მიმართულებით მოქნილად მოძრაობა. ითამაშეთ მასთან „სარკის თამაში“: თქვენ გვერდზე გადადგით ნაბიჯი, ბავშვმა კი გაგიმეოროთ. ეს არა მხოლოდ სახალისოა, არამედ სხეულის კოორდინაციასაც ახალ დონეზე ავითარებს.') WHERE id = 'da0e2216-17ef-49f2-83ad-1599f6a6e332';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „ზოგადი და კონკრეტული“. ბავშვს უკვე ესმის, რომ ვაშლი, მსხალი და ბანანი — ყველა „ხილია“. აჩვენეთ მას ერთმანეთში შერეული საგნები და ჰკითხეთ: „ამ ყველაფერს ერთად რას ვუწოდებთ?“ კატეგორიებით აზროვნება მის ტვინში ინფორმაციის შენახვის სისტემას უფრო მოწესრიგებულს ხდის.') WHERE id = 'f440da85-66a5-444d-9191-5dceb0b51d20';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მხარს ზემოდან სროლა“. ბავშვი ბურთს უკვე უბრალოდ ძირს კი არ აგდებს, არამედ შეუძლია მხარს ზემოდან წინ, კონკრეტული სამიზნისკენ ისროლოს. ეს მთელი სხეულის კოორდინაციას მოითხოვს. პარკში მასთან ერთად ითამაშეთ „სამიზნეში სროლა“.') WHERE id = '5a9ea9e5-b06c-4aa9-b965-a6664f7442e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სივრცე და მიმართულება“. მიუხედავად იმისა, რომ ბავშვს „მარჯვენა“ და „მარცხენა“ ჯერ ბოლომდე ზუსტად არ აქვს გარჩეული, ბრძანებებს „წინ“, „უკან“, „ზემოთ“ და „ქვემოთ“ ზუსტად ასრულებს. ითამაშეთ მასთან „რობოტობანა“: „ორი ნაბიჯი წინ, ერთი ნაბიჯი უკან!“ ეს სახალისოცაა და სივრცეში ორიენტირების უნარსაც აძლიერებს.') WHERE id = '6ef1e101-45d4-451a-8710-b32b9878cd2e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „წარუმატებლობასთან გამკლავება“. როდესაც კუბიკები ენგრევა, ბავშვი უკვე მაშინვე აღარ ტირის და შეუძლია თქვას: „თავიდან ავაწყობ“. ხელი შეუწყვეთ მის მებრძოლ სულისკვეთებას. 1030 დღე უკან მოვიტოვეთ — თქვენი შვილი უკვე პატარა გმირია!') WHERE id = '1293c75f-beda-4513-88cc-b7951ec10777';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საგნების ერთდროულად ორი ნიშნის მიხედვით დაჯგუფება (მაგალითად, ფერისა და ფორმის მიხედვით). თუ დავალებას — „მომეცი ყველა პატარა წითელი მანქანა“ — სწორად ასრულებს, ეს მისი შემეცნებითი განვითარების ახალი საფეხურია. ყოველდღიური საოჯახო საქმეებისას მიეცით მსგავსი მცირე „შერჩევის“ დავალებები.') WHERE id = 'fa3d103a-9bc8-44ef-b8d5-cab5337e7b60';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში „სამიზნეზე დახტომა“. ბავშვი უკვე ცდილობს იატაკზე დახატული წრის ან ფერადი სამიზნის შუაგულში ჩახტეს. ეს აუმჯობესებს როგორც წონასწორობას, ისე სივრცეში მანძილის განსაზღვრის უნარს. პარკში მასთან ერთად ითამაშეთ „ქვიდან ქვაზე ხტომა“.') WHERE id = '4bbc0ebb-e4d4-4fb1-9a60-923e8fae76b3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული კითხვების გაღრმავება“. ბავშვმა შეიძლება გაგაოცოთ ისეთი კითხვებით, როგორიცაა: „სად მიდიან ღრუბლები?“ ან „რატომ ჩნდებიან ვარსკვლავები ღამით?“. პასუხის გაცემისას მისი წარმოსახვაც ჩართეთ: „შენი აზრით, რას აკეთებენ ახლა ვარსკვლავები?“. ეს მის შემოქმედებით აზროვნებას ავითარებს.') WHERE id = '1f153d5c-5da7-4c69-b731-2dc34e06cb4f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „გაზიარების სიხარული“. როცა ბავშვი უკვე საკუთარი სურვილით უზიარებს სხვას სათამაშოს ან ტკბილეულს, ის თქვენს სიხარულს ხედავს და სურს, ეს კვლავ გაიმეოროს. განსაკუთრებულად აღნიშნეთ მისი გულუხვობა და უთხარით: „დიდი მადლობა, რომ მეგობარი გაახარე“. 1040 დღე წარმატებით გავიარეთ — თქვენ შესანიშნავი დედა ხართ!') WHERE id = '3c9e08eb-1969-4283-90ec-97d2de26fd19';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '35-ე თვეში გადავდივართ! ბავშვი უკვე „ორსაფეხურიანი“ აზროვნებიდან „სამსაფეხურიანი“ დავალებების შესრულებაზე გადადის. თუ მითითებას — „აიღე სათამაშო, ჩადე ყუთში და დაახურე თავსახური“ — თანმიმდევრობის დარღვევის გარეშე ასრულებს, ეს მისი მუშა მეხსიერების (working memory) მნიშვნელოვანი მიღწევაა. დღის განმავლობაში მცირე, ლოგიკურად ერთმანეთთან დაკავშირებული დავალებების მიცემით დაეხმარეთ ამ უნარის დახვეწაში.') WHERE id = 'b4ed41fc-fc60-439e-82df-81e0242123d3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „სწრაფი სირბილი და მანევრირება“. ბავშვს უკვე შეუძლია სირბილისას წინ დაბრკოლების დანახვა და მისთვის გვერდის ავლა სიჩქარის შეუმცირებლად. ეს მიუთითებს, რომ მისი სხეულის აღქმა (პროპრიოცეფცია) კარგად არის განვითარებული. პარკში „დაბრკოლებებით სირბილის“ შეჯიბრებები მოაწყვეთ და მისი ენერგია სასარგებლო მიმართულებით წარმართეთ.') WHERE id = '140764ec-2a00-4bc6-b514-5e093357430f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „შედარების ხარისხები“. ბავშვი უკვე სწორად იყენებს ისეთ გამოთქმებს, როგორიცაა „უფრო დიდი“, „ყველაზე პატარა“ და „ძალიან გემრიელი“. ესაუბრეთ მას საგნების შედარებისას: „ეს ვაშლი უფრო ტკბილია თუ მეორე?“. ზედსართავი სახელების შედარების ხარისხების ათვისება მის აღწერით მეტყველებას ამდიდრებს და აზრის უფრო ზუსტად გამოხატვას უწყობს ხელს.') WHERE id = '5868f762-ea68-431f-855d-54c5a04efe50';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ძერწვა“. პლასტილინთან ან კინეტიკურ ქვიშასთან მუშაობისას ბავშვი მათ უკვე მხოლოდ კი არ ჭყლეტს, არამედ აკეთებს ისეთ ამოსაცნობ ფორმებს, როგორიცაა „ბურთი“, „გველი“ ან „პური“. ეს შესანიშნავი ვარჯიშია როგორც შემოქმედებითი აზროვნების განვითარებისთვის, ისე თითის წვერების წვრილი კუნთების გასაძლიერებლად.') WHERE id = '060a9ae6-7e66-446f-800a-a74eb2d502d9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე უფრო ღრმად აღიქვამს „ჯერ“ და „შემდეგ“ თანმიმდევრობას. როდესაც ეუბნებით: „ჩაიცვი და შემდეგ გარეთ გავიდეთ“, ის ხვდება, რომ მეორე მოქმედება ერთგვარი ჯილდოა. ეს ბავშვში მოთმინებისა და დაგეგმვის უნარის პირველი ჩანასახებია. ხშირად შეახსენეთ ეს თანმიმდევრობა ყოველდღიური რიტუალების დროს.') WHERE id = '2add65f7-d33c-4b48-a1e7-f388a5549421';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ცოცვის ოსტატობა“. ბავშვი უკვე უფრო თავდაჯერებულად ადის პარკის კიბეებზე ან სახლში უსაფრთხო სიმაღლეებზე. ამ დროს ხელებისა და ფეხების კუნთები სინქრონულად მუშაობს. ყოველთვის ახლოს იყავით, თუმცა მიეცით საშუალება, საკუთარი ძალები გამოსცადოს.') WHERE id = '25d5eedf-59a2-4e4e-8131-39a811d36fe6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ლოგიკური კავშირები“. ბავშვი უკვე ორ მოვლენას ერთ წინადადებაში აერთიანებს: „გარეთ ცივა, ქურთუკი ჩაიცვი“. ეს აჩვენებს, რომ ის უბრალოდ კი არ ბაძავს, არამედ აზროვნებს კიდეც. დაუდასტურეთ მისი ლოგიკური მსჯელობა სიტყვებით: „დიახ, მართალი ხარ“, რათა საკუთარი აზრების გამოხატვის მეტი სურვილი გაუჩნდეს.') WHERE id = '90469c76-8fc0-41db-a7e9-3862f12f4d6b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ქაღალდით მანიპულირება“. ბავშვმა შეიძლება უკვე გამოიჩინოს ინტერესი ქაღალდის დაკეცვის ან მარტივად გამოჭრის მიმართ (დიდი საბავშვო მაკრატლით, ზედამხედველობის ქვეშ). ეს მოქმედებები თითების კუნთების კონტროლს ახალ დონეზე ავითარებს. შეუქმენით პირობები ფერადი ქაღალდებით სამუშაოდ.') WHERE id = '8f149cc4-a06e-4928-a8cb-2b953480c3af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „როლური თამაშების გართულება“. ბავშვი უკვე ირგებს „ექიმის“, „მზარეულის“ ან „მძღოლის“ როლს. ამ თამაშების მეშვეობით ის გარშემო მყოფი ადამიანების მოვალეობებს ეცნობა და ემპათიას ავითარებს. შეუერთდით მის თამაშებს და მოიქეცით იმ „როლის“ შესაბამისად, რომელსაც მოგანიჭებთ.') WHERE id = 'c9bd395e-c3c2-46e2-abf3-1f924d619000';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად სისუფთავის დაცვის“ ჩვევა. ხელების დაბანისას ბავშვს უკვე თითქმის დამოუკიდებლად შეუძლია საპნის წასმა და ხელების ჩამობანა. ამ ასაკში ჰიგიენური ჩვევების განმტკიცება ძალიან მნიშვნელოვანია. დაუდგით მისი სიმაღლის შესაბამისი საფეხურიანი სკამი, რათა ეს პროცესი მისთვის სასიამოვნო იყოს.') WHERE id = 'dd1b7d3a-2552-45df-81c5-cf8e1914b882';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"დამოუკიდებლად ჩაცმა: ტანსაცმლის უკუღმა და სწორად გარჩევა". ბავშვი უკვე ცდილობს გაარჩიოს მაისურისა და შარვლის უკუღმა და სწორი მხარეები, ასევე მარჯვენა და მარცხენა ფეხსაცმელი (თუმცა ზოგჯერ ჯერ კიდევ ეშლება). მიეცით მცირე მინიშნებები: "შეხედე, ნახატიანი მხარე წინ უნდა იყოს". ეს ეხმარება მას, ყურადღება დეტალებზე გაამახვილოს და თვითმოვლის უნარები განივითაროს.') WHERE id = 'a1a89564-b6bb-483a-bd10-bb44b24484a4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"გუნდური სულისკვეთება" სოციალურ ქცევაში. ბავშვს უკვე შეუძლია სხვა ბავშვებთან ერთად საერთო მიზნის მისაღწევად თამაში (მაგალითად, დიდი ციხესიმაგრის ასაშენებლად). ეს არის "პარალელური თამაშიდან" "თანამშრომლობით თამაშზე" გადასვლა. დააკვირდით, როგორ პოულობს ის საერთო ენას სხვა ბავშვებთან და რთულ მომენტებში დაეხმარეთ სოციალური "ხიდის" აგებაში.') WHERE id = '999ddf88-03eb-4dd0-856d-79ce3e7385df';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"რიცხვისა და რაოდენობის შესაბამისობა" შემეცნებით განვითარებაში. ბავშვმა იცის 1-დან 5-მდე დათვლა და ახლა, როდესაც ციფრ "3"-ს ხედავს, შეუძლია 3 სათამაშო ცალკე გადადოს. ეს მათემატიკური აზროვნების განვითარების ერთ-ერთი უმნიშვნელოვანესი ეტაპია. ყოველდღიურ ცხოვრებაში ეს კავშირი განამტკიცეთ ისეთი დავალებებით, როგორიცაა: "მომეცი 2 კოვზი".') WHERE id = '8193ed91-5f04-4955-a4b1-522d5a941870';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: "ზემოდან ნასროლი ბურთის დაჭერა". ბავშვი უკვე ცდილობს, მისკენ ნელა ნასროლი დიდი ბურთი ორივე ხელით დაიჭიროს. ეს მოძრაობა მოითხოვს როგორც ხელისა და თვალის კოორდინაციას, ისე სწრაფ რეაქციას. ახლო მანძილიდან ეთამაშეთ მას "ბურთის დაჭერა".') WHERE id = '575cf871-23de-446e-8398-4dd4c0ff6773';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"აბსტრაქტული კითხვების პიკი" მეტყველებაში. ბავშვი უკვე სვამს კითხვებს სამყაროსა და ბუნებრივი მოვლენების შესახებ, მაგალითად: "რატომ ქრის ქარი?", "სად მიდის მზე დასაძინებლად?". პასუხის გაცემისას წარმოსახვაც ჩართეთ: "მზე დაიღალა და დასასვენებლად მიდის, რათა ხვალ ისევ გაგვაღვიძოს". ეს აფართოებს მის მსოფლმხედველობას და სწავლის სურვილს აძლიერებს.') WHERE id = 'fdfb7732-94cf-4e6c-8519-4e6877b4ad89';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმწიფე: "სხვისი ემოციების აღიარება". როდესაც ბავშვი ხედავს, რომ თქვენ დაიღალეთ ან სხვა ბავშვი ნაწყენია, უკვე გეკითხებათ: "რა მოხდა?" და ცდილობს დაგამშვიდოთ. ეს აჩვენებს, რომ ის თანაგრძნობით სავსე პიროვნებად ყალიბდება. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '9721a15c-607b-4236-9999-231bdd0b4e99';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარება: „იპოვე განსხვავებული“. ბავშვს უკვე შეუძლია საგნების ჯგუფიდან ვიზუალურად გამოარჩიოს განსხვავებული ნივთი (მაგალითად, მანქანებს შორის ვაშლი). ეს მის ანალიზის უნარს ავითარებს. სახლში მოუწყეთ მარტივი თამაშები — „რომელია ზედმეტი?“. ეს სამომავლო მათემატიკური და ლოგიკური დავალებებისთვის შესანიშნავი მომზადებაა.') WHERE id = 'f8163db2-8f81-44fa-bc05-1057d8b42f15';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ერთ ფეხზე დგომის მცდელობები“. ბავშვს უკვე შეუძლია, თუნდაც რამდენიმე წამით, ერთი ფეხი ასწიოს და წონასწორობის შენარჩუნება სცადოს. ეს მნიშვნელოვანია სხეულის სიმძიმის ცენტრის აღქმისთვის. მასთან ერთად ითამაშეთ „ყარყატის თამაში“ და ნახეთ, ვინ უფრო დიდხანს გაჩერდება ერთ ფეხზე.') WHERE id = '0dbea1ae-3808-4d99-b129-68ed1447a173';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „გრძნობების გამოხატვა“. ბავშვს უკვე შეუძლია სიტყვებით თქვას, რომ მოწყენილია, მხიარულადაა ან ეშინია: „შემეშინდა“ ან „მხიარულად ვარ“. გრძნობებისთვის სახელის დარქმევა ბავშვის ემოციური ინტელექტის საფუძველია. როცა თავის გრძნობაზე გესაუბრებათ, მოუსმინეთ და უთხარით: „დიახ, მესმის შენი“, რათა დაანახოთ, რომ მის განცდებს აღიარებთ.') WHERE id = '384f5938-24c1-4dc2-8691-403780565471';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის ძალა: „სიმბოლური აზროვნება“. ბავშვმა შეიძლება ჯოხი „ცხენად“ წარმოიდგინოს და მასზე ამხედრებულივით ირბინოს. ეს არის უნარი, გაიაზროს, რომ ერთი საგანი შეიძლება სხვა რამეს განასახიერებდეს. ეს უნარი მომავალში კითხვისა და მათემატიკისთვის (სიმბოლოების გასაგებად) ძალიან მნიშვნელოვანია. თქვენ შესანიშნავი მეგზური ხართ!') WHERE id = '94697180-1105-4fe0-9d68-ffdaab53705e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე სწორად იყენებს ნაცვალსახელებს „მე“, „შენ“ და „ჩვენ“. როცა ამბობს: „ახლა ჩვენ ვჭამთ?“, თავს ოჯახის აქტიურ წევრად გრძნობს. მასთან საუბრისას თქვენს გეგმებში ისიც ჩართეთ: „მოდი, სუფრა ერთად გავშალოთ“. ეს აძლიერებს მის მიკუთვნებულობისა და პასუხისმგებლობის განცდას.') WHERE id = '38010093-f42b-4818-a3db-81219f590eee';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოძრაობა: „კიბეზე თავისუფლად ასვლა“. ბავშვი უკვე თავდაჯერებით ადის კიბეზე, ყოველ საფეხურზე მონაცვლეობით დგამს თითო ფეხს და მხოლოდ ერთი ხელით ეჭიდება უფროსს. ეს მიუთითებს, რომ მისი მსხვილი მოტორული უნარები სრულად მომწიფდა. უბრალოდ მის გვერდით იყავით და მორალურად მხარი დაუჭირეთ.') WHERE id = '8503d4e9-2c78-4879-9d8c-ef7c6d2a467c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ამბის შეთხზვა“. ბავშვს უკვე შეუძლია, სურათების დათვალიერებისას მარტივი ამბები მოიგონოს. ისეთი თანმიმდევრული წინადადებები, როგორიცაა „კატა მოვიდა, რძე დალია და დაიძინა“, მისი მეხსიერებისა და წარმოსახვის ერთობლივი მუშაობის შედეგია. მიეცით წიგნები საინტერესო ილუსტრაციებით და ჰკითხეთ: „რა ხდება აქ?“ ეს მის შემოქმედებით აზროვნებას გააღვივებს.') WHERE id = 'ebe63eb5-d3b9-410d-8ddc-267b97751075';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ზუსტი განთავსება“. ბავშვს უკვე ნაკლები შეცდომით შეუძლია პატარა სათამაშო ფიგურების სწორ ადგილას მოთავსება ან მძივების ძაფზე აცმა. ამ პერიოდში თითის წვერების მგრძნობელობა იზრდება. შესთავაზეთ თამაშები სხვადასხვა ტექსტურის მქონე პატარა საგნებით (თქვენი მეთვალყურეობის ქვეშ).') WHERE id = '9acc3fd3-37ec-4b80-9709-ac31444a2801';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმის“ დაჟინებული სურვილი. ბავშვი უკვე დაჟინებით ცდილობს, ღილების გარეშე მაისური ან შარვალი თვითონ ჩაიცვას. როცა ამბობს: „მე თვითონ!“, მიეცით დრო. დამოუკიდებლობისკენ ასეთი სწრაფვა მომავალში თავდაჯერებულობისა და პირადი პასუხისმგებლობის ყველაზე მტკიცე საფუძველია. აღნიშნეთ მისი პატარა წარმატებები სიტყვებით: „ხედავ, სულ მარტომ შეძელი!“') WHERE id = '48d41fa6-6f48-4a84-a2b6-f82cae4ce209';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „თავაზიანობის წესები“. ბავშვი ისეთ სიტყვებსა და ფრაზებს, როგორებიცაა „თუ შეიძლება“, „დიდი მადლობა“ და „გთხოვ“, უკვე უბრალოდ კი არ იმეორებს, არამედ მიზანმიმართულად იყენებს. თქვენი თავაზიანი ქცევა მისთვის საუკეთესო მაგალითია. შეაქეთ ასეთი ქცევისთვის და ამით კომუნიკაციის კულტურა განუმტკიცეთ.') WHERE id = 'fe3ec85d-8b47-408d-a0ad-870b3b58db94';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დროის ზმნიზედები“. ბავშვი სიტყვების „შემდეგ“, „ცოტა ხანში“ და „ახლა“ სწორად გამოყენებას იწყებს. როდესაც ეუბნებით: „ცოტა ხანში მოვალ“, ის აცნობიერებს, რომ დრო უნდა გავიდეს. ეს ბავშვს ლოდინისა და თვითრეგულირების უნარს უვითარებს. ხშირად გამოიყენეთ ეს სიტყვები თქვენს ყოველდღიურ რიტუალებში.') WHERE id = 'df8b2f32-9f00-4805-8e4c-c754c399be31';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დარტყმა და მიზანში მოხვედრა“. ბავშვი ბურთს უკვე უბრალოდ კი არ ურტყამს, არამედ ცდილობს, კონკრეტული მიმართულებით გააგოროს — მაგალითად, ორ სათამაშოს შორის გაატაროს. ეს ხელისა და თვალის, ასევე ფეხისა და თვალის კოორდინაციის სინქრონული მუშაობაა. მოაწყვეთ მასთან ერთად სახლში „მინი ფეხბურთის“ ტურნირი.') WHERE id = '852439ac-fd00-4ba1-aa13-d519b9407d5f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული კითხვები“. ბავშვმა შეიძლება დასვას კითხვები, როგორიცაა: „საიდან მოდის ღრუბელი?“ ან „სად წავიდა მთვარე?“. პასუხის გაცემისას წარმოსახვითი და რეალური ინფორმაცია დააბალანსეთ: „ღრუბლები შორიდან მოდიან და წვიმა მოაქვთ“. ასეთი საუბრები წარმოუდგენლად აფართოებს მის მსოფლმხედველობას და სწავლის სურვილს.') WHERE id = 'fe4cb6a5-1e61-4aaa-9066-7165c1ab72dd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური გამძლეობა: ბავშვი უკვე უფრო მედეგია წარუმატებლობის მიმართ. როდესაც კუბიკებით აშენებული კონსტრუქცია ენგრევა, მაშინვე აღარ ტირის და შეუძლია თქვას: „თავიდან ავაშენებ“. მხარი დაუჭირეთ მის შეუპოვრობას. უკვე 1070 დღე გავიარეთ და 3 წლის შესრულებამდე ძალიან ცოტა დარჩა! ამ გზაზე თქვენ მისთვის მასწავლებელიც ხართ და საუკეთესო მეგობარიც!') WHERE id = '39f0d5e2-0187-4785-9bb9-453ef9250d3e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე იწყებს საკუთარი თავის სხვა ბავშვებთან შედარებას: „მე მასზე სწრაფად დავრბივარ“. ეს მეტოქეობის განცდა კი არა, საკუთარი შესაძლებლობების გაცნობიერების ერთ-ერთი ფორმაა. მარტივი ენით აუხსენით, რომ ყველას განსხვავებული უნარები აქვს. ეს მასში საკუთარი თავის პატივისცემასა და სხვების მიმართ შემწყნარებლობას აყალიბებს.') WHERE id = 'b9b4b281-d07d-4b24-8be3-a13d61d2de12';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „სწრაფად გაჩერება“. სირბილისას ბავშვს შეუძლია თქვენი ბრძანების — „გაჩერდი!“ — გაგონებისთანავე გაჩერდეს. ეს მიუთითებს როგორც კუნთების ფიზიკური მართვის, ისე ტვინში იმპულსების შეკავების უნარზე (inhibitory control). შესანიშნავი დროა, რომ პარკში თამაში „წითელი შუქი, მწვანე შუქი“ ითამაშოთ.') WHERE id = '36d86d2b-43c1-4460-afbb-45a783701a53';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „რთული დიალოგები“. ბავშვს უკვე შეუძლია თანმიმდევრულად მოგიყვეთ რაიმე ამბავი: „ჯერ პარკში წავედით, შემდეგ ნაყინი ვჭამეთ, მერე კი კატა დავინახეთ“. ამბის თხრობის ეს უნარი მისი მეხსიერებისა და მეტყველების ერთობლივი განვითარების შედეგია. ჰკითხეთ: „და შემდეგ რა მოხდა?“ — და წაახალისეთ, რომ ამბავი განავრცოს.') WHERE id = '62cbc2dc-4d91-48c4-8b87-f71ac5555a0a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „გეომეტრიული ფიგურების გადახატვა“. ბავშვს უკვე შეუძლია თქვენ მიერ დახატული წრის ან ჯვრის გამეორება. ეს ნიშნავს, რომ უვითარდება თვალით დანახული ფორმის ხელით გამეორების უნარი (ვიზუალურ-მოტორული ინტეგრაცია). ასწავლეთ სხვადასხვა ფერის ფანქრებით ფორმების დახატვა.') WHERE id = 'c219d541-0794-4388-b19c-1b3296bc6f1a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი გადაწყვეტილებები“. ბავშვი უკვე მტკიცედ ირჩევს, რომელი სათამაშოთი ითამაშოს ან რომელი წიგნი წაიკითხოს. მიეცით მას ამ არჩევანის გაკეთების შესაძლებლობა. როდესაც ბავშვი ხედავს, რომ მის არჩევანს პატივს სცემენ, თავდაჯერებულობა ემატება და მისი შინაგანი სამყარო მდიდრდება.') WHERE id = '064446a8-f711-4f01-89fb-101964123929';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „რიგის დაცვა“. ბავშვს უკვე ესმის, რომ საქანელაზე ყველა ერთდროულად ვერ იქანავებს. ის, რომ შეუძლია თქვას: „ახლა ის ქანაობს, შემდეგ კი მე“, სოციალური ინტელექტის განვითარებაში დიდი წინგადადგმული ნაბიჯია. აუცილებლად შეაქეთ ამ მოთმინებისთვის, რათა ასეთი ქცევა ჩვევად ექცეს.') WHERE id = '9280edaf-2356-4dce-a273-2cd4a5d6fd57';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დახარისხება და კატეგორიზაცია“. ბავშვი ნივთებს უკვე არა მხოლოდ ფერის, არამედ დანიშნულების მიხედვითაც აჯგუფებს: „ესენი საკვებია, ესენი კი სათამაშოები“. მიეცით მას ერთმანეთში არეული ნივთები და უთხარით: „იპოვე ის ნივთები, რომლებიც სამზარეულოს ეკუთვნის“. ეს მის გონებაში ინფორმაციის სისტემატიზებას უწყობს ხელს.') WHERE id = '55b33de4-6e1b-4815-985d-641594c12f05';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მხარს ზემოდან სროლა“. ბავშვს უკვე შეუძლია, ბურთი არა მხოლოდ ქვემოდან, არამედ მხრის დონიდან წინაც ისროლოს. ეს იმაზე მიუთითებს, რომ მისი მკლავისა და მხრის კუნთები გაძლიერდა და მას მოძრაობის ტრაექტორიის დაგეგმვა შეუძლია. პარკში მასთან ერთად ითამაშეთ პატარა თამაშები — „მიზანში სროლა“.') WHERE id = 'eb04363a-ab4d-4a94-888d-e7e2e5211e9c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ნაცვალსახელების სწორად გამოყენება“. ბავშვი უკვე თითქმის არასდროს ურევს ერთმანეთში ნაცვალსახელებს „მე“, „შენ“, „ის“, „ჩვენ“. ეს ნიშნავს, რომ მას სრულად ესმის საკუთარი ადგილი სოციალურ გარემოში და სხვებთან ურთიერთობა. მასთან საუბრისას ნუ მოერიდებით რთული წინადადებების გამოყენებას.') WHERE id = '4705908e-12af-4329-ab11-ab69b76d1be9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „შეცდომებზე სწავლა“. როდესაც ბავშვს რაიმე არ გამოსდის, ის მაშინვე აღარ ტირის და შეიძლება შემოგხედოთ და გკითხოთ: „არ გამომივიდა, თავიდან ვცადო?“ ეს მისი ემოციური მდგრადობის ზრდაზე მიუთითებს. გაამხნევეთ სიტყვებით: „შეცდომა ყველას შეიძლება მოუვიდეს, მთავარია, კიდევ ერთხელ სცადო“. თქვენ შესანიშნავი მეგზური ხართ!') WHERE id = 'cb464c9f-f6c4-48c0-ab1a-62c435d01c32';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი საკუთარ თავს უკვე არა მხოლოდ როგორც „მე“-ს, არამედ როგორც „უნარების მქონე ადამიანს“ აღიქვამს. ის საკუთარ თავს ასე ახასიათებს: „მე სწრაფად დავრბივარ“ ან „მე ვაფერადებ“. მხარი დაუჭირეთ მის ამ პოზიტიურ თვითაღქმას. დააკვირდით, როგორ აღწერს ის საკუთარ თავს — ეს მისი მომავალი თავდაჯერებულობის ხმაა.') WHERE id = '24b05457-5c55-4e7e-93bd-e8e2e24e7b8c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობის ეტაპი — „სიმაღლის შიშის დაძლევა“. ბავშვს უკვე სურს, პარკში უფრო მაღალი სასრიალოები ან კიბეები გამოსცადოს. მისი ფიზიკური შესაძლებლობები ახლა სრულად შეესაბამება მის გონებაში არსებულ აზრს: „მე ეს შემიძლია“. თქვენ უბრალოდ მის გვერდით იდექით, როგორც „უხილავი დამცველი“.') WHERE id = 'a48cb007-600a-438e-b8fd-ac64a32480ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში კითხვის „რატომ?“ ფილოსოფია. ახლა ის „რატომ“-ს მხოლოდ პასუხის მისაღებად კი აღარ გეკითხებათ, არამედ თქვენთან საუბრის გასაგრძელებლადაც. თუ პასუხის დასრულების შემდეგ კვლავ გკითხავთ „რატომ?“, კითხვა მას დაუბრუნეთ: „შენ რას ფიქრობ?“. მისი წარმოსახვითი ახსნა-განმარტებები გაგაცინებთ და თან გაგაოცებთ.') WHERE id = 'a7f2070c-4631-4744-b176-d7bba5b19ea6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „სიმბოლოების დაბადება“. ბავშვი ქაღალდზე უკვე „დახურულ ფორმებს“ ხატავს. მის მიერ დახატული ერთი წრე შეიძლება ერთდროულად მზეც იყოს, ბურთიც და დედაც. ეს აბსტრაქტული აზროვნების მწვერვალია: ერთ სიმბოლოს ყველაფრის გამოხატვა შეუძლია. აუცილებლად შეინახეთ მისი ეს პირველი „ხელოვნების ნიმუშები“ და თარიღიც მიუწერეთ.') WHERE id = '8291f627-bff8-4ae0-9fda-966d1f2e80ac';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„საზღვრების გამომცდელი“. ბავშვმა შეიძლება განზრახ გააკეთოს ის, რაც აუკრძალეთ, და თქვენს რეაქციას დააკვირდეს. ეს არ ნიშნავს, რომ ის „ცუდია“ — ამგვარად თქვენს ემოციურ საზღვრებსა და წესების უცვლელობას ამოწმებს. თქვენი სიმშვიდე და მტკიცე პოზიცია მისთვის უსაფრთხოების ყველაზე მნიშვნელოვანი გზავნილია: „სამყარო კვლავ სტაბილური და უსაფრთხოა“.') WHERE id = 'a9bf7bd3-b390-48c2-b220-67d40659de03';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ინტელექტში — „თამაშის წესები“. ბავშვს უკვე ესმის, რომ თამაშის გასაგრძელებლად წესების დაცვაა საჭირო. მაგალითად, დამალობანას თამაშისას იცის, რომ თვალების დახუჭვა აუცილებელია. ეს საზოგადოებაში მისი პირველი „სოციალური შეთანხმებებია“. დაიწყეთ მასთან მარტივი წესების მქონე სამაგიდო თამაშების თამაში.') WHERE id = '6de77e4c-02d9-4646-a638-e1f9881237a4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებაში — „დროის რიტუალები“. მიუხედავად იმისა, რომ ბავშვს ჯერ ბოლომდე არ აქვს გააზრებული „გუშინ“, „დღეს“ და „ხვალ“, მან კარგად იცის ყოველდღიური რიტუალები: „ჭამის შემდეგ — პარკი“ ან „ძილის წინ — ზღაპარი“. ასეთი თანმიმდევრობები მის გონებაში დროის ხაზს აყალიბებს. დაეხმარეთ მას მოვლენების თანმიმდევრობით მოყოლით.') WHERE id = '3677e8d8-da75-4da9-b002-0343f54de7f8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ კოორდინაციაში — „ზუსტი მოძრაობები“. ბავშვს უკვე შეუძლია სითხით სავსე ჭიქის ისე წაღება, რომ ბევრი არ დაღვაროს, ან ვიწრო ბილიკზე გაიაროს. ეს აჩვენებს, რამდენად დაიხვეწა მისი მხედველობით-მოტორული კოორდინაცია. სახლში მიეცით „პატარა ოფიციანტის“ როლი.') WHERE id = '24b745fb-d8d2-4191-b523-51bef737292f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ემოციების ლექსიკონი“. ბავშვი უკვე მხოლოდ „ცუდად ვარ“ ან „კარგად ვარ“ აღარ ამბობს. ის სწორად იყენებს ისეთ სიტყვებს, როგორებიცაა „გავბრაზდი“, „მოვიწყინე“, „მიხარია“. აღიარეთ და დაუდასტურეთ მისი გრძნობები: „ნორმალურია, რომ ტირი, რადგან მოწყენილი ხარ“. ეს მისი ემოციური ჯანმრთელობის ერთ-ერთი ყველაზე მნიშვნელოვანი გარანტიაა.') WHERE id = 'e9c2314b-a8e3-4e87-93f6-fa6cd95e6e36';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '3 წლის (1095 დღის) ზღურბლზე. ბავშვი უკვე შორდება „ჩვილობის“ ნაპირს და „ბავშვობის“ ოკეანეში შედის. ის უკვე არა მხოლოდ თქვენს ქცევებს, არამედ თქვენს ემოციურ მდგომარეობასაც ბაძავს. თქვენ მისთვის ყველაზე დიდი სარკე ხართ. იამაყეთ საკუთარი თავით — უკვე 1090 დღეა, შესანიშნავ ადამიანს ზრდით!') WHERE id = '6d3a16a2-1643-4f5c-be11-40251b29e16d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '3 წლის შესრულებამდე (1095 დღემდე) სულ რაღაც 5 დღე დარჩა! ბავშვს უკვე სრულად აქვს გააზრებული საკუთარი „მე“ და ჯიუტად იცავს პირად საზღვრებს. ამ დღეებში ხშირად მოსმენილი „არა“ თქვენ წინააღმდეგ მიმართული კი არ არის, არამედ მისი პიროვნების დამკვიდრების გზაა. არჩევანის შესაძლებლობის მიცემით დაეხმარეთ, რომ ეს გარდამავალი პერიოდი უფრო მარტივად გაიაროს.') WHERE id = '1dacdad0-c90b-4399-810b-283d367d437c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „სრული დამოუკიდებლობა“. ბავშვს უკვე შეუძლია ორივე ფეხით ერთდროულად ახტეს, კიბეზე დახმარების გარეშე ავიდეს და ჩამოვიდეს და სამთვლიანი ველოსიპედი მართოს. მისი ფიზიკური ენერგია უკვე ორგანიზებულ და კოორდინირებულ მოძრაობებად გარდაიქმნა.') WHERE id = '0788e284-3cae-46fe-a730-5b0adb5d2052';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „აბსტრაქტული აზროვნება“. ბავშვს უკვე შეუძლია დიდხანს ისაუბროს საგნებზე, რომლებიც იქ აღარ არის, ან წარსულში მომხდარ ამბებზე. ისეთი წინადადებები, როგორიცაა „გახსოვს, იქ რომ წავედით?“, მისი ხანგრძლივი მეხსიერებისა და მეტყველების უნარის შესანიშნავი შერწყმაა. ხშირად გაუზიარეთ მას ძველი მოგონებები.') WHERE id = 'f3f07ee7-1804-4733-8e04-f58c824d1ef9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „წერისთვის მოსამზადებელი უნარები“. ბავშვს უკვე ფანქარი თითებით უჭირავს (და არა მთელი ხელისგულით) და ხატავს შეკრულ წრეებს, ჯვრებსა და ზოგიერთი ასოს მსგავს ხაზებსაც კი. ეს მისი მომავალი წერის უნარის განვითარებისთვის უმნიშვნელოვანესი ფიზიკური ეტაპია.') WHERE id = '1e35d34e-147e-430a-a51b-7c615ecdd852';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ დაბადების დღეს! ზუსტად 3 წელი, ანუ 1095 დღე! ბავშვმა უკვე ოფიციალურად დატოვა „ჩვილობის“ ნაპირი. ახლა ის პატარა ადამიანია, რომელიც საუბრობს, აზროვნებს, ხუმრობს და თავისი სამყარო აქვს. ამ 1095 დღის განმავლობაში თქვენ მის გონებაში ნდობისა და სიყვარულის ურყევი საფუძველი შექმენით. ყოჩაღ, დედა!') WHERE id = '94af9664-3a01-40cf-b485-6d92b46dd312';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-4 წლის პირველი დღე! ბავშვს „პასუხისმგებლობის“ გრძნობა უღვივდება. მას უკვე შეუძლია გაიგოს, რომ საკუთარი სათამაშოების ალაგებაც თამაშის ნაწილია. მიეცით მცირე საოჯახო დავალებები (მაგალითად, სუფრაზე ხელსახოცების დადება). ეს მას განუმტკიცებს განცდას, რომ ოჯახის სასარგებლო წევრია.') WHERE id = '8a58846e-740c-494e-b055-cca0e1dee700';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „ემპათიის განვითარება“. ბავშვს უკვე ესმის არა მხოლოდ საკუთარი გრძნობები, არამედ ისიც, რომ სხვებიც შეიძლება დამწუხრდნენ. კითხვა „ის ბავშვი რატომ ტირის?“ იმის დასტურია, რომ ის სამყაროს სხვების თვალით დანახვას იწყებს.') WHERE id = '3be5dfbf-e6fa-4586-9735-23266743fb18';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებაში „ლოგიკური თანმიმდევრობა“. ბავშვს უკვე შეუძლია 3-4 ნაწილისგან შემდგარი მოვლენები სწორი თანმიმდევრობით დაალაგოს: „ჯერ ხელები დავიბანე, შემდეგ პური ვჭამე, მერე ვითამაშე“. შესთავაზეთ, ერთად დაგეგმოთ თქვენი დღე. ეს მის გონებაში არსებულ „ქაოსს“ მოწესრიგებულ „დროის ღერძად“ გარდაქმნის.') WHERE id = 'cce49adb-3f97-4be9-9435-40b81895ee05';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ფერებისა და ფორმების ერთმანეთთან დაკავშირების გზით აღწერს სამყაროს. თუ ამბობს: „მომეცი ის ყვითელი კვადრატული კუბიკი“, ეს აჩვენებს, რომ მისი ტვინი ერთდროულად რამდენიმე მახასიათებელს ამუშავებს. ხელი შეუწყვეთ ამ უნარის განვითარებას ყოველდღიურ ცხოვრებაში მცირე დავალებებით (მაგალითად, „იპოვე შენი ლურჯი წინდები“).') WHERE id = 'd8ae8173-4cc7-42b0-8737-2bedce267dcb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „დინამიკური წონასწორობა“. ბავშვს უკვე შეუძლია ერთ ფეხზე 5 წამამდე გაჩერება. ეს ვესტიბულური სისტემისა და ფეხის კუნთების გაძლიერებაზე მიუთითებს. ეთამაშეთ „ყარყატი“ და შეამოწმეთ, ვინ შეძლებს ერთ ფეხზე უფრო დიდხანს გაჩერებას.') WHERE id = '071b03c5-b7b5-42d1-a970-a44e8e806595';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მიზეზშედეგობრივი კავშირები“. ბავშვი უკვე იწყებს „თუ... მაშინ...“ ტიპის წინადადებების გაგებას. როდესაც ეუბნებით: „თუ სათამაშოებს დაალაგებ, მულტფილმს ვუყურებთ“, მას პირობის არსი ესმის. ეს მნიშვნელოვანი ნაბიჯია როგორც ლოგიკური აზროვნების, ისე შინაგანი დისციპლინის ჩამოყალიბებისთვის.') WHERE id = 'a7ceb34f-04f4-4303-a5f6-fca236e067db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „მაკრატლის გამოყენების პირველი გამოცდილება“. ბავშვი უკვე ინტერესდება ქაღალდის სწორ ხაზზე გაჭრით (უსაფრთხო მაკრატლის გამოყენებით). ეს მოქმედება აუმჯობესებს როგორც ხელისა და თვალის კოორდინაციას, ისე თითების წვრილ მოტორიკას. ნუ დატოვებთ მას ზედამხედველობის გარეშე, თუმცა არც დამოუკიდებლად მოქმედებაში შეუშალოთ ხელი.') WHERE id = '42cc6ea9-d4af-4873-a31f-be87ca7ae22d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წარმოსახვითი თანამოთამაშეები“. ბავშვი უკვე მარტო თამაშის დროსაც ხმამაღლა საუბრობს და სათამაშოებს სხვადასხვა როლს ანიჭებს. ეს ეხმარება მას, საკუთარი მოქმედებები სიტყვებით დაარეგულიროს. თუ მის ამ „მონოლოგებს“ მოუსმენთ, შეძლებთ გაიგოთ, რა ხდება მის შინაგან სამყაროში.') WHERE id = 'b9a0516e-a5fd-46ab-abb8-4e16e305575b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი არჩევანი: გადაწყვეტილების მიღება“. ბავშვმა უკვე ზუსტად იცის, რისი ჭამა ან რომელი თამაშის თამაში სურს. ყოველდღე შესთავაზეთ ორი ალტერნატივა: „ვაშლი გინდა თუ ბანანი?“. ეს მას საკუთარ ცხოვრებაზე კონტროლის განცდას უჩენს და თავდაჯერებულობას უმაღლებს.') WHERE id = 'd2594413-54bc-4a0b-857c-1959a2b007b2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმა: ელვა და ღილი“. ბავშვს უკვე ძალიან აინტერესებს დიდი ღილების გახსნა ან ელვის ზემოთ აწევა (მას შემდეგ, რაც შეკვრას დაუწყებთ). უთხარით: „მოდი, თავად სცადე“ და მოთმინებით დაელოდეთ. დამოუკიდებლად ჩაცმის უნარი ბავშვში „მე შემიძლია“ განცდასა და თავდაჯერებულობას წარმოუდგენლად აძლიერებს.') WHERE id = '9a464aa6-3d95-421a-948d-be4bbc442bbe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „გაზიარების გააზრება“. ბავშვს უკვე ესმის, რომ მეგობრისთვის სათამაშოს მიცემა მის სამუდამოდ დაკარგვას კი არ ნიშნავს, არამედ უბრალოდ „მორიგეობით თამაშს“. ეს ემპათიის პირველი მარცვლებია. აუცილებლად განუმტკიცეთ ეს ქცევა სიტყვებით: „დიდი მადლობა, რომ მეგობარს უზიარებ“.') WHERE id = '7f75fc5d-eb6e-4e7a-abdd-f9659116f406';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „რიცხვისა და რაოდენობის კავშირი“. ბავშვს უკვე არა მხოლოდ ზეპირად შეუძლია 1-დან 10-მდე დათვლა, არამედ იწყებს რეალური რაოდენობის დათვლასაც — საგნებზე თითით მიუთითებს და ამბობს: „ერთი, ორი, სამი“. მიეცით ისეთი დავალებები, როგორიცაა: „მაგიდაზე 3 კოვზი დავდოთ“. ეს ის ეტაპია, როდესაც აბსტრაქტული რიცხვები პირველად მჭიდროდ უკავშირდება რეალურ სამყაროს.') WHERE id = '6bc8719d-b139-4ea0-af7e-596754bfb254';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკან-უკან სიარული“. ბავშვს უკვე შეუძლია უკანმოუხედავად თავდაჯერებულად გადადგას რამდენიმე ნაბიჯი უკან. ეს მოძრაობა აძლიერებს მისი სხეულის შეგრძნებას (პროპრიოცეფციას) და სივრცეში ორიენტაციის უნარს. ითამაშეთ მასთან „კიბორჩხალების რბოლა“ — ასე გაერთობით და ამავდროულად მის კუნთებსაც ავარჯიშებთ.') WHERE id = '2fce926c-604e-40c3-aff1-959bf3574903';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „აბსტრაქტული კითხვები“. ბავშვი უკვე კითხვებით „რატომ?“ და „როგორ?“ სამყაროს შეიცნობს. ისეთი კითხვები, როგორიცაა „ღრუბელი სად მიდის?“ და „ჭიანჭველა საით გარბის?“, მის ცნობისმოყვარეობასა და გარემომცველ სამყაროსთან დამყარებულ ლოგიკურ კავშირებზე მეტყველებს. მნიშვნელოვანია, პასუხები მარტივი და მისთვის გასაგები ენით იყოს გადმოცემული.') WHERE id = '5eb5c186-69a6-483f-9ba1-b6f471501a76';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „მოთმინების გამოცდა“. ბავშვს უკვე ესმის, რომ სასურველი ნივთის მისაღებად რამდენიმე წუთი უნდა დაიცადოს. თუ სიტყვებზე „ახლა არა, ცოტა ხანში“ მაშინვე არ ტირის, ეს მისი ემოციების რეგულირების უნარის განვითარებაზე მიუთითებს. როდესაც მის მოთმინებას შეამჩნევთ, გაამხნევეთ სიტყვებით: „დიდი მადლობა, რომ დაიცადე“.') WHERE id = '6751f01f-eb8d-4bf5-bdeb-fec3d11483e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვით თამაშებში — „რთული როლური თამაშები“. ახლა თამაშები უფრო დეტალური ხდება. ბავშვი უბრალოდ „ექიმი“ კი არ არის, არამედ „რეცეპტსაც გიწერთ“ და „ნემსსაც გიკეთებთ“. ასეთი თამაშები ბავშვს სტრესთან გამკლავებასა და საზოგადოების შეცნობაში ეხმარება. პატივისცემით ჩაერთეთ მის წარმოსახვით სამყაროში.') WHERE id = '63c35556-85c7-4de4-956c-b06072fe14e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1100-დღიანი გზის ბოლო გაჩერება. ბავშვი უკვე თავს „დიდად“ გრძნობს. მისი ინდივიდუალობა, გემოვნება და ხასიათი უკვე სრულად ჩამოყალიბებულია. თქვენ ეს გზა მოთმინებით, ცოდნით და, რაც მთავარია, უსაზღვრო სიყვარულით გაიარეთ. აპლიკაცია „Anacan“ ყოველთვის თქვენ და თქვენი პატარა გმირის გვერდითაა!') WHERE id = 'b3b1d154-d59c-44d1-8bf7-a6ef75357962';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 3 წლის ასაკის პირველ ათ დღეში! ამ პერიოდში ბავშვის ლექსიკური მარაგი უკვე დაახლოებით 1000 სიტყვისგან შედგება. ის მხოლოდ თავის საჭიროებებს კი აღარ გიზიარებთ, არამედ ოცნებებსაც. საუბრისას ხშირად ჰკითხეთ: „შენი აზრით, რატომ?“ — ამით მას ლოგიკური მსჯელობისკენ წაახალისებთ.') WHERE id = 'a79f70f3-f350-4b22-984a-7f58dfd4b7fb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ზუსტი ნახტომი“. ბავშვს უკვე შეუძლია ადგილიდან როგორც სიმაღლეზე, ისე კონკრეტული სამიზნისკენ გადახტომა (მაგალითად, იატაკზე დაფენილ ფერად ხალიჩაზე). ეს მიუთითებს როგორც წონასწორობის დაცვაზე, ისე სივრცეში მანძილის განსაზღვრის უნარზე. პარკში თამაში „ქვიდან ქვაზე ხტომა“ მისთვის შესანიშნავი ვარჯიშია.') WHERE id = '05ceca15-09f0-41f4-a54b-99db2b828cc8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ნაცვალსახელისა და სქესის კატეგორიები“. ბავშვი უკვე სრულიად სწორად იყენებს ნაცვალსახელებს „მე“, „შენ“ და „ის“. თუ ზოგჯერ ჯერ კიდევ საკუთარ თავს სახელით, მესამე პირში მოიხსენიებს (მაგალითად, „ალის წყალი უნდა“), ნაზად შეუსწორეთ: „დიახ, შენ გინდა წყალი“.') WHERE id = '03d396dd-e487-41b7-9885-73235271ea53';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ფაზლები და კონსტრუქციები“. ბავშვი უკვე დამოუკიდებლად აწყობს 8-12-ნაწილიან ფაზლებს და კუბებით რთულ კოშკებსა და ხიდებს აგებს. ეს ავითარებს როგორც ვიზუალური ანალიზის უნარს, ისე თითების მოქნილობასა და ზუსტი მოძრაობების შესრულების უნარს. თუ არ გამოუვა, მზა გადაწყვეტას ნუ მისცემთ — უბრალოდ მიანიშნეთ.') WHERE id = 'ca591a5d-4734-459d-be9b-3eaadeddb81b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სივრცე და მიმართულება“. მიუხედავად იმისა, რომ ბავშვს „მარჯვენა“ და „მარცხენა“ ჯერ კიდევ ბოლომდე ზუსტად არ ესმის, მითითებებს „წინ“, „უკან“, „ზემოთ“ და „ქვემოთ“ უშეცდომოდ ასრულებს. ითამაშეთ მასთან „რობოტობანა“: „ორი ნაბიჯი წინ, ერთი ნაბიჯი უკან!“ ეს სახალისოცაა და სივრცეში ორიენტირების უნარსაც აძლიერებს.') WHERE id = 'd6a03598-2471-4b13-a839-fb2c51010318';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „წარუმატებლობასთან გამკლავება“. როდესაც კუბიკებით აშენებული კონსტრუქცია ენგრევა, ბავშვი მაშინვე აღარ ტირის და შეუძლია თქვას: „თავიდან ავაწყობ“. ხელი შეუწყვეთ მის შეუპოვრობას. უკვე 1130 დღე გავიარეთ — თქვენი შვილი უკვე პატარა გმირია!') WHERE id = 'b7ab015d-a4e4-4c1d-a9a5-7f26c5798a69';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საგნების ერთდროულად ორი ნიშნის მიხედვით დახარისხება (მაგალითად, ფერისა და ფორმის მიხედვით). თუ ის ახერხებს თქვენი თხოვნის — „ყველა პატარა წითელი მანქანა მომეცი“ — შესრულებას, ეს მისი კოგნიტიური განვითარების ახალი საფეხურია. ყოველდღიური საოჯახო საქმეების დროს მიეცით ასეთი პატარა „შერჩევის“ დავალებები.') WHERE id = 'ff1dcdb3-fd81-4345-80ce-058e6b7a0d6b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „სამიზნეზე ხტომა“. ბავშვი უკვე ცდილობს იატაკზე დახატული წრის ან ფერადი სამიზნის ცენტრში ჩახტომას. ეს აუმჯობესებს როგორც წონასწორობას, ისე სივრცეში მანძილის განსაზღვრის უნარს. პარკში ითამაშეთ მასთან „ქვიდან ქვაზე ხტომა“.') WHERE id = '5d8b4009-8971-48b6-aa55-75a96a823d2d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „საპირისპირო მნიშვნელობის სიტყვების მარაგის გაფართოება“. ბავშვს უკვე ესმის ისეთი აბსტრაქტული საპირისპირო ცნებები, როგორებიცაა „ადრე-გვიან“, „ბნელი-ნათელი“ და „ცარიელი-სავსე“. აჩვენეთ ცარიელი და სავსე ჭიქები და ჰკითხეთ, რა განსხვავებაა მათ შორის. ეს გარემომცველი სამყაროს შედარებითი ანალიზის უნარს აძლიერებს.') WHERE id = '18232b0a-482a-40e1-90c7-8a04a56dc3b9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ფაზლების ოსტატობა“. ბავშვს უკვე შეუძლია 10-12-ნაწილიანი რთული ფაზლების აწყობა (სურათის კიდეებისა და ცენტრის ერთმანეთისგან გარჩევით). ეს ავითარებს როგორც მხედველობით მეხსიერებას, ისე თითებით ზუსტი მოძრაობების შესრულების უნარს. თუ ვერ გამოსდის, მშვიდი ტონით მიეცით მინიშნებები.') WHERE id = '3045e148-b927-4872-8354-b9edb5116d18';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიური განვითარების ეტაპი — „მოცულობისა და რაოდენობის უცვლელობა“. ბავშვს ჯერ კიდევ შეიძლება ეგონოს, რომ მაღალ, ვიწრო ჭურჭელში უფრო მეტი წყალია, ვიდრე განიერ ჭურჭელში. ამ ასაკში ეს ნორმალურია. ეთამაშეთ წყლით და ერთად გადაასხით წყალი სხვადასხვა ჭურჭელში. ეს პრაქტიკული გამოცდილება მას ლოგიკური აზროვნების განვითარებაში დაეხმარება.') WHERE id = 'c2c7f4f2-7e4e-4f22-9785-bdddbd705503';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია — „ორი ფეხით წინ გადახტომა“. ბავშვს უკვე შეუძლია დაბრკოლებებს (მაგალითად, იატაკზე დადებულ თოკს) ორივე ფეხით ერთდროულად გადაახტეს. ეს მთელი სხეულის კოორდინაციას მოითხოვს. უსაფრთხო ადგილებში მოუწყეთ დაბრკოლებების პატარა ზოლი.') WHERE id = '3c4e0869-e516-493c-90a9-df3b2f2e738b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „დროის აბსტრაქტული აღქმა“. ბავშვი უკვე ყოველდღიური რიტუალების მეშვეობით აცნობიერებს განსხვავებას „დილას“, „შუადღესა“ და „საღამოს“ შორის. როდესაც ეუბნებით: „საღამოს, როცა მამა მოვა...“, მას შეუძლია დღის ეს მონაკვეთი წარმოიდგინოს. ყოველდღიური რეჟიმის დაცვა ეხმარება, დროის ეს აღქმა უსაფრთხოების განცდას დაუკავშიროს.') WHERE id = 'd719015d-011e-40f6-8ffa-5cdcb4302e71';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმწიფე — სიტყვა „მაპატიეს“ მნიშვნელობა. ბავშვს უკვე ესმის, რამდენად მნიშვნელოვანია ბოდიშის მოხდა, როდესაც განზრახ ან უნებლიეთ ვინმეს აწყენინებს. ყოველთვის მიეცით მაგალითი: როცა შეცდომას დაუშვებთ, ბავშვს ბოდიში მოუხადეთ, რათა მანაც ეს ქცევა ძლიერი ხასიათის ნიშნად აღიქვას.') WHERE id = 'c8c25e23-7ba2-4ee9-a363-3be20d076417';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე სურათების დათვალიერებისას მარტივ ამბებს იგონებს. ისეთი თანმიმდევრული წინადადებები, როგორიცაა „დათვი ტყეში წავიდა, მოშივდა და თაფლი შეჭამა“, მიუთითებს, რომ მას ლოგიკური თანმიმდევრობა ესმის. მიეცით წიგნები საინტერესო ილუსტრაციებით და ჰკითხეთ: „როგორ ფიქრობ, ამის შემდეგ რა მოხდება?“ ეს მის შემოქმედებით წარმოსახვას კიდევ უფრო განავითარებს.') WHERE id = 'd67be23e-c203-4809-a7a3-cbfd66266b55';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოძრაობის უნარი — „კიბეზე დამოუკიდებლად გადაადგილება“. ბავშვი უკვე თავდაჯერებულად ჩამოდის კიბეზე, მონაცვლეობით თითო საფეხურზე თითო ფეხს დგამს და მხოლოდ ერთი ხელით გეჭიდებათ (ან საერთოდ არ გეჭიდებათ). ეს მიუთითებს, რომ მისი მსხვილი მოტორული უნარები სრულად მომწიფდა. უბრალოდ მის გვერდით იყავით და ემოციურად გაამხნევეთ.') WHERE id = '7b344d73-ef09-40bc-8962-14de04d0a9d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვა-პასუხის ჯაჭვი“. ბავშვი თქვენს კითხვებს უკვე არა მხოლოდ „კი/არა“-თი, არამედ სრული წინადადებებით პასუხობს. კითხვაზე „დღეს პარკში ვისთან ერთად ითამაშე?“ მას დეტალური პასუხის გაცემა შეუძლია. მასთან საუბრისას დაუსვით დამატებითი კითხვები, მაგალითად: „რა ფერის იყო?“ ან „რა გააკეთეთ?“ — ასე მის მეტყველებას განავითარებთ.') WHERE id = '728c62de-e9bd-4825-a015-839c4ef09ac4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „უფრო ზუსტად გაფერადება“. ბავშვი უკვე პატარა ფიგურების საზღვრებსაც აღიქვამს და გაფერადებისას ცდილობს, ხაზებს ზედმეტად არ გადასცდეს. ეს ხელის კუნთების მართვაში დიდი წინსვლაა. მიეცით სხვადასხვა სისქის ფანქრები და შეუქმენით პირობები, რომ მოსინჯოს ისინი.') WHERE id = '1e2db868-b348-4ed1-a7d7-4e1b235065d6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმა: ელვა და ღილი“. ბავშვს უკვე კარგად შეუძლია დიდი ღილების გახსნა და ელვის ზემოთ აწევა, თუ მის შეკვრაში თავდაპირველად დაეხმარებით. უთხარით: „მოდი, თავად სცადე“ და მოთმინებით დაელოდეთ. დამოუკიდებლად ჩაცმის უნარი ბავშვში „მე შემიძლია“ განცდასა და თავდაჯერებას საოცრად აძლიერებს.') WHERE id = 'd0289832-2e1f-4c80-bf6f-025f04fde8c3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გაზიარების არსი“. ბავშვი უკვე ცდილობს, სათამაშო სხვა ბავშვს ხელიდან მაშინვე არ წაართვას, არამედ თქვას „მომეცი“ და დაელოდოს. ეს თვითრეგულირების (self-regulation) უნარის გაძლიერებაზე მიუთითებს. როდესაც ასეთ მომთმენ ქცევას შეამჩნევთ, აუცილებლად შეაქეთ და უთხარით: „დიდი მადლობა, რომ შენს რიგს დაელოდე“.') WHERE id = '8b0e05af-2727-418a-b763-3601d197e7d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „ზოგადი და კონკრეტული“. ბავშვს უკვე ესმის, რომ ვაშლი, მსხალი და ბანანი ყველა „ხილია“. აჩვენეთ სხვადასხვა ნივთი და ჰკითხეთ: „ამ ყველაფერს ერთად რას ვუწოდებთ?“ კატეგორიების მიხედვით აზროვნება მის ტვინში ინფორმაციის შენახვის სისტემას უფრო მოწესრიგებულს ხდის.') WHERE id = 'cfa7be75-1286-4575-9a59-47547f98434d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მხარს ზემოდან სროლა“. ბავშვი ბურთს უკვე უბრალოდ ძირს აღარ აგდებს — მას მხარს ზემოდან წინ, კონკრეტული სამიზნისკენ ისვრის. ეს მთელი სხეულის კოორდინაციას მოითხოვს. პარკში მასთან ერთად ითამაშეთ „მიზანში სროლა“.') WHERE id = '7ccd147e-b878-45ff-a8c8-f2d12fac2b06';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად დალაგება და დახმარება“. ბავშვს უკვე ძალიან მოსწონს სუფრის ალაგებისას თავისი ცარიელი თეფშის წაღება და ნამცეცების გადაწმენდა. მიეცით მისი სიმაღლის შესაბამისი დასალაგებელი ნივთები. ეს ოჯახში პასუხისმგებლობისა და მიკუთვნებულობის განცდას აძლიერებს. საკუთარი შრომის შედეგის დანახვა მას ძალიან აბედნიერებს.') WHERE id = '5fed215f-7140-471a-887f-855f666792ab';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წესები და საზღვრები“. ბავშვს უკვე უკეთ ესმის სიტყვა „არას“ მიზეზი, თუმცა საზღვრების გამოცდა კვლავ უყვარს. თქვენი მოთმინება და თანმიმდევრულობა მას უსაფრთხოების განცდას უქმნის. ეცადეთ, წესები ყოველთვის ერთნაირად გამოიყენოთ.') WHERE id = 'ad322e7c-2c29-48c7-ba0d-376889e0bc86';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რიგობითი რიცხვითი სახელები“. ბავშვს უკვე ესმის ცნებები „პირველი“, „მეორე“ და „ბოლო“. დააწყვეთ მანქანები მწკრივად და ჰკითხეთ: „რომელი მანქანაა პირველი?“. ეს თანმიმდევრულობის აღქმასა და მათემატიკურ აზროვნებას უვითარებს. შეჯიბრებისას სიტყვები „შენ მოხვედი პირველი!“ მისთვის დიდი მოტივაციაა.') WHERE id = 'ccdeb036-ba4e-49c8-960c-f4271e0fc740';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკან და გვერდულად სიარული“. ბავშვს უკვე შეუძლია სხვადასხვა მიმართულებით მოქნილად მოძრაობა. ითამაშეთ მასთან „სარკის თამაში“: თქვენ გვერდზე გადადგით ნაბიჯი, მან კი თქვენი მოძრაობა გაიმეოროს. ეს არა მხოლოდ სახალისოა, არამედ სხეულის კოორდინაციასაც ახალ დონეზე ავითარებს.') WHERE id = '53f08fbe-8240-4c06-91f5-3a6645fa77af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული კითხვების გაღრმავება“. ბავშვმა შეიძლება გაგაოცოთ ისეთი კითხვებით, როგორებიცაა: „ღრუბლები სად მიდიან?“ და „ვარსკვლავები რატომ ჩნდებიან ღამით?“. პასუხის გაცემისას მისი წარმოსახვაც ჩართეთ: „შენი აზრით, რას აკეთებენ ახლა ვარსკვლავები?“. ეს მის შემოქმედებით აზროვნებას ასაზრდოებს.') WHERE id = 'ca368c4f-966b-4846-b9ca-ff68822b1eca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „გაზიარების სიხარული“. როდესაც ბავშვი ნებაყოფლობით სხვას უზიარებს სათამაშოს ან ტკბილეულს, ის უკვე ამჩნევს თქვენს სიხარულს და ამის გამეორება სურს. განსაკუთრებით გაუსვით ხაზი მის გულუხვობას და უთხარით: „დიდი მადლობა, რომ შენი მეგობარი გაახარე“. 1140 დღე წარმატებით გავიარეთ — თქვენ შესანიშნავი დედა ხართ!') WHERE id = '706c863b-0328-4280-9ae2-b61f0dddff18';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში — „რიცხვისა და რაოდენობის შესაბამისობა“. ბავშვმა 1-დან 5-მდე დათვლა იცის და ახლა, როცა ციფრ „3“-ს ხედავს, შეუძლია 3 სათამაშო ცალკე გადადოს. ეს მათემატიკური აზროვნების განვითარების ერთ-ერთი უმნიშვნელოვანესი ეტაპია. ყოველდღიურ ცხოვრებაში ეს კავშირი განამტკიცეთ ისეთი დავალებებით, როგორიცაა: „მომეცი 2 კოვზი“.') WHERE id = '5b8b658c-3ba9-46dd-b7e1-a329bde32c59';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ზემოდან ნასროლი ბურთის დაჭერა“. ბავშვი უკვე ცდილობს ორივე ხელით დაიჭიროს მისკენ ნელა ნასროლი დიდი ბურთი. ეს მოძრაობა მოითხოვს როგორც ხელისა და თვალის კოორდინაციას, ისე რეაქციის სისწრაფეს. ითამაშეთ მასთან ახლო მანძილიდან ბურთის სროლა-დაჭერა.') WHERE id = '9cbfafe8-e2d3-4b4c-a7dd-a7d50a0d73a4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული კითხვების მწვერვალი“. ბავშვი უკვე სვამს კითხვებს სამყაროსა და ბუნებრივი მოვლენების შესახებ, მაგალითად: „რატომ ქრის ქარი?“, „სად მიდის მზე დასაძინებლად?“. პასუხის გაცემისას ფანტაზიაც ჩართეთ: „მზე დაიღალა და დასასვენებლად მიდის, რათა ხვალ ისევ გაგვაღვიძოს“. ეს მის მსოფლმხედველობას აფართოებს და სწავლის სურვილს აძლიერებს.') WHERE id = 'be40f099-56c3-42b3-90d0-8aec32c8e2ca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმწიფე: „სხვისი ემოციების აღიარება“. როცა ბავშვი ამჩნევს, რომ დაღლილი ხართ ან სხვა ბავშვს ეწყინა, უკვე გეკითხებათ: „რა მოხდა?“ და ცდილობს დაგამშვიდოთ. ეს მიუთითებს, რომ ის თანაგრძნობით სავსე პიროვნებად ყალიბდება. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '28850826-f8da-4cde-a0f3-c10d2981e7f4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე სოციალურ ურთიერთობებში ცდის „მე“-სა და „ჩემის“ ცნებებს. როცა სათამაშოს გაზიარება არ სურს, ეს უფრო საკუთარი საზღვრების დადგენის მცდელობაა, ვიდრე ეგოიზმი. უთხარით: „ეს შენი სათამაშოა და შეგიძლია მეგობარს მაშინ მისცე, როცა მზად იქნები“ — ამით აჩვენებთ, რომ პატივს სცემთ მის საკუთრების განცდას. ეს მომავალში მას სხვების საზღვრების პატივისცემის უნარს განუვითარებს.') WHERE id = '3d0a961f-8311-4c15-82e4-3b93885267b5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „სიმაღლიდან გადმოხტომა“. ბავშვს უკვე მოსწონს დაბალი საფეხურიდან ან შემაღლებული ზედაპირიდან ორივე ფეხით ერთდროულად მიწაზე გადმოხტომა. ეს მოძრაობა მნიშვნელოვანია მისი ვესტიბულური სისტემის განვითარებისთვის. მიწაზე რბილი ლეიბი დაუფინეთ და უსაფრთხოდ შეუწყვეთ ხელი მის გაბედულ მცდელობებს.') WHERE id = '0680b361-8e77-46ad-a0ea-0e96e9759bdc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '39-ე თვეში გადავდივართ! ბავშვი უკვე „ორსაფეხურიანი“ აზროვნებიდან „სამსაფეხურიანი“ დავალებების შესრულებაზე გადადის. თუ თხოვნისას: „აიღე სათამაშო, ჩადე ყუთში და დაახურე თავსახური“ — თანმიმდევრობას არ არღვევს, ეს მისი სამუშაო მეხსიერების (working memory) მნიშვნელოვანი მიღწევაა. დღის განმავლობაში მცირე, ლოგიკურად ერთმანეთთან დაკავშირებული დავალებები მიეცით, რათა ეს უნარი კიდევ უფრო განუვითარდეს.') WHERE id = '0f30e0b2-fa18-4fe2-8164-072ae2911569';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „სწრაფი სირბილი და მანევრირება“. ბავშვს უკვე შეუძლია სირბილისას წინ დაბრკოლება დაინახოს და სიჩქარის შეუმცირებლად გვერდი აუაროს. ეს მიუთითებს, რომ მისი სხეულის შეგრძნება (პროპრიოცეფცია) სრულად ჩამოყალიბდა. პარკში „დაბრკოლებებიანი სირბილის“ შეჯიბრებები მოაწყვეთ, რათა მისი ენერგია სასარგებლო აქტივობისკენ მიმართოთ.') WHERE id = 'c69b10fa-3ecf-43fd-9d25-d70589994cb8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „შედარების ხარისხები“. ბავშვი უკვე სწორად იყენებს ისეთ გამოთქმებს, როგორებიცაა „უფრო დიდი“, „ყველაზე პატარა“ და „ძალიან გემრიელი“. ესაუბრეთ მას საგნების შედარებით: „ეს ვაშლი უფრო ტკბილია თუ ის?“. ზედსართავი სახელების შედარების ხარისხების ათვისება მის აღწერით მეტყველებას ამდიდრებს და აზრის უფრო ზუსტად გამოხატვაში ეხმარება.') WHERE id = '10874a8b-618a-44ed-9a23-9c2c3bcf6530';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ძერწვა“. პლასტილინთან ან კინეტიკურ ქვიშასთან მუშაობისას ბავშვი მასალას უკვე მხოლოდ კი არ ჭყლეტს, არამედ მისგან ისეთ ამოსაცნობ ფორმებსაც აკეთებს, როგორებიცაა „ბურთი“, „გველი“ ან „პური“. ეს შესანიშნავი სავარჯიშოა როგორც შემოქმედებითი აზროვნების განვითარებისთვის, ისე თითის წვერების წვრილი კუნთების გასაძლიერებლად.') WHERE id = '8ef81138-3a54-4c5e-ab33-5ab135be888d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმა: უკუღმა და სწორად ჩაცმის განსხვავება“. ბავშვი უკვე ცდილობს გაარჩიოს მაისურისა თუ შარვლის უკუღმა და სწორად ჩაცმა, ასევე მარჯვენა და მარცხენა ფეხსაცმელი (თუმცა ზოგჯერ შეიძლება შეცდეს). მიეცით მცირე მინიშნებები: „შეხედე, ნახატიანი მხარე წინ უნდა იყოს“. ეს ეხმარება მას დეტალებზე ყურადღების გამახვილებასა და თავის მოვლის უნარების გაუმჯობესებაში.') WHERE id = '0d252040-b7cf-42d1-8e5c-b4a1ea436608';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გუნდური სულისკვეთება“. ბავშვს უკვე შეუძლია სხვა ბავშვებთან ერთად საერთო მიზნისთვის თამაში (მაგალითად, დიდი ციხესიმაგრის ასაშენებლად). ეს „პარალელური თამაშიდან“ „თანამშრომლობით თამაშზე“ გადასვლაა. დააკვირდით, როგორ პოულობს ის საერთო ენას სხვა ბავშვებთან და რთულ მომენტებში სოციალური „ხიდის“ აგებაში დაეხმარეთ.') WHERE id = 'b59f81d2-048d-48f5-8c51-231cd1498118';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მომავალი დროის დაზუსტება“. ბავშვი უკვე მხოლოდ „წავალთ“-ს კი არ ამბობს, არამედ თანმიმდევრულ გეგმებს აყალიბებს, მაგალითად: „ხვალ ბებიასთან წავალთ და კატასთან ვითამაშებთ“. დღის ბოლოს მასთან ერთად განიხილეთ მომდევნო დღის გეგმები. ეს ავითარებს მის უნარს, წინასწარ წარმოიდგინოს მოვლენები და დაგეგმოს მოქმედებები (აღმასრულებელი ფუნქცია).') WHERE id = 'e7723585-78f9-489b-95f6-9d306c6417b7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „უფრო რთული ფორმები“. ბავშვს უკვე ოსტატურად უჭირავს ფანქარი სამი თითით (ტრიპოდული ჩაჭიდება) და ცდილობს, ფურცელზე სამკუთხედი დახატოს ან გადამკვეთი ხაზები გაავლოს. ეს მიუთითებს, რომ მისი ხელის კუნთები წერისთვის თითქმის მზადაა. შესთავაზეთ თამაში: „მოდი, წერტილები შევაერთოთ“.') WHERE id = '23c81011-ddf7-4cf3-aec3-f115d29c3f5e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებელი ჰიგიენა: კბილების გახეხვა“. ბავშვმა უკვე იცის კბილების გახეხვის მოქმედებათა თანმიმდევრობა. მიუხედავად იმისა, რომ ბოლოს ჯერ კიდევ თქვენ უნდა „შეამოწმოთ“, მიეცით საშუალება, ეს დამოუკიდებლად გააკეთოს. ეს ჩვევა აძლიერებს მის პასუხისმგებლობას საკუთარ სხეულზე ზრუნვის მიმართ.') WHERE id = '94615e85-6da2-44c7-a201-6901c2a92ddf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „გამოგონილი ამბები და ტყუილი“. ბავშვმა ზოგჯერ შეიძლება არარეალური ამბები მოყვეს (მაგალითად, „მე ცაში ვიფრინე“). ეს მოტყუება კი არა, წარმოსახვისა და მეტყველების შერწყმაა. უთხარით: „რა საინტერესო ამბავია!“ და შეაქეთ მისი წარმოსახვა, თუმცა ამავდროულად რეალობასა და ფანტაზიას შორის არსებული მცირე განსხვავებაც დელიკატურად აუხსენით.') WHERE id = 'd70b5fda-77b6-4fb1-bc69-d894fe21ca89';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „კატეგორიების გაღრმავება“. ბავშვი საგნებს უკვე არა მხოლოდ „მანქანად“ მოიხსენიებს, არამედ ქვეჯგუფებადაც ყოფს, მაგალითად: „სწრაფი მანქანა“, „სატვირთო მანქანა“. შესთავაზეთ ცდა: „რომელი საგნები ტივტივებს წყალში და რომელი იძირება?“ ეს მისი მეცნიერული დაკვირვების უნარის საფუძველია.') WHERE id = '164e0d4f-5849-466c-88ec-e6961c6d0680';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ფეხით მართვა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ფეხით ოდნავ წინ გააგოროს და ასე გადაადგილდეს. ეს დინამიკური წონასწორობის შესანიშნავი ვარჯიშია. პარკში მასთან ერთად მოაწყვეთ პატარა „საფეხბურთო ბილიკი“.') WHERE id = 'c019ed6e-efde-47c2-b2ac-37c3fbd433b5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დამოუკიდებლად ჩაცმა: ღილები და ელვა“. ბავშვს უკვე ძალიან უნდა, რომ დიდი ღილები თავად შეიკრას და ელვაც დამოუკიდებლად შეკრას. ეს თითების წვრილი მოტორიკის კოორდინაციას მოითხოვს. დილით ჩაცმისას მას 5 წუთით მეტი დრო მიეცით, რათა პროცესი თავად დაასრულოს. სიამაყე, რომელსაც საკუთარი ძალებით გაკეთებისას განიცდის, შეუფასებელია.') WHERE id = '24f54158-6d74-423e-b96c-5270e549d121';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „რიგის დაცვა და მოთმინება“. ბავშვს უკვე ესმის, რომ საქანელაზე დასაჯდომად უნდა დაელოდოს, სანამ სხვა ბავშვი ჩამოვა. ცნებები „შენი ჯერია“ და „ჩემი ჯერია“ სოციალურ გარემოში უთანხმოებას ამცირებს. აუცილებლად შეაქეთ მოთმინებისთვის და უთხარით: „დიდი მადლობა, რომ შენს რიგს დაელოდე“.') WHERE id = '97f18e0c-30d0-42a5-aa90-ac6015233d99';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რაოდენობის აღქმა“. ბავშვს 1-დან 10-მდე დათვლის გარდა უკვე შეუძლია 3 ან 4 საგნის რაოდენობა დაუთვლელად, ერთი შეხედვით ამოიცნოს (სუბიტიზაცია). ჰკითხეთ: „აქ რამდენი ვაშლია?“ და სთხოვეთ, თითით მიუთითოს და დაითვალოს. ეს სამომავლო მათემატიკური აზროვნების საფუძველია.') WHERE id = '6e61f63b-18f2-4f84-b98e-0d07b524e3e9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ორი ხელით დაჭერა“. ბავშვი უკვე იწყებს მისკენ ნელა ნასროლი ბურთის დაჭერას — ხელებს იდაყვებში ხრის და გულმკერდთან აერთებს. ეს რეაქციის სისწრაფისა და ხელისა და თვალის კოორდინაციის განვითარებაზე მიუთითებს. სახლში რბილი ბურთით ერთად ითამაშეთ „ბურთის დაჭერა“.') WHERE id = 'eb5816aa-f53e-4699-abf2-d1ff0b98f5f9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული ცნებები: დრო“. მიუხედავად იმისა, რომ ბავშვს ჯერ არ ესმის შეკითხვა „რომელი საათია?“, ცდილობს, სიტყვები „ხვალ“, „გუშინ“ და „შემდეგ“ სწორად გამოიყენოს. დრო ყოველდღიური რიტუალების დახმარებით აუხსენით: „როცა დაიძინებ და გაიღვიძებ, ხვალ იქნება“. ეს მას ეხმარება, სამყარო უფრო მოწესრიგებულად და პროგნოზირებადად აღიქვას.') WHERE id = '6c159ac6-63d6-41de-9c9e-e48fdddeeaef';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური გამძლეობა: „წარუმატებლობის არშიში“. თუ ბავშვს რაიმე არ გამოსდის (მაგალითად, კუბებისგან კოშკის აშენება), ის უკვე მაშინვე აღარ ტირის, შეიძლება შემოგხედოთ და გკითხოთ: „კიდევ ვცადო?“ შეაქეთ არა შედეგი, არამედ ძალისხმევა: „ძალიან ეცადე და თავიდან სცადე, ყოჩაღ!“ თქვენ შესანიშნავი თანამგზავრი ხართ!') WHERE id = '487ce40e-d1a5-42bb-ab35-fd94c37e1b74';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ზედსართავი სიტყვების მრავალფეროვნება“. ბავშვი საგნების აღწერისას იწყებს ისეთი სიტყვების გამოყენებას, როგორიცაა „რბილი“, „ეკლიანი“, „გლუვი“, „ბზინვარე“. ეთამაშეთ თამაში „შეეხე და გამოიცანი“: სთხოვეთ, თვალები დახუჭოს, საგანს შეეხოს და აღწეროს, როგორია ის შეხებით.') WHERE id = '0b5835ed-17d3-46e9-b2cd-eb9c92154c53';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „სხვისი დახმარება“. ბავშვმა შეიძლება უკვე შეამჩნიოს, რომ რაიმეს გაკეთება გიჭირთ ან რაღაცას ეძებთ, და დახმარება შემოგთავაზოთ. ეს აჩვენებს, რომ ის ეგოცენტრული პერიოდიდან გამოდის და ნამდვილ „სოციალურ პარტნიორად“ ყალიბდება. განსაკუთრებულად აღნიშნეთ მისი დახმარება და უთხარით: „შენ რომ არა, ამას ვერ ვიპოვიდი“.') WHERE id = '95ef23e6-3a1e-4eb7-bed7-103fc452a1e2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე იწყებს „შედეგზე“ ორიენტირებულ აზროვნებას. მაგალითად, თქვენი შეხსენებით ცდილობს გაიაზროს ისეთი მიზეზშედეგობრივი კავშირები, როგორიცაა: „თუ ტკბილეულს შევჭამ, შეიძლება კბილები ამტკივდეს“. ამ პერიოდში ძალიან მნიშვნელოვანია, აუხსნათ წესების მიზეზები. ასე მას უყალიბდება არა ბრმად დამორჩილებაზე, არამედ შინაგან ლოგიკაზე დაფუძნებული დისციპლინა.') WHERE id = '602eea29-96df-4d75-b3f3-a89b088efbe3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „დინამიკური წონასწორობა“. ბავშვს უკვე შეუძლია, იატაკზე გავლებული სწორი ხაზის ან თოკის გასწვრივ წონასწორობის დაუკარგავად, „თოკზე მოსიარულესავით“ გაიაროს. ეს ვესტიბულური სისტემის სრულ მომწიფებაზე მიუთითებს. პარკში ბორდიურზე თქვენი ხელის ჩაჭიდებით სიარული მას ამ უნარის კიდევ უფრო დახვეწაში დაეხმარება.') WHERE id = '5465b5ac-4749-433f-99e1-222fda8c10bf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ამბის დეტალები“. ბავშვს უკვე შეუძლია, დღის განმავლობაში მომხდარი ამბავი 4-5 თანმიმდევრული წინადადებით მოყვეს. „დღეს პარკში წავედით, ელჯანი ვნახე, ქვიშაში ვითამაშეთ“. ყურადღებით მოუსმინეთ მის ისტორიებს და დიალოგის გასაგრძელებლად ჰკითხეთ: „შემდეგ რა მოხდა?“ ეს აუმჯობესებს მის ვერბალურ მეხსიერებასა და მეტყველების გამართულობას.') WHERE id = '7607f78f-a199-4155-af72-552bbd09b140';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „წრიდან სიმბოლოებამდე“. ბავშვი უკვე ხატავს დახურულ წრეებს და მათ „ადამიანად“ (ჯოხის კაცუნად) გამოსახატავად ქვემოთ ხაზებს ამატებს. ეს ვიზუალური სიმბოლიზმის დასაწყისია. მიეცით ფერადი ფანქრები და წარმოსახვის გასავითარებლად ჰკითხეთ: „დღეს ვის ხატავ?“') WHERE id = 'ead2dac9-db7b-47ae-9b92-23aa29cddd39';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე უფრო რთული ფორმით გამოხატავს თავის გრძნობებს: „მოწყენილი ვარ, რადგან ჩემი სათამაშო გატყდა“. ეს ემოციური ინტელექტის განვითარებაში დიდი ნახტომია. არა მხოლოდ მიიღეთ მისი გრძნობები, არამედ მიეცით საშუალება, თავადაც შემოგთავაზოთ გამოსავალი: „როგორ ფიქრობ, როგორ შეგვიძლია მისი შეკეთება?“ ეს მასში მედეგობასაც (resilience) ავითარებს.') WHERE id = '72c6a670-175e-4e59-a40a-08a5b3924e43';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობებში ჩნდება „გვერდზე ხტომა“. ბავშვს უკვე შეუძლია არა მხოლოდ წინ, არამედ გვერდზეც გადახტეს. ამისთვის საჭიროა ბარძაყისა და ფეხის კუნთების კოორდინირებული მუშაობა სხვადასხვა მიმართულებით. მოაწყვეთ მასთან შეჯიბრი — ვინ უკეთ გადახტება გვერდულად იატაკზე გავლებული ხაზების მეორე მხარეს.') WHERE id = '7ad7a096-5914-4eed-80cb-8089f672c249';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ნაცვალსახელების სრულად ათვისება“. ბავშვი უკვე აღარ ურევს ერთმანეთში ცნებებს „ჩემი“, „შენი“ და „მისი“. ფრაზით „ეს ჩემი სათამაშოა, ის კი შენია“ იგი ნივთების კუთვნილების სოციალურ საზღვრებს განსაზღვრავს. ეს შესანიშნავი პერიოდია იმის ასახსნელად, თუ რით განსხვავდება საერთო ნივთები (მაგალითად, ოჯახის წიგნი) პირადი ნივთებისგან.') WHERE id = '2b8c7b62-f908-41ef-8972-07466c4a7bd0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში ჩნდება „სიმეტრიის მცდელობები“. ბავშვი ცდილობს ქაღალდის დაკეცვას ან ნახატზე დეტალების სიმეტრიულად განლაგებას. მაგალითად, დახატულ ადამიანს ორივე მხარეს უხატავს ყურს ან ხელს. ეს ტვინის ორივე ნახევარსფეროს კოორდინირებული განვითარების მაჩვენებელია.') WHERE id = 'bd356611-73c3-4619-9883-1f920ac53fa9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სუფრასთან დამოუკიდებლად ქცევის კულტურა“. ბავშვი უკვე ოსტატურად იყენებს ჩანგალს და ცდილობს დანით (ბავშვებისთვის განკუთვნილი უსაფრთხო დანით) რბილი საკვების (მაგალითად, ბანანის ან ომლეტის) დაჭრას. მიეცით მას ეს თავისუფლება. საკუთარი თავის მომსახურების უნარი მის თავდაჯერებულობას შინაგანად აძლიერებს.') WHERE id = 'a07fbd02-0c2f-49de-ba5e-43f31c0bcc20';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში ჩნდება „წესებიანი თამაშები“. ბავშვი უკვე ინტერესით თამაშობს მარტივი წესების მქონე თამაშებს, როგორიცაა „დამალობანა“ ან „დაჭერობანა“, და ცდილობს, პირობები არ დაარღვიოს. ეს სოციალური ადაპტაციის მნიშვნელოვანი ეტაპია. როდესაც წესებს იცავს, აუცილებლად შეაქეთ სიტყვებით: „ყოჩაღ, რომ სამართლიანად ითამაშე“.') WHERE id = 'e172dbdc-63ea-4b2b-afac-30588be411eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარების უნარი — „სიმაღლისა და სიგრძის შედარება“. ბავშვს უკვე შეუძლია საგნების სიმაღლის მიხედვით დალაგება. მიეცით მას სხვადასხვა ზომის 3-4 სათამაშო და უთხარით: „დაალაგე ყველაზე მაღლიდან ყველაზე დაბლისკენ“. ეს მის ვიზუალურ აღქმასა და ლოგიკური თანმიმდევრობით დალაგების უნარს ავითარებს.') WHERE id = '3281647e-af83-48c8-9e0e-9deebd826a8f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სამთვლიანი ველოსიპედით მანევრირება“. ბავშვს უკვე შეუძლია ველოსიპედით მოძრაობისას წინ დაბრკოლება დაინახოს, საჭე მოაბრუნოს და გვერდი აუაროს. ეს პედლების ტრიალის (ფიზიკური) და გზის თვალყურის დევნების (ვიზუალური) უნარების ერთობლიობაა. პარკში მისთვის უსაფრთხო „სავალი ბილიკის“ მოწყობით ხელი შეუწყვეთ ამ უნარის განვითარებას.') WHERE id = 'cccc4e73-bd8f-49ce-ac37-8b06ba255913';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დრო და თანმიმდევრობა“ მეტყველებაში. ბავშვი უკვე ადგენს სამომავლო გეგმებს, მაგალითად: „ხვალ ბებიასთან წავალთ, შემდეგ კი მე პარკში წავალ“. ეს მის გონებაში მოვლენების წინასწარ წარმოდგენის (ვიზუალიზაციის) უნარის განვითარებაზე მიუთითებს. დღის ბოლოს ხვალინდელი გეგმები მასთან ერთად „ზღაპარივით“ მოყევით და ასე დაიძინეთ.') WHERE id = '533647bf-c77f-434e-8420-bd22239f3086';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „მოთმინება და ლოდინი“. ბავშვს უკვე ესმის, რომ რიგში რამდენიმე წუთით ლოდინი „დასასრული“ კი არა, უბრალოდ დროებითი მდგომარეობაა. ეს მისი თვითრეგულაციის (აღმასრულებელი ფუნქციის) უნარის განვითარებაზე მიუთითებს. 1180 დღე — თქვენი ბავშვი უკვე პატარა პიროვნებაა, რომელსაც სამყარო ესმის და მასთან ადაპტირდება. თქვენ შესანიშნავი თანამგზავრი ხართ ამ გზაზე!') WHERE id = 'fe96ce06-9654-4a3f-8b50-d93363f0cbca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე საკუთარი ფიზიკური თვისებებით ახასიათებს თავს: „მე სწრაფად დავრბივარ“ ან „მე მაღალი ვარ“. ეს თვითშემეცნების ეტაპის ახალი საფეხურია. მხარი დაუჭირეთ მის დადებით წარმოდგენას საკუთარ თავზე. დაუსვით კითხვები იმის შესახებ, თუ როგორ ხედავს საკუთარ თავს: „როგორ ფიქრობ, კიდევ რისი კეთება გამოგდის კარგად?“.') WHERE id = '4f2b9702-c295-43cf-9776-2d9fd4b98c79';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დინამიკური ხტომა“ ფიზიკურ მოძრაობაში. ბავშვს უკვე შეუძლია სირბილისას გზად შეხვედრილ მცირე დაბრკოლებას (მაგალითად, მიწაზე დადებულ თოკს) სიჩქარის შეუმცირებლად გადაახტეს. ეს თავის ტვინში მოძრაობის წინასწარ დაგეგმვის (მოტორული დაგეგმვის) უნარის განვითარებაზე მიუთითებს.') WHERE id = '63d363dc-9356-4fa8-bbd3-57a0c8ed1083';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მიზანმიმართული კითხვები“. ბავშვი უკვე მხოლოდ „ეს რა არის?“ კი აღარ კითხულობს, არამედ აინტერესებს: „ეს როგორ მუშაობს?“. ის ნივთების შინაგანი მექანიზმებით ინტერესდება. პასუხის გაცემისას ზედმეტად ნუ გაართულებთ, თუმცა ლოგიკური თანმიმდევრობა შეინარჩუნეთ. ეს კითხვები მომავალი მეცნიერული აზროვნების პირველი ნაპერწკლებია.') WHERE id = 'fda8c637-494b-4891-b635-d2a91f4dbd7b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ფორმების კომბინაციები“. ბავშვი უკვე მხოლოდ წრეს კი აღარ ხატავს, არამედ წრეების შეერთებით „მუხლუხოს“ ან „თოვლის კაცს“ ქმნის. ეს მეტყველებს მის უნარზე, გააერთიანოს ვიზუალური სიმბოლოები და მათგან ახალი მნიშვნელობები შექმნას.') WHERE id = 'c2392a7c-85eb-4d9e-aff3-15371b541a80';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პოლიტიკური“ მოლაპარაკებები. ბავშვი უკვე „გევაჭრებათ“: „თუ ჩემს სათამაშოს ავალაგებ, კიდევ ერთ ზღაპარს წამიკითხავ?“. ეს მიუთითებს, რომ ის სოციალური გავლენის მექანიზმებს სწავლობს. ასეთ „მოლაპარაკებებში“ სამართლიანი იყავით, თუმცა თქვენი ძირითადი წესები შეინარჩუნეთ.') WHERE id = '1c3607b2-8132-49bc-b9ba-d3f310a2378b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წარმოსახვითი სცენარები“. ახლა თამაშები უფრო რთულია: „მე მზარეული ვარ, შენ კი მომხმარებელი ხარ და ფული უნდა გადამიხადო“. ამ თამაშებში ბავშვი საზოგადოებაში არსებულ როლებსა და ეკონომიკურ ურთიერთობებს ცდის. აჰყევით მის სცენარებს და ამით შემოქმედებითი პროცესი წაახალისეთ.') WHERE id = '74c3e2b6-b59d-47f7-ac39-b3a6571a3f4e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „ნივთების დანიშნულება“. ბავშვი ნივთებს უკვე მხოლოდ გარეგნობის მიხედვით კი არ აჯგუფებს, არამედ მათი დანიშნულების მიხედვითაც. „ესენი საჭრელი ხელსაწყოებია (მაკრატელი, დანა)“, „ესენი კი საწერი საშუალებებია“. ეს მიუთითებს, რომ მის ტვინში არსებული ინფორმაციის სისტემა უფრო მოწესრიგებული და ფუნქციური ხდება.') WHERE id = '78693b6d-347d-4486-94dc-37e920221a4d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „კიბეზე დამოუკიდებლად მოძრაობა“. ბავშვი კიბეზე უკვე თავდაჯერებულად ადის, ყოველ საფეხურზე მონაცვლეობით თითო ფეხს დგამს და თითქმის არაფერს ეყრდნობა. ეს წონასწორობისა და ფეხის კუნთების ძალის განვითარების უმაღლესი ეტაპია.') WHERE id = 'cc0be0ea-ed32-4ad7-a00e-446a9d717d47';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „იმიტომ, რომ“-ის ეტაპი. ბავშვი ცდილობს, თავისი ქმედებები დაასაბუთოს: „ამას არ ვიცვამ, იმიტომ, რომ მჩხვლეტს“. მოუსმინეთ მის ამ „იმიტომ, რომ“-ებს. ეს აძლიერებს მის უნარს, საკუთარი საჭიროებები და დისკომფორტი რაციონალურად გამოხატოს.') WHERE id = '1172f061-c7e1-4517-8b34-e51a76cdf51e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „სხვისი წარმატებით გახარება“. ბავშვს უკვე შეუძლია, თქვენი ან მეგობრის წარმატების დანახვისას (მაგალითად, თამაშში გამარჯვებისას) თქვას: „ყოჩაღ!“. ეს ეგოცენტრიზმის (მხოლოდ საკუთარ თავზე ფიქრის) შემცირებისა და სხვების წარმატებით გახარების უნარის ჩამოყალიბების დასაწყისია. თქვენ შესანიშნავ პიროვნებას ზრდით!') WHERE id = 'e58983bd-cd78-4d0a-8590-e07b73fa9e05';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი კითხვას „რატომ?“ უკვე მხოლოდ პასუხის მისაღებად კი არა, მიზეზშედეგობრივი კავშირის გასაგებადაც სვამს. მას უფრო მეტად აინტერესებს ბუნებრივი მოვლენები, მაგალითად: „რატომ ცვივა ფოთლები მიწაზე?“. გაეცით მარტივი, მეცნიერულ ფაქტებზე დაფუძნებული პასუხები. ეს მას გარემომცველი სამყაროს მიმართ ანალიტიკური ხედვის ჩამოყალიბებაში ეხმარება.') WHERE id = '8335f345-0d57-482d-b821-779e730295ca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „წონასწორობის ოსტატობა“. ბავშვს უკვე შეუძლია, ვიწრო ბილიკზე ან იატაკზე დადებულ თოკზე წონასწორობის შენარჩუნებით თავდაჯერებულად გაიაროს. ეს ვესტიბულური სისტემის განვითარების მაღალი ეტაპია. სახლში მასთან ერთად ითამაშეთ „თოკზე მოსიარულე“, რათა მოძრაობების სიზუსტე გააუმჯობესოს.') WHERE id = '00cce1f4-ca47-462d-b84a-6205502d4f13';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „წარსულისა და მომავლის ერთიანობა“. ბავშვი დროით განსხვავებებს წინადადებაში უკვე სწორად გამოხატავს, მაგალითად: „გუშინ პარკში ვიყავი, ხვალ კი ბებიასთან წავალ“. დროის აღქმის გასამყარებლად განაგრძეთ მისთვის დღის ჩვეული აქტივობების „ჯერ, ახლა, შემდეგ“ თანმიმდევრობით შეხსენება.') WHERE id = '10538e9b-c203-4dd2-8b24-d807c72fa3fb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „ადამიანის დეტალური გამოსახულება“. როცა ბავშვი სქემატურ ადამიანს ხატავს, მას უკვე უფრო მეტ დეტალს, მაგალითად, თითებს, თმას ან თვალებს უმატებს. ეს აჩვენებს, რამდენად დაიხვეწა მისი ვიზუალური დაკვირვების უნარი და ხელისა და ტვინის კოორდინაცია.') WHERE id = 'e534e280-1b5b-4f3e-b1db-79a0cf64e3af';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 41-ე თვეში! ამ პერიოდში ბავშვს „განზრახვის“ ცნება უყალიბდება. ის უკვე იწყებს იმის გარჩევას, შემთხვევით მოხდა რამე თუ განზრახ. მაგალითად, თუ ვინმე შეეხო, შეიძლება ჰკითხოს: „ეს განზრახ გააკეთე?“ ეს მნიშვნელოვანი ეტაპია სოციალური ურთიერთობებისას გულწრფელობისა და განზრახვის გასაგებად.') WHERE id = 'be82050e-9ad6-486e-9d98-a2c2c31a243e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ცალ ფეხზე ხტომა“. ბავშვი უკვე ცდილობს ცალ ფეხზე ზედიზედ რამდენჯერმე ახტომას. ეს მოითხოვს როგორც ძალას, ისე წონასწორობის კარგად დაცვის უნარს. ამ უნარის განვითარებაში ხელი შეუწყვეთ — პარკში მასთან ერთად ითამაშეთ „ცალ ფეხზე რბოლა“.') WHERE id = '59f9bda8-ddf4-49be-ad49-7ae815287273';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ლოგიკური კავშირები“. ბავშვი წინადადებებში უკვე ოსტატურად იყენებს კავშირებს „მაგრამ“, „რადგან“ და „თუ“. „პარკში წასვლა მინდა, მაგრამ წვიმს“. ეს მიუთითებს მის უნარზე, გონებაში ურთიერთსაწინააღმდეგო აზრები გააერთიანოს. ამ კავშირების გამოყენებით მასთან დიალოგები უფრო ხანგრძლივი გახადეთ.') WHERE id = 'b5dc9cdd-e5bc-4c21-ba9e-2e9fe7dbdaee';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ქაღალდის გამოჭრა“. ბავშვს უკვე შეუძლია უსაფრთხო მაკრატლით ქაღალდზე გავლებული სწორი ხაზის მიყოლებით გაჭრა. ეს ხელისა და თვალის კოორდინაციის უმაღლესი დონეა. აპლიკაციების გასაკეთებლად მიეცით ფერადი ქაღალდები და შაბლონები, რათა გამოჭრას და დააწებოს.') WHERE id = '93689350-75d1-4dc3-befa-2516fff9cb92';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითრეგულაცია (Self-regulation)“. როდესაც ბავშვი ბრაზდება ან მოწყენილია, უკვე შეუძლია დასამშვიდებლად თქვენ მიერ შეთავაზებული მეთოდების გამოყენება (მაგალითად, ღრმად სუნთქვა ან სათამაშოსთან ჩახუტება). ეს ემოციურ ინტელექტთან დაკავშირებული ერთ-ერთი უმნიშვნელოვანესი ცხოვრებისეული უნარია.') WHERE id = 'cad2a6f6-14d3-4ac8-a455-240edf668e56';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წესებზე დაფუძნებული გუნდური თამაშები“. ბავშვი უკვე ინტერესდება ჯგუფში ყველასთვის საერთო წესებით თამაშით. როდესაც ეუბნებით: „ახლა ყველანი კურდღლებივით ვხტუნაობთ“, ის გუნდს ეწყობა. ეს სკოლისთვის მნიშვნელოვანი უნარის — „ჯგუფში მოქმედების“ — საფუძველია.') WHERE id = '6f7c2344-f4ee-4701-9810-594e0c930fc0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„საზღვრების დაცვა“. ბავშვი უკვე განსაზღვრავს თავის პირად სივრცეს ისეთი გამოთქმებით, როგორებიცაა „ჩემი ოთახი“ და „ჩემი მაგიდა“. პატივი ეცით მისი პირადი სივრცის განცდას. კითხვით „შეიძლება, შენს ოთახში შემოვიდე?“ მას ასწავლით პირადი საზღვრების პატივისცემას და მომავალში სხვების საზღვრების აღიარებასაც.') WHERE id = '19704700-4f78-4a2f-8063-e34e01705522';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სამართლიანობის განცდა“ სოციალურ ქცევაში. ბავშვი უკვე რეაგირებს თამაშის წესების დარღვევაზე: „მან რიგი დაარღვია!“. ეს სოციალური სამართლიანობისა და წესების შესახებ მისი წარმოდგენის განვითარებაზე მიუთითებს. აუხსენით, რატომ არის წესები მნიშვნელოვანი, მაგალითად, იმისთვის, რომ თამაში საინტერესო იყოს, და ამით სოციალური ეთიკის საფუძველი ჩაუყარეთ.') WHERE id = 'bb50baca-3306-43e8-84f0-8ecfe4ce2ed7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„რაოდენობისა და რიცხვის დაკავშირება“ შემეცნებით განვითარებაში. ბავშვს უკვე შეუძლია 10-მდე დათვლა, ახლა კი რიცხვებს რაოდენობას უკავშირებს. როდესაც ეუბნებით: „აქ 5 ცალი თხილი დავდე“, მას უკვე შეუძლია რაოდენობის ვიზუალურად შეფასება. ყოველდღიური საქმიანობისას მიეცით ისეთი დავალებები, როგორიცაა: „მომეცი 4 ცალი კოვზი“.') WHERE id = '3b180a00-84f2-4ef7-b180-bb007866d4c3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სიჩქარე სამთვლიან ველოსიპედზე“. ბავშვი უკვე უფრო სწრაფად მართავს ველოსიპედს და დაბრკოლებებს მანევრირებით უვლის გვერდს. ეს ქვედა კიდურების ძალისა და მხედველობით-მოტორული კოორდინაციის განვითარების მაღალი დონეა. პარკში მისთვის უსაფრთხო „სავალი მარშრუტები“ განსაზღვრეთ, რათა საკუთარი სიჩქარე მოსინჯოს.') WHERE id = 'cf35973e-cf99-454b-b4d7-5058e5466945';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ხუმრობა და იუმორი“ მეტყველებაში. ბავშვი უკვე სიტყვებით თამაშობს და „უცნაური“ წინადადებების შედგენით თქვენს გაცინებას ცდილობს. მაგალითად, შეიძლება თქვას: „ძაღლმა მიაუ თქვა“ და გაიცინოს. ეს აჩვენებს, რომ მან ენის წესები იცის და იუმორის შესაქმნელად მათ განზრახ არღვევს. გაიცინეთ მასთან ერთად და დაეხმარეთ იუმორის გრძნობის განვითარებაში.') WHERE id = '7856919f-0f1f-4c55-9554-5d9226e933f6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1200-დღიანი დიდი მოგზაურობა! ბავშვმა უკვე 40 თვე გაიარა. ახლა ის სრულფასოვანი პიროვნებაა — პატარა ადამიანი საკუთარი აზრებით, ხუმრობებითა და ოცნებებით. ამ 1200 დღის განმავლობაში თქვენ მისი სამყაროს არქიტექტორი იყავით. მის თავდაჯერებულ მზერაში თქვენი სიყვარულის კვალია. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '1104a81e-20a0-469a-b38d-bffb8442b875';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დროის ვიზუალიზაცია“. ბავშვს უკვე შეუძლია კითხვას „გუშინ რა გავაკეთეთ?“ თანმიმდევრულად უპასუხოს. შეუდგინეთ „დღის გეგმა“, რომელშიც დღის მოვლენები სურათებით იქნება ნაჩვენები. ეს დროის აბსტრაქტულ ცნებას მისთვის უფრო კონკრეტულსა და გასაგებს გახდის.') WHERE id = 'ecad2493-1c0b-4ab4-b089-7a992488d7c5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მიზანში სროლა“. ბავშვი ბურთს უკვე უბრალოდ კი არ ისვრის, არამედ ცდილობს, ის კონკრეტულ ყუთში ან სამიზნეში მოარტყას. ეს სივრცეში მანძილისა და ძალის განსაზღვრის (spatial estimation) უნარს ავითარებს.') WHERE id = '6f552613-227f-4085-940c-f293c42bd5f1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვების გაღრმავება“. ბავშვმა შეიძლება არსებობასთან დაკავშირებული რთული კითხვები დაგისვათ, მაგალითად: „რა არის სიკვდილი?“, „საიდან მოვედით?“. პასუხის გაცემისას ყოველთვის გულწრფელი იყავით, თუმცა მისი ასაკისთვის შესაფერისი, მარტივი და დამამშვიდებელი ახსნა შეარჩიეთ. ამ კითხვებით ის ცდილობს, სამყარო გაიაზროს.') WHERE id = '5eb1ed63-47a4-4170-b1fc-b58d4507160b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „შემოქმედებითი თვითგამოხატვა“. როდესაც ბავშვი მოწყენილია, მას უკვე შეუძლია ხატვით ან სათამაშოებთან „გულახდილი საუბრით“ დამშვიდდეს. ყურადღება მიაქციეთ მის ნახატებს — ფერები და ფორმები მისი შინაგანი სამყაროს სარკეა. თქვენ მისთვის ყველაზე საიმედო ნავსაყუდელი ხართ და თქვენდამი ნდობა მისი უდიდესი ძალაა.') WHERE id = '48efdb3a-063c-40d5-837a-9373492693c6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ინტერესდება მის გარშემო არსებული წარწერებით. შესაძლოა, გაუხარდეს, როცა მაღაზიების სახელებსა ან წიგნების სათაურებში მისთვის ნაცნობ ასოებს დაინახავს (მაგალითად, საკუთარი სახელის პირველ ასოს). ეს „ადრეული წიგნიერების“ ეტაპია. ნუ აიძულებთ ასოების სწავლას — უბრალოდ წაახალისეთ მისი ინტერესი.') WHERE id = '4c700caf-0287-4ea7-8bd0-73ca97292800';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „კიბეზე მონაცვლეობითი ნაბიჯებით ჩამოსვლა“. ბავშვი კიბეზე ჩამოსვლისას უკვე იწყებს ყოველ მომდევნო საფეხურზე ფეხების მონაცვლეობით დადგმას. ეს კიბეზე ასვლაზე რთულია და წონასწორობის კარგად დაცვას მოითხოვს. უბრალოდ ახლოს დადექით, რათა მას უსაფრთხოების განცდა შეუქმნათ.') WHERE id = '970cfec9-666d-4324-ad8a-2d2689753b64';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „თავაზიანობა და ნიუანსები“. ბავშვი უკვე იწყებს ხმის ტონისა და სიტყვების მორგებას იმის მიხედვით, თუ ვის ესაუბრება (მაგალითად, ბავშვს უფრო ნაზად, უფროსებს კი უფრო სერიოზულად). ეს სოციოლინგვისტური უნარების განვითარების დასაწყისია. თქვენი მეტყველების კულტურა მისთვის ყველაზე მნიშვნელოვანი და სრულყოფილი მაგალითია.') WHERE id = '3eaa8096-e288-4159-9aa2-8223399dd023';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „საკუთარი თავის შექება“. როდესაც ბავშვი რაიმეს კარგად გააკეთებს, ამბობს: „ნახე, რა კარგად გავაკეთე!“ და თქვენგან მოწონებას ელის. მის შინაგან სიამაყეს უპასუხეთ სიტყვებით: „დიახ, შენ ძალიან მოინდომე“. თქვენი მხარდაჭერა მისი მომავალი თავდაჯერებულობის საფუძველია!') WHERE id = '97ef6f09-4fed-4fcd-abbe-7756d8045e1e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საგნების ერთდროულად რამდენიმე ნიშნის მიხედვით დაჯგუფება: „სათამაშოები, რომლებიც დიდიცაა და ლურჯიც“. ეს კოგნიტური მოქნილობის (cognitive flexibility) მაჩვენებელია. მიეცით საინტერესო საძიებო დავალებები, მაგალითად: „მოდი, ყველა რბილი და წითელი ნივთი ვიპოვოთ“.') WHERE id = '0d946fb4-d148-46c8-80fc-f0a7b324c07f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „თავისუფლად სირბილი და გაჩერება“. ბავშვს უკვე შეუძლია მთელი სისწრაფით სირბილისას თქვენს ბრძანებაზე „გაჩერდი!“ დაუყოვნებლივ შეჩერდეს ისე, რომ წონასწორობა არ დაკარგოს. ეს მისი ნერვ-კუნთოვანი კონტროლის განვითარების დონეზე მიუთითებს. პარკში თამაში „წითელი შუქი, მწვანე შუქი“ სახალისოცაა და სასარგებლო ვარჯიშიც.') WHERE id = '824aa9f8-040c-4665-a6d8-64a894fd7261';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „საპირისპირო მნიშვნელობის სიტყვები“. ბავშვს უკვე არა მხოლოდ ესმის ისეთი საპირისპირო ცნებები, როგორებიცაა „ცხელი-ცივი“, „მაღალი-დაბალი“, „მძიმე-მსუბუქი“, არამედ საუბარშიც იყენებს მათ. დაუსვით გამოცანები საპირისპირო მნიშვნელობებზე: „სპილო დიდია, თაგვი კი?“. ეს მის ლექსიკურ მარაგსა და შედარებითი აზროვნების უნარს ავითარებს.') WHERE id = '56f799be-0231-4113-94ee-9fbaa18f177f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „დეტალები ადამიანის გამოსახულებაში“. ბავშვი უკვე ცდილობს დახატულ ადამიანს ხელები, ფეხები და თითებიც კი დაუმატოს. ეს ნახატები აჩვენებს, როგორ აღიქვამს ის საკუთარ სხეულსა და გარშემომყოფებს. მოუსმინეთ მის თითოეულ „ნამუშევარს“, როგორც პატარა ამბავს.') WHERE id = '0006f22d-7d35-4a7c-abab-057194f6402c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სიტყვებით თამაში და რითმა“. ბავშვს სიამოვნებს მსგავსი ჟღერადობის სიტყვების პოვნა: „ბურთი-მურთი“, „ვაშლი-მაშლი“. ეს ფონოლოგიური აღქმის — ბგერების გარჩევის უნარის — განვითარებაზე მიუთითებს. წაუკითხეთ პატარა რითმიანი ლექსები ან ეთამაშეთ სიტყვებით. ეს მომავალში კითხვის უნარის განვითარებას მყარ საფუძველს შეუქმნის.') WHERE id = '2fa13e97-2173-4c5c-afa8-90f8eaedaa8a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „კვანძი და მარყუჟი“. ბავშვი უკვე ინტერესდება ფეხსაცმლის თასმებითა და სხვა ზონრებით და ცდილობს მათ ერთმანეთში გადახლართვას. მიეცით მძივები დიდი ნახვრეტებით ან სპეციალური „ასაცმელი სათამაშოები“. ეს თითების მცირე კუნთებს წერისა და უფრო რთული მოქმედებებისთვის ამზადებს.') WHERE id = '5b2e2766-e73a-4ec2-b386-7bdc27e2bf73';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარმოსახვითი შიშები“. ამ პერიოდში ბავშვის წარმოსახვა იმდენად ძლიერია, რომ მას შეიძლება სიბნელის ან წარმოსახვითი „ურჩხულების“ ეშინოდეს. ნუ დასცინებთ მის შიშს და ნუ ეტყვით: „ეს მოგონილია“. ამის ნაცვლად, გახდით მისთვის ემოციური თავშესაფარი და უთხარით: „მე აქ ვარ და გიცავ“. ეს თქვენდამი მის ნდობას ურყევს გახდის.') WHERE id = 'b420b26f-d658-40bc-93d9-fcbe9a159330';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „დიპლომატიის მცდელობები“. ბავშვი უკვე ცდილობს კონფლიქტების მოგვარებას ისეთი შეთავაზებებით, როგორიცაა: „შენ ეს მომეცი, მე კი იმას მოგცემ“. ეს სოციალური ინტელექტის ერთ-ერთი ყველაზე ნათელი მაჩვენებელია. შეაქეთ მისი ეს „მომლაპარაკებელი“ მხარე და მხარი დაუჭირეთ სამართლიანი გამოსავლის პოვნაში.') WHERE id = '4ee1a693-af27-4c8f-b294-06b8239d80b9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რაოდენობის უცვლელობის ცდები“. თუ ერთნაირი რაოდენობის წყალს განსხვავებული ფორმის ჭურჭელში ჩაასხამთ, ბავშვმა შეიძლება ჯერ კიდევ იფიქროს, რომ მაღალ ჭურჭელში მეტი წყალია. ეთამაშეთ წყლით ან ქვიშით და მიეცით საშუალება, გამოცდილებით აღმოაჩინოს, რომ ჭურჭლის ფორმის შეცვლით რაოდენობა არ იცვლება.') WHERE id = '13a54bb2-22dc-4956-ad40-80e7f13eda7c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სწრაფად გაჩერება და შემობრუნება“. ბავშვს უკვე შეუძლია სირბილის დროს თქვენი ბრძანების — „გაჩერდი!“ — გაგონებისთანავე გაჩერდეს ან მკვეთრად შემობრუნდეს. ეს კუნთებისა და ნერვული სისტემის ერთობლივი მუშაობის შედეგია. პარკში ეთამაშეთ „წითელი შუქი, მწვანე შუქი“; ეს მის თვითკონტროლის (ინჰიბიტორული კონტროლის) უნარს აუმჯობესებს.') WHERE id = '29ee5396-69c9-428e-9152-0052da7ababd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი საგნებს უკვე არა მხოლოდ ფერის, არამედ დანიშნულების მიხედვითაც აჯგუფებს. „ესენი საჭმელადაა“, „ესენი ჩასაცმელადაა“. სახლში მასთან ერთად ითამაშეთ თამაში „რომელია ზედმეტი?“ (მაგალითად, დადეთ 3 ხილი და 1 სათამაშო). ეს მის ლოგიკურ აზროვნებას ავითარებს.') WHERE id = 'c4b0066e-1d1d-4a2d-b280-39f147e134fe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „სწრაფი მანევრი“. ბავშვს უკვე შეუძლია, მთელი სისწრაფით სირბილისას წინ დაბრკოლება დაინახოს და დაცემის გარეშე გვერდი აუაროს. ეს ტვინის „მოტორული დაგეგმვის“ უნარის უმაღლესი დონეა. პარკში მისთვის დაბრკოლებების პატარა ზოლი მოაწყვეთ. ეს აუმჯობესებს როგორც სხეულის კონტროლს, ისე მოქნილობას.') WHERE id = 'b1971b1f-63a0-40cf-bb46-3ba6bb8689b2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „წარსულის დეტალები“. ბავშვი უკვე გიზიარებთ რთულ მოგონებებს, მაგალითად: „გუშინ ბებიასთან რომ წავედით, ნაყინი ვჭამეთ“. გასულ დღეზე მასთან საუბარი მის ეპიზოდურ მეხსიერებას აძლიერებს. კითხვით „კიდევ რა გახსოვს?“ დაეხმარეთ ამბის უფრო ვრცლად მოყოლაში.') WHERE id = 'f5184b0f-58ef-4b72-af3f-546cec7ec971';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ფიგურის გადახატვა“. ბავშვი უკვე ცდილობს, გაიმეოროს თქვენ მიერ დახატული ჯვარი (+), წრე (O) ან ზოგიერთი ასო. ეს თვალისა და ხელის შეთანხმებული მუშაობაა (ვიზუალურ-მოტორული ინტეგრაცია). მიეცით ფერადი ფანქრები და წაახალისეთ, სხვადასხვა გეომეტრიული ფიგურა დახატოს.') WHERE id = '5ee5e247-d8bd-4375-9669-ceda6b1b0a73';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სამართლიანობა და წესები“. ბავშვი თამაშისას წესების დარღვევაზე უკვე რეაგირებს: „მან რიგი დაარღვია!“. ეს სოციალური თვითცნობიერების განვითარებაა. აუხსენით, რომ წესები ყველასთვის ერთნაირია — ამით მის შინაგან სამართლიანობის განცდასა და სოციალურ დისციპლინას განამტკიცებთ.') WHERE id = 'd1358d5f-b48d-4121-a736-887203ecfc67';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ლიდერობის მცდელობები“. ბავშვს უკვე თავად სურს თამაშის სცენარის შექმნა: „მე ექიმი ვიქნები, შენ კი — პაციენტი“. ასეთი როლური თამაშებით ის სამყაროს შეიცნობს და გადაწყვეტილებების მიღებას სწავლობს. ზოგჯერ მის სცენარს მიჰყევით; ეს მასში ლიდერობისა და პასუხისმგებლობის გრძნობას აყალიბებს.') WHERE id = 'd27742a4-8533-4759-aff4-185d7dbf081f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „რაოდენობისა და რიცხვის შესაბამისობა“. ბავშვს უკვე არა მხოლოდ 5-მდე დათვლა შეუძლია, არამედ ციფრ „3“-ის დანახვისას 3 სათამაშოს ცალკე გადადებაც. ეს მომავალი მათემატიკური წიგნიერების საფუძველია. ყოველდღიური საქმიანობისას მიეცით ისეთი დავალებები, როგორიცაა: „მომეცი 4 ვაშლი“.') WHERE id = '0f53eb59-1dad-4d39-84e5-43e97150561c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორი ფეხით ხტომა“. ბავშვს უკვე შეუძლია დაბრკოლებებს ორივე ფეხით ერთდროულად და თავისუფლად გადაახტეს. ამისთვის საჭიროა როგორც სხეულის ქვედა ნაწილის ძალა, ისე სინქრონული კოორდინაცია. სახლში იატაკზე თოკი დადეთ და მასთან ერთად ითამაშეთ „მდინარის გადალახვა“ — გადაახტით თოკს.') WHERE id = '080c3ee9-a0ea-4062-9f79-5fba44d2d0e4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ხუმრობა და იუმორი“ მეტყველებაში. ბავშვი უკვე ცდილობს, განზრახ არასწორად წარმოთქმული სიტყვებით ან სასაცილო ხმების გამოცემით გაგაცინოთ. ეს ენობრივი ნორმების გააზრების ერთ-ერთი ფორმაა. გაიცინეთ მის ხუმრობებზე და მასთან ერთად განავითარეთ იუმორის გრძნობა.') WHERE id = '9fb34927-219f-4b2d-bb9f-dda7da92c634';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „შეცდომის აღიარება“. როცა ბავშვი რამეს გატეხავს ან დაყრის, უკვე აღარ ცდილობს ამის დაუყოვნებლივ დამალვას და შეუძლია თქვას: „მე გავაკეთე“. გულწრფელობის ასეთ მომენტში ნუ დასჯით; ამის ნაცვლად, შესთავაზეთ ერთად დალაგება. თქვენ მისთვის უსაფრთხო თავშესაფარი ხართ!') WHERE id = 'c4b6f5da-e09e-4e7a-8e0a-9a60747fa087';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საგნები ერთდროულად ფერისა და ფორმის მიხედვით დააჯგუფოს. ის დეტალებს აერთიანებს და ამბობს: „ეს წითელიცაა და მრგვალიც“. ეს კოგნიტიური მოქნილობის მნიშვნელოვანი მაჩვენებელია. შესთავაზეთ თამაშები სხვადასხვა გეომეტრიული ფიგურით.') WHERE id = '2b4289d9-5b1f-4994-a054-e4727135705c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „დინამიკური ხტომა“. ბავშვს უკვე შეუძლია სირბილისას გზაზე არსებული პატარა დაბრკოლების გადახტომა სიჩქარის შეუნელებლად. ეს მიუთითებს ტვინში მოძრაობის წინასწარი დაგეგმვის (მოტორული დაგეგმვის) უნარის განვითარებაზე. პარკში შეგიძლიათ მისთვის პატარა დაბრკოლებები მოაწყოთ.') WHERE id = 'ae389307-05d6-4296-90e1-0a21e776e282';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარმოსახვითი თამაშის მეგობარი“. ამ პერიოდში ზოგიერთმა ბავშვმა შეიძლება წარმოსახვითი მეგობარი გამოიგონოს. ეს ბავშვის შემოქმედებითი უნარისა და მდიდარი ემოციური სამყაროს ნიშანია. ნუ გაკიცხავთ და ნუ ეტყვით, რომ ის „არ არსებობს“. ამ მეგობრის მეშვეობით ბავშვი საკუთარ შიშებსა და სურვილებს იკვლევს. მოთმინებითა და ინტერესით დააკვირდით.') WHERE id = '9ce75a82-fd02-47a8-adbb-96eadd2b8653';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ლიდერობა და დამორჩილება“ სოციალურ ქცევაში. თამაშისას ბავშვი ზოგჯერ თავად ადგენს წესებს, ზოგჯერ კი სხვის წესებს ერგება. ეს სოციალური მოქნილობის საფუძველია. სახლში როლების მონაცვლეობით ითამაშეთ: „ახლა შენ იყავი მასწავლებელი, მე კი მოსწავლე ვიქნები“.') WHERE id = 'd0b4ac9e-9bd0-4b78-83ac-e932a23bb3ff';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მიზეზ-შედეგობრივი ჯაჭვი“ შემეცნებით განვითარებაში. ბავშვს უკვე შეუძლია ისეთი ლოგიკური მსჯელობა, როგორიცაა: „თუ იწვიმებს, პარკში ვერ წავალთ“. ესაუბრეთ მას მოვლენების შედეგებზე. ეს ბავშვს უყალიბებს უნარს, მომავალში გააცნობიეროს პასუხისმგებლობა საკუთარ ქმედებებზე (ლოგიკური შედეგები).') WHERE id = '44001e8a-e9dc-4edd-96dc-e3baba2b5ba4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სამთვლიანი ველოსიპედის დამოუკიდებლად მართვა“. ბავშვს უკვე შეუძლია საჭის მართვის პარალელურად პედლების რიტმულად ტრიალი და საჭიროებისას მუხრუჭის გამოყენება. ამ დროს სხეულის ზედა და ქვედა ნაწილების კოორდინაცია სინქრონულად მუშაობს. პარკში პატარა „ველობილიკი“ მოუნიშნეთ.') WHERE id = 'ec14848a-2298-473c-80f2-13859ca28476';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თავაზიანი თხოვნები“ მეტყველებაში. ბავშვი უკვე მიზანმიმართულად იყენებს ისეთ გამოთქმებს, როგორიცაა „შეიძლება?“ და „გთხოვ“, რათა სასურველი მიიღოს. თქვენი თავაზიანი ქცევა მისთვის საუკეთესო მაგალითია. როდესაც ბავშვი თავაზიანად იქცევა, აუცილებლად გაუსვით ამას ხაზი: „რადგან ასე ლამაზად მთხოვე, ძალიან მიხარია, რომ დაგეხმარები“.') WHERE id = 'c89c5c28-c3bd-46e0-93e1-c16bc60a714b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „თვითრეგულაცია“. როდესაც ბავშვს რაიმე არ გამოსდის (მაგალითად, სათამაშო იშლება), ის მაშინვე არ ტირის — თქვენ გიყურებთ და დახმარებას ითხოვს ან კიდევ ერთხელ ცდილობს. ეს ემოციური სიმწიფისკენ გადადგმული დიდი ნაბიჯია. თქვენ მისი ყველაზე საიმედო მხარდამჭერი ხართ!') WHERE id = 'a0873db2-259d-4791-a8af-c5e115589858';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მიზანმიმართული კითხვები“. ბავშვი უკვე მხოლოდ „ეს რა არის?“ კი აღარ კითხულობს, არამედ აინტერესებს: „ეს როგორ მუშაობს?“. ინტერესდება ნივთების შიდა მექანიზმებით, საათებითა და სათამაშოების ბორბლებით. პასუხის გაცემისას დაიცავით ლოგიკური თანმიმდევრობა — ეს კითხვები მომავალი მეცნიერული აზროვნების პირველი ნაპერწკლებია.') WHERE id = 'd2e255d4-c4cb-4992-b207-917bc8c7e987';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „სიმეტრიის მცდელობები“. ბავშვი ცდილობს, ქაღალდი გადაკეცოს ან ნახატზე დეტალები (მაგალითად, ადამიანის ორი თვალი და ორი ხელი) უფრო სიმეტრიულად განათავსოს. ეს აჩვენებს, რამდენად ვითარდება მისი ვიზუალურ-სივრცითი აღქმა (visual-spatial awareness).') WHERE id = 'b4315b1b-9d62-41cc-a063-b3b09c4c589a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პოლიტიკური“ მოლაპარაკებები. ბავშვი უკვე იწყებს თქვენთან „ვაჭრობას“: „თუ ბოსტნეულს შევჭამ, მერე პარკში უფრო დიდხანს დავრჩებით?“. ეს მიუთითებს, რომ ის სოციალური გავლენის მექანიზმებს სწავლობს. ამ „მოლაპარაკებებისას“ იყავით გულწრფელი და თანმიმდევრული — სწორედ ასე სწავლობს ბავშვი საზღვრებს.') WHERE id = '431cd610-a165-475a-8f4f-464196e237c1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წარმოსახვითი სცენარები“. ახლა თამაშები უფრო რთული ხდება: „მე გამყიდველი ვარ, შენ კი მოდი და ჩემგან პური იყიდე“. ამ თამაშებში ბავშვი საზოგადოებაში არსებულ როლებს სცდის. აჰყევით მის სცენარებს და ამით ხელი შეუწყვეთ შემოქმედებით პროცესს.') WHERE id = '81128f46-ecb8-47f0-aa0b-337c398b3230';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დროის რიტუალები“. მიუხედავად იმისა, რომ ბავშვს „გუშინ“, „დღეს“ და „ხვალ“ ჯერ სრულად არ აქვს გააზრებული, მან კარგად იცის რიტუალები: „ჭამის შემდეგ — პარკი“ ან „ძილის წინ — ზღაპარი“. ასეთი თანმიმდევრობები მის ტვინში დროის ხაზს აყალიბებს.') WHERE id = '5cb6d50d-147c-44f7-91b0-1d67f401019b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ კოორდინაციაში — „ფაქიზი მანევრები“. ბავშვს უკვე შეუძლია სითხით სავსე ჭიქა ისე გადაიტანოს, რომ ბევრი არ დაღვაროს, ან ვიწრო ბილიკზე გაიაროს. ეს აჩვენებს, რამდენად დაიხვეწა მისი ვიზუალურ-მოტორული კოორდინაცია. სახლში „პატარა დამხმარის“ როლების მიცემით დაეხმარეთ, კიდევ უფრო განივითაროს ყურადღება.') WHERE id = 'efc83589-a712-4c32-9e12-c9ee0f9cee01';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარმოსახვითი შიშები“. ამ პერიოდში ბავშვის წარმოსახვა იმდენად ძლიერია, რომ მას შეიძლება სიბნელის ან წარმოსახვითი „ურჩხულების“ ეშინოდეს. ნუ დასცინებთ მის შიშს და ნუ ეტყვით, რომ „ეს ტყუილია“. ამის ნაცვლად, უთხარით: „მე აქ ვარ და გიცავ“ — და მისთვის ემოციურ თავშესაფრად იქეცით. ეს თქვენს მიმართ მის ნდობას ურყევს გახდის.') WHERE id = '09cee55c-899d-468c-bef9-66eb86e868c6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „დიპლომატიის მცდელობები“. ბავშვი უკვე ცდილობს კონფლიქტების მოგვარებას ისეთი შეთავაზებებით, როგორიცაა: „შენ ეს მომეცი, მე კი იმას მოგცემ“. ეს სოციალური ინტელექტის ერთ-ერთი ყველაზე ნათელი მაჩვენებელია. შეაქეთ მისი ეს „მომლაპარაკებლის“ მხარე და მხარი დაუჭირეთ სამართლიან გადაწყვეტილებებს.') WHERE id = '1f6c2927-0b20-482c-b17f-a447f8fef25d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რაოდენობის უცვლელობის ცდები“. თუ ერთნაირი რაოდენობის წყალს განსხვავებული ფორმის ჭურჭლებში ჩაასხამთ, ბავშვმა შეიძლება ჯერ კიდევ იფიქროს, რომ მაღალ ჭურჭელში მეტი წყალია. ითამაშეთ მასთან წყლით ან ქვიშით, რათა პრაქტიკულად აღმოაჩინოს, რომ ფორმის შეცვლით რაოდენობა არ იცვლება.') WHERE id = '73557d3a-6c9c-4c6a-a67f-c5d4bc801f0d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „სწრაფად გაჩერება და შემობრუნება“. ბავშვს უკვე შეუძლია სირბილისას თქვენი ბრძანების — „გაჩერდი!“ — გაგონებისთანავე შეჩერდეს ან მკვეთრად შემობრუნდეს. ეს კუნთებისა და ნერვული სისტემის ერთობლივი მუშაობის შედეგია. ითამაშეთ მასთან პარკში „წითელი შუქი, მწვანე შუქი“ — ეს მას თვითკონტროლის უნარს განუვითარებს.') WHERE id = '2c94b5e7-3f3c-4f5a-97ae-e15891e8c592';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „თავაზიანობა და ნიუანსები“. ბავშვი უკვე იწყებს ხმის ტონისა და სიტყვების შერჩევას იმის მიხედვით, თუ ვის ესაუბრება (მაგალითად, ბავშვთან უფრო ნაზად, უფროსებთან კი უფრო სერიოზულად). ეს სოციოლინგვისტური უნარების დასაწყისია. თქვენი მეტყველების კულტურა მისთვის ყველაზე მნიშვნელოვანი და სრულყოფილი მაგალითია.') WHERE id = '708f00c5-3974-4a48-b57b-7ac187203dd5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „საკუთარი თავის შექება“. როდესაც ბავშვი რაიმეს კარგად გაართმევს თავს, ამბობს: „ნახე, რა კარგად გავაკეთე!“ — და თქვენგან მოწონებას ელის. მის შინაგან სიამაყეს უპასუხეთ სიტყვებით: „დიახ, შენ ძალიან მოინდომე“. თქვენი მხარდაჭერა მისი მომავალი თავდაჯერებულობის საძირკველია!') WHERE id = '1eae35d0-6f20-4979-87f2-c88eacf3b104';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ემოციების ლექსიკონი“. ბავშვი მხოლოდ „ცუდად ვარ“ ან „კარგად ვარ“ აღარ ამბობს. ის შესაბამის სიტუაციაში იყენებს ისეთ სიტყვებს, როგორებიცაა: „გავბრაზდი“, „მომენატრა“, „მიხარია“. აღიარეთ და დაადასტურეთ მისი გრძნობები: „ნორმალურია, რომ ტირი, რადგან მოგენატრა“. ეს მისი ემოციური ჯანმრთელობის ერთ-ერთი ყველაზე მყარი საფუძველია.') WHERE id = 'e498f733-de85-4e45-8875-b886111a89f8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სამ-ნახევარი წლის ასაკის მწვერვალზე! ბავშვმა ჩვილობის პერიოდი უკვე სრულად გაიარა და ახლა „ადრეული ბავშვობის“ ყველაზე აქტიურ ეტაპზეა. ის უკვე როგორც ფიზიკურად, ისე ემოციურად ჩამოყალიბებული ინდივიდია. ამ 1250 დღის განმავლობაში თქვენ მის სამყაროში ურყევი ნდობის საფუძველი შექმენით. იამაყეთ საკუთარი თავით!') WHERE id = 'a45a87d4-253c-4fea-ac32-9cea3f5b1168';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ინტერესდება მის გარშემო არსებული წარწერებით. შეიძლება გაუხარდეს, როცა მაღაზიების სახელებსა თუ წიგნების სათაურებში ნაცნობ ასოებს, მაგალითად, თავისი სახელის პირველ ასოს დაინახავს. ეს „წიგნიერების საწყისი“ ეტაპია. ნუ აიძულებთ ასოების სწავლას — უბრალოდ წაახალისეთ მისი ინტერესი.') WHERE id = '0aedbd42-1452-4a3e-aa54-4adb1ad4a556';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „კიბეზე მონაცვლეობითი ნაბიჯებით ჩამოსვლა“. ბავშვი კიბეზე ჩამოსვლისას უკვე იწყებს ყოველ მომდევნო საფეხურზე მეორე ფეხის დადგმას, ანუ ფეხებს მონაცვლეობით იყენებს. ეს ასვლაზე რთულია და წონასწორობის კარგად დაცვას მოითხოვს. უბრალოდ ახლოს იდექით და უსაფრთხოების განცდა შეუქმენით.') WHERE id = '4a1598de-455f-4bae-a8b3-0f5696c065c6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სიტყვებით თამაში და რითმა“. ბავშვს სიამოვნებს მსგავსი ჟღერადობის სიტყვების პოვნა: „კატა-ნატა“, „ვაშლი-ბაშლი“. ეს ფონეტიკური აღქმის, ანუ ბგერების გარჩევის უნარის განვითარებაა. მასთან ერთად წაიკითხეთ პატარა რითმული ლექსები ან ითამაშეთ სიტყვებით. ეს მომავალში კითხვის უნარისთვის მყარ საფუძველს შექმნის.') WHERE id = '3f6a6fa9-4e7a-4539-93e7-6da1070ea997';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „კვანძი და მარყუჟი“. ბავშვი უკვე ინტერესდება ფეხსაცმლის თასმებითა და თოკებით და ცდილობს, ისინი ერთმანეთს გადააბას. მიეცით დიდი ნახვრეტების მქონე მძივები ან სპეციალური „თასმების გასაყრელი სათამაშოები“. ეს თითების წვრილ კუნთებს წერისა და უფრო რთული საქმიანობისთვის ამზადებს.') WHERE id = 'cf6a8a3d-c742-40b0-a3c1-38fd2db89aec';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე რთულ მოვლენებსაც უსადაგებს თანმიმდევრობას — „ჯერ, ახლა, შემდეგ“. „ჯერ ხელებს დავიბან, შემდეგ საჭმელს შევჭამ, ბოლოს კი ვითამაშებ“. ეს მის ტვინში მოქმედებების დაგეგმვის უნარის (აღმასრულებელი ფუნქციის) განვითარებაზე მიუთითებს. სთხოვეთ, დღის განმავლობაში მცირე გეგმები შეადგინოს. ეს მასში ორგანიზებულობისა და დისციპლინის განცდას აძლიერებს.') WHERE id = 'c4e864cd-f8ff-486c-994b-11d240e723ca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური აქტივობის კუთხით — „სამთვლიანი ველოსიპედით მანევრირება“. ბავშვს უკვე შეუძლია ველოსიპედით მოძრაობისას წინ არსებული დაბრკოლებები დაინახოს და საჭე დროულად მოატრიალოს. ეს პედლების ტრიალისა (ფიზიკური უნარი) და გზაზე დაკვირვების (ვიზუალური უნარი) შესანიშნავი ერთობლიობაა.') WHERE id = '63226ba2-0699-459a-be66-a4c9af97d876';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მიზეზშედეგობრივი დიალოგები“. ის უკვე კითხვებს სვამს თქვენი გადაწყვეტილებების შესახებ: „რატომ უნდა დავიძინო?“. პასუხისას ლოგიკური ახსნა მიეცით: „იმიტომ, რომ შენმა სხეულმა უნდა დაისვენოს, რათა ხვალ კვლავ ენერგიულად ითამაშო“. ასეთი მიდგომა ბავშვში ბრმა მორჩილების ნაცვლად გააზრებულ დისციპლინას აყალიბებს.') WHERE id = 'aba02008-e74d-4081-9df9-4e23bad078b6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილი მოტორიკის კუთხით — „ქაღალდის გამოჭრა“. ბავშვი უკვე ცდილობს, უსაფრთხო მაკრატლით ქაღალდი სწორ ხაზზე გაჭრას (ან მარტივი წრე გამოჭრას). ეს თვალისა და ხელის კოორდინაციის ერთ-ერთი უმნიშვნელოვანესი გამოცდაა. მიეცით ფერადი ქაღალდები და გამოსაჭრელი შაბლონები, რათა ხელის კუნთები ავარჯიშოს.') WHERE id = 'd337c2b8-8f8a-4037-8a7a-e030f9920b04';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„საზღვრები და გაზიარება“. ბავშვს უკვე ესმის, რომ ზოგიერთი ნივთი საერთოა (მაგალითად, პარკის საქანელა), ზოგი კი მხოლოდ მას ეკუთვნის. პატივი ეცით მის საკუთრების განცდას და უთხარით: „ეს შენი სათამაშოა და მისი გაზიარება შენი არჩევანია“. ბავშვი, რომლის საკუთრებასაც პატივს სცემენ, სხვების ნივთებსაც უფრო ადვილად სცემს პატივს.') WHERE id = '9f384019-50a1-4540-baab-8643e931568a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „რთული როლური თამაშები“. ახლა მის თამაშებს უკვე სიუჟეტი აქვს: „შენ ავად ხარ, მე ექიმი ვარ და ნემსს გაგიკეთებ“. ასეთი თამაშების მეშვეობით ბავშვი რეალურ ცხოვრებაში არსებულ შიშებს (მაგალითად, ექიმის შიშს) უკეთ იაზრებს და უმკლავდება. აქტიურად ჩაერთეთ მის სცენარში.') WHERE id = '9206ce15-0a76-4431-b07b-049bdcbed6b0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „რაოდენობისა და რიცხვის შესაბამისობა“. ბავშვმა უკვე იცის 5-მდე დათვლა და ასევე შეუძლია, რიცხვი „3“-ის გაგონებისას ვიზუალურად გამოყოს 3 საგანი. მიეცით ისეთი დავალებები, როგორიცაა: „მომეცი 4 კოვზი“. ეს ის ეტაპია, როდესაც აბსტრაქტული რიცხვები პირველად მჭიდროდ უკავშირდება რეალურ სამყაროს.') WHERE id = 'eaf2d09d-f792-4b9d-ab37-65dbbde32f39';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ორივე ფეხით ხტომა“. ბავშვს უკვე შეუძლია დაბრკოლებებს (მაგალითად, იატაკზე დადებულ თოკს) ორივე ფეხით ერთდროულად და თავისუფლად გადაახტეს. ამისთვის საჭიროა როგორც სხეულის ქვედა ნაწილის ძალა, ისე მოძრაობების სინქრონული კოორდინაცია. სახლში მასთან ერთად ითამაშეთ თამაში „მდინარის გადალახვა“, რათა მისი ფიზიკური აქტივობა გაზარდოთ.') WHERE id = '9a61025f-abc9-4c98-bf07-819847137992';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ხუმრობა და იუმორი“ მეტყველებაში. ბავშვი განზრახ არასწორად წარმოთქვამს სიტყვებს ან სასაცილო ხმებს გამოსცემს, რათა თქვენ გაგაცინოთ. ეს აჩვენებს, რომ მან ენის ნორმები იცის და იუმორის შესაქმნელად მათ შეგნებულად არღვევს. მის ხუმრობებზე სიცილი ბავშვის თავდაჯერებულობასა და სოციალურ ინტელექტს აძლიერებს.') WHERE id = 'b25c4c56-1f97-4223-b20b-689b5e94d1d3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „წარუმატებლობასთან გამკლავება“. თუ ბავშვს რაიმე არ გამოუვა (მაგალითად, კუბებისგან კოშკის აშენება), ის მაშინვე აღარ ტირის და შეიძლება შემოგხედოთ და გკითხოთ: „კიდევ ვცადო?“. შეაქეთ არა შედეგი, არამედ მისი ძალისხმევა: „ძალიან ეცადე, ყოჩაღ!“. თქვენ მისი მოტივაციის უდიდესი წყარო ხართ!') WHERE id = 'f9148bba-3642-4b13-ad48-62db8da7ed80';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი საგნებს უკვე არა მხოლოდ გარეგნობის, არამედ მასალის მიხედვითაც განასხვავებს: „ეს პლასტმასაა, ეს კი რკინაა“. მიეცით სხვადასხვა ტექსტურის მქონე საგნები და ჰკითხეთ, რით განსხვავდება ისინი. ეს ეხმარება მას, უფრო დეტალურად გააანალიზოს გარემომცველი სამყარო და ფიზიკური სამყაროს შესახებ ცოდნა სისტემაში მოიყვანოს.') WHERE id = '80e00e5a-2a93-4c1b-a710-db553822e4ae';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „ცალ ფეხზე წონასწორობის შენარჩუნება“. ბავშვს უკვე შეუძლია ცალ ფეხზე 5 წამზე მეტხანს დგომა. ეს მიუთითებს ნათხემისა და კუნთების კოორდინაციის მომწიფებაზე. მასთან ერთად ითამაშეთ „ყარყატის თამაში“ და შეამოწმეთ, ვინ შეძლებს ცალ ფეხზე უფრო დიდხანს დგომას.') WHERE id = '18ab2c20-2470-41d2-b5e5-3121b8d7e0c1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ზედსართავი სახელების მრავალფეროვნება“. ნივთების აღწერისას ბავშვი მხოლოდ ფერს აღარ ასახელებს და იყენებს ისეთ სიტყვებსაც, როგორიცაა „რბილი“, „ეკლიანი“, „გლუვი“. ეთამაშეთ თამაში „შეეხე და გამოიცანი“: თვალები დაახუჭვინეთ და სთხოვეთ, აღწეროს, როგორი შეგრძნება აქვს ნივთზე შეხებისას.') WHERE id = '6a7056fe-a7e8-4d7e-91b2-4d5b5277e537';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „სიმბოლოების აღმოჩენა“. ბავშვი უკვე ცდილობს ზოგიერთი ასოს (განსაკუთრებით საკუთარი სახელის პირველი ასოს) ან ციფრის გადაწერას. ეს აჩვენებს, რომ მას ესმის კავშირი ვიზუალურ სიმბოლოებსა და ბგერას ან მნიშვნელობას შორის. ავარჯიშეთ „წერაში“ ქვიშაზე ან ფერადი ფანქრებით.') WHERE id = 'b57332a7-c381-44a7-bdb8-aef8d6820036';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითკონტროლი და მოთმინება“. ბავშვი უკვე უფრო მშვიდად იღებს იმას, რომ სასურველი რამის მისაღებად 5-10 წუთი უნდა დაიცადოს (მაგალითად, სანამ საჭმელი მომზადდება). თქვენს სიტყვებს „ცოტა მოიცადე“ ის სასჯელად კი არა, დროის საჭიროებად აღიქვამს. როცა ამ მოთმინებას შეამჩნევთ, აუცილებლად გაამხნევეთ სიტყვებით: „დიდი მადლობა, რომ მოიცადე“.') WHERE id = '7374ce80-a74f-4d7f-bb0f-135ec7c6d431';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ემპათია და ნუგეშისცემა“. როცა ბავშვი ამჩნევს, რომ თქვენ დაღლილი ხართ ან მისი მეგობარი მოწყენილია, მან შეიძლება სათამაშო მიუტანოს ან მოეფეროს. ეს აჩვენებს, რამდენად გამდიდრდა მისი შინაგანი სამყარო და როგორ გადადის ის „მე“-დან „ჩვენ“-ისკენ.') WHERE id = '62ab0290-ec13-4b50-86f2-b4a69aba6dda';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „მოცულობის აღქმა“. ახლა ბავშვი ცდილობს გამოიცნოს, რამდენი პატარა სათამაშო ჩაეტევა დიდ ყუთში. მიეცით სხვადასხვა ზომის ჭურჭელი და ჰკითხეთ: „როგორ ფიქრობ, ეს წყალი იმ ჭურჭელში ჩაეტევა?“ ასეთი ექსპერიმენტები საფუძველს უყრის მომავალ მათემატიკურ და ფიზიკურ წარმოდგენებს.') WHERE id = 'd68476f5-47bc-4622-82c1-31e6c34eeecd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „უკან სიარული“. ბავშვს უკვე შეუძლია თავდაჯერებულად გადადგას რამდენიმე ნაბიჯი უკან ისე, რომ წონასწორობა არ დაკარგოს. ეს მოძრაობა აძლიერებს საკუთარი სხეულის აღქმას (პროპრიოცეფციას). პარკში ეთამაშეთ „კიბორჩხალების რბოლა“ — ასე ერთადაც გაერთობით და მის კუნთებსაც გაავარჯიშებთ.') WHERE id = 'ff4d4dbc-967a-48e5-b6f7-ae29e0a5390d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითრეგულაცია და ემოციები“. როდესაც ბავშვი ბრაზდება ან ნაწყენია, ზოგჯერ თავის დასამშვიდებლად შეიძლება თქვენ მიერ შეთავაზებული ხერხები გამოიყენოს (მაგალითად, ღრმად ჩაისუნთქოს). ეს ემოციური ინტელექტის ერთ-ერთი უმნიშვნელოვანესი ცხოვრებისეული უნარია. როცა დამშვიდდება, აუცილებლად შეაქეთ ამ ნაბიჯისთვის.') WHERE id = 'cab1e84e-d4d4-48e6-a7cb-8122f2485764';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„გუნდური თამაშები“ სოციალურ ქცევაში. ბავშვს უკვე შეუძლია სხვა ბავშვთან საერთო მიზნის მისაღწევად თანამშრომლობა (მაგალითად, დიდი ქვიშის სასახლის ასაშენებლად). ეს „პარალელური თამაშიდან“ „სოციალურ თამაშზე“ სრულად გადასვლაა. დააკვირდით და მხარი დაუჭირეთ მის მცდელობებს, გამონახოს საერთო ენა მეგობრებთან.') WHERE id = '35da39d6-0c56-4410-8592-5e1cbd4b1e03';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„რიცხვისა და რაოდენობის შესაბამისობა“ შემეცნებით განვითარებაში. ბავშვს შეუძლია 10-მდე დათვლა, თუმცა ახლა, როცა ციფრ „3“-ს ხედავს, უკვე შეუძლია 3 სათამაშოს ცალკე გადადება. ეს მათემატიკური აზროვნების განვითარების ერთ-ერთი უმნიშვნელოვანესი ეტაპია. ყოველდღიურ ცხოვრებაში განუმტკიცეთ ეს კავშირი ისეთი დავალებებით, როგორიცაა: „მომეცი 2 კოვზი“.') WHERE id = '4397b751-5eff-493f-b5d9-774c99d1ca07';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ორივე ხელით დაჭერა“. ბავშვი უკვე ცდილობს, მისკენ ნელა ნასროლი დიდი ბურთი ორივე ხელით დაიჭიროს (ზოგჯერ მკერდზე მიკვრით). ეს მოძრაობა მოითხოვს როგორც თვალისა და ხელის კოორდინაციას, ისე რეაქციის სისწრაფეს. ეთამაშეთ ახლო მანძილიდან.') WHERE id = '416872cb-a02b-4d4e-ac74-f040d4ce096b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თავაზიანი თხოვნები“ მეტყველებაში. ბავშვი უკვე მიზანმიმართულად იყენებს ისეთ გამოთქმებს, როგორიცაა „შეიძლება?“ და „გთხოვ“, რათა სასურველი მიიღოს. თქვენი თავაზიანი ქცევა მისთვის საუკეთესო მაგალითია. როცა თავაზიანად იქცევა, აუცილებლად გაუსვით ამას ხაზი: „რადგან ასე ლამაზად მთხოვე, ძალიან მიხარია, რომ დაგეხმარები“.') WHERE id = 'eb838920-fe5c-415a-a9ba-0dabdeaffb4e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „საკუთარი შეცდომის აღიარება“. როცა ბავშვი რამეს აფუჭებს, უკვე აღარ ცდილობს ამის დაუყოვნებლივ დამალვას და შეუძლია თქვას: „მე გავაკეთე“. გულწრფელობის ამ მომენტში ნუ დასჯით; ამის ნაცვლად, შესთავაზეთ, ერთად დაალაგოთ. ეს მასში პასუხისმგებლობის გრძნობას აყალიბებს. 1290-დღიანი გზის ყოველი წამი ძვირფასია!') WHERE id = 'fba8e58a-849a-4502-b3b8-829b5d503078';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „თავაზიანობა და ნიუანსები“. ბავშვი უკვე იწყებს ხმის ტონის მორგებას იმის მიხედვით, თუ ვის ესაუბრება (მაგალითად, პატარას უფრო ნაზად, უფროსებს კი უფრო სერიოზულად). ეს სოციოლინგვისტიკის საწყისი ეტაპია. თქვენი მეტყველების კულტურა მისთვის მთავარი და საუკეთესო მაგალითია.') WHERE id = '3f691af2-a53f-4e9e-bda8-73c25f9784e5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'განვითარების 1280 მნიშვნელოვანი დღე! ბავშვი უკვე „ადრეული ბავშვობის“ ყველაზე ნაყოფიერ პერიოდშია. ის ახლა სრულფასოვანი პიროვნებაა — პატარა ადამიანი საკუთარი გემოვნებით, შიშებითა და უსასრულო კითხვებით. თქვენ ეს გზა ცოდნითა და სიყვარულით გამოიარეთ. „Anacan“ ყოველთვის თქვენს გვერდითაა!') WHERE id = 'cb9230b0-c04d-4749-92fd-37201aec8ecd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საგნების დაჯგუფება არა მხოლოდ ერთი, არამედ ორი თვისების მიხედვით: „მანქანები, რომლებიც წითელიცაა და პატარაც“. ეს კოგნიტიური მოქნილობის მნიშვნელოვანი ეტაპია. მიეცით მას სხვადასხვა სათამაშო და ავარჯიშეთ მისი გონება დავალებით: „იპოვე ყველა რბილი და ლურჯი სათამაშო“.') WHERE id = '7f3f7af2-f05b-47b3-bb9a-bf661d551477';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში — „ზუსტი ნახტომი“. ბავშვს უკვე შეუძლია ადგილიდან ახტეს როგორც სიმაღლეზე, ისე კონკრეტული სამიზნისკენ (მაგალითად, იატაკზე დახაზული წრის შიგნით). ეს მიუთითებს როგორც წონასწორობის დაცვის, ისე სივრცეში მანძილის განსაზღვრის უნარზე. პარკში თამაში „ქვიდან ქვაზე გადახტომა“ მისთვის შესანიშნავი ვარჯიშია.') WHERE id = 'b66ed3bb-08b0-48a9-9270-0f8d21791b6b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროითი თანმიმდევრობა“. ბავშვი უკვე უფრო ზუსტად იყენებს ცნებებს „ჯერ, ახლა, შემდეგ“: „ჯერ ხელებს დავიბან, შემდეგ პურს შევჭამ“. მასთან დღის გეგმის განხილვა უვითარებს მოწესრიგებულობას და უსაფრთხოების განცდას. მის კითხვას „ახლა რას გავაკეთებთ?“ ყოველთვის თანმიმდევრულად უპასუხეთ.') WHERE id = '4a19271e-0252-465e-a5b6-220dfc833dfa';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ფიგურების გადახატვა: სამკუთხედი და ჯვარი“. ბავშვს უკვე შეუძლია სწორი ხაზების გადაკვეთით ჯვრის (+) დახატვა და ცდილობს სამკუთხედის მსგავსი ფიგურების შექმნას. ეს წერის უნარის საწყისი საფუძველია. მიეცით მას ფერადი ფანქრები და სუფთა ფურცლები, რათა ხელი შეუწყოთ მის ამ „გეომეტრიულ აღმოჩენებს“.') WHERE id = '5e0bb7b8-fe4c-40a9-87b2-d5ec3dff9314';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე სრულად ესმის „თუ... მაშინ...“ ლოგიკა. „თუ სათამაშოს გავტეხ, ის აღარ იმუშავებს“. ეს მომავლის პროგნოზირების უნარის დასაწყისია. შესთავაზეთ, წინასწარ დაფიქრდეს საკუთარი ქმედებების შედეგებზე: „როგორ ფიქრობ, რა მოხდება, თუ ჭიქას კიდეზე დავდებთ?“ ეს პასუხისმგებლობის გრძნობას უყალიბებს.') WHERE id = '98264d01-8080-47ff-9743-5076f3c1e9fb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „სტატიკური წონასწორობის მწვერვალი“. ბავშვს უკვე შეუძლია, ცალ ფეხზე 5-10 წამი ისე იდგეს, რომ არაფერს შეეხოს. ეს მიუთითებს როგორც შიგნითა ყურში არსებული წონასწორობის ცენტრის განვითარებაზე, ისე წელისა და ფეხის კუნთების გაძლიერებაზე. ეთამაშეთ „გაშეშობანას“ და ეს უნარი სახალისო აქტივობად აქციეთ.') WHERE id = 'e5ea1656-41df-45ea-937c-07b3a21bce4f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რთული ამბის აგება“. ილუსტრირებული წიგნის დათვალიერებისას ბავშვი უკვე მხოლოდ საგნებს კი არ ასახელებს, არამედ მოვლენებს შორის კავშირსაც ხსნის: „კურდღელი გარბის, რადგან მელა მოდის“. წარმოსახვის გასავითარებლად დაუსვით კითხვები, მაგალითად: „როგორ ფიქრობ, რას იტყვის მელა?“ ეს მის კოგნიტიურ მოქნილობას ზრდის.') WHERE id = '991395b5-cce5-4484-973b-52ea93850c86';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „თითების დამოუკიდებელი მოძრაობა“. ბავშვს უკვე შეუძლია რთული მოქმედებების შესრულება — თითების ერთმანეთზე დაკაკუნება ან თითის წვერებით პატარა მძივების ძაფზე ასხმა. ეს თავის ტვინის ორივე ნახევარსფეროს კოორდინირებულ მუშაობას მოითხოვს. შესთავაზეთ ღილების შეკვრისა და მარყუჟების გახსნის თამაშები.') WHERE id = '7718afa5-181a-4995-b727-92bfdea228d9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარმოსახვითი შიშების მართვა“. ამ ასაკში ბავშვებს ზოგჯერ სიბნელის ან „ურჩხულების“ ეშინიათ. ნუ უარყოფთ მის შიშს; პირიქით, მოიფიქრეთ თამაშები, მაგალითად „ჯადოსნური ფარანი, რომელიც ურჩხულს განდევნის“. თქვენი ემოციური მხარდაჭერა ასწავლის, რომ ეს შიშები დროებითია.') WHERE id = '5da5688a-9254-4a8e-94a4-a6cdb8624f11';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „შედეგზე ორიენტირებული თანამშრომლობა“. ბავშვს უკვე შეუძლია, მეგობართან ერთად დიდი კოშკის ასაშენებლად „ქვები“ გაინაწილოს. ეს უკვე უბრალოდ გვერდიგვერდ თამაში კი არა, საერთო მიზნისთვის თანამშრომლობაა (თანამშრომლობითი თამაში). შეაქეთ მისი სოციალური დიპლომატიის უნარი სიტყვებით: „რა შესანიშნავი გუნდი ხართ!“') WHERE id = '12a2b82c-6975-4312-a2f7-fbbdcf5d9909';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ხუმრობისა და იუმორის გაღრმავება“. ბავშვს უკვე შეუძლია სიტყვების მნიშვნელობის შეცვლით იხუმროს. მაგალითად, შეიძლება „მამა“ დაგიძახოთ და გაიცინოს. ეს აჩვენებს, რომ მან ენის ნორმები კარგად იცის და იუმორის შესაქმნელად მათ განზრახ არღვევს. გაერთეთ მასთან ერთად.') WHERE id = '8c83e3c0-4591-49c2-a059-525f584c28d3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „მოთმინების გამოცდა“. ბავშვს უკვე შეუძლია, მისთვის სასურველი რამის მისაღებად რამდენიმე წუთი ჩუმად დაიცადოს (მაგალითად, სანამ თქვენ ტელეფონზე საუბრობთ). ეს მისი თვითკონტროლის უნარის განმტკიცებაზე მიუთითებს. ლოდინის შემდეგ აუცილებლად გადაუხადეთ მადლობა და უთხარით: „დიდი მადლობა, რომ დამელოდე“.') WHERE id = '75df2db1-9a5a-4048-99dc-80b484b6d396';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია გარშემო არსებული ლოგოებისა და წარწერების ამოცნობა. მაგალითად, საყვარელი ნაყინის ბრენდის ან მაღაზიის ლოგოს დანახვისას მის სახელს ამბობს. ეს სიმბოლური აზროვნების განვითარებაზე მიუთითებს. აჩვენეთ სხვადასხვა საგზაო ნიშანი ან მარტივი პიქტოგრამა და ჰკითხეთ, რას ნიშნავს ისინი. ეს მომავალში კითხვის უნარის განვითარებისთვის ვიზუალურ საფუძველს ქმნის.') WHERE id = 'bb1f5dc6-7300-4f63-9d44-40f2e54dfb71';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „უკან ხტომა“. ბავშვს უკვე შეუძლია უკან პატარა ნახტომების გაკეთება. ეს როგორც წონასწორობის, ისე სივრცეში სხეულის მართვის უნარის ახალი დონეა. მისი აქტიურობის წასახალისებლად ეთამაშეთ „კიბორჩხალასა და ბაყაყის“ რბოლა.') WHERE id = '2c74b1f3-a8fd-4086-88da-377857855b8c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „საპირისპირო თვისებების შედარება“. ბავშვი უკვე სათანადოდ იყენებს წინადადებაში შედარების ფორმებს, როგორიცაა „ყველაზე დიდი“, „უფრო პატარა“ და „ძალიან მძიმე“. მიეცით 3 სხვადასხვა ზომის სათამაშო და ჰკითხეთ: „რომელია ყველაზე დიდი?“ ეს აჩვენებს, რომ მისი ლექსიკური მარაგი რაოდენობრივად და თვისებრივად მდიდრდება.') WHERE id = 'f9bd7f70-01bc-46e8-8391-e80ede82d1cc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „პროპორციულობა ადამიანის გამოსახულებაში“. ადამიანის ხატვისას ბავშვი უკვე სხეულის ნაწილებს უფრო ლოგიკურად ათავსებს: თვალები სახის შუაშია, ხელები კი სხეულის გვერდებზე. ეს ნახატები საკუთარი სხეულის აღქმის (body image) განვითარებას ასახავს.') WHERE id = 'b857a3b6-e216-49cf-a9c0-e7adabf3fdba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „კითხვების ხარისხი“. ახლა ბავშვი მხოლოდ „ეს რა არის?“ კი აღარ კითხულობს, არამედ — „რატომ არის ასე?“. ის მოვლენების შინაგანი ლოგიკის გაგებას ცდილობს. პასუხის გაცემისას მისი წარმოსახვაც გაააქტიურეთ: „შენი აზრით, რატომ წვიმს?“. ეს მის შემოქმედებით და მეცნიერულ აზროვნებას ასტიმულირებს.') WHERE id = '104d37cc-f454-4cee-bc62-45a7dd638317';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ფიგურის გადახატვა: კვადრატი და სამკუთხედი“. ბავშვი უკვე ცდილობს კუთხეებიანი ფიგურების დახატვას. ეს წრის დახატვაზე რთულია, რადგან ფანქრის განსაზღვრულ წერტილში გაჩერებასა და მიმართულების შეცვლას მოითხოვს. აჩვენეთ, როგორ შეიძლება კუთხეებიანი ფიგურების გაერთიანებით „სახლის“ ან „მანქანის“ დახატვა.') WHERE id = '72c3574b-2a9a-4755-8727-8d01b439e56e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სამართლიანობა და წესები“. ბავშვი თამაშისას წესების დარღვევაზე უკვე მკვეთრად რეაგირებს: „მან რიგი დაარღვია!“. ეს სოციალური თვითშეგნებისა და ეთიკური წარმოდგენების განვითარების ნიშანია. აუხსენით, რომ წესები ყველასთვის ერთნაირია — ამით მას სამართლიანობის შინაგან განცდასა და სოციალურ დისციპლინას განუმტკიცებთ.') WHERE id = '6e14d59c-92a1-4b52-9746-19ec45e3a240';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „დიპლომატიის მცდელობები“. ბავშვი კონფლიქტების მოგვარებას ისეთი შეთავაზებებით ცდილობს, როგორიცაა: „შენ ეს მომეცი, მე კი იმას მოგცემ“. ეს სოციალური ინტელექტის ერთ-ერთი ყველაზე მკაფიო მაჩვენებელია. შეაქეთ მისი ეს „მომლაპარაკებელი“ მხარე და მხარი დაუჭირეთ სამართლიანი გამოსავლის პოვნაში.') WHERE id = '1bc59678-d965-4c53-ad57-e91ac3a6bece';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რაოდენობის მყისიერი ამოცნობა (Subitizing)“. ბავშვს უკვე შეუძლია, 3 ან 4 საგანს უბრალოდ შეხედოს და დათვლის გარეშე მიხვდეს, რამდენია. აჩვენეთ ბარათები სხვადასხვა რაოდენობის წერტილებით და სთხოვეთ, დაუყოვნებლივ თქვას, რამდენია. ეს მომავალში სწრაფი მათემატიკური გამოთვლის უნარის საფუძველია.') WHERE id = '9268aa12-9e8f-498d-a13c-fd38e4e68957';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მხარს ზემოდან გადაგდება“. ბავშვი ბურთს უკვე უბრალოდ ძირს კი არ აგდებს, არამედ შეუძლია, მხრის დონიდან შორს და განსაზღვრული სამიზნისკენ ისროლოს. ეს მთელი სხეულის კოორდინირებასა და ძალის რეგულირებას მოითხოვს. პარკში მასთან ერთად ითამაშეთ სამიზნეში ბურთის სროლა.') WHERE id = 'dbdc7993-c5ce-4ff8-a2f5-69daf1b98fea';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „რაოდენობის მუდმივობის ტესტი“. ბავშვს ჯერ კიდევ შეიძლება ეგონოს, რომ გაბრტყელებული პლასტილინი პლასტილინის გუნდაზე დიდია. ჩაატარეთ მასთან ასეთი ცდები: გუნდა გააბრტყელეთ, შემდეგ კი კვლავ გუნდად აქციეთ. ეს მას ფიზიკური სამყაროს უცვლელი კანონების გააზრებაში ეხმარება.') WHERE id = 'ae824ed0-4f75-4515-b7bf-83483a6c043d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ფეხით მართვა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ფეხით ოდნავ წინ გაგორებით გადაადგილოს (დრიბლინგი). ამას დინამიკური წონასწორობა და ფეხისა და თვალის კოორდინაცია სჭირდება. პარკში მოუწყვეთ პატარა „საფეხბურთო ბილიკი“ და სთხოვეთ, ბურთი მიზნისკენ წაიყვანოს.') WHERE id = '6f891729-8e3d-4c9f-bdb3-588b6de557c3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ზრდილობა და ეტიკეტი“. ბავშვი სიტყვებს „ბოდიში“ და „თუ შეიძლება“ უკვე არა უბრალოდ დაზეპირებულად, არამედ გააზრებულად იყენებს. ტონი, რომლითაც თქვენ სხვებს ესაუბრებით, მისთვის საუკეთესო სახელმძღვანელოა. როდესაც ის თავაზიანად იქცევა, აგრძნობინეთ, რა დადებით გავლენას ახდენს მისი ქცევა გარშემომყოფებზე.') WHERE id = '8553307b-a429-4fdd-a8d5-b4776f0fb3d5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1300-დღიანი საოცარი გზა! ბავშვმა ჩვილობის ჩვევები უკვე მთლიანად უკან მოიტოვა და სკოლამდელი ასაკის ყველაზე აქტიურ ეტაპზე გადადის. ის უკვე საკუთარ თავს დამოუკიდებელ „მედ“ აღიქვამს და მზადაა, სამყარო შეცვალოს. ამ 1300 დღის განმავლობაში თქვენ მისი ყველაზე სანდო მეგზური იყავით. მადლობა გადაუხადეთ საკუთარ თავს სიყვარულისა და მოთმინებისთვის!') WHERE id = '7883dc4b-dac2-42dc-8a35-51e8d5b489b1';